drawSwatchCanvas(color){
  const sc=document.createElement('canvas');sc.width=480;sc.height=600;
  const sx=sc.getContext('2d');
  sx.imageSmoothingEnabled=false;
  // color block — top 2/3
  sx.fillStyle=color.hex;sx.fillRect(0,0,480,400);
  // meta bg
  sx.fillStyle='#faf9f7';sx.fillRect(0,400,480,200);
  // divider
  sx.fillStyle='#e0dbd4';sx.fillRect(0,400,480,2);
  // outer border
  sx.strokeStyle='#e0dbd4';sx.lineWidth=2;sx.strokeRect(1,1,478,598);
  // name
  sx.fillStyle='#2a2520';
  sx.font='bold 22px Helvetica Neue, Helvetica, Arial, sans-serif';
  sx.fillText((color.name||namify(color.r,color.g,color.b)).toUpperCase(),32,452);
  // hex
  sx.fillStyle='#a09a92';
  sx.font='400 20px Courier New, monospace';
  sx.fillText(color.hex.toUpperCase(),32,490);
  // rgb
  sx.fillStyle='#c0b8b0';
  sx.font='400 16px Courier New, monospace';
  sx.fillText(`RGB(${color.r}, ${color.g}, ${color.b})`,32,522);
  return sc;
}

copySwatch(color,idx,btn){
  const sc=this.drawSwatchCanvas(color);
  sc.toBlob(blob=>{
    if(navigator.clipboard&&window.ClipboardItem){
      navigator.clipboard.write([new ClipboardItem({'image/png':blob})]).then(()=>{
        btn.textContent='Copied';btn.classList.add('copied');
        setTimeout(()=>{btn.textContent='Copy';btn.classList.remove('copied');},1600);
      }).catch(()=>this.fallbackSwatchDownload(sc,color,btn));
    }else{this.fallbackSwatchDownload(sc,color,btn);}
  },'image/png');
}

