import { useState, useRef, useEffect, useCallback } from "react";
import { BarChart, Bar, LineChart, Line, AreaChart, Area, PieChart, Pie, Cell, ScatterChart, Scatter, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from "recharts";

const FALLBACK = [
  { hex: "#c8b89a", name: "Sand" },
  { hex: "#8a7a6a", name: "Clay" },
  { hex: "#5a4a3a", name: "Bark" },
  { hex: "#a09a92", name: "Pebble" },
  { hex: "#d4c8b8", name: "Linen" },
];

const BAR_DATA = [
  { label: "Jan", A: 42, B: 28, C: 18 },
  { label: "Feb", A: 55, B: 35, C: 24 },
  { label: "Mar", A: 38, B: 48, C: 30 },
  { label: "Apr", A: 62, B: 41, C: 22 },
  { label: "May", A: 48, B: 52, C: 35 },
  { label: "Jun", A: 71, B: 38, C: 28 },
  { label: "Jul", A: 58, B: 45, C: 40 },
];
const LINE_DATA = [
  { label: "W1", A: 30, B: 20, C: 15 },
  { label: "W2", A: 45, B: 28, C: 22 },
  { label: "W3", A: 38, B: 35, C: 30 },
  { label: "W4", A: 60, B: 42, C: 25 },
  { label: "W5", A: 52, B: 38, C: 35 },
  { label: "W6", A: 68, B: 50, C: 28 },
  { label: "W7", A: 75, B: 55, C: 42 },
  { label: "W8", A: 63, B: 48, C: 38 },
];
const PIE_DATA = [
  { name: "Outerwear", value: 32 },
  { name: "Tops", value: 24 },
  { name: "Bottoms", value: 20 },
  { name: "Dresses", value: 15 },
  { name: "Accessories", value: 9 },
];
const SCATTER_DATA = [
  { x: 12, y: 42, z: 8 }, { x: 18, y: 58, z: 12 }, { x: 25, y: 35, z: 6 },
  { x: 32, y: 72, z: 15 }, { x: 40, y: 48, z: 10 }, { x: 15, y: 65, z: 18 },
  { x: 28, y: 30, z: 7 }, { x: 45, y: 80, z: 20 }, { x: 20, y: 55, z: 9 },
  { x: 35, y: 62, z: 14 }, { x: 50, y: 40, z: 11 }, { x: 22, y: 78, z: 16 },
];
const HEATMAP_DATA = (() => {
  const days = ["Mon","Tue","Wed","Thu","Fri","Sat","Sun"];
  const hours = ["8a","10a","12p","2p","4p","6p","8p"];
  return days.map(d => hours.map(h => ({ day: d, hour: h, val: Math.round(20 + Math.random() * 80) })));
})();

function lumV(r, g, b) { return (0.299 * r + 0.587 * g + 0.114 * b) / 255; }
function hRgb(h) { return { r: parseInt(h.slice(1,3),16), g: parseInt(h.slice(3,5),16), b: parseInt(h.slice(5,7),16) }; }
function textOn(hex) { const c = hRgb(hex); return lumV(c.r,c.g,c.b) > 0.48 ? "#2a2520" : "#f5f3f0"; }
function blend(h1, h2, t) {
  const a = hRgb(h1), b = hRgb(h2);
  const r = v => v.toString(16).padStart(2,"0");
  return "#"+r(Math.round(a.r+(b.r-a.r)*t))+r(Math.round(a.g+(b.g-a.g)*t))+r(Math.round(a.b+(b.b-a.b)*t));
}
function toHex(r,g,b){return"#"+[r,g,b].map(x=>x.toString(16).padStart(2,"0")).join("");}
function dst(a,b){return Math.sqrt((a[0]-b[0])**2+(a[1]-b[1])**2+(a[2]-b[2])**2);}
function namify(r,g,b){
  const h=Math.max(r,g,b),l=Math.min(r,g,b),lum=Math.round((h+l)/2*100/255);
  const sat=h===l?0:Math.round((h-l)*100/(255-Math.abs(2*lum*255/100-255)));
  const hue=h===l?0:h===r?((g-b)/(h-l)+6)%6*60:h===g?(b-r)/(h-l)*60+120:(r-g)/(h-l)*60+240;
  const t=["Onyx","Ebony","Charcoal","Graphite","Pebble","Flint","Pewter","Silver","Bone","Pearl"];
  if(sat<18)return t[Math.min(9,Math.floor(lum/10))];
  const hu=[[0,30,"Rust"],[30,50,"Amber"],[50,70,"Ochre"],[70,100,"Moss"],[100,150,"Fern"],[150,195,"Sage"],[195,230,"Slate"],[230,260,"Indigo"],[260,290,"Plum"],[290,330,"Mauve"],[330,360,"Blush"]];
  for(const[a,z,n]of hu)if(hue>=a&&hue<z)return n;
  return "Dusk";
}
function initC(px,k){
  const r=[[...px[Math.floor(Math.random()*px.length)]]];
  while(r.length<k){let best=null,bm=0;for(let t=0;t<50;t++){const c=px[Math.floor(Math.random()*px.length)];let md=Infinity;r.forEach(e=>{md=Math.min(md,dst(c,e));});if(md>bm){bm=md;best=c;}}r.push([...best||px[Math.floor(Math.random()*px.length)]]);}
  return r;
}
function kmeans(data,W,H){
  const px=[];
  for(let y=0;y<H;y+=4)for(let x=0;x<W;x+=4){const i=(y*W+x)*4;if(i<data.length)px.push([data[i],data[i+1],data[i+2]]);}
  if(!px.length)return[];
  let cents=initC(px,5),asgn=new Array(px.length);
  for(let it=0;it<15;it++){
    const cl=Array(5).fill().map(()=>[]);
    px.forEach((p,pi)=>{let md=Infinity,mc=0;cents.forEach((c,ci)=>{const d=dst(p,c);if(d<md){md=d;mc=ci;}});cl[mc].push(p);asgn[pi]=mc;});
    cents=cl.map(c=>{if(!c.length)return[...px[Math.floor(Math.random()*px.length)]];const s=c.reduce((a,p)=>[a[0]+p[0],a[1]+p[1],a[2]+p[2]],[0,0,0]);return[Math.round(s[0]/c.length),Math.round(s[1]/c.length),Math.round(s[2]/c.length)];});
  }
  return cents.slice(0,5).map(rgb=>({r:rgb[0],g:rgb[1],b:rgb[2],hex:toHex(rgb[0],rgb[1],rgb[2]),name:namify(rgb[0],rgb[1],rgb[2])}));
}

const CHART_TYPES = ["Bar","Stacked bar","Line","Area","Pie / donut","Scatter","Heatmap"];

const CustomTooltip = ({ active, payload, label, bg, border, textPrimary, textSecondary }) => {
  if (!active || !payload?.length) return null;
  return (
    <div style={{ background: bg, border: `1px solid ${border}`, padding: "10px 14px", fontFamily: "Helvetica Neue, Arial, sans-serif" }}>
      {label && <div style={{ fontSize: 9, letterSpacing: "0.12em", textTransform: "uppercase", color: textSecondary, marginBottom: 6 }}>{label}</div>}
      {payload.map((p, i) => (
        <div key={i} style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 3 }}>
          <div style={{ width: 8, height: 8, background: p.color || p.fill }} />
          <span style={{ fontSize: 11, color: textSecondary }}>{p.name}</span>
          <span style={{ fontSize: 12, fontFamily: "Courier New, monospace", color: textPrimary, marginLeft: "auto", paddingLeft: 12 }}>{p.value}</span>
        </div>
      ))}
    </div>
  );
};

export default function App() {
  const [palette, setPalette] = useState(FALLBACK);
  const [chartType, setChartType] = useState(0);
  const [darkMode, setDarkMode] = useState(false);
  const [showGrid, setShowGrid] = useState(true);
  const [chartTitle, setChartTitle] = useState("Seasonal Performance");
  const [chartSubtitle, setChartSubtitle] = useState("Units by category — SS 2026");
  const fileRef = useRef();
  const offRef = useRef();

  const p = palette;
  const bg = darkMode ? blend(p[p.length-1].hex, "#000000", 0.6) : "#faf9f7";
  const surface = darkMode ? blend(p[p.length-1].hex, "#000000", 0.45) : "#ffffff";
  const gridColor = darkMode ? "rgba(255,255,255,0.07)" : "#e8e3dc";
  const axisColor = darkMode ? "rgba(255,255,255,0.3)" : "#a09a92";
  const textPrimary = darkMode ? "#f5f3f0" : "#2a2520";
  const textSecondary = darkMode ? "rgba(255,255,255,0.5)" : "#a09a92";
  const border = darkMode ? "rgba(255,255,255,0.1)" : "#e0dbd4";

  const handleFile = useCallback((e) => {
    const f = e.target.files[0]; if (!f) return;
    const reader = new FileReader();
    reader.onload = ev => {
      const img = new Image();
      img.onload = () => {
        const cv = offRef.current;
        cv.width = img.width; cv.height = img.height;
        const cx = cv.getContext("2d");
        cx.fillStyle = "#fff"; cx.fillRect(0,0,img.width,img.height);
        cx.drawImage(img,0,0);
        const data = cx.getImageData(0,0,img.width,img.height).data;
        const extracted = kmeans(data, img.width, img.height);
        if (extracted.length) setPalette(extracted);
      };
      img.src = ev.target.result;
    };
    reader.readAsDataURL(f);
    e.target.value = "";
  }, []);

  const axisProps = { tick: { fill: axisColor, fontSize: 10, fontFamily: "Courier New, monospace" }, axisLine: { stroke: border }, tickLine: false };
  const tooltipProps = { content: <CustomTooltip bg={surface} border={border} textPrimary={textPrimary} textSecondary={textSecondary} /> };
  const gridProps = showGrid ? { stroke: gridColor, strokeDasharray: "3 3" } : false;

  function renderChart() {
    const h = 280;
    switch(chartType) {
      case 0: return (
        <ResponsiveContainer width="100%" height={h}>
          <BarChart data={BAR_DATA} barGap={2} barCategoryGap="28%">
            {showGrid && <CartesianGrid {...(gridProps||{})} vertical={false} />}
            <XAxis dataKey="label" {...axisProps} />
            <YAxis {...axisProps} />
            <Tooltip {...tooltipProps} />
            <Legend wrapperStyle={{ fontSize: 9, letterSpacing: "0.1em", textTransform: "uppercase", color: textSecondary, fontFamily: "Helvetica Neue, Arial" }} />
            <Bar dataKey="A" name={p[0].name} fill={p[0].hex} radius={[2,2,0,0]} />
            <Bar dataKey="B" name={p[1].name} fill={p[1].hex} radius={[2,2,0,0]} />
            <Bar dataKey="C" name={p[2].name} fill={p[2].hex} radius={[2,2,0,0]} />
          </BarChart>
        </ResponsiveContainer>
      );
      case 1: return (
        <ResponsiveContainer width="100%" height={h}>
          <BarChart data={BAR_DATA} barCategoryGap="28%">
            {showGrid && <CartesianGrid {...(gridProps||{})} vertical={false} />}
            <XAxis dataKey="label" {...axisProps} />
            <YAxis {...axisProps} />
            <Tooltip {...tooltipProps} />
            <Legend wrapperStyle={{ fontSize: 9, letterSpacing: "0.1em", textTransform: "uppercase", color: textSecondary, fontFamily: "Helvetica Neue, Arial" }} />
            <Bar dataKey="A" name={p[0].name} fill={p[0].hex} stackId="a" />
            <Bar dataKey="B" name={p[1].name} fill={p[1].hex} stackId="a" />
            <Bar dataKey="C" name={p[2].name} fill={p[2].hex} stackId="a" radius={[2,2,0,0]} />
          </BarChart>
        </ResponsiveContainer>
      );
      case 2: return (
        <ResponsiveContainer width="100%" height={h}>
          <LineChart data={LINE_DATA}>
            {showGrid && <CartesianGrid {...(gridProps||{})} />}
            <XAxis dataKey="label" {...axisProps} />
            <YAxis {...axisProps} />
            <Tooltip {...tooltipProps} />
            <Legend wrapperStyle={{ fontSize: 9, letterSpacing: "0.1em", textTransform: "uppercase", color: textSecondary, fontFamily: "Helvetica Neue, Arial" }} />
            <Line type="monotone" dataKey="A" name={p[0].name} stroke={p[0].hex} strokeWidth={2} dot={{ r: 3, fill: p[0].hex, strokeWidth: 0 }} activeDot={{ r: 5 }} />
            <Line type="monotone" dataKey="B" name={p[1].name} stroke={p[1].hex} strokeWidth={2} dot={{ r: 3, fill: p[1].hex, strokeWidth: 0 }} activeDot={{ r: 5 }} />
            <Line type="monotone" dataKey="C" name={p[2].name} stroke={p[2].hex} strokeWidth={2} dot={{ r: 3, fill: p[2].hex, strokeWidth: 0 }} activeDot={{ r: 5 }} />
          </LineChart>
        </ResponsiveContainer>
      );
      case 3: return (
        <ResponsiveContainer width="100%" height={h}>
          <AreaChart data={LINE_DATA}>
            {showGrid && <CartesianGrid {...(gridProps||{})} />}
            <XAxis dataKey="label" {...axisProps} />
            <YAxis {...axisProps} />
            <Tooltip {...tooltipProps} />
            <Legend wrapperStyle={{ fontSize: 9, letterSpacing: "0.1em", textTransform: "uppercase", color: textSecondary, fontFamily: "Helvetica Neue, Arial" }} />
            <defs>
              {p.slice(0,3).map((c,i) => (
                <linearGradient key={i} id={`ag${i}`} x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor={c.hex} stopOpacity={0.35} />
                  <stop offset="95%" stopColor={c.hex} stopOpacity={0.03} />
                </linearGradient>
              ))}
            </defs>
            <Area type="monotone" dataKey="C" name={p[2].name} stroke={p[2].hex} strokeWidth={1.5} fill={`url(#ag2)`} />
            <Area type="monotone" dataKey="B" name={p[1].name} stroke={p[1].hex} strokeWidth={1.5} fill={`url(#ag1)`} />
            <Area type="monotone" dataKey="A" name={p[0].name} stroke={p[0].hex} strokeWidth={1.5} fill={`url(#ag0)`} />
          </AreaChart>
        </ResponsiveContainer>
      );
      case 4: return (
        <div style={{ display: "flex", gap: 24, alignItems: "center" }}>
          <ResponsiveContainer width="55%" height={h}>
            <PieChart>
              <Pie data={PIE_DATA} cx="50%" cy="50%" innerRadius="52%" outerRadius="78%" paddingAngle={2} dataKey="value">
                {PIE_DATA.map((_, i) => <Cell key={i} fill={p[i % p.length].hex} stroke="none" />)}
              </Pie>
              <Tooltip content={<CustomTooltip bg={surface} border={border} textPrimary={textPrimary} textSecondary={textSecondary} />} />
            </PieChart>
          </ResponsiveContainer>
          <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 10 }}>
            {PIE_DATA.map((d, i) => (
              <div key={i} style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <div style={{ width: 10, height: 10, background: p[i%p.length].hex, flexShrink: 0 }} />
                <span style={{ fontSize: 11, color: textSecondary, flex: 1, letterSpacing: "0.04em" }}>{d.name}</span>
                <span style={{ fontSize: 12, fontFamily: "Courier New, monospace", color: textPrimary }}>{d.value}%</span>
              </div>
            ))}
          </div>
        </div>
      );
      case 5: return (
        <ResponsiveContainer width="100%" height={h}>
          <ScatterChart>
            {showGrid && <CartesianGrid {...(gridProps||{})} />}
            <XAxis type="number" dataKey="x" name="Price" {...axisProps} />
            <YAxis type="number" dataKey="y" name="Units" {...axisProps} />
            <Tooltip cursor={{ stroke: border }} content={<CustomTooltip bg={surface} border={border} textPrimary={textPrimary} textSecondary={textSecondary} />} />
            <Scatter name="Products" data={SCATTER_DATA} fill={p[0].hex}>
              {SCATTER_DATA.map((d, i) => (
                <Cell key={i} fill={p[i % p.length].hex} fillOpacity={0.8} />
              ))}
            </Scatter>
          </ScatterChart>
        </ResponsiveContainer>
      );
      case 6: {
        const days = ["Mon","Tue","Wed","Thu","Fri","Sat","Sun"];
        const hours = ["8a","10a","12p","2p","4p","6p","8p"];
        const cellW = 100 / hours.length;
        const baseHex = p[0].hex;
        const accentHex = p[2]?.hex || p[1].hex;
        return (
          <div style={{ overflowX: "auto" }}>
            <div style={{ minWidth: 460 }}>
              <div style={{ display: "flex", marginBottom: 4, paddingLeft: 36 }}>
                {hours.map(h => (
                  <div key={h} style={{ flex: 1, textAlign: "center", fontSize: 9, letterSpacing: "0.1em", textTransform: "uppercase", color: textSecondary, fontFamily: "Courier New, monospace" }}>{h}</div>
                ))}
              </div>
              {HEATMAP_DATA.map((row, di) => (
                <div key={di} style={{ display: "flex", alignItems: "center", marginBottom: 3 }}>
                  <div style={{ width: 32, fontSize: 9, letterSpacing: "0.1em", textTransform: "uppercase", color: textSecondary, fontFamily: "Courier New, monospace", flexShrink: 0 }}>{days[di]}</div>
                  {row.map((cell, hi) => {
                    const t = cell.val / 100;
                    const cellColor = blend(baseHex, accentHex, t);
                    return (
                      <div key={hi} style={{ flex: 1, height: 28, background: cellColor, margin: "0 1px", display: "flex", alignItems: "center", justifyContent: "center", cursor: "default" }} title={`${cell.val}`}>
                        <span style={{ fontSize: 8, color: textOn(cellColor), opacity: 0.7, fontFamily: "Courier New, monospace" }}>{cell.val}</span>
                      </div>
                    );
                  })}
                </div>
              ))}
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 12, paddingLeft: 36 }}>
                <span style={{ fontSize: 9, color: textSecondary }}>Low</span>
                <div style={{ display: "flex", flex: 1, maxWidth: 160, height: 8 }}>
                  {Array.from({length: 20}, (_,i) => (
                    <div key={i} style={{ flex: 1, background: blend(baseHex, accentHex, i/19) }} />
                  ))}
                </div>
                <span style={{ fontSize: 9, color: textSecondary }}>High</span>
              </div>
            </div>
          </div>
        );
      }
      default: return null;
    }
  }

  return (
    <div style={{ fontFamily: "Helvetica Neue, Arial, sans-serif", background: "#f5f3f0", minHeight: "100vh", padding: 20, display: "flex", flexDirection: "column", gap: 12, alignItems: "center" }}>
      <canvas ref={offRef} style={{ display: "none" }} />
      <div style={{ width: "100%", maxWidth: 860, display: "flex", flexDirection: "column", gap: 10 }}>

        {/* TOOLBAR */}
        <div style={{ background: "#faf9f7", border: "1px solid #e0dbd4", padding: "11px 16px", display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
          <span style={{ fontSize: 8, letterSpacing: "0.2em", textTransform: "uppercase", color: "#a09a92" }}>Chart Theme</span>
          <div style={{ width: 1, height: 18, background: "#e0dbd4" }} />
          <span style={{ fontSize: 9, letterSpacing: "0.1em", textTransform: "uppercase", color: "#a09a92" }}>Title</span>
          <input value={chartTitle} onChange={e=>setChartTitle(e.target.value)} style={{ background: "#fff", border: "1px solid #e0dbd4", padding: "5px 9px", fontSize: 11, color: "#2a2520", fontFamily: "inherit", width: 200 }} />
          <span style={{ fontSize: 9, letterSpacing: "0.1em", textTransform: "uppercase", color: "#a09a92" }}>Subtitle</span>
          <input value={chartSubtitle} onChange={e=>setChartSubtitle(e.target.value)} style={{ background: "#fff", border: "1px solid #e0dbd4", padding: "5px 9px", fontSize: 11, color: "#2a2520", fontFamily: "inherit", width: 200 }} />
          <div style={{ flex: 1 }} />
          <label style={{ background: "transparent", border: "1px solid #2a2520", color: "#2a2520", padding: "6px 13px", fontSize: 9, letterSpacing: "0.1em", textTransform: "uppercase", cursor: "pointer", fontFamily: "inherit", position: "relative" }}>
            Import palette
            <input ref={fileRef} type="file" accept="image/*" onChange={handleFile} style={{ position: "absolute", inset: 0, opacity: 0, cursor: "pointer", width: "100%" }} />
          </label>
        </div>

        {/* CONTROLS */}
        <div style={{ background: "#faf9f7", border: "1px solid #e0dbd4", padding: "10px 16px", display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
          <span style={{ fontSize: 8, letterSpacing: "0.18em", textTransform: "uppercase", color: "#a09a92" }}>Chart type</span>
          <div style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
            {CHART_TYPES.map((ct, i) => (
              <button key={i} onClick={() => setChartType(i)} style={{ background: chartType===i ? "#2a2520" : "transparent", color: chartType===i ? "#f5f3f0" : "#2a2520", border: `1px solid ${chartType===i ? "#2a2520" : "#e0dbd4"}`, padding: "5px 11px", fontSize: 9, letterSpacing: "0.08em", textTransform: "uppercase", cursor: "pointer", fontFamily: "inherit", transition: "all 0.15s" }}>
                {ct}
              </button>
            ))}
          </div>
          <div style={{ width: 1, height: 18, background: "#e0dbd4" }} />
          <button onClick={() => setDarkMode(d => !d)} style={{ background: darkMode ? "#2a2520" : "transparent", color: darkMode ? "#f5f3f0" : "#2a2520", border: "1px solid #2a2520", padding: "5px 11px", fontSize: 9, letterSpacing: "0.08em", textTransform: "uppercase", cursor: "pointer", fontFamily: "inherit" }}>
            {darkMode ? "Dark" : "Light"}
          </button>
          <button onClick={() => setShowGrid(g => !g)} style={{ background: "transparent", color: "#2a2520", border: `1px solid ${showGrid ? "#2a2520" : "#e0dbd4"}`, padding: "5px 11px", fontSize: 9, letterSpacing: "0.08em", textTransform: "uppercase", cursor: "pointer", fontFamily: "inherit" }}>
            Grid {showGrid ? "on" : "off"}
          </button>
        </div>

        {/* CHART CARD */}
        <div style={{ background: bg, border: `1px solid ${border}`, padding: "28px 28px 20px", transition: "background 0.3s" }}>
          <div style={{ marginBottom: 20 }}>
            <div style={{ fontSize: 8, letterSpacing: "0.2em", textTransform: "uppercase", color: axisColor, marginBottom: 5 }}>
              {p[0].name.toUpperCase()} · {p[1]?.name.toUpperCase()} · {p[2]?.name.toUpperCase()}
            </div>
            <div style={{ fontSize: 17, fontWeight: 300, color: textPrimary, letterSpacing: "-0.01em" }}>{chartTitle}</div>
            <div style={{ fontSize: 11, color: axisColor, marginTop: 3, letterSpacing: "0.04em" }}>{chartSubtitle}</div>
          </div>
          {renderChart()}
          <div style={{ display: "flex", justifyContent: "space-between", marginTop: 16, paddingTop: 12, borderTop: `1px solid ${border}` }}>
            <span style={{ fontSize: 8, letterSpacing: "0.12em", textTransform: "uppercase", color: axisColor }}>Color Intelligence · Palette Theme</span>
            <span style={{ fontSize: 8, letterSpacing: "0.12em", textTransform: "uppercase", color: axisColor }}>{new Date().toLocaleDateString("en-US", { month: "long", year: "numeric" })}</span>
          </div>
        </div>

        {/* PALETTE + THEME TOKENS */}
        <div style={{ background: "#faf9f7", border: "1px solid #e0dbd4", padding: "14px 16px", display: "flex", gap: 16, alignItems: "flex-start", flexWrap: "wrap" }}>
          <div>
            <div style={{ fontSize: 8, letterSpacing: "0.2em", textTransform: "uppercase", color: "#a09a92", marginBottom: 10 }}>Active palette</div>
            <div style={{ display: "flex", gap: 8 }}>
              {p.map((c, i) => (
                <div key={i} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 4 }}>
                  <div style={{ width: 36, height: 36, background: c.hex, border: "1px solid rgba(0,0,0,0.07)" }} />
                  <span style={{ fontSize: 7, letterSpacing: "0.06em", textTransform: "uppercase", color: "#a09a92" }}>{c.name}</span>
                  <span style={{ fontSize: 7, fontFamily: "Courier New, monospace", color: "#c0b8b0" }}>{c.hex.toUpperCase()}</span>
                </div>
              ))}
            </div>
          </div>
          <div style={{ width: 1, background: "#e0dbd4", alignSelf: "stretch", margin: "0 4px" }} />
          <div style={{ flex: 1, minWidth: 280 }}>
            <div style={{ fontSize: 8, letterSpacing: "0.2em", textTransform: "uppercase", color: "#a09a92", marginBottom: 10 }}>Theme tokens</div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "6px 24px" }}>
              {[
                ["Background", bg],
                ["Grid", gridColor],
                ["Axis / label", axisColor],
                ["Series 1", p[0].hex],
                ["Series 2", p[1]?.hex],
                ["Series 3", p[2]?.hex],
                ["Border", border],
                ["Text primary", textPrimary],
              ].map(([label, val]) => (
                <div key={label} style={{ display: "flex", alignItems: "center", gap: 7 }}>
                  <div style={{ width: 10, height: 10, background: val, border: "1px solid rgba(0,0,0,0.08)", flexShrink: 0 }} />
                  <span style={{ fontSize: 9, color: "#a09a92", flex: 1 }}>{label}</span>
                  <span style={{ fontSize: 9, fontFamily: "Courier New, monospace", color: "#2a2520" }}>{val?.toUpperCase?.()}</span>
                </div>
              ))}
            </div>
          </div>
        </div>

      </div>
    </div>
  );
}

