const STATUS_COLOR = {
  "Done": "bg-emerald-100 text-emerald-700",
  "In Progress": "bg-blue-100 text-blue-700",
  "Not Started": "bg-gray-100 text-gray-500",
  "Planning": "bg-amber-100 text-amber-700",
  "Complete": "bg-emerald-100 text-emerald-700",
};
const STATUS_OPTIONS = ["Not Started", "In Progress", "Done", "Planning", "Complete"];

const pct = (a, b) => b === 0 ? 0 : Math.min(100, Math.round((a / b) * 100));

function BudgetBar({ spent, budget }) {
  const p = pct(spent, budget);
  const color = p > 90 ? "bg-red-500" : p > 70 ? "bg-amber-400" : "bg-emerald-500";
  return (
    <div className="w-full">
      <div className="flex justify-between text-xs text-gray-500 mb-1">
        <span>${spent.toLocaleString()} spent</span>
        <span>${budget.toLocaleString()} budget</span>
      </div>
      <div className="w-full bg-gray-100 rounded-full h-2">
        <div className={`${color} h-2 rounded-full transition-all`} style={{ width: `${p}%` }} />
      </div>
      <div className="text-xs text-gray-400 mt-1">{p}% utilized</div>
    </div>
  );
}

function InlineText({ value, onSave, className = "" }) {
  const [editing, setEditing] = useState(false);
  const [val, setVal] = useState(value);
  const commit = () => { onSave(val); setEditing(false); };
  const cancel = () => { setVal(value); setEditing(false); };
  if (editing) return (
    <span className="inline-flex items-center gap-1">
      <input autoFocus className="border-b border-blue-400 outline-none bg-transparent text-sm px-0.5 min-w-0 w-40"
        value={val} onChange={e => setVal(e.target.value)}
        onKeyDown={e => { if (e.key === "Enter") commit(); if (e.key === "Escape") cancel(); }} />
      <Check className="w-3.5 h-3.5 text-emerald-500 cursor-pointer shrink-0" onClick={commit} />
      <X className="w-3.5 h-3.5 text-gray-400 cursor-pointer shrink-0" onClick={cancel} />
    </span>
  );
  return (
    <span className={`group inline-flex items-center gap-1 cursor-pointer ${className}`} onClick={() => setEditing(true)}>
      {value}
      <Pencil className="w-3 h-3 text-gray-300 group-hover:text-gray-400 opacity-0 group-hover:opacity-100 transition-opacity shrink-0" />
    </span>
  );
}

function InlineNumber({ value, onSave, prefix = "" }) {
  const [editing, setEditing] = useState(false);
  const [val, setVal] = useState(value);
  const commit = () => { const n = parseFloat(val); if (!isNaN(n)) onSave(n); setEditing(false); };
  const cancel = () => { setVal(value); setEditing(false); };
  if (editing) return (
    <span className="inline-flex items-center gap-1">
      <input autoFocus className="border-b border-blue-400 outline-none bg-transparent w-24 text-sm"
        value={val} onChange={e => setVal(e.target.value)}
        onKeyDown={e => { if (e.key === "Enter") commit(); if (e.key === "Escape") cancel(); }} />
      <Check className="w-3.5 h-3.5 text-emerald-500 cursor-pointer" onClick={commit} />
      <X className="w-3.5 h-3.5 text-gray-400 cursor-pointer" onClick={cancel} />
    </span>
  );
  return (
    <span className="group inline-flex items-center gap-1 cursor-pointer" onClick={() => setEditing(true)}>
      {prefix}{value.toLocaleString()}
      <Pencil className="w-3 h-3 text-gray-300 group-hover:text-gray-400 opacity-0 group-hover:opacity-100 transition-opacity" />
    </span>
  );
}

function InlineSelect({ value, options, onSave }) {
  const [editing, setEditing] = useState(false);
  if (editing) return (
    <select autoFocus className="text-xs border border-gray-200 rounded px-1 py-0.5 bg-white"
      value={value}
      onChange={e => { onSave(e.target.value); setEditing(false); }}
      onBlur={() => setEditing(false)}>
      {options.map(o => <option key={o}>{o}</option>)}
    </select>
  );
  return (
    <span className={`px-2 py-0.5 rounded-full text-xs font-medium cursor-pointer ${STATUS_COLOR[value] || "bg-gray-100 text-gray-500"}`}
      onClick={() => setEditing(true)}>
      {value}
    </span>
  );
}

function NotesPanel({ value, onSave }) {
  const [editing, setEditing] = useState(false);
  const [val, setVal] = useState(value);
  return (
    <div className="bg-white rounded-xl border border-gray-200 p-5 shadow-sm mb-6">
