          ? <div className="flex gap-2">
              <button onClick={() => { onSave(val); setEditing(false); }} className="flex items-center gap-1 text-xs text-emerald-600 hover:text-emerald-700 font-medium"><Check className="w-3.5 h-3.5" /> Save</button>
              <button onClick={() => { setVal(value); setEditing(false); }} className="flex items-center gap-1 text-xs text-gray-400 hover:text-gray-600"><X className="w-3.5 h-3.5" /> Cancel</button>
            </div>
          : <button onClick={() => setEditing(true)} className="flex items-center gap-1 text-xs text-blue-500 hover:text-blue-700"><Pencil className="w-3.5 h-3.5" /> Edit</button>
        }
      </div>
      {editing
        ? <textarea autoFocus rows={4}
            className="w-full text-sm text-gray-700 border border-blue-200 rounded-lg p-3 outline-none resize-none focus:border-blue-400"
            value={val} onChange={e => setVal(e.target.value)} />
        : <p className="text-sm text-gray-600 leading-relaxed whitespace-pre-wrap min-h-12">{value || <span className="text-gray-300 italic">No notes yet — click Edit to add context, decisions, or vendor notes.</span>}</p>
      }
    </div>
  );
}

function DraggableTaskTable({ tasks, onUpdate, onDelete, onAdd, onReorder }) {
  const dragIdx = useRef(null);
  const [dragOver, setDragOver] = useState(null);

  const handleDragStart = (e, i) => {
    dragIdx.current = i;
    e.dataTransfer.effectAllowed = "move";
  };
  const handleDragOver = (e, i) => {
    e.preventDefault();
    setDragOver(i);
  };
  const handleDrop = (e, i) => {
    e.preventDefault();
    if (dragIdx.current !== null && dragIdx.current !== i) {
      const reordered = [...tasks];
      const [moved] = reordered.splice(dragIdx.current, 1);
      reordered.splice(i, 0, moved);
      onReorder(reordered);
    }
    dragIdx.current = null;
    setDragOver(null);
  };
  const handleDragEnd = () => { dragIdx.current = null; setDragOver(null); };

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-5 shadow-sm">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-sm font-semibold text-gray-700">Tasks <span className="text-xs text-gray-400 font-normal ml-1">drag to reorder</span></h2>
        <button onClick={onAdd} className="flex items-center gap-1 text-xs text-blue-500 hover:text-blue-700">
          <Plus className="w-3.5 h-3.5" /> Add task
        </button>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="text-left text-xs text-gray-400 border-b border-gray-100">
              <th className="pb-2 w-6" />
              <th className="pb-2 font-medium">Task</th>
              <th className="pb-2 font-medium">Owner</th>
              <th className="pb-2 font-medium">Due</th>
              <th className="pb-2 font-medium">Status</th>
              <th className="pb-2 w-6" />
            </tr>
          </thead>
          <tbody>
            {tasks.map((t, i) => (
              <tr key={t.id}
                draggable
                onDragStart={e => handleDragStart(e, i)}
                onDragOver={e => handleDragOver(e, i)}
                onDrop={e => handleDrop(e, i)}
                onDragEnd={handleDragEnd}
                className={`border-b border-gray-50 last:border-0 group transition-colors ${dragOver === i ? "bg-blue-50" : ""}`}>
                <td className="py-2.5 pr-1">
                  <GripVertical className="w-3.5 h-3.5 text-gray-300 cursor-grab active:cursor-grabbing group-hover:text-gray-400" />
                </td>
                <td className="py-2.5 text-gray-700">
                  <InlineText value={t.name} onSave={v => onUpdate(t.id, "name", v)} />
                </td>
                <td className="py-2.5 text-gray-500">
                  <InlineText value={t.owner} onSave={v => onUpdate(t.id, "owner", v)} />
                </td>
                <td className="py-2.5 text-gray-500">
                  <InlineText value={t.due} onSave={v => onUpdate(t.id, "due", v)} />
                </td>
                <td className="py-2.5">
                  <InlineSelect value={t.status} options={STATUS_OPTIONS} onSave={v => onUpdate(t.id, "status", v)} />
                </td>
                <td className="py-2.5 text-right">
                  <button onClick={() => onDelete(t.id)} className="opacity-0 group-hover:opacity-100 transition-opacity">
                    <Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function exportCSV(proj) {
  const rows = [
    ["Project", proj.name],
    ["Client", proj.client],
    ["Status", proj.status],
    ["Budget", proj.budget],
    ["Spent", proj.spent],
    ["Remaining", proj.budget - proj.spent],
    ["Notes", `"${(proj.notes || "").replace(/"/g, '""')}"`],
    [],
    ["TASKS"],
    ["Task", "Owner", "Due", "Status"],
    ...proj.tasks.map(t => [t.name, t.owner, t.due, t.status]),
    [],
    ["MILESTONES"],
    ["Milestone", "Date", "Done"],
    ...proj.milestones.map(m => [m.name, m.date, m.done ? "Yes" : "No"]),
    [],
    ["BUDGET HISTORY"],
    ["Month", "Planned", "Actual"],
    ...proj.budgetHistory.map(b => [b.month, b.planned, b.actual]),
  ];
  const csv = rows.map(r => r.join(",")).join("\n");
  const blob = new Blob([csv], { type: "text/csv" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `${proj.name.replace(/\s+/g, "_")}_export.csv`;
  a.click();
  URL.revokeObjectURL(url);
}

export default function Dashboard() {
  const [projects, setProjects] = useState(INITIAL_PROJECTS);
  const [activeId, setActiveId] = useState(1);

  const proj = projects.find(p => p.id === activeId);

  const updateProj = (field, value) =>
    setProjects(ps => ps.map(p => p.id === activeId ? { ...p, [field]: value } : p));

  const updateTask = (tid, field, value) =>
    updateProj("tasks", proj.tasks.map(t => t.id === tid ? { ...t, [field]: value } : t));
  const addTask = () =>
    updateProj("tasks", [...proj.tasks, { id: Date.now(), name: "New task", status: "Not Started", owner: "Addie", due: "2026-07-01" }]);
  const deleteTask = (tid) =>
    updateProj("tasks", proj.tasks.filter(t => t.id !== tid));
  const reorderTasks = (reordered) => updateProj("tasks", reordered);

  const toggleMilestone = (i) =>
    updateProj("milestones", proj.milestones.map((m, idx) => idx === i ? { ...m, done: !m.done } : m));
  const updateMilestone = (i, field, value) =>
    updateProj("milestones", proj.milestones.map((m, idx) => idx === i ? { ...m, [field]: value } : m));
  const addMilestone = () =>
    updateProj("milestones", [...proj.milestones, { name: "New milestone", date: "2026-08-01", done: false }]);
  const deleteMilestone = (i) =>
    updateProj("milestones", proj.milestones.filter((_, idx) => idx !== i));

  const milestonesDone = proj.milestones.filter(m => m.done).length;
  const milestonePct = pct(milestonesDone, proj.milestones.length);
  const budgetPct = pct(proj.spent, proj.budget);
  const remaining = proj.budget - proj.spent;

  return (
    <div className="min-h-screen bg-gray-50 p-6 font-sans">
      <div className="mb-5 flex items-start justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">SX Collective — Project Dashboard</h1>
          <p className="text-xs text-gray-400 mt-0.5">Click any value to edit · drag rows to reorder · Addie</p>
        </div>
        <button onClick={() => exportCSV(proj)}
          className="flex items-center gap-2 px-4 py-2 bg-gray-800 hover:bg-gray-700 text-white text-sm rounded-lg shadow-sm transition-colors">
          <Download className="w-4 h-4" />
          Export CSV
        </button>
      </div>

      {/* Project Tabs */}
      <div className="flex gap-2 mb-6 flex-wrap">
        {projects.map(p => (
          <button key={p.id} onClick={() => setActiveId(p.id)}
            className={`px-4 py-2 rounded-lg text-sm font-medium border transition-all ${
              activeId === p.id ? "bg-gray-800 text-white border-gray-800" : "bg-white text-gray-600 border-gray-200 hover:border-gray-400"
            }`}>
            <InlineText
              value={p.name}
              onSave={v => setProjects(ps => ps.map(x => x.id === p.id ? { ...x, name: v } : x))}
              className={activeId === p.id ? "text-white" : "text-gray-700"}
            />
            <span className={`ml-2 px-1.5 py-0.5 rounded text-xs ${STATUS_COLOR[p.status] || "bg-gray-100 text-gray-500"}`}>{p.status}</span>
          </button>
        ))}
      </div>

      {/* KPI Row */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
        {[
          { label: "Budget Remaining", value: <InlineNumber value={remaining} prefix="$" onSave={v => updateProj("spent", proj.budget - v)} />, sub: `${100 - budgetPct}% left`, icon: <DollarSign className="w-5 h-5 text-emerald-500" />, hi: budgetPct > 90 ? "border-red-300" : "" },
          { label: "Budget Used", value: <InlineNumber value={proj.spent} prefix="$" onSave={v => updateProj("spent", v)} />, sub: <>of <InlineNumber value={proj.budget} prefix="$" onSave={v => updateProj("budget", v)} /></>, icon: <TrendingUp className="w-5 h-5 text-blue-500" /> },
          { label: "Milestones", value: `${milestonesDone} / ${proj.milestones.length}`, sub: `${milestonePct}% complete`, icon: <CheckCircle className="w-5 h-5 text-purple-500" /> },
          { label: "Open Tasks", value: proj.tasks.filter(t => t.status !== "Done" && t.status !== "Complete").length, sub: `${proj.tasks.length} total`, icon: <Clock className="w-5 h-5 text-amber-500" /> },
        ].map((k, i) => (
          <div key={i} className={`bg-white rounded-xl border ${k.hi || "border-gray-200"} p-4 shadow-sm`}>
            <div className="flex items-center justify-between mb-2">
              <span className="text-xs text-gray-500 font-medium">{k.label}</span>
              {k.icon}
            </div>
            <div className="text-2xl font-bold text-gray-800">{k.value}</div>
            <div className="text-xs text-gray-400 mt-0.5">{k.sub}</div>
          </div>
        ))}
      </div>

      {/* Budget Chart + Milestones */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        <div className="bg-white rounded-xl border border-gray-200 p-5 shadow-sm">
          <h2 className="text-sm font-semibold text-gray-700 mb-1">Budget: Planned vs. Actual</h2>
          <p className="text-xs text-gray-400 mb-4">Monthly spend</p>
          <ResponsiveContainer width="100%" height={200}>
            <BarChart data={proj.budgetHistory} barCategoryGap="30%">
              <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
              <XAxis dataKey="month" tick={{ fontSize: 11 }} />
              <YAxis tick={{ fontSize: 11 }} tickFormatter={v => `$${(v / 1000).toFixed(0)}k`} />
              <Tooltip formatter={v => `$${v.toLocaleString()}`} />
              <Legend wrapperStyle={{ fontSize: 11 }} />
              <Bar dataKey="planned" name="Planned" fill="#e5e7eb" radius={[4, 4, 0, 0]} />
              <Bar dataKey="actual" name="Actual" fill="#3b82f6" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
          <div className="mt-4">
            <BudgetBar spent={proj.spent} budget={proj.budget} />
          </div>
        </div>

        <div className="bg-white rounded-xl border border-gray-200 p-5 shadow-sm">
          <div className="flex items-center justify-between mb-1">
            <h2 className="text-sm font-semibold text-gray-700">Milestones</h2>
            <button onClick={addMilestone} className="flex items-center gap-1 text-xs text-blue-500 hover:text-blue-700">
              <Plus className="w-3.5 h-3.5" /> Add
            </button>
          </div>
          <p className="text-xs text-gray-400 mb-3">{milestonePct}% complete · {proj.milestones.length - milestonesDone} remaining</p>
          <div className="w-full bg-gray-100 rounded-full h-1.5 mb-4">
            <div className="bg-purple-500 h-1.5 rounded-full transition-all" style={{ width: `${milestonePct}%` }} />
          </div>
          <div className="space-y-2 max-h-52 overflow-y-auto pr-1">
            {proj.milestones.map((m, i) => (
              <div key={i} className="flex items-start gap-2 group">
                <button onClick={() => toggleMilestone(i)} className="mt-0.5 shrink-0">
                  {m.done ? <CheckCircle className="w-4 h-4 text-emerald-500" /> : <Circle className="w-4 h-4 text-gray-300 hover:text-gray-400" />}
                </button>
                <div className="flex-1 min-w-0">
                  <InlineText value={m.name} onSave={v => updateMilestone(i, "name", v)}
                    className={`text-sm ${m.done ? "line-through text-gray-400" : "text-gray-700"}`} />
                  <p className="text-xs text-gray-400">
                    <InlineText value={m.date} onSave={v => updateMilestone(i, "date", v)} className="text-gray-400" />
                  </p>
                </div>
                <button onClick={() => deleteMilestone(i)} className="opacity-0 group-hover:opacity-100 transition-opacity">
                  <Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" />
                </button>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Notes */}
      <NotesPanel value={proj.notes || ""} onSave={v => updateProj("notes", v)} />

      {/* Tasks */}
      <DraggableTaskTable
        tasks={proj.tasks}
        onUpdate={updateTask}
        onDelete={deleteTask}
        onAdd={addTask}
        onReorder={reorderTasks}
      />
    </div>
  );
}

