      <div className="space-y-2">
        {Object.entries(PANEL_LABELS).map(([key, label]) => (
          <label key={key} className="flex items-center gap-2 cursor-pointer">
            <input type="checkbox" checked={panels[key]} onChange={e => onChange(key, e.target.checked)} className="rounded" />
            <span className="text-sm text-gray-700">{label}</span>
            {panels[key] ? <Eye className="w-3.5 h-3.5 text-gray-300 ml-auto" /> : <EyeOff className="w-3.5 h-3.5 text-gray-300 ml-auto" />}
          </label>
        ))}
      </div>
      <button onClick={() => setOpen(false)} className="mt-3 w-full text-xs text-gray-400 hover:text-gray-600 text-center">Done</button>
    </div>}
  </div>;
}

// ── DRAG TABLE ─────────────────────────────────────────────────────────────────
function DragTable({ tasks, onUpdate, onDelete, onAdd, onReorder }) {
  const dragIdx = useRef(null);
  const [dragOver, setDragOver] = useState(null);
  const start = (e, i) => { dragIdx.current = i; e.dataTransfer.effectAllowed = "move"; };
  const over = (e, i) => { e.preventDefault(); setDragOver(i); };
  const drop = (e, i) => {
    e.preventDefault();
    if (dragIdx.current !== null && dragIdx.current !== i) {
      const r = [...tasks]; const [m] = r.splice(dragIdx.current, 1); r.splice(i, 0, m); onReorder(r);
    }
    dragIdx.current = null; setDragOver(null);
  };
  return <Card>
    <SectionHeader title={<>Tasks <span className="text-xs text-gray-400 font-normal ml-1">drag to reorder</span></>} onAdd={onAdd} addLabel="Add task" />
    <div className="overflow-x-auto">
      <table className="w-full text-sm">
        <thead><tr className="text-left text-xs text-gray-400 border-b border-gray-100">
          <th className="pb-2 w-5" /><th className="pb-2 font-medium">Task</th><th className="pb-2 font-medium">Owner</th>
          <th className="pb-2 font-medium">Due</th><th className="pb-2 font-medium">Status</th><th className="pb-2 w-5" />
        </tr></thead>
        <tbody>
          {tasks.map((t, i) => <tr key={t.id} draggable onDragStart={e => start(e, i)} onDragOver={e => over(e, i)}
            onDrop={e => drop(e, i)} onDragEnd={() => { dragIdx.current = null; setDragOver(null); }}
            className={`border-b border-gray-50 last:border-0 group transition-colors ${dragOver === i ? "bg-blue-50" : ""}`}>
            <td className="py-2"><GripVertical className="w-3.5 h-3.5 text-gray-300 cursor-grab group-hover:text-gray-400" /></td>
            <td className="py-2 text-gray-700"><InlineText value={t.name} onSave={v => onUpdate(t.id, "name", v)} wide /></td>
            <td className="py-2 text-gray-500"><InlineText value={t.owner} onSave={v => onUpdate(t.id, "owner", v)} /></td>
            <td className="py-2 text-gray-500"><InlineText value={t.due} onSave={v => onUpdate(t.id, "due", v)} /></td>
            <td className="py-2"><InlineSel value={t.status} options={STATUS_OPTIONS} onSave={v => onUpdate(t.id, "status", v)} /></td>
            <td className="py-2 text-right"><button onClick={() => onDelete(t.id)} className="opacity-0 group-hover:opacity-100">
              <Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button></td>
          </tr>)}
        </tbody>
      </table>
    </div>
  </Card>;
}

// ── CSV EXPORT ─────────────────────────────────────────────────────────────────
function exportCSV(p) {
  const q = s => `"${String(s || "").replace(/"/g, '""')}"`;
  const rows = [
    ["Project", p.name], ["Client", p.client], ["Status", p.status], ["RAG", p.rag],
    ["Budget", p.budget], ["Spent", p.spent], ["Remaining", p.budget - p.spent], [],
    ["EXEC SUMMARY"], [q(p.execSummary)], [],
    ["TASKS"], ["Task", "Owner", "Due", "Status"],
    ...p.tasks.map(t => [q(t.name), t.owner, t.due, t.status]), [],
    ["MILESTONES"], ["Milestone", "Date", "Done", "Variance (days)"],
    ...p.milestones.map(m => [q(m.name), m.date, m.done ? "Yes" : "No", m.variance || 0]), [],
    ["DELIVERABLES"], ["Deliverable", "Status", "Due"],
    ...p.deliverables.map(d => [q(d.name), d.status, d.due]), [],
    ["RISKS"], ["Flag", "Risk", "Owner", "Mitigation"],
    ...p.risks.map(r => [r.flag, q(r.item), r.owner, q(r.mitigation)]), [],
    ["DECISIONS"], ["Date", "Decision", "Made By"],
    ...p.decisions.map(d => [d.date, q(d.decision), d.madeBy]), [],
    ["OPEN ASKS"], ["Ask", "Asked Of", "Due By", "Done"],
    ...p.openAsks.map(a => [q(a.ask), a.askedOf, a.dueBy, a.done ? "Yes" : "No"]), [],
    ["MEETINGS"], ["Date", "Attendees", "Summary"],
    ...p.meetings.map(m => [m.date, q(m.attendees), q(m.summary)]),
  ];
  const csv = rows.map(r => r.join(",")).join("\n");
  const a = Object.assign(document.createElement("a"), { href: URL.createObjectURL(new Blob([csv], { type: "text/csv" })), download: `${p.name.replace(/\s+/g, "_")}.csv` });
  a.click();
}

// ── MAIN ───────────────────────────────────────────────────────────────────────
export default function Dashboard() {
  const [projects, setProjects] = useState(INITIAL_PROJECTS);
  const [activeId, setActiveId] = useState(1);
  const [panels, setPanels] = useState(DEFAULT_PANELS);

  const proj = projects.find(p => p.id === activeId);
  const up = (field, value) => setProjects(ps => ps.map(p => p.id === activeId ? { ...p, [field]: value } : p));

  const updTask = (tid, f, v) => up("tasks", proj.tasks.map(t => t.id === tid ? { ...t, [f]: v } : t));
  const updMile = (i, f, v) => up("milestones", proj.milestones.map((m, idx) => idx === i ? { ...m, [f]: v } : m));
  const updDeliv = (tid, f, v) => up("deliverables", proj.deliverables.map(d => d.id === tid ? { ...d, [f]: v } : d));
  const updRisk = (tid, f, v) => up("risks", proj.risks.map(r => r.id === tid ? { ...r, [f]: v } : r));
  const updDec = (tid, f, v) => up("decisions", proj.decisions.map(d => d.id === tid ? { ...d, [f]: v } : d));
  const updAsk = (tid, f, v) => up("openAsks", proj.openAsks.map(a => a.id === tid ? { ...a, [f]: v } : a));
  const updMeet = (tid, f, v) => up("meetings", proj.meetings.map(m => m.id === tid ? { ...m, [f]: v } : m));

  const milDone = proj.milestones.filter(m => m.done).length;
  const milPct = pct(milDone, proj.milestones.length);
  const budPct = pct(proj.spent, proj.budget);

  return (
    <div className="min-h-screen bg-gray-50 p-6 font-sans">
      {/* Header */}
      <div className="flex items-start justify-between flex-wrap gap-3 mb-5">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">SX Collective — Project Dashboard</h1>
          <p className="text-xs text-gray-400 mt-0.5">Click any value to edit inline · Addie</p>
        </div>
        <div className="flex gap-2">
          <PanelSettings panels={panels} onChange={(k, v) => setPanels(p => ({ ...p, [k]: v }))} />
          <button onClick={() => exportCSV(proj)} className="flex items-center gap-2 px-4 py-2 bg-gray-800 hover:bg-gray-700 text-white text-sm rounded-lg shadow-sm">
            <Download className="w-4 h-4" /> Export CSV
          </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex gap-2 mb-6 flex-wrap">
        {projects.map(p => (
          <button key={p.id} onClick={() => setActiveId(p.id)}
            className={`px-4 py-2 rounded-lg text-sm font-medium border transition-all flex items-center gap-2 ${activeId === p.id ? "bg-gray-800 text-white border-gray-800" : "bg-white text-gray-600 border-gray-200 hover:border-gray-400"}`}>
            <span className={`w-2.5 h-2.5 rounded-full shrink-0 ${RAG_COLOR[p.rag] || "bg-gray-300"}`} />
            <InlineText value={p.name} onSave={v => setProjects(ps => ps.map(x => x.id === p.id ? { ...x, name: v } : x))} className={activeId === p.id ? "text-white" : "text-gray-700"} />
          </button>
        ))}
      </div>

      {/* RAG + Exec Summary */}
      {panels.execSummary && <Card className="mb-6">
        <div className="flex items-start gap-4 flex-wrap">
          <div className="flex flex-col gap-1.5 shrink-0">
            <span className="text-xs text-gray-500 font-medium">RAG Status</span>
            <InlineSel value={proj.rag} options={["Green", "Amber", "Red"]} onSave={v => up("rag", v)}
              colorMap={{ Green: "text-emerald-700 bg-emerald-50 border-emerald-200", Amber: "text-amber-700 bg-amber-50 border-amber-200", Red: "text-red-700 bg-red-50 border-red-200" }} />
          </div>
          <div className="flex-1 min-w-0">
            <span className="text-xs text-gray-500 font-medium block mb-1">Executive Summary</span>
            <TextArea value={proj.execSummary} onSave={v => up("execSummary", v)} rows={2} />
          </div>
        </div>
      </Card>}

      {/* KPIs */}
      {panels.kpis && <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
        {[
          { label: "Budget Remaining", val: <InlineNum value={proj.budget - proj.spent} prefix="$" onSave={v => up("spent", proj.budget - v)} />, sub: `${100 - budPct}% left`, icon: <DollarSign className="w-5 h-5 text-emerald-500" />, hi: budPct > 90 },
          { label: "Budget Used", val: <InlineNum value={proj.spent} prefix="$" onSave={v => up("spent", v)} />, sub: <>of <InlineNum value={proj.budget} prefix="$" onSave={v => up("budget", v)} /></>, icon: <TrendingUp className="w-5 h-5 text-blue-500" /> },
          { label: "Milestones", val: `${milDone} / ${proj.milestones.length}`, sub: `${milPct}% complete`, icon: <CheckCircle className="w-5 h-5 text-purple-500" /> },
          { label: "Open Tasks", val: proj.tasks.filter(t => t.status !== "Done" && t.status !== "Complete").length, sub: `${proj.tasks.length} total`, icon: <Clock className="w-5 h-5 text-amber-500" /> },
        ].map((k, i) => <div key={i} className={`bg-white rounded-xl border ${k.hi ? "border-red-300" : "border-gray-200"} p-4 shadow-sm`}>
          <div className="flex items-center justify-between mb-2"><span className="text-xs text-gray-500 font-medium">{k.label}</span>{k.icon}</div>
          <div className="text-2xl font-bold text-gray-800">{k.val}</div>
          <div className="text-xs text-gray-400 mt-0.5">{k.sub}</div>
        </div>)}
      </div>}

      {/* Budget + Milestones */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        {panels.budget && <Card>
          <SectionHeader title="Budget: Planned vs. Actual" />
          <ResponsiveContainer width="100%" height={190}>
            <BarChart data={proj.budgetHistory} barCategoryGap="30%">
              <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
              <XAxis dataKey="month" tick={{ fontSize: 11 }} />
              <YAxis tick={{ fontSize: 11 }} tickFormatter={v => `$${(v / 1000).toFixed(0)}k`} />
              <Tooltip formatter={v => `$${v.toLocaleString()}`} />
              <Legend wrapperStyle={{ fontSize: 11 }} />
              <Bar dataKey="planned" name="Planned" fill="#e5e7eb" radius={[4, 4, 0, 0]} />
              <Bar dataKey="actual" name="Actual" fill="#3b82f6" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
          <div className="mt-4"><BudgetBar spent={proj.spent} budget={proj.budget} /></div>
        </Card>}

        {panels.milestones && <Card>
          <SectionHeader title="Milestones" onAdd={() => up("milestones", [...proj.milestones, { name: "New milestone", date: "2026-08-01", done: false, variance: 0 }])} />
          <p className="text-xs text-gray-400 mb-3">{milPct}% complete · {proj.milestones.length - milDone} remaining</p>
          <div className="w-full bg-gray-100 rounded-full h-1.5 mb-4">
            <div className="bg-purple-500 h-1.5 rounded-full" style={{ width: `${milPct}%` }} />
          </div>
          <div className="space-y-2 max-h-52 overflow-y-auto pr-1">
            {proj.milestones.map((m, i) => <div key={i} className="flex items-start gap-2 group">
              <button onClick={() => updMile(i, "done", !m.done)} className="mt-0.5 shrink-0">
                {m.done ? <CheckCircle className="w-4 h-4 text-emerald-500" /> : <Circle className="w-4 h-4 text-gray-300 hover:text-gray-400" />}
              </button>
              <div className="flex-1 min-w-0">
                <InlineText value={m.name} onSave={v => updMile(i, "name", v)} className={`text-sm ${m.done ? "line-through text-gray-400" : "text-gray-700"}`} wide />
                <div className="flex items-center gap-2">
                  <InlineText value={m.date} onSave={v => updMile(i, "date", v)} className="text-xs text-gray-400" />
                  {m.variance > 0 && <span className="text-xs text-amber-500">+{m.variance}d</span>}
                  {m.variance < 0 && <span className="text-xs text-emerald-500">{m.variance}d</span>}
                </div>
              </div>
              <button onClick={() => up("milestones", proj.milestones.filter((_, idx) => idx !== i))} className="opacity-0 group-hover:opacity-100">
                <Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" />
              </button>
            </div>)}
          </div>
        </Card>}
      </div>

      {/* Notes */}
      {panels.notes && <Card className="mb-6">
        <SectionHeader title={<><FileText className="w-4 h-4 text-gray-400 inline mr-1.5" />Project Notes</>} />
        <TextArea value={proj.notes} onSave={v => up("notes", v)} rows={3} />
      </Card>}

      {/* Deliverables + Risks */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        {panels.deliverables && <Card>
          <SectionHeader title="Deliverables" onAdd={() => up("deliverables", [...proj.deliverables, { id: Date.now(), name: "New deliverable", status: "Not Started", due: "2026-07-01" }])} />
          <table className="w-full text-sm">
            <thead><tr className="text-xs text-gray-400 border-b border-gray-100 text-left">
              <th className="pb-2 font-medium">Output</th><th className="pb-2 font-medium">Due</th><th className="pb-2 font-medium">Status</th><th className="pb-2 w-5" />
            </tr></thead>
            <tbody>{proj.deliverables.map(d => <tr key={d.id} className="border-b border-gray-50 last:border-0 group">
              <td className="py-2 text-gray-700"><InlineText value={d.name} onSave={v => updDeliv(d.id, "name", v)} wide /></td>
              <td className="py-2 text-gray-500"><InlineText value={d.due} onSave={v => updDeliv(d.id, "due", v)} /></td>
              <td className="py-2"><InlineSel value={d.status} options={STATUS_OPTIONS} onSave={v => updDeliv(d.id, "status", v)} /></td>
              <td className="py-2 text-right"><button onClick={() => up("deliverables", proj.deliverables.filter(x => x.id !== d.id))} className="opacity-0 group-hover:opacity-100">
                <Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button></td>
            </tr>)}</tbody>
          </table>
        </Card>}

        {panels.risks && <Card>
          <SectionHeader title="Risk Log" onAdd={() => up("risks", [...proj.risks, { id: Date.now(), flag: "Amber", item: "New risk", owner: "TBD", mitigation: "" }])} />
          <div className="space-y-3">
            {proj.risks.length === 0 && <p className="text-sm text-gray-300 italic">No risks logged.</p>}
            {proj.risks.map(r => <div key={r.id} className="flex gap-2 group">
              <InlineSel value={r.flag} options={["Green", "Amber", "Red"]} onSave={v => updRisk(r.id, "flag", v)}
                colorMap={{ Green: "text-emerald-700 bg-emerald-50 border-emerald-200", Amber: "text-amber-700 bg-amber-50 border-amber-200", Red: "text-red-700 bg-red-50 border-red-200" }} />
              <div className="flex-1 min-w-0">
                <InlineText value={r.item} onSave={v => updRisk(r.id, "item", v)} className="text-sm text-gray-700" wide />
                <div className="text-xs text-gray-400 mt-0.5">Owner: <InlineText value={r.owner} onSave={v => updRisk(r.id, "owner", v)} className="text-gray-400" /></div>
                <div className="text-xs text-gray-400">Mitigation: <InlineText value={r.mitigation} onSave={v => updRisk(r.id, "mitigation", v)} className="text-gray-400" wide /></div>
              </div>
              <button onClick={() => up("risks", proj.risks.filter(x => x.id !== r.id))} className="opacity-0 group-hover:opacity-100 shrink-0">
                <Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button>
            </div>)}
          </div>
        </Card>}
      </div>

      {/* Decisions + Open Asks */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        {panels.decisions && <Card>
          <SectionHeader title="Decision Log" onAdd={() => up("decisions", [...proj.decisions, { id: Date.now(), date: "2026-04-06", decision: "New decision", madeBy: "Addie" }])} />
          <div className="space-y-2">
            {proj.decisions.length === 0 && <p className="text-sm text-gray-300 italic">No decisions logged.</p>}
            {proj.decisions.map(d => <div key={d.id} className="flex gap-2 group border-b border-gray-50 pb-2 last:border-0">
              <div className="flex-1 min-w-0">
                <InlineText value={d.decision} onSave={v => updDec(d.id, "decision", v)} className="text-sm text-gray-700" wide />
                <div className="text-xs text-gray-400 mt-0.5">
                  <InlineText value={d.date} onSave={v => updDec(d.id, "date", v)} className="text-gray-400" /> · <InlineText value={d.madeBy} onSave={v => updDec(d.id, "madeBy", v)} className="text-gray-400" />
                </div>
              </div>
              <button onClick={() => up("decisions", proj.decisions.filter(x => x.id !== d.id))} className="opacity-0 group-hover:opacity-100 shrink-0">
                <Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button>
            </div>)}
          </div>
        </Card>}

        {panels.openAsks && <Card>
          <SectionHeader title="Open Asks from Client" onAdd={() => up("openAsks", [...proj.openAsks, { id: Date.now(), ask: "New ask", askedOf: "SX", dueBy: "2026-05-01", done: false }])} />
          <div className="space-y-2">
            {proj.openAsks.length === 0 && <p className="text-sm text-gray-300 italic">No open asks.</p>}
            {proj.openAsks.map(a => <div key={a.id} className="flex items-start gap-2 group border-b border-gray-50 pb-2 last:border-0">
              <button onClick={() => updAsk(a.id, "done", !a.done)} className="mt-0.5 shrink-0">
                {a.done ? <CheckCircle className="w-4 h-4 text-emerald-500" /> : <Circle className="w-4 h-4 text-gray-300 hover:text-gray-400" />}
              </button>
              <div className="flex-1 min-w-0">
                <InlineText value={a.ask} onSave={v => updAsk(a.id, "ask", v)} className={`text-sm ${a.done ? "line-through text-gray-400" : "text-gray-700"}`} wide />
                <div className="text-xs text-gray-400 mt-0.5">
                  Asked of: <InlineText value={a.askedOf} onSave={v => updAsk(a.id, "askedOf", v)} className="text-gray-400" /> · Due: <InlineText value={a.dueBy} onSave={v => updAsk(a.id, "dueBy", v)} className="text-gray-400" />
                </div>
              </div>
              <button onClick={() => up("openAsks", proj.openAsks.filter(x => x.id !== a.id))} className="opacity-0 group-hover:opacity-100 shrink-0">
                <Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button>
            </div>)}
          </div>
        </Card>}
      </div>

      {/* Meeting Log */}
      {panels.meetings && <Card className="mb-6">
        <SectionHeader title="Meeting Log" onAdd={() => up("meetings", [...proj.meetings, { id: Date.now(), date: "2026-04-06", attendees: "Addie, SX team", summary: "Add summary..." }])} />
        <table className="w-full text-sm">
          <thead><tr className="text-xs text-gray-400 border-b border-gray-100 text-left">
            <th className="pb-2 font-medium w-24">Date</th><th className="pb-2 font-medium w-40">Attendees</th><th className="pb-2 font-medium">Summary</th><th className="pb-2 w-5" />
          </tr></thead>
          <tbody>{proj.meetings.map(m => <tr key={m.id} className="border-b border-gray-50 last:border-0 group">
            <td className="py-2 text-gray-500 align-top"><InlineText value={m.date} onSave={v => updMeet(m.id, "date", v)} /></td>
            <td className="py-2 text-gray-500 align-top"><InlineText value={m.attendees} onSave={v => updMeet(m.id, "attendees", v)} wide /></td>
            <td className="py-2 text-gray-700 align-top"><InlineText value={m.summary} onSave={v => updMeet(m.id, "summary", v)} wide /></td>
            <td className="py-2 align-top text-right"><button onClick={() => up("meetings", proj.meetings.filter(x => x.id !== m.id))} className="opacity-0 group-hover:opacity-100">
              <Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button></td>
          </tr>)}</tbody>
        </table>
      </Card>}

      {/* Tasks */}
      {panels.tasks && <DragTable
        tasks={proj.tasks}
        onUpdate={updTask}
        onDelete={tid => up("tasks", proj.tasks.filter(t => t.id !== tid))}
        onAdd={() => up("tasks", [...proj.tasks, { id: Date.now(), name: "New task", status: "Not Started", owner: "Addie", due: "2026-07-01" }])}
        onReorder={r => up("tasks", r)}
      />}
    </div>
  );
}

