const pct = (a, b) => b === 0 ? 0 : Math.min(100, Math.round((a / b) * 100));

// ── INLINE EDITORS ─────────────────────────────────────────────────────────────
function IT({ value, onSave, className = "", wide = false }) {
  const [ed, setEd] = useState(false); const [v, setV] = useState(value);
  const commit = () => { onSave(v); setEd(false); };
  const cancel = () => { setV(value); setEd(false); };
  if (ed) return <span className="inline-flex items-center gap-1">
    <input autoFocus className={`border-b border-blue-400 outline-none bg-transparent text-sm px-0.5 ${wide ? "w-56" : "w-36"}`}
      value={v} onChange={e => setV(e.target.value)}
      onKeyDown={e => { if (e.key === "Enter") commit(); if (e.key === "Escape") cancel(); }} />
    <Check className="w-3.5 h-3.5 text-emerald-500 cursor-pointer shrink-0" onClick={commit} />
    <X className="w-3.5 h-3.5 text-gray-400 cursor-pointer shrink-0" onClick={cancel} />
  </span>;
  return <span className={`group inline-flex items-center gap-1 cursor-pointer ${className}`} onClick={() => setEd(true)}>
    {value}<Pencil className="w-3 h-3 text-gray-300 group-hover:text-gray-400 opacity-0 group-hover:opacity-100 shrink-0" />
  </span>;
}
function IN({ value, onSave, prefix = "" }) {
  const [ed, setEd] = useState(false); const [v, setV] = useState(value);
  const commit = () => { const n = parseFloat(v); if (!isNaN(n)) onSave(n); setEd(false); };
  const cancel = () => { setV(value); setEd(false); };
  if (ed) return <span className="inline-flex items-center gap-1">
    <input autoFocus className="border-b border-blue-400 outline-none bg-transparent w-24 text-sm"
      value={v} onChange={e => setV(e.target.value)}
      onKeyDown={e => { if (e.key === "Enter") commit(); if (e.key === "Escape") cancel(); }} />
    <Check className="w-3.5 h-3.5 text-emerald-500 cursor-pointer" onClick={commit} />
    <X className="w-3.5 h-3.5 text-gray-400 cursor-pointer" onClick={cancel} />
  </span>;
  return <span className="group inline-flex items-center gap-1 cursor-pointer" onClick={() => setEd(true)}>
    {prefix}{value.toLocaleString()}<Pencil className="w-3 h-3 text-gray-300 group-hover:text-gray-400 opacity-0 group-hover:opacity-100" />
  </span>;
}
function IS({ value, options, onSave, colorMap }) {
  const [ed, setEd] = useState(false);
  if (ed) return <select autoFocus className="text-xs border border-gray-200 rounded px-1 py-0.5 bg-white"
    value={value} onChange={e => { onSave(e.target.value); setEd(false); }} onBlur={() => setEd(false)}>
    {options.map(o => <option key={o}>{o}</option>)}
  </select>;
  const cls = colorMap ? (colorMap[value] || "bg-gray-100 text-gray-500") : (STATUS_COLOR[value] || "bg-gray-100 text-gray-500");
  return <span className={`px-2 py-0.5 rounded-full text-xs font-medium cursor-pointer border ${cls}`} onClick={() => setEd(true)}>{value}</span>;
}
function TA({ value, onSave, rows = 3 }) {
  const [ed, setEd] = useState(false); const [v, setV] = useState(value);
  return ed
    ? <div><textarea autoFocus rows={rows} className="w-full text-sm text-gray-700 border border-blue-200 rounded-lg p-3 outline-none resize-none" value={v} onChange={e => setV(e.target.value)} />
        <div className="flex gap-2 mt-1">
          <button onClick={() => { onSave(v); setEd(false); }} className="flex items-center gap-1 text-xs text-emerald-600 font-medium"><Check className="w-3.5 h-3.5" />Save</button>
          <button onClick={() => { setV(value); setEd(false); }} className="flex items-center gap-1 text-xs text-gray-400"><X className="w-3.5 h-3.5" />Cancel</button>
        </div></div>
    : <div className="group relative cursor-pointer" onClick={() => setEd(true)}>
        <p className="text-sm text-gray-600 leading-relaxed whitespace-pre-wrap min-h-8">{value || <span className="text-gray-300 italic">Click to add...</span>}</p>
        <Pencil className="w-3 h-3 text-gray-300 group-hover:text-gray-400 absolute top-0 right-0 opacity-0 group-hover:opacity-100" />
      </div>;
}

function Card({ children, className = "" }) {
  return <div className={`bg-white rounded-xl border border-gray-200 shadow-sm p-5 ${className}`}>{children}</div>;
}
function SH({ title, onAdd, addLabel = "Add" }) {
  return <div className="flex items-center justify-between mb-3">
    <h2 className="text-sm font-semibold text-gray-700">{title}</h2>
    {onAdd && <button onClick={onAdd} className="flex items-center gap-1 text-xs text-blue-500 hover:text-blue-700"><Plus className="w-3.5 h-3.5" />{addLabel}</button>}
  </div>;
}
function BudgetBar({ spent, budget }) {
  const p = pct(spent, budget);
  const col = p > 90 ? "bg-red-500" : p > 70 ? "bg-amber-400" : "bg-emerald-500";
  return <div className="w-full">
    <div className="flex justify-between text-xs text-gray-500 mb-1"><span>${spent.toLocaleString()} spent</span><span>${budget.toLocaleString()} budget</span></div>
    <div className="w-full bg-gray-100 rounded-full h-2"><div className={`${col} h-2 rounded-full`} style={{ width: `${p}%` }} /></div>
    <div className="text-xs text-gray-400 mt-1">{p}% utilized · projected finish: ${Math.round(spent / Math.max(p, 1) * 100).toLocaleString()}</div>
  </div>;
}

// ── SHARE MODAL ────────────────────────────────────────────────────────────────
function buildClientHTML(proj) {
  const ragBg = { Green: "#d1fae5", Amber: "#fef3c7", Red: "#fee2e2" };
  const ragTxt = { Green: "#065f46", Amber: "#92400e", Red: "#991b1b" };
  const scBg = { "Done": "#d1fae5", "Complete": "#d1fae5", "In Progress": "#dbeafe", "In Review": "#dbeafe", "Not Started": "#f3f4f6", "Planning": "#fef3c7" };
  const scTxt = { "Done": "#065f46", "Complete": "#065f46", "In Progress": "#1e40af", "In Review": "#1e40af", "Not Started": "#6b7280", "Planning": "#92400e" };
  const badge = (v) => `<span style="background:${scBg[v]||'#f3f4f6'};color:${scTxt[v]||'#6b7280'};padding:2px 8px;border-radius:999px;font-size:11px;font-weight:600">${v}</span>`;
  const p = pct(proj.spent, proj.budget);
  const barCol = p > 90 ? "#ef4444" : p > 70 ? "#f59e0b" : "#10b981";
  const milDone = proj.milestones.filter(m => m.done).length;
  return `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>${proj.name} — Project Status</title>
<style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background:#f9fafb;color:#111827;padding:40px 24px}
.wrap{max-width:860px;margin:0 auto}.header{background:#fff;border-radius:16px;border:1px solid #e5e7eb;padding:28px 32px;margin-bottom:24px}
.header h1{font-size:22px;font-weight:700;color:#111827}.header .sub{font-size:13px;color:#6b7280;margin-top:4px}
.rag{display:inline-block;padding:4px 14px;border-radius:999px;font-size:12px;font-weight:700;margin-top:12px}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:24px}
.grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:24px}
.card{background:#fff;border-radius:12px;border:1px solid #e5e7eb;padding:20px}
.card h2{font-size:13px;font-weight:600;color:#374151;margin-bottom:12px}
.kpi-val{font-size:26px;font-weight:700;color:#111827}.kpi-sub{font-size:11px;color:#9ca3af;margin-top:2px}
table{width:100%;border-collapse:collapse;font-size:13px}th{text-align:left;font-size:11px;color:#9ca3af;font-weight:500;padding-bottom:8px;border-bottom:1px solid #f3f4f6}
td{padding:8px 0;border-bottom:1px solid #f9fafb;color:#374151;vertical-align:top}
.ms-row{display:flex;align-items:flex-start;gap:8px;margin-bottom:8px}
.ms-dot{width:16px;height:16px;border-radius:50%;border:2px solid #d1d5db;margin-top:2px;flex-shrink:0}
.ms-done{background:#10b981;border-color:#10b981}
.risk-row{padding:8px 0;border-bottom:1px solid #f9fafb}
.footer{text-align:center;font-size:11px;color:#d1d5db;margin-top:32px}
@media(max-width:600px){.grid4{grid-template-columns:1fr 1fr}.grid2{grid-template-columns:1fr}}
</style></head><body><div class="wrap">
<div class="header">
  <div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:12px">
    <div><h1>${proj.name}</h1><div class="sub">${proj.client} · Lead: ${proj.lead} · As of ${new Date().toLocaleDateString("en-US",{month:"long",day:"numeric",year:"numeric"})}</div></div>
    <span class="rag" style="background:${ragBg[proj.rag]||'#f3f4f6'};color:${ragTxt[proj.rag]||'#374151'}">${proj.rag}</span>
  </div>
  <div style="margin-top:16px;font-size:13px;color:#4b5563;line-height:1.6">${proj.execSummary}</div>
</div>
<div class="grid4">
  <div class="card"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Budget Remaining</div><div class="kpi-val">$${(proj.budget-proj.spent).toLocaleString()}</div><div class="kpi-sub">${100-p}% left</div></div>
  <div class="card"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Budget Used</div><div class="kpi-val">$${proj.spent.toLocaleString()}</div><div class="kpi-sub">of $${proj.budget.toLocaleString()}</div></div>
  <div class="card"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Milestones</div><div class="kpi-val">${milDone}/${proj.milestones.length}</div><div class="kpi-sub">${pct(milDone,proj.milestones.length)}% complete</div></div>
  <div class="card"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Open Tasks</div><div class="kpi-val">${proj.tasks.filter(t=>t.status!=="Done"&&t.status!=="Complete").length}</div><div class="kpi-sub">${proj.tasks.length} total</div></div>
</div>
<div style="margin-bottom:20px">
  <div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Budget: $${proj.spent.toLocaleString()} of $${proj.budget.toLocaleString()} (${p}%)</div>
  <div style="background:#f3f4f6;border-radius:999px;height:8px"><div style="background:${barCol};height:8px;border-radius:999px;width:${p}%"></div></div>
</div>
<div class="grid2">
  <div class="card"><h2>Milestones</h2>${proj.milestones.map(m=>`<div class="ms-row"><div class="ms-dot${m.done?" ms-done":""}"></div><div><div style="font-size:13px;color:${m.done?"#9ca3af":"#374151"};${m.done?"text-decoration:line-through":""}">${m.name}</div><div style="font-size:11px;color:#9ca3af">${m.date}${m.variance>0?` <span style="color:#f59e0b">+${m.variance}d</span>`:""}</div></div></div>`).join("")}</div>
  <div class="card"><h2>Deliverables</h2><table><thead><tr><th>Output</th><th>Due</th><th>Status</th></tr></thead><tbody>${proj.deliverables.map(d=>`<tr><td>${d.name}</td><td style="color:#6b7280">${d.due}</td><td>${badge(d.status)}</td></tr>`).join("")}</tbody></table></div>
</div>
<div class="grid2">
  <div class="card"><h2>Risk Log</h2>${proj.risks.length===0?`<p style="font-size:13px;color:#d1d5db;font-style:italic">No risks logged.</p>`:proj.risks.map(r=>`<div class="risk-row"><div style="display:flex;align-items:center;gap:8px;margin-bottom:4px"><span style="background:${ragBg[r.flag]||'#f3f4f6'};color:${ragTxt[r.flag]||'#374151'};padding:1px 8px;border-radius:999px;font-size:11px;font-weight:600">${r.flag}</span><span style="font-size:13px;color:#374151">${r.item}</span></div><div style="font-size:11px;color:#9ca3af">Owner: ${r.owner} · Mitigation: ${r.mitigation}</div></div>`).join("")}</div>
  <div class="card"><h2>Open Asks from Client</h2>${proj.openAsks.length===0?`<p style="font-size:13px;color:#d1d5db;font-style:italic">No open asks.</p>`:proj.openAsks.map(a=>`<div class="risk-row" style="display:flex;align-items:flex-start;gap:8px"><div style="width:14px;height:14px;border-radius:50%;background:${a.done?"#10b981":"#e5e7eb"};margin-top:2px;flex-shrink:0"></div><div><div style="font-size:13px;color:${a.done?"#9ca3af":"#374151"};${a.done?"text-decoration:line-through":""}">${a.ask}</div><div style="font-size:11px;color:#9ca3af">Asked of: ${a.askedOf} · Due: ${a.dueBy}</div></div></div>`).join("")}</div>
</div>
<div class="card" style="margin-top:20px"><h2>Decision Log</h2><table><thead><tr><th>Date</th><th>Decision</th><th>Made By</th></tr></thead><tbody>${proj.decisions.map(d=>`<tr><td style="color:#6b7280;white-space:nowrap">${d.date}</td><td>${d.decision}</td><td style="color:#6b7280">${d.madeBy}</td></tr>`).join("")}</tbody></table></div>
<div class="footer">Generated by Addie · ${proj.client} · ${new Date().toLocaleDateString()}</div>
</div></body></html>`;
}

function buildShareURL(proj) {
  try {
    const data = btoa(encodeURIComponent(JSON.stringify(proj)));
    return `${window.location.href.split("?")[0]}?view=${data}`;
  } catch { return window.location.href; }
}

function ShareModal({ proj, onClose }) {
  const [copied, setCopied] = useState(false);
  const [emailSent, setEmailSent] = useState(false);
  const [sending, setSending] = useState(false);
  const [emailTo, setEmailTo] = useState("");
  const shareURL = buildShareURL(proj);

  const copyLink = () => {
    navigator.clipboard.writeText(shareURL).then(() => { setCopied(true); setTimeout(() => setCopied(false), 2000); });
  };

  const downloadHTML = () => {
    const html = buildClientHTML(proj);
    const a = Object.assign(document.createElement("a"), {
      href: URL.createObjectURL(new Blob([html], { type: "text/html" })),
      download: `${proj.name.replace(/\s+/g, "_")}_status.html`
    });
    a.click();
  };

  const sendEmail = async () => {
    if (!emailTo.trim()) return;
    setSending(true);
    try {
      const response = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514",
          max_tokens: 1000,
          system: "You are a helpful assistant. Draft a concise, professional project status email. Return ONLY a JSON object with keys: subject (string) and body (string). No markdown, no preamble.",
          messages: [{
            role: "user",
            content: `Draft a brief project status update email to a client. Project: ${proj.name}. Client: ${proj.client}. RAG: ${proj.rag}. Summary: ${proj.execSummary}. Milestones done: ${proj.milestones.filter(m=>m.done).length}/${proj.milestones.length}. Budget used: $${proj.spent} of $${proj.budget}. Open asks: ${proj.openAsks.filter(a=>!a.done).map(a=>a.ask).join("; ")||"none"}. Keep it under 150 words. Sign off as Addie.`
          }]
        })
      });
      const data = await response.json();
      const text = data.content?.find(b => b.type === "text")?.text || "";
      let parsed;
      try { parsed = JSON.parse(text.replace(/```json|```/g, "").trim()); }
      catch { parsed = { subject: `${proj.name} — Status Update`, body: text }; }

      const gmailUrl = `https://mail.google.com/mail/?view=cm&to=${encodeURIComponent(emailTo)}&su=${encodeURIComponent(parsed.subject)}&body=${encodeURIComponent(parsed.body + "\n\nFull dashboard: " + shareURL)}`;
      window.open(gmailUrl, "_blank");
      setEmailSent(true);
    } catch (e) {
      const gmailUrl = `https://mail.google.com/mail/?view=cm&to=${encodeURIComponent(emailTo)}&su=${encodeURIComponent(proj.name + " — Status Update")}&body=${encodeURIComponent(proj.execSummary + "\n\nFull dashboard: " + shareURL)}`;
      window.open(gmailUrl, "_blank");
      setEmailSent(true);
    }
    setSending(false);
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-40 z-50 flex items-center justify-center p-4" onClick={onClose}>
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-6" onClick={e => e.stopPropagation()}>
        <div className="flex items-center justify-between mb-5">
          <div className="flex items-center gap-2">
            <Share2 className="w-5 h-5 text-gray-600" />
            <h2 className="text-base font-semibold text-gray-800">Share with Client</h2>
          </div>
          <button onClick={onClose}><X className="w-5 h-5 text-gray-400 hover:text-gray-600" /></button>
        </div>

        <div className="text-xs text-gray-500 mb-1 font-medium uppercase tracking-wide">Project</div>
        <div className="text-sm font-semibold text-gray-800 mb-5">{proj.name} — {proj.client}</div>

        {/* Shareable Link */}
        <div className="border border-gray-200 rounded-xl p-4 mb-3">
          <div className="flex items-center gap-2 mb-2">
            <Link className="w-4 h-4 text-blue-500" />
            <span className="text-sm font-medium text-gray-700">Shareable Link</span>
          </div>
          <p className="text-xs text-gray-400 mb-3">Encodes a read-only snapshot of the current project state into a URL.</p>
          <div className="flex gap-2">
            <input readOnly value={shareURL} className="flex-1 text-xs border border-gray-200 rounded-lg px-3 py-2 bg-gray-50 text-gray-500 truncate" />
            <button onClick={copyLink} className={`flex items-center gap-1 px-3 py-2 rounded-lg text-xs font-medium transition-colors ${copied ? "bg-emerald-500 text-white" : "bg-gray-800 text-white hover:bg-gray-700"}`}>
              {copied ? <><Check className="w-3.5 h-3.5" />Copied</> : <><Copy className="w-3.5 h-3.5" />Copy</>}
            </button>
          </div>
        </div>

        {/* Email */}
        <div className="border border-gray-200 rounded-xl p-4 mb-3">
          <div className="flex items-center gap-2 mb-2">
            <Mail className="w-4 h-4 text-purple-500" />
            <span className="text-sm font-medium text-gray-700">Send via Gmail</span>
          </div>
          <p className="text-xs text-gray-400 mb-3">AI-drafts a status update email with your exec summary and opens it in Gmail.</p>
          <div className="flex gap-2">
            <input value={emailTo} onChange={e => setEmailTo(e.target.value)}
              placeholder="client@email.com" className="flex-1 text-xs border border-gray-200 rounded-lg px-3 py-2 outline-none focus:border-blue-300" />
            <button onClick={sendEmail} disabled={sending || !emailTo.trim()}
              className={`flex items-center gap-1 px-3 py-2 rounded-lg text-xs font-medium transition-colors ${emailSent ? "bg-emerald-500 text-white" : sending ? "bg-gray-300 text-gray-500" : "bg-purple-600 text-white hover:bg-purple-700"} disabled:opacity-50`}>
              {emailSent ? <><Check className="w-3.5 h-3.5" />Opened</> : sending ? "Drafting..." : <><ExternalLink className="w-3.5 h-3.5" />Open in Gmail</>}
            </button>
          </div>
        </div>

        {/* HTML Export */}
        <div className="border border-gray-200 rounded-xl p-4">
          <div className="flex items-center gap-2 mb-2">
            <FileDown className="w-4 h-4 text-emerald-500" />
            <span className="text-sm font-medium text-gray-700">Export Static HTML</span>
          </div>
          <p className="text-xs text-gray-400 mb-3">Downloads a standalone HTML file — no login needed, opens in any browser. Good for email attachments.</p>
          <button onClick={downloadHTML} className="flex items-center gap-2 w-full justify-center px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-medium rounded-lg transition-colors">
            <Download className="w-3.5 h-3.5" /> Download {proj.name.replace(/\s+/g,"_")}_status.html
          </button>
        </div>
      </div>
    </div>
  );
}

// ── PANEL SETTINGS ─────────────────────────────────────────────────────────────
