// ── DRAG TABLE ─────────────────────────────────────────────────────────────────
function DragTable({ tasks, onUpdate, onDelete, onAdd, onReorder }) {
  const dragIdx = useRef(null);
  const [dragOver, setDragOver] = useState(null);
  const start = (e, i) => { dragIdx.current = i; e.dataTransfer.effectAllowed = "move"; };
  const over = (e, i) => { e.preventDefault(); setDragOver(i); };
  const drop = (e, i) => {
    e.preventDefault();
    if (dragIdx.current !== null && dragIdx.current !== i) {
      const r = [...tasks]; const [m] = r.splice(dragIdx.current, 1); r.splice(i, 0, m); onReorder(r);
    }
    dragIdx.current = null; setDragOver(null);
  };
  return <Card>
    <SH title={<>Tasks <span className="text-xs text-gray-400 font-normal ml-1">drag to reorder</span></>} onAdd={onAdd} addLabel="Add task" />
    <div className="overflow-x-auto">
      <table className="w-full text-sm">
        <thead><tr className="text-left text-xs text-gray-400 border-b border-gray-100">
          <th className="pb-2 w-5" /><th className="pb-2 font-medium">Task</th><th className="pb-2 font-medium">Owner</th>
          <th className="pb-2 font-medium">Due</th><th className="pb-2 font-medium">Status</th><th className="pb-2 w-5" />
        </tr></thead>
        <tbody>{tasks.map((t, i) => <tr key={t.id} draggable onDragStart={e => start(e, i)} onDragOver={e => over(e, i)}
          onDrop={e => drop(e, i)} onDragEnd={() => { dragIdx.current = null; setDragOver(null); }}
          className={`border-b border-gray-50 last:border-0 group transition-colors ${dragOver === i ? "bg-blue-50" : ""}`}>
          <td className="py-2"><GripVertical className="w-3.5 h-3.5 text-gray-300 cursor-grab group-hover:text-gray-400" /></td>
          <td className="py-2 text-gray-700"><IT value={t.name} onSave={v => onUpdate(t.id, "name", v)} wide /></td>
          <td className="py-2 text-gray-500"><IT value={t.owner} onSave={v => onUpdate(t.id, "owner", v)} /></td>
          <td className="py-2 text-gray-500"><IT value={t.due} onSave={v => onUpdate(t.id, "due", v)} /></td>
          <td className="py-2"><IS value={t.status} options={STATUS_OPTIONS} onSave={v => onUpdate(t.id, "status", v)} /></td>
          <td className="py-2 text-right"><button onClick={() => onDelete(t.id)} className="opacity-0 group-hover:opacity-100">
            <Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button></td>
        </tr>)}</tbody>
      </table>
    </div>
  </Card>;
}

// ── CSV EXPORT ─────────────────────────────────────────────────────────────────
function exportCSV(p) {
  const q = s => `"${String(s || "").replace(/"/g, '""')}"`;
  const rows = [
    ["Project", p.name], ["Client", p.client], ["Status", p.status], ["RAG", p.rag],
    ["Budget", p.budget], ["Spent", p.spent], ["Remaining", p.budget - p.spent], [],
    ["EXEC SUMMARY"], [q(p.execSummary)], [],
    ["TASKS"], ["Task", "Owner", "Due", "Status"], ...p.tasks.map(t => [q(t.name), t.owner, t.due, t.status]), [],
    ["MILESTONES"], ["Milestone", "Date", "Done", "Variance"], ...p.milestones.map(m => [q(m.name), m.date, m.done ? "Yes" : "No", m.variance || 0]), [],
    ["DELIVERABLES"], ["Deliverable", "Status", "Due"], ...p.deliverables.map(d => [q(d.name), d.status, d.due]), [],
    ["RISKS"], ["Flag", "Risk", "Owner", "Mitigation"], ...p.risks.map(r => [r.flag, q(r.item), r.owner, q(r.mitigation)]), [],
    ["DECISIONS"], ["Date", "Decision", "Made By"], ...p.decisions.map(d => [d.date, q(d.decision), d.madeBy]), [],
    ["OPEN ASKS"], ["Ask", "Asked Of", "Due By", "Done"], ...p.openAsks.map(a => [q(a.ask), a.askedOf, a.dueBy, a.done ? "Yes" : "No"]), [],
    ["MEETINGS"], ["Date", "Attendees", "Summary"], ...p.meetings.map(m => [m.date, q(m.attendees), q(m.summary)]),
  ];
  const a = Object.assign(document.createElement("a"), { href: URL.createObjectURL(new Blob([rows.map(r => r.join(",")).join("\n")], { type: "text/csv" })), download: `${p.name.replace(/\s+/g, "_")}.csv` });
  a.click();
}

