const PANEL_LABELS = {
  execSummary: "Executive Summary", kpis: "KPI Cards", budget: "Budget Chart",
  milestones: "Milestones", notes: "Internal Notes (not shared)", deliverables: "Deliverables",
  risks: "Risk Log", decisions: "Decision Log", openAsks: "Open Asks from Client",
  meetings: "Meeting Log", tasks: "Task Table",
};

const STATUS_COLOR = {
  "Done": "bg-emerald-100 text-emerald-700", "Complete": "bg-emerald-100 text-emerald-700",
  "In Progress": "bg-blue-100 text-blue-700", "In Review": "bg-blue-100 text-blue-700",
  "Not Started": "bg-gray-100 text-gray-500", "Planning": "bg-amber-100 text-amber-700",
};
const STATUS_OPTIONS = ["Not Started", "In Progress", "In Review", "Done", "Complete", "Planning"];
const RAG_DOT = { Green: "bg-emerald-500", Amber: "bg-amber-400", Red: "bg-red-500" };
const RAG_BADGE = { Green: "text-emerald-700 bg-emerald-50 border-emerald-200", Amber: "text-amber-700 bg-amber-50 border-amber-200", Red: "text-red-700 bg-red-50 border-red-200" };
const pct = (a, b) => b === 0 ? 0 : Math.min(100, Math.round((a / b) * 100));
const now = () => new Date().toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "2-digit", minute: "2-digit" });

// ── PERSISTENCE ───────────────────────────────────────────────────────────────
function loadState() {
  try {
    const raw = window.storage && typeof window.storage.get === "function" ? null : null;
    const ls = localStorage.getItem(STORAGE_KEY);
    if (ls) return JSON.parse(ls);
  } catch {}
  return null;
}
function saveState(data) {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); } catch {}
}

// ── INLINE EDITORS ─────────────────────────────────────────────────────────────
function IT({ value, onSave, className = "", wide = false, placeholder = "Click to edit" }) {
  const [ed, setEd] = useState(false); const [v, setV] = useState(value);
  const commit = () => { onSave(v); setEd(false); };
  const cancel = () => { setV(value); setEd(false); };
  if (ed) return <span className="inline-flex items-center gap-1">
    <input autoFocus placeholder={placeholder} className={`border-b border-blue-400 outline-none bg-transparent text-sm px-0.5 ${wide ? "w-56" : "w-36"}`}
      value={v} onChange={e => setV(e.target.value)}
      onKeyDown={e => { if (e.key === "Enter") commit(); if (e.key === "Escape") cancel(); }} />
    <Check className="w-3.5 h-3.5 text-emerald-500 cursor-pointer shrink-0" onClick={commit} />
    <X className="w-3.5 h-3.5 text-gray-400 cursor-pointer shrink-0" onClick={cancel} />
  </span>;
  return <span className={`group inline-flex items-center gap-1 cursor-pointer ${className}`} onClick={() => setEd(true)}>
    {value || <span className="text-gray-300 italic text-sm">{placeholder}</span>}
    <Pencil className="w-3 h-3 text-gray-300 group-hover:text-gray-400 opacity-0 group-hover:opacity-100 shrink-0" />
  </span>;
}
function IN({ value, onSave, prefix = "" }) {
  const [ed, setEd] = useState(false); const [v, setV] = useState(value);
  const commit = () => { const n = parseFloat(v); if (!isNaN(n)) onSave(n); setEd(false); };
  const cancel = () => { setV(value); setEd(false); };
  if (ed) return <span className="inline-flex items-center gap-1">
    <input autoFocus className="border-b border-blue-400 outline-none bg-transparent w-24 text-sm"
      value={v} onChange={e => setV(e.target.value)}
      onKeyDown={e => { if (e.key === "Enter") commit(); if (e.key === "Escape") cancel(); }} />
    <Check className="w-3.5 h-3.5 text-emerald-500 cursor-pointer" onClick={commit} />
    <X className="w-3.5 h-3.5 text-gray-400 cursor-pointer" onClick={cancel} />
  </span>;
  return <span className="group inline-flex items-center gap-1 cursor-pointer" onClick={() => setEd(true)}>
    {prefix}{value.toLocaleString()}<Pencil className="w-3 h-3 text-gray-300 group-hover:text-gray-400 opacity-0 group-hover:opacity-100" />
  </span>;
}
function IS({ value, options, onSave, colorMap }) {
  const [ed, setEd] = useState(false);
  if (ed) return <select autoFocus className="text-xs border border-gray-200 rounded px-1 py-0.5 bg-white"
    value={value} onChange={e => { onSave(e.target.value); setEd(false); }} onBlur={() => setEd(false)}>
    {options.map(o => <option key={o}>{o}</option>)}
  </select>;
  const cls = colorMap ? (colorMap[value] || "bg-gray-100 text-gray-500 border-gray-200") : (STATUS_COLOR[value] || "bg-gray-100 text-gray-500");
  return <span className={`px-2 py-0.5 rounded-full text-xs font-medium cursor-pointer border ${cls}`} onClick={() => setEd(true)}>{value}</span>;
}
function TA({ value, onSave, rows = 3, placeholder = "Click to add..." }) {
  const [ed, setEd] = useState(false); const [v, setV] = useState(value);
  return ed
    ? <div><textarea autoFocus rows={rows} placeholder={placeholder} className="w-full text-sm text-gray-700 border border-blue-200 rounded-lg p-3 outline-none resize-none focus:border-blue-400" value={v} onChange={e => setV(e.target.value)} />
        <div className="flex gap-2 mt-1">
          <button onClick={() => { onSave(v); setEd(false); }} className="flex items-center gap-1 text-xs text-emerald-600 font-medium"><Check className="w-3.5 h-3.5" />Save</button>
          <button onClick={() => { setV(value); setEd(false); }} className="flex items-center gap-1 text-xs text-gray-400"><X className="w-3.5 h-3.5" />Cancel</button>
        </div></div>
    : <div className="group relative cursor-pointer" onClick={() => setEd(true)}>
        <p className="text-sm text-gray-600 leading-relaxed whitespace-pre-wrap min-h-8">{value || <span className="text-gray-300 italic">{placeholder}</span>}</p>
        <Pencil className="w-3 h-3 text-gray-300 group-hover:text-gray-400 absolute top-0 right-0 opacity-0 group-hover:opacity-100" />
      </div>;
}

function Card({ children, className = "" }) { return <div className={`bg-white rounded-xl border border-gray-200 shadow-sm p-5 ${className}`}>{children}</div>; }
function SH({ title, onAdd, addLabel = "Add" }) {
  return <div className="flex items-center justify-between mb-3">
    <h2 className="text-sm font-semibold text-gray-700">{title}</h2>
    {onAdd && <button onClick={onAdd} className="flex items-center gap-1 text-xs text-blue-500 hover:text-blue-700"><Plus className="w-3.5 h-3.5" />{addLabel}</button>}
  </div>;
}
function BudgetBar({ spent, budget }) {
  const p = pct(spent, budget);
  const col = p > 90 ? "bg-red-500" : p > 70 ? "bg-amber-400" : "bg-emerald-500";
  const projected = budget > 0 ? Math.round(spent / Math.max(p, 1) * 100) : 0;
  return <div className="w-full">
    <div className="flex justify-between text-xs text-gray-500 mb-1"><span>${spent.toLocaleString()} spent</span><span>${budget.toLocaleString()} budget</span></div>
    <div className="w-full bg-gray-100 rounded-full h-2"><div className={`${col} h-2 rounded-full`} style={{ width: `${p}%` }} /></div>
    <div className="text-xs text-gray-400 mt-1">{p}% utilized{budget > 0 ? ` · projected finish: $${projected.toLocaleString()}` : ""}</div>
  </div>;
}

// ── CLIENT HTML EXPORT ────────────────────────────────────────────────────────
function buildClientHTML(proj, dashTitle, updatedAt) {
  const ragBg = { Green: "#d1fae5", Amber: "#fef3c7", Red: "#fee2e2" };
  const ragTxt = { Green: "#065f46", Amber: "#92400e", Red: "#991b1b" };
  const scBg = { "Done": "#d1fae5", "Complete": "#d1fae5", "In Progress": "#dbeafe", "In Review": "#dbeafe", "Not Started": "#f3f4f6", "Planning": "#fef3c7" };
  const scTxt = { "Done": "#065f46", "Complete": "#065f46", "In Progress": "#1e40af", "In Review": "#1e40af", "Not Started": "#6b7280", "Planning": "#92400e" };
  const badge = v => `<span style="background:${scBg[v]||"#f3f4f6"};color:${scTxt[v]||"#6b7280"};padding:2px 8px;border-radius:999px;font-size:11px;font-weight:600">${v}</span>`;
  const p = pct(proj.spent, proj.budget);
  const barCol = p > 90 ? "#ef4444" : p > 70 ? "#f59e0b" : "#10b981";
  const milDone = proj.milestones.filter(m => m.done).length;
  return `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>${proj.name} — Status</title>
<style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background:#f9fafb;color:#111827;padding:40px 24px}
.wrap{max-width:860px;margin:0 auto}.header{background:#fff;border-radius:16px;border:1px solid #e5e7eb;padding:28px 32px;margin-bottom:24px}
.header h1{font-size:22px;font-weight:700}.header .sub{font-size:13px;color:#6b7280;margin-top:4px}
.rag{display:inline-block;padding:4px 14px;border-radius:999px;font-size:12px;font-weight:700;margin-top:12px}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:24px}
.grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:24px}
.card{background:#fff;border-radius:12px;border:1px solid #e5e7eb;padding:20px}
.card h2{font-size:13px;font-weight:600;color:#374151;margin-bottom:12px}
.kpi-val{font-size:26px;font-weight:700}.kpi-sub{font-size:11px;color:#9ca3af;margin-top:2px}
table{width:100%;border-collapse:collapse;font-size:13px}th{text-align:left;font-size:11px;color:#9ca3af;font-weight:500;padding-bottom:8px;border-bottom:1px solid #f3f4f6}
td{padding:8px 0;border-bottom:1px solid #f9fafb;color:#374151;vertical-align:top}
.ms-row{display:flex;align-items:flex-start;gap:8px;margin-bottom:8px}
.ms-dot{width:16px;height:16px;border-radius:50%;border:2px solid #d1d5db;margin-top:2px;flex-shrink:0}.ms-done{background:#10b981;border-color:#10b981}
.row{padding:8px 0;border-bottom:1px solid #f9fafb}
.footer{text-align:center;font-size:11px;color:#d1d5db;margin-top:32px}
@media(max-width:600px){.grid4{grid-template-columns:1fr 1fr}.grid2{grid-template-columns:1fr}}
</style></head><body><div class="wrap">
<div class="header">
  <div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:12px">
    <div><h1>${proj.name}</h1><div class="sub">${proj.client} · Lead: ${proj.lead} · As of ${updatedAt}</div></div>
    <span class="rag" style="background:${ragBg[proj.rag]||"#f3f4f6"};color:${ragTxt[proj.rag]||"#374151"}">${proj.rag}</span>
  </div>
  <div style="margin-top:16px;font-size:13px;color:#4b5563;line-height:1.6">${proj.execSummary || "<em>No summary provided.</em>"}</div>
</div>
<div class="grid4">
  <div class="card"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Budget Remaining</div><div class="kpi-val">$${(proj.budget-proj.spent).toLocaleString()}</div><div class="kpi-sub">${100-p}% left</div></div>
  <div class="card"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Budget Used</div><div class="kpi-val">$${proj.spent.toLocaleString()}</div><div class="kpi-sub">of $${proj.budget.toLocaleString()}</div></div>
  <div class="card"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Milestones</div><div class="kpi-val">${milDone}/${proj.milestones.length}</div><div class="kpi-sub">${pct(milDone,proj.milestones.length)}% complete</div></div>
  <div class="card"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Open Tasks</div><div class="kpi-val">${proj.tasks.filter(t=>t.status!=="Done"&&t.status!=="Complete").length}</div><div class="kpi-sub">${proj.tasks.length} total</div></div>
</div>
${proj.budget > 0 ? `<div style="margin-bottom:20px"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Budget: $${proj.spent.toLocaleString()} of $${proj.budget.toLocaleString()} (${p}%)</div><div style="background:#f3f4f6;border-radius:999px;height:8px"><div style="background:${barCol};height:8px;border-radius:999px;width:${p}%"></div></div></div>` : ""}
<div class="grid2">
  <div class="card"><h2>Milestones</h2>${proj.milestones.length ? proj.milestones.map(m=>`<div class="ms-row"><div class="ms-dot${m.done?" ms-done":""}"></div><div><div style="font-size:13px;color:${m.done?"#9ca3af":"#374151"};${m.done?"text-decoration:line-through":""}">${m.name}</div><div style="font-size:11px;color:#9ca3af">${m.date}${m.variance>0?` <span style="color:#f59e0b">+${m.variance}d</span>`:""}</div></div></div>`).join("") : "<p style='font-size:13px;color:#d1d5db;font-style:italic'>No milestones added.</p>"}</div>
  <div class="card"><h2>Deliverables</h2>${proj.deliverables.length ? `<table><thead><tr><th>Output</th><th>Due</th><th>Status</th></tr></thead><tbody>${proj.deliverables.map(d=>`<tr><td>${d.name}</td><td style="color:#6b7280">${d.due}</td><td>${badge(d.status)}</td></tr>`).join("")}</tbody></table>` : "<p style='font-size:13px;color:#d1d5db;font-style:italic'>No deliverables added.</p>"}</div>
</div>
<div class="grid2">
  <div class="card"><h2>Risk Log</h2>${proj.risks.length ? proj.risks.map(r=>`<div class="row"><div style="display:flex;align-items:center;gap:8px;margin-bottom:4px"><span style="background:${ragBg[r.flag]||"#f3f4f6"};color:${ragTxt[r.flag]||"#374151"};padding:1px 8px;border-radius:999px;font-size:11px;font-weight:600">${r.flag}</span><span style="font-size:13px;color:#374151">${r.item}</span></div><div style="font-size:11px;color:#9ca3af">Owner: ${r.owner} · Mitigation: ${r.mitigation}</div></div>`).join("") : "<p style='font-size:13px;color:#d1d5db;font-style:italic'>No risks logged.</p>"}</div>
  <div class="card"><h2>Open Asks from Client</h2>${proj.openAsks.length ? proj.openAsks.map(a=>`<div class="row" style="display:flex;align-items:flex-start;gap:8px"><div style="width:14px;height:14px;border-radius:50%;background:${a.done?"#10b981":"#e5e7eb"};margin-top:2px;flex-shrink:0"></div><div><div style="font-size:13px;color:${a.done?"#9ca3af":"#374151"};${a.done?"text-decoration:line-through":""}">${a.ask}</div><div style="font-size:11px;color:#9ca3af">Asked of: ${a.askedOf} · Due: ${a.dueBy}</div></div></div>`).join("") : "<p style='font-size:13px;color:#d1d5db;font-style:italic'>No open asks.</p>"}</div>
</div>
${proj.decisions.length ? `<div class="card" style="margin-bottom:20px"><h2>Decision Log</h2><table><thead><tr><th>Date</th><th>Decision</th><th>Made By</th></tr></thead><tbody>${proj.decisions.map(d=>`<tr><td style="color:#6b7280;white-space:nowrap">${d.date}</td><td>${d.decision}</td><td style="color:#6b7280">${d.madeBy}</td></tr>`).join("")}</tbody></table></div>` : ""}
<div class="footer">Prepared by ${proj.lead} · ${proj.client} · Last updated ${updatedAt}</div>
</div></body></html>`;
}

function buildShareURL(proj) {
  try { return `${window.location.href.split("?")[0]}?view=${btoa(encodeURIComponent(JSON.stringify(proj)))}`; }
  catch { return window.location.href; }
}

// ── SHARE MODAL ────────────────────────────────────────────────────────────────
function ShareModal({ proj, dashTitle, updatedAt, onClose }) {
  const [copied, setCopied] = useState(false);
  const [emailSent, setEmailSent] = useState(false);
  const [sending, setSending] = useState(false);
  const [emailTo, setEmailTo] = useState("");
  const shareURL = buildShareURL(proj);

  const copyLink = () => {
    navigator.clipboard.writeText(shareURL).then(() => { setCopied(true); setTimeout(() => setCopied(false), 2000); });
  };
  const downloadHTML = () => {
    const html = buildClientHTML(proj, dashTitle, updatedAt);
    const a = Object.assign(document.createElement("a"), { href: URL.createObjectURL(new Blob([html], { type: "text/html" })), download: `${proj.client.replace(/\s+/g,"_")}_${proj.name.replace(/\s+/g,"_")}_status.html` });
    a.click();
  };
  const sendEmail = async () => {
    if (!emailTo.trim()) return;
    setSending(true);
    try {
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514", max_tokens: 1000,
          system: "Draft a concise professional project status email. Return ONLY a JSON object with keys: subject (string) and body (string). No markdown, no preamble.",
          messages: [{ role: "user", content: `Draft a brief project status update. Project: ${proj.name}. Client: ${proj.client}. RAG: ${proj.rag}. Summary: ${proj.execSummary}. Milestones done: ${proj.milestones.filter(m=>m.done).length}/${proj.milestones.length}. Budget used: $${proj.spent} of $${proj.budget}. Open asks: ${proj.openAsks.filter(a=>!a.done).map(a=>a.ask).join("; ")||"none"}. Under 150 words. Sign off as ${proj.lead}.` }]
        })
      });
      const data = await res.json();
      const text = data.content?.find(b => b.type === "text")?.text || "";
      let parsed; try { parsed = JSON.parse(text.replace(/```json|```/g,"").trim()); } catch { parsed = { subject: `${proj.name} — Status Update`, body: text }; }
      window.open(`https://mail.google.com/mail/?view=cm&to=${encodeURIComponent(emailTo)}&su=${encodeURIComponent(parsed.subject)}&body=${encodeURIComponent(parsed.body + "\n\nFull dashboard: " + shareURL)}`, "_blank");
      setEmailSent(true);
    } catch {
      window.open(`https://mail.google.com/mail/?view=cm&to=${encodeURIComponent(emailTo)}&su=${encodeURIComponent(proj.name+" — Status Update")}&body=${encodeURIComponent(proj.execSummary+"\n\nFull dashboard: "+shareURL)}`, "_blank");
      setEmailSent(true);
    }
    setSending(false);
  };

  return <div className="fixed inset-0 bg-black bg-opacity-40 z-50 flex items-center justify-center p-4" onClick={onClose}>
    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-6" onClick={e => e.stopPropagation()}>
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2"><Share2 className="w-5 h-5 text-gray-600" /><h2 className="text-base font-semibold text-gray-800">Share with Client</h2></div>
        <button onClick={onClose}><X className="w-5 h-5 text-gray-400 hover:text-gray-600" /></button>
      </div>
      <div className="text-xs text-gray-500 mb-0.5 font-medium">Project</div>
      <div className="text-sm font-semibold text-gray-800 mb-1">{proj.name}</div>
      <div className="text-xs text-gray-400 mb-4">Last updated: {updatedAt}</div>
      <div className="p-3 bg-amber-50 border border-amber-200 rounded-lg mb-4 text-xs text-amber-700">
        <strong>Note:</strong> Internal Notes panel is excluded from all share formats. Review Risk Log and Decision Log before sharing.
      </div>

      {[
        { icon: <Link className="w-4 h-4 text-blue-500" />, title: "Shareable Link", desc: "Read-only snapshot encoded into a URL.", action: <div className="flex gap-2"><input readOnly value={shareURL} className="flex-1 text-xs border border-gray-200 rounded-lg px-3 py-2 bg-gray-50 text-gray-500 truncate" /><button onClick={copyLink} className={`flex items-center gap-1 px-3 py-2 rounded-lg text-xs font-medium ${copied ? "bg-emerald-500 text-white" : "bg-gray-800 text-white hover:bg-gray-700"}`}>{copied ? <><Check className="w-3.5 h-3.5" />Copied</> : <><Copy className="w-3.5 h-3.5" />Copy</>}</button></div> },
        { icon: <Mail className="w-4 h-4 text-purple-500" />, title: "Send via Gmail", desc: "AI-drafts a status email and opens it in Gmail.", action: <div className="flex gap-2"><input value={emailTo} onChange={e => setEmailTo(e.target.value)} placeholder="client@email.com" className="flex-1 text-xs border border-gray-200 rounded-lg px-3 py-2 outline-none focus:border-blue-300" /><button onClick={sendEmail} disabled={sending || !emailTo.trim()} className={`flex items-center gap-1 px-3 py-2 rounded-lg text-xs font-medium ${emailSent ? "bg-emerald-500 text-white" : sending ? "bg-gray-200 text-gray-400" : "bg-purple-600 text-white hover:bg-purple-700"} disabled:opacity-50`}>{emailSent ? <><Check className="w-3.5 h-3.5" />Opened</> : sending ? "Drafting..." : <><ExternalLink className="w-3.5 h-3.5" />Gmail</>}</button></div> },
        { icon: <FileDown className="w-4 h-4 text-emerald-500" />, title: "Export Static HTML", desc: "Standalone file, opens in any browser. Safe to attach.", action: <button onClick={downloadHTML} className="flex items-center gap-2 w-full justify-center px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-medium rounded-lg"><Download className="w-3.5 h-3.5" />Download HTML</button> },
      ].map((s, i) => <div key={i} className="border border-gray-200 rounded-xl p-4 mb-3 last:mb-0">
        <div className="flex items-center gap-2 mb-1">{s.icon}<span className="text-sm font-medium text-gray-700">{s.title}</span></div>
        <p className="text-xs text-gray-400 mb-3">{s.desc}</p>
        {s.action}
      </div>)}
    </div>
  </div>;
}

// ── PANEL SETTINGS ─────────────────────────────────────────────────────────────
function PanelSettings({ panels, onChange }) {
  const [open, setOpen] = useState(false);
  return <div className="relative">
    <button onClick={() => setOpen(o => !o)} className="flex items-center gap-1.5 px-3 py-2 bg-white border border-gray-200 text-gray-600 text-sm rounded-lg hover:border-gray-400 shadow-sm">
      <Settings className="w-4 h-4" /> Panels
    </button>
    {open && <div className="absolute right-0 top-10 bg-white border border-gray-200 rounded-xl shadow-lg z-50 p-4 w-64">
      <p className="text-xs font-semibold text-gray-500 mb-3 uppercase tracking-wide">Toggle Panels</p>
      <div className="space-y-2">
        {Object.entries(PANEL_LABELS).map(([key, label]) => <label key={key} className="flex items-center gap-2 cursor-pointer">
          <input type="checkbox" checked={panels[key]} onChange={e => onChange(key, e.target.checked)} className="rounded" />
          <span className="text-sm text-gray-700">{label}</span>
          {panels[key] ? <Eye className="w-3.5 h-3.5 text-gray-300 ml-auto" /> : <EyeOff className="w-3.5 h-3.5 text-gray-300 ml-auto" />}
        </label>)}
      </div>
      <button onClick={() => setOpen(false)} className="mt-3 w-full text-xs text-gray-400 hover:text-gray-600 text-center">Done</button>
    </div>}
  </div>;
}

// ── DRAG TABLE ─────────────────────────────────────────────────────────────────
function DragTable({ tasks, onUpdate, onDelete, onAdd, onReorder }) {
  const dragIdx = useRef(null); const [dragOver, setDragOver] = useState(null);
  const start = (e, i) => { dragIdx.current = i; e.dataTransfer.effectAllowed = "move"; };
  const over = (e, i) => { e.preventDefault(); setDragOver(i); };
  const drop = (e, i) => { e.preventDefault(); if (dragIdx.current !== null && dragIdx.current !== i) { const r = [...tasks]; const [m] = r.splice(dragIdx.current, 1); r.splice(i, 0, m); onReorder(r); } dragIdx.current = null; setDragOver(null); };
  return <Card>
    <SH title={<>Tasks <span className="text-xs text-gray-400 font-normal ml-1">drag to reorder</span></>} onAdd={onAdd} addLabel="Add task" />
    <div className="overflow-x-auto"><table className="w-full text-sm">
      <thead><tr className="text-left text-xs text-gray-400 border-b border-gray-100"><th className="pb-2 w-5" /><th className="pb-2 font-medium">Task</th><th className="pb-2 font-medium">Owner</th><th className="pb-2 font-medium">Due</th><th className="pb-2 font-medium">Status</th><th className="pb-2 w-5" /></tr></thead>
      <tbody>{tasks.map((t, i) => <tr key={t.id} draggable onDragStart={e => start(e, i)} onDragOver={e => over(e, i)} onDrop={e => drop(e, i)} onDragEnd={() => { dragIdx.current = null; setDragOver(null); }} className={`border-b border-gray-50 last:border-0 group transition-colors ${dragOver === i ? "bg-blue-50" : ""}`}>
        <td className="py-2"><GripVertical className="w-3.5 h-3.5 text-gray-300 cursor-grab group-hover:text-gray-400" /></td>
        <td className="py-2"><IT value={t.name} onSave={v => onUpdate(t.id, "name", v)} wide /></td>
        <td className="py-2 text-gray-500"><IT value={t.owner} onSave={v => onUpdate(t.id, "owner", v)} /></td>
        <td className="py-2 text-gray-500"><IT value={t.due} onSave={v => onUpdate(t.id, "due", v)} /></td>
        <td className="py-2"><IS value={t.status} options={STATUS_OPTIONS} onSave={v => onUpdate(t.id, "status", v)} /></td>
        <td className="py-2 text-right"><button onClick={() => onDelete(t.id)} className="opacity-0 group-hover:opacity-100"><Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button></td>
      </tr>)}</tbody>
    </table></div>
  </Card>;
}

// ── MAIN ───────────────────────────────────────────────────────────────────────
const INIT_STATE = {
  dashTitle: "Project Dashboard",
  projects: [blankProject(1)],
  updatedAt: now(),
};

export default function Dashboard() {
  const [state, setState] = useState(() => loadState() || INIT_STATE);
  const [activeId, setActiveId] = useState(state.projects[0]?.id || 1);
  const [panels, setPanels] = useState(DEFAULT_PANELS);
  const [showShare, setShowShare] = useState(false);
  const [saved, setSaved] = useState(false);
  const [showImport, setShowImport] = useState(false);
  const [importErr, setImportErr] = useState("");

  const { dashTitle, projects, updatedAt } = state;
  const proj = projects.find(p => p.id === activeId) || projects[0];

  const touch = (newState) => {
    const updated = { ...newState, updatedAt: now() };
    setState(updated);
    saveState(updated);
    setSaved(true);
    setTimeout(() => setSaved(false), 1500);
  };

  const setProjects = (ps) => touch({ ...state, projects: ps });
  const up = (field, value) => setProjects(projects.map(p => p.id === activeId ? { ...p, [field]: value } : p));

  const addProject = () => {
    const id = Date.now();
    const ps = [...projects, blankProject(id)];
    touch({ ...state, projects: ps });
    setActiveId(id);
  };
  const removeProject = (id) => {
    if (projects.length === 1) return;
    const ps = projects.filter(p => p.id !== id);
    touch({ ...state, projects: ps });
    setActiveId(ps[0].id);
  };

  const updTask = (tid, f, v) => up("tasks", proj.tasks.map(t => t.id === tid ? { ...t, [f]: v } : t));
  const updMile = (i, f, v) => up("milestones", proj.milestones.map((m, idx) => idx === i ? { ...m, [f]: v } : m));
  const updDeliv = (tid, f, v) => up("deliverables", proj.deliverables.map(d => d.id === tid ? { ...d, [f]: v } : d));
  const updRisk = (tid, f, v) => up("risks", proj.risks.map(r => r.id === tid ? { ...r, [f]: v } : r));
  const updDec = (tid, f, v) => up("decisions", proj.decisions.map(d => d.id === tid ? { ...d, [f]: v } : d));
  const updAsk = (tid, f, v) => up("openAsks", proj.openAsks.map(a => a.id === tid ? { ...a, [f]: v } : a));
  const updMeet = (tid, f, v) => up("meetings", proj.meetings.map(m => m.id === tid ? { ...m, [f]: v } : m));

  const exportJSON = () => {
    const a = Object.assign(document.createElement("a"), { href: URL.createObjectURL(new Blob([JSON.stringify(state, null, 2)], { type: "application/json" })), download: "dashboard_backup.json" });
    a.click();
  };
  const importJSON = (e) => {
    const file = e.target.files?.[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const parsed = JSON.parse(ev.target.result);
        if (!parsed.projects) throw new Error("Invalid format");
        touch(parsed);
        setActiveId(parsed.projects[0]?.id);
        setShowImport(false); setImportErr("");
      } catch { setImportErr("Invalid file. Make sure it's a dashboard backup JSON."); }
    };
    reader.readAsText(file);
  };
  const resetAll = () => { if (window.confirm("Reset everything? This cannot be undone.")) { touch(INIT_STATE); setActiveId(INIT_STATE.projects[0].id); } };
  const exportCSV = () => {
    const q = s => `"${String(s||"").replace(/"/g,'""')}"`;
    const rows = [["Project",proj.name],["Client",proj.client],["Status",proj.status],["RAG",proj.rag],["Budget",proj.budget],["Spent",proj.spent],["Remaining",proj.budget-proj.spent],[],["EXEC SUMMARY"],[q(proj.execSummary)],[],["TASKS"],["Task","Owner","Due","Status"],...proj.tasks.map(t=>[q(t.name),t.owner,t.due,t.status]),[],["MILESTONES"],["Milestone","Date","Done","Variance"],...proj.milestones.map(m=>[q(m.name),m.date,m.done?"Yes":"No",m.variance||0]),[],["DELIVERABLES"],["Deliverable","Status","Due"],...proj.deliverables.map(d=>[q(d.name),d.status,d.due]),[],["RISKS"],["Flag","Risk","Owner","Mitigation"],...proj.risks.map(r=>[r.flag,q(r.item),r.owner,q(r.mitigation)]),[],["DECISIONS"],["Date","Decision","Made By"],...proj.decisions.map(d=>[d.date,q(d.decision),d.madeBy]),[],["OPEN ASKS"],["Ask","Asked Of","Due By","Done"],...proj.openAsks.map(a=>[q(a.ask),a.askedOf,a.dueBy,a.done?"Yes":"No"]),[],["MEETINGS"],["Date","Attendees","Summary"],...proj.meetings.map(m=>[m.date,q(m.attendees),q(m.summary)])];
    const a = Object.assign(document.createElement("a"),{href:URL.createObjectURL(new Blob([rows.map(r=>r.join(",")).join("\n")],{type:"text/csv"})),download:`${proj.client.replace(/\s+/g,"_")}_${proj.name.replace(/\s+/g,"_")}.csv`});
    a.click();
  };

  const milDone = proj.milestones.filter(m => m.done).length;
  const milPct = pct(milDone, proj.milestones.length);
  const budPct = pct(proj.spent, proj.budget);

  return (
    <div className="min-h-screen bg-gray-50 p-6 font-sans">
      {showShare && <ShareModal proj={proj} dashTitle={dashTitle} updatedAt={updatedAt} onClose={() => setShowShare(false)} />}

      {/* Header */}
      <div className="flex items-start justify-between flex-wrap gap-3 mb-2">
        <div>
          <IT value={dashTitle} onSave={v => touch({ ...state, dashTitle: v })} className="text-2xl font-bold text-gray-800" wide placeholder="Dashboard Title" />
          <div className="flex items-center gap-3 mt-1">
            <span className="text-xs text-gray-400">Click any value to edit</span>
            {saved && <span className="text-xs text-emerald-500 flex items-center gap-1"><Check className="w-3 h-3" />Saved</span>}
            <span className="text-xs text-gray-300">Last updated: {updatedAt}</span>
          </div>
        </div>
        <div className="flex gap-2 flex-wrap">
          <PanelSettings panels={panels} onChange={(k, v) => setPanels(p => ({ ...p, [k]: v }))} />
          <div className="relative">
            <button onClick={() => setShowImport(v => !v)} className="flex items-center gap-1.5 px-3 py-2 bg-white border border-gray-200 text-gray-600 text-sm rounded-lg hover:border-gray-400 shadow-sm">
              <Save className="w-4 h-4" /> Data
            </button>
            {showImport && <div className="absolute right-0 top-10 bg-white border border-gray-200 rounded-xl shadow-lg z-50 p-4 w-64">
              <p className="text-xs font-semibold text-gray-500 mb-3 uppercase tracking-wide">Data Management</p>
              <div className="space-y-2">
                <button onClick={exportJSON} className="flex items-center gap-2 w-full text-sm text-gray-700 hover:text-gray-900 py-1"><Download className="w-3.5 h-3.5" />Export backup (JSON)</button>
                <label className="flex items-center gap-2 w-full text-sm text-gray-700 hover:text-gray-900 py-1 cursor-pointer"><Upload className="w-3.5 h-3.5" />Import backup (JSON)<input type="file" accept=".json" className="hidden" onChange={importJSON} /></label>
                <button onClick={resetAll} className="flex items-center gap-2 w-full text-sm text-red-400 hover:text-red-600 py-1"><RefreshCw className="w-3.5 h-3.5" />Reset all data</button>
              </div>
              {importErr && <p className="text-xs text-red-500 mt-2">{importErr}</p>}
            </div>}
          </div>
          <button onClick={() => setShowShare(true)} className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm rounded-lg shadow-sm">
            <Share2 className="w-4 h-4" /> Share
          </button>
          <button onClick={exportCSV} className="flex items-center gap-2 px-4 py-2 bg-gray-800 hover:bg-gray-700 text-white text-sm rounded-lg shadow-sm">
            <Download className="w-4 h-4" /> CSV
          </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex gap-2 mb-6 flex-wrap items-center">
        {projects.map(p => (
          <div key={p.id} className={`flex items-center gap-1 rounded-lg border transition-all ${activeId === p.id ? "bg-gray-800 border-gray-800" : "bg-white border-gray-200 hover:border-gray-400"}`}>
            <button onClick={() => setActiveId(p.id)} className="flex items-center gap-2 px-3 py-2 text-sm font-medium">
              <span className={`w-2.5 h-2.5 rounded-full shrink-0 ${RAG_DOT[p.rag] || "bg-gray-300"}`} />
              <IT value={p.name} onSave={v => setProjects(projects.map(x => x.id === p.id ? { ...x, name: v } : x))} className={activeId === p.id ? "text-white" : "text-gray-700"} />
            </button>
            {projects.length > 1 && <button onClick={() => removeProject(p.id)} className={`pr-2 ${activeId === p.id ? "text-gray-400 hover:text-gray-200" : "text-gray-300 hover:text-red-400"}`}><X className="w-3.5 h-3.5" /></button>}
          </div>
        ))}
        <button onClick={addProject} className="flex items-center gap-1 px-3 py-2 text-sm text-blue-500 hover:text-blue-700 border border-dashed border-blue-200 rounded-lg hover:border-blue-400">
          <Plus className="w-4 h-4" /> New project
        </button>
      </div>

      {/* Client + Lead */}
      <div className="flex gap-4 mb-5 text-sm text-gray-500">
        <span>Client: <IT value={proj.client} onSave={v => up("client", v)} className="text-gray-700 font-medium" placeholder="Client name" /></span>
        <span>Lead: <IT value={proj.lead} onSave={v => up("lead", v)} className="text-gray-700" /></span>
        <span>Start: <IT value={proj.startDate} onSave={v => up("startDate", v)} className="text-gray-700" placeholder="YYYY-MM-DD" /></span>
        <span>End: <IT value={proj.endDate} onSave={v => up("endDate", v)} className="text-gray-700" placeholder="YYYY-MM-DD" /></span>
      </div>

      {/* Exec Summary + RAG */}
      {panels.execSummary && <Card className="mb-6">
        <div className="flex items-start gap-4 flex-wrap">
          <div className="flex flex-col gap-1.5 shrink-0">
            <span className="text-xs text-gray-500 font-medium">RAG Status</span>
            <IS value={proj.rag} options={["Green","Amber","Red"]} onSave={v => up("rag",v)} colorMap={RAG_BADGE} />
          </div>
          <div className="flex-1 min-w-0">
            <span className="text-xs text-gray-500 font-medium block mb-1">Executive Summary</span>
            <TA value={proj.execSummary} onSave={v => up("execSummary",v)} rows={2} placeholder="Write a 2–3 sentence status summary for the client..." />
          </div>
        </div>
      </Card>}

      {/* KPIs */}
      {panels.kpis && <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
        {[
          { label: "Budget Remaining", val: <IN value={proj.budget-proj.spent} prefix="$" onSave={v => up("spent",proj.budget-v)} />, sub: `${100-budPct}% left`, icon: <DollarSign className="w-5 h-5 text-emerald-500" />, hi: budPct > 90 },
          { label: "Budget Used", val: <IN value={proj.spent} prefix="$" onSave={v => up("spent",v)} />, sub: <>of <IN value={proj.budget} prefix="$" onSave={v => up("budget",v)} /></>, icon: <TrendingUp className="w-5 h-5 text-blue-500" /> },
          { label: "Milestones", val: `${milDone} / ${proj.milestones.length}`, sub: `${milPct}% complete`, icon: <CheckCircle className="w-5 h-5 text-purple-500" /> },
          { label: "Open Tasks", val: proj.tasks.filter(t=>t.status!=="Done"&&t.status!=="Complete").length, sub: `${proj.tasks.length} total`, icon: <Clock className="w-5 h-5 text-amber-500" /> },
        ].map((k,i) => <div key={i} className={`bg-white rounded-xl border ${k.hi?"border-red-300":"border-gray-200"} p-4 shadow-sm`}>
          <div className="flex items-center justify-between mb-2"><span className="text-xs text-gray-500 font-medium">{k.label}</span>{k.icon}</div>
          <div className="text-2xl font-bold text-gray-800">{k.val}</div>
          <div className="text-xs text-gray-400 mt-0.5">{k.sub}</div>
        </div>)}
      </div>}

      {/* Budget + Milestones */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        {panels.budget && <Card>
          <SH title="Budget: Planned vs. Actual" />
          {proj.budgetHistory.length === 0
            ? <p className="text-sm text-gray-300 italic">No budget history yet. Add months below.</p>
            : <ResponsiveContainer width="100%" height={190}>
                <BarChart data={proj.budgetHistory} barCategoryGap="30%">
                  <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                  <XAxis dataKey="month" tick={{fontSize:11}} />
                  <YAxis tick={{fontSize:11}} tickFormatter={v=>`$${(v/1000).toFixed(0)}k`} />
                  <Tooltip formatter={v=>`$${v.toLocaleString()}`} />
                  <Legend wrapperStyle={{fontSize:11}} />
                  <Bar dataKey="planned" name="Planned" fill="#e5e7eb" radius={[4,4,0,0]} />
                  <Bar dataKey="actual" name="Actual" fill="#3b82f6" radius={[4,4,0,0]} />
                </BarChart>
              </ResponsiveContainer>}
          <div className="mt-4"><BudgetBar spent={proj.spent} budget={proj.budget} /></div>
        </Card>}
        {panels.milestones && <Card>
          <SH title="Milestones" onAdd={() => up("milestones",[...proj.milestones,{name:"New milestone",date:"",done:false,variance:0}])} />
          {proj.milestones.length > 0 && <>
            <p className="text-xs text-gray-400 mb-3">{milPct}% complete · {proj.milestones.length-milDone} remaining</p>
            <div className="w-full bg-gray-100 rounded-full h-1.5 mb-4"><div className="bg-purple-500 h-1.5 rounded-full" style={{width:`${milPct}%`}} /></div>
          </>}
          <div className="space-y-2 max-h-52 overflow-y-auto pr-1">
            {proj.milestones.length === 0 && <p className="text-sm text-gray-300 italic">No milestones yet.</p>}
            {proj.milestones.map((m,i) => <div key={i} className="flex items-start gap-2 group">
              <button onClick={() => updMile(i,"done",!m.done)} className="mt-0.5 shrink-0">
                {m.done ? <CheckCircle className="w-4 h-4 text-emerald-500" /> : <Circle className="w-4 h-4 text-gray-300 hover:text-gray-400" />}
              </button>
              <div className="flex-1 min-w-0">
                <IT value={m.name} onSave={v => updMile(i,"name",v)} className={`text-sm ${m.done?"line-through text-gray-400":"text-gray-700"}`} wide />
                <div className="flex items-center gap-2">
                  <IT value={m.date} onSave={v => updMile(i,"date",v)} className="text-xs text-gray-400" placeholder="YYYY-MM-DD" />
                  {m.variance > 0 && <span className="text-xs text-amber-500">+{m.variance}d</span>}
                </div>
              </div>
              <button onClick={() => up("milestones",proj.milestones.filter((_,idx)=>idx!==i))} className="opacity-0 group-hover:opacity-100"><Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button>
            </div>)}
          </div>
        </Card>}
      </div>

      {/* Internal Notes */}
      {panels.notes && <Card className="mb-6">
        <SH title={<><FileText className="w-4 h-4 text-gray-400 inline mr-1.5" />Internal Notes <span className="text-xs text-amber-500 font-normal">(not included in client share)</span></>} />
        <TA value={proj.notes} onSave={v => up("notes",v)} rows={3} placeholder="Internal context, open questions, vendor notes..." />
      </Card>}

      {/* Deliverables + Risks */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        {panels.deliverables && <Card>
          <SH title="Deliverables" onAdd={() => up("deliverables",[...proj.deliverables,{id:Date.now(),name:"New deliverable",status:"Not Started",due:""}])} />
          {proj.deliverables.length === 0 ? <p className="text-sm text-gray-300 italic">No deliverables yet.</p> :
          <table className="w-full text-sm">
            <thead><tr className="text-xs text-gray-400 border-b border-gray-100 text-left"><th className="pb-2 font-medium">Output</th><th className="pb-2 font-medium">Due</th><th className="pb-2 font-medium">Status</th><th className="pb-2 w-5" /></tr></thead>
            <tbody>{proj.deliverables.map(d => <tr key={d.id} className="border-b border-gray-50 last:border-0 group">
              <td className="py-2"><IT value={d.name} onSave={v=>updDeliv(d.id,"name",v)} wide /></td>
              <td className="py-2 text-gray-500"><IT value={d.due} onSave={v=>updDeliv(d.id,"due",v)} placeholder="YYYY-MM-DD" /></td>
              <td className="py-2"><IS value={d.status} options={STATUS_OPTIONS} onSave={v=>updDeliv(d.id,"status",v)} /></td>
              <td className="py-2 text-right"><button onClick={()=>up("deliverables",proj.deliverables.filter(x=>x.id!==d.id))} className="opacity-0 group-hover:opacity-100"><Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button></td>
            </tr>)}</tbody>
          </table>}
        </Card>}
        {panels.risks && <Card>
          <SH title="Risk Log" onAdd={() => up("risks",[...proj.risks,{id:Date.now(),flag:"Amber",item:"New risk",owner:"TBD",mitigation:""}])} />
          {proj.risks.length === 0 ? <p className="text-sm text-gray-300 italic">No risks logged.</p> :
          <div className="space-y-3">{proj.risks.map(r => <div key={r.id} className="flex gap-2 group">
            <IS value={r.flag} options={["Green","Amber","Red"]} onSave={v=>updRisk(r.id,"flag",v)} colorMap={RAG_BADGE} />
            <div className="flex-1 min-w-0">
              <IT value={r.item} onSave={v=>updRisk(r.id,"item",v)} className="text-sm text-gray-700" wide />
              <div className="text-xs text-gray-400 mt-0.5">Owner: <IT value={r.owner} onSave={v=>updRisk(r.id,"owner",v)} className="text-gray-400" /></div>
              <div className="text-xs text-gray-400">Mitigation: <IT value={r.mitigation} onSave={v=>updRisk(r.id,"mitigation",v)} className="text-gray-400" wide /></div>
            </div>
            <button onClick={()=>up("risks",proj.risks.filter(x=>x.id!==r.id))} className="opacity-0 group-hover:opacity-100 shrink-0"><Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button>
          </div>)}</div>}
        </Card>}
      </div>

      {/* Decisions + Open Asks */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        {panels.decisions && <Card>
          <SH title="Decision Log" onAdd={() => up("decisions",[...proj.decisions,{id:Date.now(),date:new Date().toISOString().slice(0,10),decision:"New decision",madeBy:proj.lead}])} />
          {proj.decisions.length === 0 ? <p className="text-sm text-gray-300 italic">No decisions logged.</p> :
          <div className="space-y-2">{proj.decisions.map(d => <div key={d.id} className="flex gap-2 group border-b border-gray-50 pb-2 last:border-0">
            <div className="flex-1 min-w-0">
              <IT value={d.decision} onSave={v=>updDec(d.id,"decision",v)} className="text-sm text-gray-700" wide />
              <div className="text-xs text-gray-400 mt-0.5"><IT value={d.date} onSave={v=>updDec(d.id,"date",v)} className="text-gray-400" /> · <IT value={d.madeBy} onSave={v=>updDec(d.id,"madeBy",v)} className="text-gray-400" /></div>
            </div>
            <button onClick={()=>up("decisions",proj.decisions.filter(x=>x.id!==d.id))} className="opacity-0 group-hover:opacity-100 shrink-0"><Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button>
          </div>)}</div>}
        </Card>}
        {panels.openAsks && <Card>
          <SH title="Open Asks from Client" onAdd={() => up("openAsks",[...proj.openAsks,{id:Date.now(),ask:"New ask",askedOf:"Client",dueBy:"",done:false}])} />
          {proj.openAsks.length === 0 ? <p className="text-sm text-gray-300 italic">No open asks.</p> :
          <div className="space-y-2">{proj.openAsks.map(a => <div key={a.id} className="flex items-start gap-2 group border-b border-gray-50 pb-2 last:border-0">
            <button onClick={()=>updAsk(a.id,"done",!a.done)} className="mt-0.5 shrink-0">
              {a.done ? <CheckCircle className="w-4 h-4 text-emerald-500" /> : <Circle className="w-4 h-4 text-gray-300 hover:text-gray-400" />}
            </button>
            <div className="flex-1 min-w-0">
              <IT value={a.ask} onSave={v=>updAsk(a.id,"ask",v)} className={`text-sm ${a.done?"line-through text-gray-400":"text-gray-700"}`} wide />
              <div className="text-xs text-gray-400 mt-0.5">Asked of: <IT value={a.askedOf} onSave={v=>updAsk(a.id,"askedOf",v)} className="text-gray-400" /> · Due: <IT value={a.dueBy} onSave={v=>updAsk(a.id,"dueBy",v)} className="text-gray-400" placeholder="YYYY-MM-DD" /></div>
            </div>
            <button onClick={()=>up("openAsks",proj.openAsks.filter(x=>x.id!==a.id))} className="opacity-0 group-hover:opacity-100 shrink-0"><Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button>
          </div>)}</div>}
        </Card>}
      </div>

      {/* Meeting Log */}
      {panels.meetings && <Card className="mb-6">
        <SH title="Meeting Log" onAdd={() => up("meetings",[...proj.meetings,{id:Date.now(),date:new Date().toISOString().slice(0,10),attendees:proj.lead+", Client",summary:""}])} />
        {proj.meetings.length === 0 ? <p className="text-sm text-gray-300 italic">No meetings logged.</p> :
        <table className="w-full text-sm">
          <thead><tr className="text-xs text-gray-400 border-b border-gray-100 text-left"><th className="pb-2 font-medium w-24">Date</th><th className="pb-2 font-medium w-40">Attendees</th><th className="pb-2 font-medium">Summary</th><th className="pb-2 w-5" /></tr></thead>
          <tbody>{proj.meetings.map(m => <tr key={m.id} className="border-b border-gray-50 last:border-0 group">
            <td className="py-2 text-gray-500 align-top"><IT value={m.date} onSave={v=>updMeet(m.id,"date",v)} /></td>
            <td className="py-2 text-gray-500 align-top"><IT value={m.attendees} onSave={v=>updMeet(m.id,"attendees",v)} wide /></td>
            <td className="py-2 text-gray-700 align-top"><IT value={m.summary} onSave={v=>updMeet(m.id,"summary",v)} wide /></td>
            <td className="py-2 align-top text-right"><button onClick={()=>up("meetings",proj.meetings.filter(x=>x.id!==m.id))} className="opacity-0 group-hover:opacity-100"><Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button></td>
          </tr>)}</tbody>
        </table>}
      </Card>}

      {/* Tasks */}
      {panels.tasks && <DragTable
        tasks={proj.tasks}
        onUpdate={updTask}
        onDelete={tid => up("tasks",proj.tasks.filter(t=>t.id!==tid))}
        onAdd={() => up("tasks",[...proj.tasks,{id:Date.now(),name:"New task",status:"Not Started",owner:proj.lead,due:""}])}
        onReorder={r => up("tasks",r)}
      />}
    </div>
  );
}

