import { useState, useRef } from "react";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from "recharts";
import {
  CheckCircle, Circle, Clock, DollarSign, TrendingUp, Plus, Trash2, Pencil,
  Check, X, Download, GripVertical, FileText, Settings, Eye, EyeOff,
  Share2, Link, Mail, FileDown, Copy, ExternalLink, RefreshCw, Save, Upload
} from "lucide-react";
import PptxGenJS from "pptxgenjs";
import * as XLSX from "xlsx";

const blankProject = (id) => ({
  id, name: "New Project", client: "Client Name", lead: "Addie",
  status: "Planning", rag: "Green", budget: 0, spent: 0,
  startDate: "", endDate: "",
  notes: "", execSummary: "",
  tasks: [], milestones: [], deliverables: [],
  risks: [], decisions: [], openAsks: [], meetings: [],
  budgetHistory: [],
});

const STORAGE_KEY = "consulting_dashboard_v1";
const DEFAULT_PANELS = {
  execSummary: true, kpis: true, budget: true, milestones: true,
  notes: false, deliverables: true, risks: true, decisions: true,
  openAsks: true, meetings: true, tasks: true,
};
const PANEL_LABELS = {
  execSummary: "Executive Summary", kpis: "KPI Cards", budget: "Budget Chart",
  milestones: "Milestones", notes: "Internal Notes (not shared)", deliverables: "Deliverables",
  risks: "Risk Log", decisions: "Decision Log", openAsks: "Open Asks from Client",
  meetings: "Meeting Log", tasks: "Task Table",
};
const STATUS_COLOR = {
  "Done": "bg-emerald-100 text-emerald-700", "Complete": "bg-emerald-100 text-emerald-700",
  "In Progress": "bg-blue-100 text-blue-700", "In Review": "bg-blue-100 text-blue-700",
  "Not Started": "bg-gray-100 text-gray-500", "Planning": "bg-amber-100 text-amber-700",
};
const STATUS_OPTIONS = ["Not Started", "In Progress", "In Review", "Done", "Complete", "Planning"];
const RAG_DOT = { Green: "bg-emerald-500", Amber: "bg-amber-400", Red: "bg-red-500" };
const RAG_BADGE = { Green: "text-emerald-700 bg-emerald-50 border-emerald-200", Amber: "text-amber-700 bg-amber-50 border-amber-200", Red: "text-red-700 bg-red-50 border-red-200" };
const pct = (a, b) => b === 0 ? 0 : Math.min(100, Math.round((a / b) * 100));
const now = () => new Date().toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "2-digit", minute: "2-digit" });

function loadState() {
  try { const ls = localStorage.getItem(STORAGE_KEY); if (ls) return JSON.parse(ls); } catch {}
  return null;
}
function saveState(data) {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); } catch {}
}

// ── INLINE EDITORS ─────────────────────────────────────────────────────────────
function IT({ value, onSave, className = "", wide = false, placeholder = "Click to edit" }) {
  const [ed, setEd] = useState(false); const [v, setV] = useState(value);
  const commit = () => { onSave(v); setEd(false); };
  const cancel = () => { setV(value); setEd(false); };
  if (ed) return <span className="inline-flex items-center gap-1">
    <input autoFocus placeholder={placeholder} className={`border-b border-blue-400 outline-none bg-transparent text-sm px-0.5 ${wide ? "w-56" : "w-36"}`}
      value={v} onChange={e => setV(e.target.value)}
      onKeyDown={e => { if (e.key === "Enter") commit(); if (e.key === "Escape") cancel(); }} />
    <Check className="w-3.5 h-3.5 text-emerald-500 cursor-pointer shrink-0" onClick={commit} />
    <X className="w-3.5 h-3.5 text-gray-400 cursor-pointer shrink-0" onClick={cancel} />
  </span>;
  return <span className={`group inline-flex items-center gap-1 cursor-pointer ${className}`} onClick={() => setEd(true)}>
    {value || <span className="text-gray-300 italic text-sm">{placeholder}</span>}
    <Pencil className="w-3 h-3 text-gray-300 group-hover:text-gray-400 opacity-0 group-hover:opacity-100 shrink-0" />
  </span>;
}
function IN({ value, onSave, prefix = "" }) {
  const [ed, setEd] = useState(false); const [v, setV] = useState(value);
  const commit = () => { const n = parseFloat(v); if (!isNaN(n)) onSave(n); setEd(false); };
  const cancel = () => { setV(value); setEd(false); };
  if (ed) return <span className="inline-flex items-center gap-1">
    <input autoFocus className="border-b border-blue-400 outline-none bg-transparent w-24 text-sm"
      value={v} onChange={e => setV(e.target.value)}
      onKeyDown={e => { if (e.key === "Enter") commit(); if (e.key === "Escape") cancel(); }} />
    <Check className="w-3.5 h-3.5 text-emerald-500 cursor-pointer" onClick={commit} />
    <X className="w-3.5 h-3.5 text-gray-400 cursor-pointer" onClick={cancel} />
  </span>;
  return <span className="group inline-flex items-center gap-1 cursor-pointer" onClick={() => setEd(true)}>
    {prefix}{value.toLocaleString()}<Pencil className="w-3 h-3 text-gray-300 group-hover:text-gray-400 opacity-0 group-hover:opacity-100" />
  </span>;
}
function IS({ value, options, onSave, colorMap }) {
  const [ed, setEd] = useState(false);
  if (ed) return <select autoFocus className="text-xs border border-gray-200 rounded px-1 py-0.5 bg-white"
    value={value} onChange={e => { onSave(e.target.value); setEd(false); }} onBlur={() => setEd(false)}>
    {options.map(o => <option key={o}>{o}</option>)}
  </select>;
  const cls = colorMap ? (colorMap[value] || "bg-gray-100 text-gray-500 border-gray-200") : (STATUS_COLOR[value] || "bg-gray-100 text-gray-500");
  return <span className={`px-2 py-0.5 rounded-full text-xs font-medium cursor-pointer border ${cls}`} onClick={() => setEd(true)}>{value}</span>;
}
function TA({ value, onSave, rows = 3, placeholder = "Click to add..." }) {
  const [ed, setEd] = useState(false); const [v, setV] = useState(value);
  return ed
    ? <div><textarea autoFocus rows={rows} placeholder={placeholder} className="w-full text-sm text-gray-700 border border-blue-200 rounded-lg p-3 outline-none resize-none focus:border-blue-400" value={v} onChange={e => setV(e.target.value)} />
        <div className="flex gap-2 mt-1">
          <button onClick={() => { onSave(v); setEd(false); }} className="flex items-center gap-1 text-xs text-emerald-600 font-medium"><Check className="w-3.5 h-3.5" />Save</button>
          <button onClick={() => { setV(value); setEd(false); }} className="flex items-center gap-1 text-xs text-gray-400"><X className="w-3.5 h-3.5" />Cancel</button>
        </div></div>
    : <div className="group relative cursor-pointer" onClick={() => setEd(true)}>
        <p className="text-sm text-gray-600 leading-relaxed whitespace-pre-wrap min-h-8">{value || <span className="text-gray-300 italic">{placeholder}</span>}</p>
        <Pencil className="w-3 h-3 text-gray-300 group-hover:text-gray-400 absolute top-0 right-0 opacity-0 group-hover:opacity-100" />
      </div>;
}
function Card({ children, className = "" }) { return <div className={`bg-white rounded-xl border border-gray-200 shadow-sm p-5 ${className}`}>{children}</div>; }
function SH({ title, onAdd, addLabel = "Add" }) {
  return <div className="flex items-center justify-between mb-3">
    <h2 className="text-sm font-semibold text-gray-700">{title}</h2>
    {onAdd && <button onClick={onAdd} className="flex items-center gap-1 text-xs text-blue-500 hover:text-blue-700"><Plus className="w-3.5 h-3.5" />{addLabel}</button>}
  </div>;
}
function BudgetBar({ spent, budget }) {
  const p = pct(spent, budget);
  const col = p > 90 ? "bg-red-500" : p > 70 ? "bg-amber-400" : "bg-emerald-500";
  const projected = budget > 0 ? Math.round(spent / Math.max(p, 1) * 100) : 0;
  return <div className="w-full">
    <div className="flex justify-between text-xs text-gray-500 mb-1"><span>${spent.toLocaleString()} spent</span><span>${budget.toLocaleString()} budget</span></div>
    <div className="w-full bg-gray-100 rounded-full h-2"><div className={`${col} h-2 rounded-full`} style={{ width: `${p}%` }} /></div>
    <div className="text-xs text-gray-400 mt-1">{p}% utilized{budget > 0 ? ` · projected finish: $${projected.toLocaleString()}` : ""}</div>
  </div>;
}

// ── EXPORTS ───────────────────────────────────────────────────────────────────
function exportCSV(proj) {
  const q = s => `"${String(s || "").replace(/"/g, '""')}"`;
  const rows = [
    ["Project", proj.name], ["Client", proj.client], ["Status", proj.status], ["RAG", proj.rag],
    ["Budget", proj.budget], ["Spent", proj.spent], ["Remaining", proj.budget - proj.spent], [],
    ["EXEC SUMMARY"], [q(proj.execSummary)], [],
    ["TASKS"], ["Task", "Owner", "Due", "Status"], ...proj.tasks.map(t => [q(t.name), t.owner, t.due, t.status]), [],
    ["MILESTONES"], ["Milestone", "Date", "Done"], ...proj.milestones.map(m => [q(m.name), m.date, m.done ? "Yes" : "No"]), [],
    ["DELIVERABLES"], ["Deliverable", "Status", "Due"], ...proj.deliverables.map(d => [q(d.name), d.status, d.due]), [],
    ["RISKS"], ["Flag", "Risk", "Owner", "Mitigation"], ...proj.risks.map(r => [r.flag, q(r.item), r.owner, q(r.mitigation)]), [],
    ["DECISIONS"], ["Date", "Decision", "Made By"], ...proj.decisions.map(d => [d.date, q(d.decision), d.madeBy]), [],
    ["OPEN ASKS"], ["Ask", "Asked Of", "Due By", "Done"], ...proj.openAsks.map(a => [q(a.ask), a.askedOf, a.dueBy, a.done ? "Yes" : "No"]),
  ];
  const a = Object.assign(document.createElement("a"), { href: URL.createObjectURL(new Blob([rows.map(r => r.join(",")).join("\n")], { type: "text/csv" })), download: `${proj.client.replace(/\s+/g, "_")}_${proj.name.replace(/\s+/g, "_")}.csv` });
  a.click();
}

function exportExcel(proj) {
  const wb = XLSX.utils.book_new();
  const addSheet = (name, data) => XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(data), name);
  addSheet("Summary", [
    ["Project", proj.name], ["Client", proj.client], ["Lead", proj.lead],
    ["Status", proj.status], ["RAG", proj.rag],
    ["Budget", proj.budget], ["Spent", proj.spent], ["Remaining", proj.budget - proj.spent],
    [], ["Executive Summary"], [proj.execSummary],
  ]);
  addSheet("Tasks", [["Task", "Owner", "Due", "Status"], ...proj.tasks.map(t => [t.name, t.owner, t.due, t.status])]);
  addSheet("Milestones", [["Milestone", "Date", "Done", "Variance"], ...proj.milestones.map(m => [m.name, m.date, m.done ? "Yes" : "No", m.variance || 0])]);
  addSheet("Deliverables", [["Deliverable", "Status", "Due"], ...proj.deliverables.map(d => [d.name, d.status, d.due])]);
  addSheet("Risks", [["Flag", "Risk", "Owner", "Mitigation"], ...proj.risks.map(r => [r.flag, r.item, r.owner, r.mitigation])]);
  addSheet("Decisions", [["Date", "Decision", "Made By"], ...proj.decisions.map(d => [d.date, d.decision, d.madeBy])]);
  addSheet("Open Asks", [["Ask", "Asked Of", "Due By", "Done"], ...proj.openAsks.map(a => [a.ask, a.askedOf, a.dueBy, a.done ? "Yes" : "No"])]);
  addSheet("Meetings", [["Date", "Attendees", "Summary"], ...proj.meetings.map(m => [m.date, m.attendees, m.summary])]);
  XLSX.writeFile(wb, `${proj.client.replace(/\s+/g, "_")}_${proj.name.replace(/\s+/g, "_")}.xlsx`);
}

function exportPPT(proj, updatedAt) {
  const pptx = new PptxGenJS();
  pptx.layout = "LAYOUT_WIDE";
  const DARK = "1a1a2e", ACCENT = "3b82f6", LIGHT = "f8fafc", GRAY = "64748b";
  const ragColor = { Green: "10b981", Amber: "f59e0b", Red: "ef4444" };
  const milDone = proj.milestones.filter(m => m.done).length;
  const budPct = pct(proj.spent, proj.budget);

  // Slide 1 — Cover
  let s = pptx.addSlide();
  s.background = { color: DARK };
  s.addText(proj.name, { x: 0.5, y: 1.5, w: 12, h: 1.2, fontSize: 36, bold: true, color: "FFFFFF" });
  s.addText(`${proj.client}  ·  Lead: ${proj.lead}  ·  As of ${updatedAt}`, { x: 0.5, y: 2.9, w: 12, h: 0.4, fontSize: 14, color: "94a3b8" });
  s.addShape(pptx.ShapeType.rect, { x: 0.5, y: 3.5, w: 1.8, h: 0.45, fill: { color: ragColor[proj.rag] || "64748b" }, line: { color: ragColor[proj.rag] || "64748b" } });
  s.addText(proj.rag, { x: 0.5, y: 3.5, w: 1.8, h: 0.45, fontSize: 13, bold: true, color: "FFFFFF", align: "center" });
  s.addText(proj.execSummary || "No summary provided.", { x: 0.5, y: 4.2, w: 12, h: 1.2, fontSize: 13, color: "cbd5e1", wrap: true });

  // Slide 2 — KPIs
  s = pptx.addSlide();
  s.background = { color: LIGHT };
  s.addText("Project Snapshot", { x: 0.5, y: 0.3, w: 12, h: 0.5, fontSize: 22, bold: true, color: DARK });
  const kpis = [
    { label: "Budget", val: `$${proj.budget.toLocaleString()}`, sub: `$${proj.spent.toLocaleString()} spent` },
    { label: "Remaining", val: `$${(proj.budget - proj.spent).toLocaleString()}`, sub: `${100 - budPct}% left` },
    { label: "Milestones", val: `${milDone}/${proj.milestones.length}`, sub: `${pct(milDone, proj.milestones.length)}% done` },
    { label: "Open Tasks", val: `${proj.tasks.filter(t => t.status !== "Done" && t.status !== "Complete").length}`, sub: `of ${proj.tasks.length} total` },
  ];
  kpis.forEach((k, i) => {
    const x = 0.4 + i * 3.15;
    s.addShape(pptx.ShapeType.rect, { x, y: 1.0, w: 2.9, h: 1.6, fill: { color: "FFFFFF" }, line: { color: "e2e8f0", pt: 1 } });
    s.addText(k.label, { x, y: 1.1, w: 2.9, h: 0.35, fontSize: 10, color: GRAY, align: "center" });
    s.addText(k.val, { x, y: 1.45, w: 2.9, h: 0.7, fontSize: 28, bold: true, color: DARK, align: "center" });
    s.addText(k.sub, { x, y: 2.15, w: 2.9, h: 0.3, fontSize: 10, color: GRAY, align: "center" });
  });
  // Budget bar
  s.addText("Budget Utilization", { x: 0.5, y: 2.9, w: 6, h: 0.3, fontSize: 11, bold: true, color: DARK });
  s.addShape(pptx.ShapeType.rect, { x: 0.5, y: 3.25, w: 12, h: 0.3, fill: { color: "e2e8f0" }, line: { color: "e2e8f0" } });
  if (budPct > 0) s.addShape(pptx.ShapeType.rect, { x: 0.5, y: 3.25, w: Math.max(0.1, 12 * budPct / 100), h: 0.3, fill: { color: budPct > 90 ? "ef4444" : budPct > 70 ? "f59e0b" : "10b981" }, line: { color: "transparent" } });
  s.addText(`${budPct}% utilized`, { x: 0.5, y: 3.65, w: 12, h: 0.25, fontSize: 10, color: GRAY });

  // Slide 3 — Milestones + Deliverables
  s = pptx.addSlide();
  s.background = { color: LIGHT };
  s.addText("Milestones & Deliverables", { x: 0.5, y: 0.3, w: 12, h: 0.5, fontSize: 22, bold: true, color: DARK });
  proj.milestones.slice(0, 8).forEach((m, i) => {
    const y = 1.0 + i * 0.45;
    s.addShape(pptx.ShapeType.ellipse, { x: 0.5, y: y + 0.05, w: 0.25, h: 0.25, fill: { color: m.done ? "10b981" : "e2e8f0" }, line: { color: m.done ? "10b981" : "cbd5e1" } });
    s.addText(`${m.name}  ·  ${m.date}${m.variance > 0 ? `  (+${m.variance}d)` : ""}`, { x: 0.9, y, w: 5.5, h: 0.35, fontSize: 11, color: m.done ? GRAY : DARK, strike: m.done });
  });
  if (proj.deliverables.length) {
    s.addText("Deliverables", { x: 7, y: 0.9, w: 5.5, h: 0.35, fontSize: 13, bold: true, color: DARK });
    proj.deliverables.slice(0, 8).forEach((d, i) => {
      s.addText(`${d.name}`, { x: 7, y: 1.4 + i * 0.45, w: 3.5, h: 0.35, fontSize: 11, color: DARK });
      s.addText(d.status, { x: 10.6, y: 1.4 + i * 0.45, w: 1.8, h: 0.3, fontSize: 10, color: GRAY, align: "right" });
    });
  }

  // Slide 4 — Risks + Open Asks
  if (proj.risks.length || proj.openAsks.length) {
    s = pptx.addSlide();
    s.background = { color: LIGHT };
    s.addText("Risks & Open Asks", { x: 0.5, y: 0.3, w: 12, h: 0.5, fontSize: 22, bold: true, color: DARK });
    proj.risks.slice(0, 6).forEach((r, i) => {
      const y = 1.0 + i * 0.7;
      s.addShape(pptx.ShapeType.rect, { x: 0.5, y, w: 0.7, h: 0.3, fill: { color: ragColor[r.flag] || "64748b" }, line: { color: "transparent" } });
      s.addText(r.flag, { x: 0.5, y, w: 0.7, h: 0.3, fontSize: 9, bold: true, color: "FFFFFF", align: "center" });
      s.addText(r.item, { x: 1.3, y, w: 5, h: 0.3, fontSize: 11, color: DARK });
      s.addText(`Mitigation: ${r.mitigation}`, { x: 1.3, y: y + 0.32, w: 5, h: 0.28, fontSize: 9, color: GRAY });
    });
    const openAsks = proj.openAsks.filter(a => !a.done);
    if (openAsks.length) {
      s.addText("Open Asks from Client", { x: 7, y: 0.9, w: 5.5, h: 0.35, fontSize: 13, bold: true, color: DARK });
      openAsks.slice(0, 6).forEach((a, i) => {
        s.addText(`• ${a.ask}`, { x: 7, y: 1.4 + i * 0.55, w: 5.5, h: 0.3, fontSize: 11, color: DARK });
        s.addText(`${a.askedOf}  ·  Due ${a.dueBy}`, { x: 7, y: 1.72 + i * 0.55, w: 5.5, h: 0.25, fontSize: 9, color: GRAY });
      });
    }
  }

  // Slide 5 — Decision Log
  if (proj.decisions.length) {
    s = pptx.addSlide();
    s.background = { color: LIGHT };
    s.addText("Decision Log", { x: 0.5, y: 0.3, w: 12, h: 0.5, fontSize: 22, bold: true, color: DARK });
    proj.decisions.slice(0, 8).forEach((d, i) => {
      const y = 1.0 + i * 0.65;
      s.addText(d.date, { x: 0.5, y, w: 1.5, h: 0.3, fontSize: 10, color: GRAY });
      s.addText(d.decision, { x: 2.2, y, w: 8, h: 0.3, fontSize: 11, color: DARK });
      s.addText(`— ${d.madeBy}`, { x: 2.2, y: y + 0.32, w: 8, h: 0.25, fontSize: 9, color: GRAY });
    });
  }

  pptx.writeFile({ fileName: `${proj.client.replace(/\s+/g, "_")}_${proj.name.replace(/\s+/g, "_")}_status.pptx` });
}

function exportPDF(proj) {
  window.print();
}

function buildClientHTML(proj, updatedAt) {
  const ragBg = { Green: "#d1fae5", Amber: "#fef3c7", Red: "#fee2e2" };
  const ragTxt = { Green: "#065f46", Amber: "#92400e", Red: "#991b1b" };
  const scBg = { "Done": "#d1fae5", "Complete": "#d1fae5", "In Progress": "#dbeafe", "In Review": "#dbeafe", "Not Started": "#f3f4f6", "Planning": "#fef3c7" };
  const scTxt = { "Done": "#065f46", "Complete": "#065f46", "In Progress": "#1e40af", "In Review": "#1e40af", "Not Started": "#6b7280", "Planning": "#92400e" };
  const badge = v => `<span style="background:${scBg[v] || "#f3f4f6"};color:${scTxt[v] || "#6b7280"};padding:2px 8px;border-radius:999px;font-size:11px;font-weight:600">${v}</span>`;
  const p = pct(proj.spent, proj.budget);
  const barCol = p > 90 ? "#ef4444" : p > 70 ? "#f59e0b" : "#10b981";
  const milDone = proj.milestones.filter(m => m.done).length;
  return `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>${proj.name} — Status</title>
<style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background:#f9fafb;color:#111827;padding:40px 24px}
.wrap{max-width:860px;margin:0 auto}.header{background:#fff;border-radius:16px;border:1px solid #e5e7eb;padding:28px 32px;margin-bottom:24px}
.header h1{font-size:22px;font-weight:700}.sub{font-size:13px;color:#6b7280;margin-top:4px}
.rag{display:inline-block;padding:4px 14px;border-radius:999px;font-size:12px;font-weight:700;margin-top:12px}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:24px}
.grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:24px}
.card{background:#fff;border-radius:12px;border:1px solid #e5e7eb;padding:20px;margin-bottom:0}
.card h2{font-size:13px;font-weight:600;color:#374151;margin-bottom:12px}
.kpi-val{font-size:26px;font-weight:700}.kpi-sub{font-size:11px;color:#9ca3af;margin-top:2px}
table{width:100%;border-collapse:collapse;font-size:13px}th{text-align:left;font-size:11px;color:#9ca3af;font-weight:500;padding-bottom:8px;border-bottom:1px solid #f3f4f6}
td{padding:8px 0;border-bottom:1px solid #f9fafb;color:#374151;vertical-align:top}
.ms-row{display:flex;align-items:flex-start;gap:8px;margin-bottom:8px}
.ms-dot{width:16px;height:16px;border-radius:50%;border:2px solid #d1d5db;margin-top:2px;flex-shrink:0}.ms-done{background:#10b981;border-color:#10b981}
.row{padding:8px 0;border-bottom:1px solid #f9fafb}
.footer{text-align:center;font-size:11px;color:#d1d5db;margin-top:32px}
@media(max-width:600px){.grid4{grid-template-columns:1fr 1fr}.grid2{grid-template-columns:1fr}}
</style></head><body><div class="wrap">
<div class="header">
  <div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:12px">
    <div><h1>${proj.name}</h1><div class="sub">${proj.client} · Lead: ${proj.lead} · As of ${updatedAt}</div></div>
    <span class="rag" style="background:${ragBg[proj.rag] || "#f3f4f6"};color:${ragTxt[proj.rag] || "#374151"}">${proj.rag}</span>
  </div>
  <div style="margin-top:16px;font-size:13px;color:#4b5563;line-height:1.6">${proj.execSummary || "<em>No summary provided.</em>"}</div>
</div>
<div class="grid4">
  <div class="card"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Budget Remaining</div><div class="kpi-val">$${(proj.budget - proj.spent).toLocaleString()}</div><div class="kpi-sub">${100 - p}% left</div></div>
  <div class="card"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Budget Used</div><div class="kpi-val">$${proj.spent.toLocaleString()}</div><div class="kpi-sub">of $${proj.budget.toLocaleString()}</div></div>
  <div class="card"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Milestones</div><div class="kpi-val">${milDone}/${proj.milestones.length}</div><div class="kpi-sub">${pct(milDone, proj.milestones.length)}% complete</div></div>
  <div class="card"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Open Tasks</div><div class="kpi-val">${proj.tasks.filter(t => t.status !== "Done" && t.status !== "Complete").length}</div><div class="kpi-sub">${proj.tasks.length} total</div></div>
</div>
${proj.budget > 0 ? `<div style="margin-bottom:20px"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Budget: $${proj.spent.toLocaleString()} of $${proj.budget.toLocaleString()} (${p}%)</div><div style="background:#f3f4f6;border-radius:999px;height:8px"><div style="background:${barCol};height:8px;border-radius:999px;width:${p}%"></div></div></div>` : ""}
<div class="grid2">
  <div class="card"><h2>Milestones</h2>${proj.milestones.length ? proj.milestones.map(m => `<div class="ms-row"><div class="ms-dot${m.done ? " ms-done" : ""}"></div><div><div style="font-size:13px;color:${m.done ? "#9ca3af" : "#374151"};${m.done ? "text-decoration:line-through" : ""}">${m.name}</div><div style="font-size:11px;color:#9ca3af">${m.date}</div></div></div>`).join("") : "<p style='font-size:13px;color:#d1d5db;font-style:italic'>No milestones.</p>"}</div>
  <div class="card"><h2>Deliverables</h2>${proj.deliverables.length ? `<table><thead><tr><th>Output</th><th>Due</th><th>Status</th></tr></thead><tbody>${proj.deliverables.map(d => `<tr><td>${d.name}</td><td style="color:#6b7280">${d.due}</td><td>${badge(d.status)}</td></tr>`).join("")}</tbody></table>` : "<p style='font-size:13px;color:#d1d5db;font-style:italic'>No deliverables.</p>"}</div>
</div>
<div class="grid2">
  <div class="card"><h2>Risk Log</h2>${proj.risks.length ? proj.risks.map(r => `<div class="row"><div style="display:flex;align-items:center;gap:8px;margin-bottom:4px"><span style="background:${ragBg[r.flag] || "#f3f4f6"};color:${ragTxt[r.flag] || "#374151"};padding:1px 8px;border-radius:999px;font-size:11px;font-weight:600">${r.flag}</span><span style="font-size:13px">${r.item}</span></div><div style="font-size:11px;color:#9ca3af">Owner: ${r.owner} · ${r.mitigation}</div></div>`).join("") : "<p style='font-size:13px;color:#d1d5db;font-style:italic'>No risks logged.</p>"}</div>
  <div class="card"><h2>Open Asks from Client</h2>${proj.openAsks.length ? proj.openAsks.map(a => `<div class="row" style="display:flex;align-items:flex-start;gap:8px"><div style="width:14px;height:14px;border-radius:50%;background:${a.done ? "#10b981" : "#e5e7eb"};margin-top:2px;flex-shrink:0"></div><div><div style="font-size:13px;color:${a.done ? "#9ca3af" : "#374151"};${a.done ? "text-decoration:line-through" : ""}">${a.ask}</div><div style="font-size:11px;color:#9ca3af">${a.askedOf} · Due ${a.dueBy}</div></div></div>`).join("") : "<p style='font-size:13px;color:#d1d5db;font-style:italic'>No open asks.</p>"}</div>
</div>
${proj.decisions.length ? `<div class="card" style="margin-bottom:20px"><h2>Decision Log</h2><table><thead><tr><th>Date</th><th>Decision</th><th>Made By</th></tr></thead><tbody>${proj.decisions.map(d => `<tr><td style="color:#6b7280;white-space:nowrap">${d.date}</td><td>${d.decision}</td><td style="color:#6b7280">${d.madeBy}</td></tr>`).join("")}</tbody></table></div>` : ""}
<div class="footer">Prepared by ${proj.lead} · ${proj.client} · Last updated ${updatedAt}</div>
</div></body></html>`;
}

function buildShareURL(proj) {
  try { return `${window.location.href.split("?")[0]}?view=${btoa(encodeURIComponent(JSON.stringify(proj)))}`; }
  catch { return window.location.href; }
}

// ── SHARE MODAL ────────────────────────────────────────────────────────────────
function ShareModal({ proj, updatedAt, onClose }) {
  const [copied, setCopied] = useState(false);
  const [emailSent, setEmailSent] = useState(false);
  const [sending, setSending] = useState(false);
  const [emailTo, setEmailTo] = useState("");
  const shareURL = buildShareURL(proj);

  const copyLink = () => {
    navigator.clipboard.writeText(shareURL).then(() => { setCopied(true); setTimeout(() => setCopied(false), 2000); });
  };
  const downloadHTML = () => {
    const html = buildClientHTML(proj, updatedAt);
    const a = Object.assign(document.createElement("a"), { href: URL.createObjectURL(new Blob([html], { type: "text/html" })), download: `${proj.client.replace(/\s+/g, "_")}_${proj.name.replace(/\s+/g, "_")}_status.html` });
    a.click();
  };
  const sendEmail = async () => {
    if (!emailTo.trim()) return;
    setSending(true);
    try {
      const apiKey = import.meta.env.VITE_ANTHROPIC_API_KEY;
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json", "x-api-key": apiKey, "anthropic-version": "2023-06-01", "anthropic-dangerous-direct-browser-access": "true" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514", max_tokens: 1000,
          system: "Draft a concise professional project status email. Return ONLY a JSON object with keys: subject (string) and body (string). No markdown, no preamble.",
          messages: [{ role: "user", content: `Draft a brief project status update. Project: ${proj.name}. Client: ${proj.client}. RAG: ${proj.rag}. Summary: ${proj.execSummary}. Milestones done: ${proj.milestones.filter(m => m.done).length}/${proj.milestones.length}. Budget used: $${proj.spent} of $${proj.budget}. Open asks: ${proj.openAsks.filter(a => !a.done).map(a => a.ask).join("; ") || "none"}. Under 150 words. Sign off as ${proj.lead}.` }]
        })
      });
      const data = await res.json();
      const text = data.content?.find(b => b.type === "text")?.text || "";
      let parsed; try { parsed = JSON.parse(text.replace(/```json|```/g, "").trim()); } catch { parsed = { subject: `${proj.name} — Status Update`, body: text }; }
      window.open(`https://mail.google.com/mail/?view=cm&to=${encodeURIComponent(emailTo)}&su=${encodeURIComponent(parsed.subject)}&body=${encodeURIComponent(parsed.body + "\n\nFull dashboard: " + shareURL)}`, "_blank");
    } catch {
      window.open(`https://mail.google.com/mail/?view=cm&to=${encodeURIComponent(emailTo)}&su=${encodeURIComponent(proj.name + " — Status Update")}&body=${encodeURIComponent(proj.execSummary + "\n\nFull dashboard: " + shareURL)}`, "_blank");
    }
    setEmailSent(true); setSending(false);
  };

  return <div className="fixed inset-0 bg-black bg-opacity-40 z-50 flex items-center justify-center p-4" onClick={onClose}>
    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-6" onClick={e => e.stopPropagation()}>
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2"><Share2 className="w-5 h-5 text-gray-600" /><h2 className="text-base font-semibold text-gray-800">Share with Client</h2></div>
        <button onClick={onClose}><X className="w-5 h-5 text-gray-400 hover:text-gray-600" /></button>
      </div>
      <div className="text-sm font-semibold text-gray-800 mb-1">{proj.name} — {proj.client}</div>
      <div className="text-xs text-gray-400 mb-4">Last updated: {updatedAt}</div>
      <div className="p-3 bg-amber-50 border border-amber-200 rounded-lg mb-4 text-xs text-amber-700">
        <strong>Note:</strong> Internal Notes are excluded from all share formats. Review Risk Log before sharing.
      </div>
      {[
        { icon: <Link className="w-4 h-4 text-blue-500" />, title: "Shareable Link", desc: "Read-only snapshot URL.", action: <div className="flex gap-2"><input readOnly value={shareURL} className="flex-1 text-xs border border-gray-200 rounded-lg px-3 py-2 bg-gray-50 text-gray-500 truncate" /><button onClick={copyLink} className={`flex items-center gap-1 px-3 py-2 rounded-lg text-xs font-medium ${copied ? "bg-emerald-500 text-white" : "bg-gray-800 text-white"}`}>{copied ? <><Check className="w-3.5 h-3.5" />Copied</> : <><Copy className="w-3.5 h-3.5" />Copy</>}</button></div> },
        { icon: <Mail className="w-4 h-4 text-purple-500" />, title: "Send via Gmail", desc: "AI-drafts a status email and opens Gmail.", action: <div className="flex gap-2"><input value={emailTo} onChange={e => setEmailTo(e.target.value)} placeholder="client@email.com" className="flex-1 text-xs border border-gray-200 rounded-lg px-3 py-2 outline-none" /><button onClick={sendEmail} disabled={sending || !emailTo.trim()} className={`flex items-center gap-1 px-3 py-2 rounded-lg text-xs font-medium ${emailSent ? "bg-emerald-500 text-white" : sending ? "bg-gray-200 text-gray-400" : "bg-purple-600 text-white"} disabled:opacity-50`}>{emailSent ? "Opened" : sending ? "Drafting..." : <><ExternalLink className="w-3.5 h-3.5" />Gmail</>}</button></div> },
        { icon: <FileDown className="w-4 h-4 text-emerald-500" />, title: "HTML File", desc: "Standalone file, opens in any browser.", action: <button onClick={downloadHTML} className="flex items-center gap-2 w-full justify-center px-4 py-2 bg-emerald-600 text-white text-xs font-medium rounded-lg"><Download className="w-3.5 h-3.5" />Download HTML</button> },
      ].map((s, i) => <div key={i} className="border border-gray-200 rounded-xl p-4 mb-3 last:mb-0">
        <div className="flex items-center gap-2 mb-1">{s.icon}<span className="text-sm font-medium text-gray-700">{s.title}</span></div>
        <p className="text-xs text-gray-400 mb-3">{s.desc}</p>
        {s.action}
      </div>)}
    </div>
  </div>;
}

// ── PANEL SETTINGS ─────────────────────────────────────────────────────────────
function PanelSettings({ panels, onChange }) {
  const [open, setOpen] = useState(false);
  return <div className="relative">
    <button onClick={() => setOpen(o => !o)} className="flex items-center gap-1.5 px-3 py-2 bg-white border border-gray-200 text-gray-600 text-sm rounded-lg hover:border-gray-400 shadow-sm">
      <Settings className="w-4 h-4" /> Panels
    </button>
    {open && <div className="absolute right-0 top-10 bg-white border border-gray-200 rounded-xl shadow-lg z-50 p-4 w-64">
      <p className="text-xs font-semibold text-gray-500 mb-3 uppercase tracking-wide">Toggle Panels</p>
      <div className="space-y-2">
        {Object.entries(PANEL_LABELS).map(([key, label]) => <label key={key} className="flex items-center gap-2 cursor-pointer">
          <input type="checkbox" checked={panels[key]} onChange={e => onChange(key, e.target.checked)} className="rounded" />
          <span className="text-sm text-gray-700">{label}</span>
          {panels[key] ? <Eye className="w-3.5 h-3.5 text-gray-300 ml-auto" /> : <EyeOff className="w-3.5 h-3.5 text-gray-300 ml-auto" />}
