          {proj.decisions.length === 0 ? <p className="text-sm text-gray-300 italic">No decisions logged.</p> :
            <div className="space-y-2">{proj.decisions.map(d => <div key={d.id} className="flex gap-2 group border-b border-gray-50 pb-2 last:border-0">
              <div className="flex-1 min-w-0">
                <IT value={d.decision} onSave={v => updDec(d.id, "decision", v)} className="text-sm text-gray-700" wide />
                <div className="text-xs text-gray-400"><IT value={d.date} onSave={v => updDec(d.id, "date", v)} className="text-gray-400" /> · <IT value={d.madeBy} onSave={v => updDec(d.id, "madeBy", v)} className="text-gray-400" /></div>
              </div>
              <button onClick={() => up("decisions", proj.decisions.filter(x => x.id !== d.id))} className="opacity-0 group-hover:opacity-100"><Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button>
            </div>)}</div>}
        </Card>}
        {panels.openAsks && <Card>
          <SH title="Open Asks from Client" onAdd={() => up("openAsks", [...proj.openAsks, { id: Date.now(), ask: "New ask", askedOf: "Client", dueBy: "", done: false }])} />
          {proj.openAsks.length === 0 ? <p className="text-sm text-gray-300 italic">No open asks.</p> :
            <div className="space-y-2">{proj.openAsks.map(a => <div key={a.id} className="flex items-start gap-2 group border-b border-gray-50 pb-2 last:border-0">
              <button onClick={() => updAsk(a.id, "done", !a.done)} className="mt-0.5 shrink-0">
                {a.done ? <CheckCircle className="w-4 h-4 text-emerald-500" /> : <Circle className="w-4 h-4 text-gray-300 hover:text-gray-400" />}
              </button>
              <div className="flex-1 min-w-0">
                <IT value={a.ask} onSave={v => updAsk(a.id, "ask", v)} className={`text-sm ${a.done ? "line-through text-gray-400" : "text-gray-700"}`} wide />
                <div className="text-xs text-gray-400">Asked of: <IT value={a.askedOf} onSave={v => updAsk(a.id, "askedOf", v)} className="text-gray-400" /> · Due: <IT value={a.dueBy} onSave={v => updAsk(a.id, "dueBy", v)} className="text-gray-400" placeholder="YYYY-MM-DD" /></div>
              </div>
              <button onClick={() => up("openAsks", proj.openAsks.filter(x => x.id !== a.id))} className="opacity-0 group-hover:opacity-100"><Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button>
            </div>)}</div>}
        </Card>}
      </div>

      {/* Meeting Log */}
      {panels.meetings && <Card className="mb-6">
        <SH title="Meeting Log" onAdd={() => up("meetings", [...proj.meetings, { id: Date.now(), date: new Date().toISOString().slice(0, 10), attendees: `${proj.lead}, Client`, summary: "" }])} />
        {proj.meetings.length === 0 ? <p className="text-sm text-gray-300 italic">No meetings logged.</p> :
          <table className="w-full text-sm">
            <thead><tr className="text-xs text-gray-400 border-b border-gray-100 text-left"><th className="pb-2 w-24">Date</th><th className="pb-2 w-40">Attendees</th><th className="pb-2">Summary</th><th className="pb-2 w-5" /></tr></thead>
            <tbody>{proj.meetings.map(m => <tr key={m.id} className="border-b border-gray-50 last:border-0 group">
              <td className="py-2 text-gray-500 align-top"><IT value={m.date} onSave={v => updMeet(m.id, "date", v)} /></td>
              <td className="py-2 text-gray-500 align-top"><IT value={m.attendees} onSave={v => updMeet(m.id, "attendees", v)} wide /></td>
              <td className="py-2 text-gray-700 align-top"><IT value={m.summary} onSave={v => updMeet(m.id, "summary", v)} wide /></td>
              <td className="py-2 align-top text-right"><button onClick={() => up("meetings", proj.meetings.filter(x => x.id !== m.id))} className="opacity-0 group-hover:opacity-100"><Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button></td>
            </tr>)}</tbody>
          </table>}
      </Card>}

      {/* Tasks */}
      {panels.tasks && <DragTable
        tasks={proj.tasks}
        onUpdate={updTask}
        onDelete={tid => up("tasks", proj.tasks.filter(t => t.id !== tid))}
        onAdd={() => up("tasks", [...proj.tasks, { id: Date.now(), name: "New task", status: "Not Started", owner: proj.lead, due: "" }])}
        onReorder={r => up("tasks", r)}
      />}
    </div>
  );
}

import { useState, useRef } from "react";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from "recharts";
import {
  CheckCircle, Circle, Clock, DollarSign, TrendingUp, Plus, Trash2, Pencil,
  Check, X, Download, GripVertical, FileText, Settings, Eye, EyeOff,
  Share2, Link, Mail, FileDown, Copy, ExternalLink, RefreshCw, Save, Upload,
  Mic, AlertTriangle, Image
} from "lucide-react";
import PptxGenJS from "pptxgenjs";
import * as XLSX from "xlsx";

// ── BLANK PROJECT ──────────────────────────────────────────────────────────────
const blankProject = (id) => ({
  id, name: "New Project", client: "Client Name", lead: "Addie",
  status: "Planning", rag: "Green", budget: 0, spent: 0,
  startDate: "", endDate: "", meetingDate: "", revision: "",
  confidential: false, logoDataUrl: "",
  notes: "", execSummary: "", talkingPoints: "",
  tasks: [], milestones: [], deliverables: [],
  risks: [], decisions: [], openAsks: [], meetings: [],
  budgetHistory: [],
});

const STORAGE_KEY = "consulting_dashboard_v2";
const DEFAULT_PANELS = {
  execSummary: true, kpis: true, budget: true, milestones: true,
  notes: false, deliverables: true, risks: true, decisions: true,
  openAsks: true, meetings: true, tasks: true, talkingPoints: true,
};
const PANEL_LABELS = {
  execSummary: "Executive Summary", kpis: "KPI Cards", budget: "Budget Chart",
  milestones: "Milestones", notes: "Internal Notes (not shared)",
  deliverables: "Deliverables", risks: "Risk Log", decisions: "Decision Log",
  openAsks: "Open Asks from Client", meetings: "Meeting Log",
  tasks: "Task Table", talkingPoints: "Talking Points / Speaker Notes",
};
const STATUS_COLOR = {
  "Done": "bg-emerald-100 text-emerald-700", "Complete": "bg-emerald-100 text-emerald-700",
  "In Progress": "bg-blue-100 text-blue-700", "In Review": "bg-blue-100 text-blue-700",
  "Not Started": "bg-gray-100 text-gray-500", "Planning": "bg-amber-100 text-amber-700",
};
const STATUS_OPTIONS = ["Not Started", "In Progress", "In Review", "Done", "Complete", "Planning"];
const RAG_DOT = { Green: "bg-emerald-500", Amber: "bg-amber-400", Red: "bg-red-500" };
const RAG_BADGE = { Green: "text-emerald-700 bg-emerald-50 border-emerald-200", Amber: "text-amber-700 bg-amber-50 border-amber-200", Red: "text-red-700 bg-red-50 border-red-200" };
const pct = (a, b) => b === 0 ? 0 : Math.min(100, Math.round((a / b) * 100));
const now = () => new Date().toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "2-digit", minute: "2-digit" });

function loadState() { try { const ls = localStorage.getItem(STORAGE_KEY); if (ls) return JSON.parse(ls); } catch {} return null; }
function saveState(d) { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(d)); } catch {} }

// ── INLINE EDITORS ─────────────────────────────────────────────────────────────
function IT({ value, onSave, className = "", wide = false, placeholder = "Click to edit" }) {
  const [ed, setEd] = useState(false); const [v, setV] = useState(value);
  const commit = () => { onSave(v); setEd(false); };
  const cancel = () => { setV(value); setEd(false); };
  if (ed) return <span className="inline-flex items-center gap-1">
    <input autoFocus placeholder={placeholder} className={`border-b border-blue-400 outline-none bg-transparent text-sm px-0.5 ${wide ? "w-56" : "w-36"}`}
      value={v} onChange={e => setV(e.target.value)}
      onKeyDown={e => { if (e.key === "Enter") commit(); if (e.key === "Escape") cancel(); }} />
    <Check className="w-3.5 h-3.5 text-emerald-500 cursor-pointer shrink-0" onClick={commit} />
    <X className="w-3.5 h-3.5 text-gray-400 cursor-pointer shrink-0" onClick={cancel} />
  </span>;
  return <span className={`group inline-flex items-center gap-1 cursor-pointer ${className}`} onClick={() => setEd(true)}>
    {value || <span className="text-gray-300 italic text-sm">{placeholder}</span>}
    <Pencil className="w-3 h-3 text-gray-300 group-hover:text-gray-400 opacity-0 group-hover:opacity-100 shrink-0" />
  </span>;
}
function IN({ value, onSave, prefix = "" }) {
  const [ed, setEd] = useState(false); const [v, setV] = useState(value);
  const commit = () => { const n = parseFloat(v); if (!isNaN(n)) onSave(n); setEd(false); };
  const cancel = () => { setV(value); setEd(false); };
  if (ed) return <span className="inline-flex items-center gap-1">
    <input autoFocus className="border-b border-blue-400 outline-none bg-transparent w-24 text-sm"
      value={v} onChange={e => setV(e.target.value)}
      onKeyDown={e => { if (e.key === "Enter") commit(); if (e.key === "Escape") cancel(); }} />
    <Check className="w-3.5 h-3.5 text-emerald-500 cursor-pointer" onClick={commit} />
    <X className="w-3.5 h-3.5 text-gray-400 cursor-pointer" onClick={cancel} />
  </span>;
  return <span className="group inline-flex items-center gap-1 cursor-pointer" onClick={() => setEd(true)}>
    {prefix}{value.toLocaleString()}<Pencil className="w-3 h-3 text-gray-300 group-hover:text-gray-400 opacity-0 group-hover:opacity-100" />
  </span>;
}
function IS({ value, options, onSave, colorMap }) {
  const [ed, setEd] = useState(false);
  if (ed) return <select autoFocus className="text-xs border border-gray-200 rounded px-1 py-0.5 bg-white"
    value={value} onChange={e => { onSave(e.target.value); setEd(false); }} onBlur={() => setEd(false)}>
    {options.map(o => <option key={o}>{o}</option>)}
  </select>;
  const cls = colorMap ? (colorMap[value] || "bg-gray-100 text-gray-500 border-gray-200") : (STATUS_COLOR[value] || "bg-gray-100 text-gray-500");
  return <span className={`px-2 py-0.5 rounded-full text-xs font-medium cursor-pointer border ${cls}`} onClick={() => setEd(true)}>{value}</span>;
}
function TA({ value, onSave, rows = 3, placeholder = "Click to add..." }) {
  const [ed, setEd] = useState(false); const [v, setV] = useState(value);
  return ed
    ? <div><textarea autoFocus rows={rows} placeholder={placeholder} className="w-full text-sm text-gray-700 border border-blue-200 rounded-lg p-3 outline-none resize-none focus:border-blue-400" value={v} onChange={e => setV(e.target.value)} />
        <div className="flex gap-2 mt-1">
          <button onClick={() => { onSave(v); setEd(false); }} className="flex items-center gap-1 text-xs text-emerald-600 font-medium"><Check className="w-3.5 h-3.5" />Save</button>
          <button onClick={() => { setV(value); setEd(false); }} className="flex items-center gap-1 text-xs text-gray-400"><X className="w-3.5 h-3.5" />Cancel</button>
        </div></div>
    : <div className="group relative cursor-pointer" onClick={() => setEd(true)}>
        <p className="text-sm text-gray-600 leading-relaxed whitespace-pre-wrap min-h-8">{value || <span className="text-gray-300 italic">{placeholder}</span>}</p>
        <Pencil className="w-3 h-3 text-gray-300 group-hover:text-gray-400 absolute top-0 right-0 opacity-0 group-hover:opacity-100" />
      </div>;
}
function Card({ children, className = "" }) { return <div className={`bg-white rounded-xl border border-gray-200 shadow-sm p-5 ${className}`}>{children}</div>; }
function SH({ title, onAdd, addLabel = "Add" }) {
  return <div className="flex items-center justify-between mb-3">
    <h2 className="text-sm font-semibold text-gray-700">{title}</h2>
    {onAdd && <button onClick={onAdd} className="flex items-center gap-1 text-xs text-blue-500 hover:text-blue-700"><Plus className="w-3.5 h-3.5" />{addLabel}</button>}
  </div>;
}
function BudgetBar({ spent, budget }) {
  const p = pct(spent, budget);
  const col = p > 90 ? "bg-red-500" : p > 70 ? "bg-amber-400" : "bg-emerald-500";
  const projected = budget > 0 ? Math.round(spent / Math.max(p, 1) * 100) : 0;
  return <div className="w-full">
    <div className="flex justify-between text-xs text-gray-500 mb-1"><span>${spent.toLocaleString()} spent</span><span>${budget.toLocaleString()} budget</span></div>
    <div className="w-full bg-gray-100 rounded-full h-2"><div className={`${col} h-2 rounded-full`} style={{ width: `${p}%` }} /></div>
    <div className="text-xs text-gray-400 mt-1">{p}% utilized{budget > 0 ? ` · projected finish: $${projected.toLocaleString()}` : ""}</div>
  </div>;
}

// ── CONFIDENTIAL BANNER ───────────────────────────────────────────────────────
function ConfidentialBanner() {
  return <div className="w-full bg-red-600 text-white text-xs font-bold text-center py-1.5 tracking-widest uppercase">
    ⚠ Confidential — Not for Distribution
  </div>;
}

// ── LOGO UPLOADER ─────────────────────────────────────────────────────────────
function LogoUploader({ logoDataUrl, onSave }) {
  const inputRef = useRef();
  const handleFile = (e) => {
    const file = e.target.files?.[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = ev => onSave(ev.target.result);
    reader.readAsDataURL(file);
  };
  return <div className="flex items-center gap-3">
    {logoDataUrl
      ? <img src={logoDataUrl} alt="Client logo" className="h-10 max-w-32 object-contain rounded" />
      : <div className="w-20 h-10 border-2 border-dashed border-gray-200 rounded flex items-center justify-center text-gray-300"><Image className="w-4 h-4" /></div>}
    <div className="flex flex-col gap-0.5">
      <button onClick={() => inputRef.current?.click()} className="text-xs text-blue-500 hover:text-blue-700 flex items-center gap-1">
        <Upload className="w-3 h-3" />{logoDataUrl ? "Replace logo" : "Upload logo"}
      </button>
      {logoDataUrl && <button onClick={() => onSave("")} className="text-xs text-gray-400 hover:text-red-400">Remove</button>}
      <input ref={inputRef} type="file" accept="image/*" className="hidden" onChange={handleFile} />
    </div>
  </div>;
}

// ── AI TALKING POINTS ─────────────────────────────────────────────────────────
function TalkingPointsPanel({ proj, talkingPoints, onSave }) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const generate = async () => {
    setLoading(true); setError("");
    try {
      const apiKey = import.meta.env.VITE_ANTHROPIC_API_KEY;
      if (!apiKey) throw new Error("No API key");
      const milDone = proj.milestones.filter(m => m.done).length;
      const openRisks = proj.risks.filter(r => r.flag !== "Green");
      const openAsks = proj.openAsks.filter(a => !a.done);
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json", "x-api-key": apiKey, "anthropic-version": "2023-06-01", "anthropic-dangerous-direct-browser-access": "true" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514", max_tokens: 800,
          system: "You are a consulting engagement manager. Generate concise, confident talking points for presenting a project status dashboard to a client. Return 4-5 bullet points as plain text, each starting with '•'. No headers, no markdown, no preamble.",
          messages: [{ role: "user", content: `Generate talking points for this project status review:\n\nProject: ${proj.name}\nClient: ${proj.client}\nRAG Status: ${proj.rag}\nExecutive Summary: ${proj.execSummary || "Not provided"}\nBudget: $${proj.spent.toLocaleString()} of $${proj.budget.toLocaleString()} used (${pct(proj.spent, proj.budget)}%)\nMilestones: ${milDone}/${proj.milestones.length} complete\nOpen Risks: ${openRisks.map(r => r.item).join(", ") || "None"}\nOpen Asks from Client: ${openAsks.map(a => a.ask).join(", ") || "None"}\nRecent Decisions: ${proj.decisions.slice(-2).map(d => d.decision).join(", ") || "None"}\n\nFocus on: what's going well, what needs client attention, key next steps, and any risks they should be aware of. Tone: confident, direct, consultant-to-client.` }]
        })
      });
      const data = await res.json();
      const text = data.content?.find(b => b.type === "text")?.text || "";
      onSave(text);
    } catch (e) {
      setError("Add your Anthropic API key (VITE_ANTHROPIC_API_KEY) to Netlify env vars to enable AI generation. You can also type notes manually below.");
    }
    setLoading(false);
  };

  return <Card className="mb-6">
    <div className="flex items-center justify-between mb-3">
      <h2 className="text-sm font-semibold text-gray-700 flex items-center gap-2"><Mic className="w-4 h-4 text-blue-400" />Talking Points <span className="text-xs text-gray-400 font-normal">(speaker notes for client meeting)</span></h2>
      <button onClick={generate} disabled={loading}
        className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg transition-colors ${loading ? "bg-gray-100 text-gray-400" : "bg-blue-600 text-white hover:bg-blue-700"}`}>
        {loading ? "Generating..." : "✦ Generate with AI"}
      </button>
    </div>
    {error && <p className="text-xs text-amber-600 bg-amber-50 rounded-lg p-2 mb-3">{error}</p>}
    <TA value={talkingPoints} onSave={onSave} rows={6} placeholder="Click 'Generate with AI' to auto-draft talking points, or type your own notes here..." />
  </Card>;
}

// ── EXPORTS ───────────────────────────────────────────────────────────────────
function exportCSV(proj) {
  const q = s => `"${String(s || "").replace(/"/g, '""')}"`;
  const rows = [
    ["Project", proj.name], ["Client", proj.client], ["Lead", proj.lead],
    ["Status", proj.status], ["RAG", proj.rag],
    ["Meeting Date", proj.meetingDate], ["Revision", proj.revision],
    ["Confidential", proj.confidential ? "Yes" : "No"],
    ["Budget", proj.budget], ["Spent", proj.spent], ["Remaining", proj.budget - proj.spent], [],
    ["EXEC SUMMARY"], [q(proj.execSummary)], [],
    ["TALKING POINTS"], [q(proj.talkingPoints)], [],
    ["TASKS"], ["Task", "Owner", "Due", "Status"], ...proj.tasks.map(t => [q(t.name), t.owner, t.due, t.status]), [],
    ["MILESTONES"], ["Milestone", "Date", "Done"], ...proj.milestones.map(m => [q(m.name), m.date, m.done ? "Yes" : "No"]), [],
    ["DELIVERABLES"], ["Deliverable", "Status", "Due"], ...proj.deliverables.map(d => [q(d.name), d.status, d.due]), [],
    ["RISKS"], ["Flag", "Risk", "Owner", "Mitigation"], ...proj.risks.map(r => [r.flag, q(r.item), r.owner, q(r.mitigation)]), [],
    ["DECISIONS"], ["Date", "Decision", "Made By"], ...proj.decisions.map(d => [d.date, q(d.decision), d.madeBy]), [],
    ["OPEN ASKS"], ["Ask", "Asked Of", "Due By", "Done"], ...proj.openAsks.map(a => [q(a.ask), a.askedOf, a.dueBy, a.done ? "Yes" : "No"]),
  ];
  const a = Object.assign(document.createElement("a"), { href: URL.createObjectURL(new Blob([rows.map(r => r.join(",")).join("\n")], { type: "text/csv" })), download: `${proj.client.replace(/\s+/g, "_")}_${proj.name.replace(/\s+/g, "_")}.csv` });
  a.click();
}

function exportExcel(proj) {
  const wb = XLSX.utils.book_new();
  const add = (name, data) => XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(data), name);
  add("Summary", [
    ["Project", proj.name], ["Client", proj.client], ["Lead", proj.lead],
    ["Status", proj.status], ["RAG", proj.rag],
    ["Meeting Date", proj.meetingDate], ["Revision", proj.revision],
    ["Confidential", proj.confidential ? "Yes" : "No"],
    ["Budget", proj.budget], ["Spent", proj.spent], ["Remaining", proj.budget - proj.spent],
    [], ["Executive Summary"], [proj.execSummary],
    [], ["Talking Points"], [proj.talkingPoints],
  ]);
  add("Tasks", [["Task", "Owner", "Due", "Status"], ...proj.tasks.map(t => [t.name, t.owner, t.due, t.status])]);
  add("Milestones", [["Milestone", "Date", "Done"], ...proj.milestones.map(m => [m.name, m.date, m.done ? "Yes" : "No"])]);
  add("Deliverables", [["Deliverable", "Status", "Due"], ...proj.deliverables.map(d => [d.name, d.status, d.due])]);
  add("Risks", [["Flag", "Risk", "Owner", "Mitigation"], ...proj.risks.map(r => [r.flag, r.item, r.owner, r.mitigation])]);
  add("Decisions", [["Date", "Decision", "Made By"], ...proj.decisions.map(d => [d.date, d.decision, d.madeBy])]);
  add("Open Asks", [["Ask", "Asked Of", "Due By", "Done"], ...proj.openAsks.map(a => [a.ask, a.askedOf, a.dueBy, a.done ? "Yes" : "No"])]);
  XLSX.writeFile(wb, `${proj.client.replace(/\s+/g, "_")}_${proj.name.replace(/\s+/g, "_")}.xlsx`);
}

function exportPPT(proj, updatedAt) {
  const pptx = new PptxGenJS();
  pptx.layout = "LAYOUT_WIDE";
  const DARK = "1a1a2e", ACCENT = "3b82f6", LIGHT = "f8fafc", GRAY = "64748b", RED = "dc2626";
  const ragColor = { Green: "10b981", Amber: "f59e0b", Red: "ef4444" };
  const milDone = proj.milestones.filter(m => m.done).length;
  const budPct = pct(proj.spent, proj.budget);

  const addConfidential = (slide) => {
    if (!proj.confidential) return;
    slide.addText("CONFIDENTIAL — NOT FOR DISTRIBUTION", { x: 0, y: 0, w: "100%", h: 0.35, fontSize: 10, bold: true, color: "FFFFFF", align: "center", fill: { color: RED } });
  };

  // Slide 1 — Cover
  let s = pptx.addSlide();
  s.background = { color: DARK };
  addConfidential(s);
  const yOff = proj.confidential ? 0.4 : 0;
  if (proj.logoDataUrl) {
    try { s.addImage({ data: proj.logoDataUrl, x: 10.5, y: 0.4 + yOff, w: 2, h: 0.8, sizing: { type: "contain", w: 2, h: 0.8 } }); } catch {}
  }
  s.addText(proj.name, { x: 0.5, y: 1.5 + yOff, w: 12, h: 1.2, fontSize: 36, bold: true, color: "FFFFFF" });
  s.addText(`${proj.client}  ·  Lead: ${proj.lead}`, { x: 0.5, y: 2.8 + yOff, w: 10, h: 0.4, fontSize: 14, color: "94a3b8" });
  const meta = [proj.meetingDate && `Meeting: ${proj.meetingDate}`, proj.revision && `Rev. ${proj.revision}`, `As of ${updatedAt}`].filter(Boolean).join("  ·  ");
  s.addText(meta, { x: 0.5, y: 3.2 + yOff, w: 12, h: 0.3, fontSize: 11, color: "64748b" });
  s.addShape(pptx.ShapeType.rect, { x: 0.5, y: 3.7 + yOff, w: 1.8, h: 0.4, fill: { color: ragColor[proj.rag] || "64748b" }, line: { color: ragColor[proj.rag] || "64748b" } });
  s.addText(proj.rag, { x: 0.5, y: 3.7 + yOff, w: 1.8, h: 0.4, fontSize: 12, bold: true, color: "FFFFFF", align: "center" });
  s.addText(proj.execSummary || "No summary provided.", { x: 0.5, y: 4.3 + yOff, w: 12, h: 1.1, fontSize: 13, color: "cbd5e1", wrap: true });

  // Slide 2 — Talking Points (if any)
  if (proj.talkingPoints) {
    s = pptx.addSlide();
    s.background = { color: LIGHT };
    addConfidential(s);
    s.addText("Talking Points", { x: 0.5, y: 0.4 + yOff, w: 12, h: 0.5, fontSize: 22, bold: true, color: DARK });
    s.addText(proj.talkingPoints, { x: 0.5, y: 1.1 + yOff, w: 12, h: 5, fontSize: 13, color: "374151", wrap: true, valign: "top" });
  }

  // Slide 3 — KPIs
  s = pptx.addSlide();
  s.background = { color: LIGHT };
  addConfidential(s);
  s.addText("Project Snapshot", { x: 0.5, y: 0.3 + yOff, w: 12, h: 0.5, fontSize: 22, bold: true, color: DARK });
  const kpis = [
    { label: "Budget", val: `$${proj.budget.toLocaleString()}`, sub: `$${proj.spent.toLocaleString()} spent` },
    { label: "Remaining", val: `$${(proj.budget - proj.spent).toLocaleString()}`, sub: `${100 - budPct}% left` },
    { label: "Milestones", val: `${milDone}/${proj.milestones.length}`, sub: `${pct(milDone, proj.milestones.length)}% done` },
    { label: "Open Tasks", val: `${proj.tasks.filter(t => t.status !== "Done" && t.status !== "Complete").length}`, sub: `of ${proj.tasks.length} total` },
  ];
  kpis.forEach((k, i) => {
    const x = 0.4 + i * 3.15;
    s.addShape(pptx.ShapeType.rect, { x, y: 1.0 + yOff, w: 2.9, h: 1.6, fill: { color: "FFFFFF" }, line: { color: "e2e8f0", pt: 1 } });
    s.addText(k.label, { x, y: 1.1 + yOff, w: 2.9, h: 0.35, fontSize: 10, color: GRAY, align: "center" });
    s.addText(k.val, { x, y: 1.45 + yOff, w: 2.9, h: 0.7, fontSize: 28, bold: true, color: DARK, align: "center" });
    s.addText(k.sub, { x, y: 2.15 + yOff, w: 2.9, h: 0.3, fontSize: 10, color: GRAY, align: "center" });
  });
  s.addText("Budget Utilization", { x: 0.5, y: 2.9 + yOff, w: 6, h: 0.3, fontSize: 11, bold: true, color: DARK });
  s.addShape(pptx.ShapeType.rect, { x: 0.5, y: 3.25 + yOff, w: 12, h: 0.3, fill: { color: "e2e8f0" }, line: { color: "e2e8f0" } });
  if (budPct > 0) s.addShape(pptx.ShapeType.rect, { x: 0.5, y: 3.25 + yOff, w: Math.max(0.1, 12 * budPct / 100), h: 0.3, fill: { color: budPct > 90 ? "ef4444" : budPct > 70 ? "f59e0b" : "10b981" }, line: { color: "transparent" } });
  s.addText(`${budPct}% utilized`, { x: 0.5, y: 3.65 + yOff, w: 12, h: 0.25, fontSize: 10, color: GRAY });

  // Slide 4 — Milestones + Deliverables
  s = pptx.addSlide();
  s.background = { color: LIGHT };
  addConfidential(s);
  s.addText("Milestones & Deliverables", { x: 0.5, y: 0.3 + yOff, w: 12, h: 0.5, fontSize: 22, bold: true, color: DARK });
  proj.milestones.slice(0, 8).forEach((m, i) => {
    const y = 1.0 + yOff + i * 0.45;
    s.addShape(pptx.ShapeType.ellipse, { x: 0.5, y: y + 0.05, w: 0.25, h: 0.25, fill: { color: m.done ? "10b981" : "e2e8f0" }, line: { color: m.done ? "10b981" : "cbd5e1" } });
    s.addText(`${m.name}  ·  ${m.date}`, { x: 0.9, y, w: 5.5, h: 0.35, fontSize: 11, color: m.done ? GRAY : DARK, strike: m.done });
  });
  if (proj.deliverables.length) {
    s.addText("Deliverables", { x: 7, y: 0.9 + yOff, w: 5.5, h: 0.35, fontSize: 13, bold: true, color: DARK });
    proj.deliverables.slice(0, 8).forEach((d, i) => {
      s.addText(d.name, { x: 7, y: 1.4 + yOff + i * 0.45, w: 3.5, h: 0.35, fontSize: 11, color: DARK });
      s.addText(d.status, { x: 10.6, y: 1.4 + yOff + i * 0.45, w: 1.8, h: 0.3, fontSize: 10, color: GRAY, align: "right" });
    });
  }

  // Slide 5 — Risks + Open Asks
  if (proj.risks.length || proj.openAsks.length) {
    s = pptx.addSlide();
    s.background = { color: LIGHT };
    addConfidential(s);
    s.addText("Risks & Open Asks", { x: 0.5, y: 0.3 + yOff, w: 12, h: 0.5, fontSize: 22, bold: true, color: DARK });
    proj.risks.slice(0, 5).forEach((r, i) => {
      const y = 1.0 + yOff + i * 0.7;
      s.addShape(pptx.ShapeType.rect, { x: 0.5, y, w: 0.7, h: 0.3, fill: { color: ragColor[r.flag] || "64748b" }, line: { color: "transparent" } });
      s.addText(r.flag, { x: 0.5, y, w: 0.7, h: 0.3, fontSize: 9, bold: true, color: "FFFFFF", align: "center" });
      s.addText(r.item, { x: 1.3, y, w: 5, h: 0.3, fontSize: 11, color: DARK });
      s.addText(`Mitigation: ${r.mitigation}`, { x: 1.3, y: y + 0.32, w: 5, h: 0.28, fontSize: 9, color: GRAY });
    });
    const openAsks = proj.openAsks.filter(a => !a.done);
    if (openAsks.length) {
      s.addText("Open Asks from Client", { x: 7, y: 0.9 + yOff, w: 5.5, h: 0.35, fontSize: 13, bold: true, color: DARK });
      openAsks.slice(0, 5).forEach((a, i) => {
        s.addText(`• ${a.ask}`, { x: 7, y: 1.4 + yOff + i * 0.55, w: 5.5, h: 0.3, fontSize: 11, color: DARK });
        s.addText(`${a.askedOf}  ·  Due ${a.dueBy}`, { x: 7, y: 1.72 + yOff + i * 0.55, w: 5.5, h: 0.25, fontSize: 9, color: GRAY });
      });
    }
  }

  // Slide 6 — Decision Log
  if (proj.decisions.length) {
    s = pptx.addSlide();
    s.background = { color: LIGHT };
    addConfidential(s);
    s.addText("Decision Log", { x: 0.5, y: 0.3 + yOff, w: 12, h: 0.5, fontSize: 22, bold: true, color: DARK });
    proj.decisions.slice(0, 8).forEach((d, i) => {
      const y = 1.0 + yOff + i * 0.65;
      s.addText(d.date, { x: 0.5, y, w: 1.5, h: 0.3, fontSize: 10, color: GRAY });
      s.addText(d.decision, { x: 2.2, y, w: 8, h: 0.3, fontSize: 11, color: DARK });
      s.addText(`— ${d.madeBy}`, { x: 2.2, y: y + 0.32, w: 8, h: 0.25, fontSize: 9, color: GRAY });
    });
  }

  pptx.writeFile({ fileName: `${proj.client.replace(/\s+/g, "_")}_${proj.name.replace(/\s+/g, "_")}_status.pptx` });
}

