</style></head><body>
${confBanner}
<div class="wrap">
<div class="header">
  <div class="header-top">
    <div><h1>${proj.name}</h1><div class="sub">${proj.client} · Lead: ${proj.lead}${meta ? " · " + meta : ""} · As of ${updatedAt}</div>
    <span class="rag" style="background:${ragBg[proj.rag] || "#f3f4f6"};color:${ragTxt[proj.rag] || "#374151"}">${proj.rag}</span></div>
    ${logoHtml}
  </div>
  <div style="margin-top:16px;font-size:13px;color:#4b5563;line-height:1.6">${proj.execSummary || "<em>No summary provided.</em>"}</div>
</div>
${proj.talkingPoints ? `<div class="card" style="margin-bottom:24px"><h2>🎙 Talking Points</h2><div class="tp">${proj.talkingPoints}</div></div>` : ""}
<div class="grid4">
  <div class="card"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Budget Remaining</div><div class="kpi-val">$${(proj.budget - proj.spent).toLocaleString()}</div><div class="kpi-sub">${100 - p}% left</div></div>
  <div class="card"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Budget Used</div><div class="kpi-val">$${proj.spent.toLocaleString()}</div><div class="kpi-sub">of $${proj.budget.toLocaleString()}</div></div>
  <div class="card"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Milestones</div><div class="kpi-val">${milDone}/${proj.milestones.length}</div><div class="kpi-sub">${pct(milDone, proj.milestones.length)}% complete</div></div>
  <div class="card"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Open Tasks</div><div class="kpi-val">${proj.tasks.filter(t => t.status !== "Done" && t.status !== "Complete").length}</div><div class="kpi-sub">${proj.tasks.length} total</div></div>
</div>
${proj.budget > 0 ? `<div style="margin-bottom:20px"><div style="font-size:11px;color:#6b7280;font-weight:500;margin-bottom:6px">Budget: $${proj.spent.toLocaleString()} of $${proj.budget.toLocaleString()} (${p}%)</div><div style="background:#f3f4f6;border-radius:999px;height:8px"><div style="background:${barCol};height:8px;border-radius:999px;width:${p}%"></div></div></div>` : ""}
<div class="grid2">
  <div class="card"><h2>Milestones</h2>${proj.milestones.length ? proj.milestones.map(m => `<div class="ms-row"><div class="ms-dot${m.done ? " ms-done" : ""}"></div><div><div style="font-size:13px;color:${m.done ? "#9ca3af" : "#374151"};${m.done ? "text-decoration:line-through" : ""}">${m.name}</div><div style="font-size:11px;color:#9ca3af">${m.date}</div></div></div>`).join("") : "<p style='font-size:13px;color:#d1d5db;font-style:italic'>No milestones.</p>"}</div>
  <div class="card"><h2>Deliverables</h2>${proj.deliverables.length ? `<table><thead><tr><th>Output</th><th>Due</th><th>Status</th></tr></thead><tbody>${proj.deliverables.map(d => `<tr><td>${d.name}</td><td style="color:#6b7280">${d.due}</td><td>${badge(d.status)}</td></tr>`).join("")}</tbody></table>` : "<p style='font-size:13px;color:#d1d5db;font-style:italic'>No deliverables.</p>"}</div>
</div>
<div class="grid2">
  <div class="card"><h2>Risk Log</h2>${proj.risks.length ? proj.risks.map(r => `<div class="row"><div style="display:flex;align-items:center;gap:8px;margin-bottom:4px"><span style="background:${ragBg[r.flag] || "#f3f4f6"};color:${ragTxt[r.flag] || "#374151"};padding:1px 8px;border-radius:999px;font-size:11px;font-weight:600">${r.flag}</span><span style="font-size:13px">${r.item}</span></div><div style="font-size:11px;color:#9ca3af">Owner: ${r.owner} · ${r.mitigation}</div></div>`).join("") : "<p style='font-size:13px;color:#d1d5db;font-style:italic'>No risks.</p>"}</div>
  <div class="card"><h2>Open Asks from Client</h2>${proj.openAsks.length ? proj.openAsks.map(a => `<div class="row" style="display:flex;align-items:flex-start;gap:8px"><div style="width:14px;height:14px;border-radius:50%;background:${a.done ? "#10b981" : "#e5e7eb"};margin-top:2px;flex-shrink:0"></div><div><div style="font-size:13px;color:${a.done ? "#9ca3af" : "#374151"};${a.done ? "text-decoration:line-through" : ""}">${a.ask}</div><div style="font-size:11px;color:#9ca3af">${a.askedOf} · Due ${a.dueBy}</div></div></div>`).join("") : "<p style='font-size:13px;color:#d1d5db;font-style:italic'>No open asks.</p>"}</div>
</div>
${proj.decisions.length ? `<div class="card" style="margin-bottom:20px"><h2>Decision Log</h2><table><thead><tr><th>Date</th><th>Decision</th><th>Made By</th></tr></thead><tbody>${proj.decisions.map(d => `<tr><td style="color:#6b7280;white-space:nowrap">${d.date}</td><td>${d.decision}</td><td style="color:#6b7280">${d.madeBy}</td></tr>`).join("")}</tbody></table></div>` : ""}
<div class="footer">Prepared by ${proj.lead} · ${proj.client}${proj.revision ? " · Rev. " + proj.revision : ""} · Last updated ${updatedAt}${proj.confidential ? " · CONFIDENTIAL" : ""}</div>
</div>${confBanner}</body></html>`;
}

function buildShareURL(proj) {
  try { return `${window.location.href.split("?")[0]}?view=${btoa(encodeURIComponent(JSON.stringify({ ...proj, logoDataUrl: "" })))}`; }
  catch { return window.location.href; }
}

// ── SHARE MODAL ────────────────────────────────────────────────────────────────
function ShareModal({ proj, updatedAt, onClose }) {
  const [copied, setCopied] = useState(false);
  const [emailSent, setEmailSent] = useState(false);
  const [sending, setSending] = useState(false);
  const [emailTo, setEmailTo] = useState("");
  const shareURL = buildShareURL(proj);

  const copyLink = () => { navigator.clipboard.writeText(shareURL).then(() => { setCopied(true); setTimeout(() => setCopied(false), 2000); }); };
  const downloadHTML = () => {
    const html = buildClientHTML(proj, updatedAt);
    const a = Object.assign(document.createElement("a"), { href: URL.createObjectURL(new Blob([html], { type: "text/html" })), download: `${proj.client.replace(/\s+/g, "_")}_${proj.name.replace(/\s+/g, "_")}_status.html` });
    a.click();
  };
  const sendEmail = async () => {
    if (!emailTo.trim()) return;
    setSending(true);
    try {
      const apiKey = import.meta.env.VITE_ANTHROPIC_API_KEY;
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json", "x-api-key": apiKey, "anthropic-version": "2023-06-01", "anthropic-dangerous-direct-browser-access": "true" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514", max_tokens: 800,
          system: "Draft a concise professional project status email. Return ONLY a JSON object with keys: subject and body. No markdown.",
          messages: [{ role: "user", content: `Status update email. Project: ${proj.name}. Client: ${proj.client}. RAG: ${proj.rag}. Summary: ${proj.execSummary}. Milestones: ${proj.milestones.filter(m => m.done).length}/${proj.milestones.length}. Budget: $${proj.spent}/$${proj.budget}. Open asks: ${proj.openAsks.filter(a => !a.done).map(a => a.ask).join("; ") || "none"}. Under 150 words. Sign off as ${proj.lead}.` }]
        })
      });
      const data = await res.json();
      const text = data.content?.find(b => b.type === "text")?.text || "";
      let parsed; try { parsed = JSON.parse(text.replace(/```json|```/g, "").trim()); } catch { parsed = { subject: `${proj.name} — Status Update`, body: text }; }
      window.open(`https://mail.google.com/mail/?view=cm&to=${encodeURIComponent(emailTo)}&su=${encodeURIComponent(parsed.subject)}&body=${encodeURIComponent(parsed.body + "\n\nFull dashboard: " + shareURL)}`, "_blank");
    } catch {
      window.open(`https://mail.google.com/mail/?view=cm&to=${encodeURIComponent(emailTo)}&su=${encodeURIComponent(proj.name + " — Status Update")}&body=${encodeURIComponent(proj.execSummary + "\n\nFull dashboard: " + shareURL)}`, "_blank");
    }
    setEmailSent(true); setSending(false);
  };

  return <div className="fixed inset-0 bg-black bg-opacity-40 z-50 flex items-center justify-center p-4" onClick={onClose}>
    <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-6" onClick={e => e.stopPropagation()}>
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2"><Share2 className="w-5 h-5 text-gray-600" /><h2 className="text-base font-semibold text-gray-800">Share with Client</h2></div>
        <button onClick={onClose}><X className="w-5 h-5 text-gray-400" /></button>
      </div>
      <div className="text-sm font-semibold text-gray-800 mb-1">{proj.name} — {proj.client}</div>
      <div className="text-xs text-gray-400 mb-3">Last updated: {updatedAt}{proj.revision ? ` · Rev. ${proj.revision}` : ""}</div>
      {proj.confidential && <div className="flex items-center gap-2 p-2 bg-red-50 border border-red-200 rounded-lg mb-3 text-xs text-red-700 font-medium"><AlertTriangle className="w-3.5 h-3.5" />Marked confidential — watermark will appear on all exports</div>}
      <div className="p-3 bg-amber-50 border border-amber-200 rounded-lg mb-4 text-xs text-amber-700">Internal Notes are excluded. Review Risk Log before sharing.</div>
      {[
        { icon: <Link className="w-4 h-4 text-blue-500" />, title: "Shareable Link", desc: "Read-only snapshot URL.", action: <div className="flex gap-2"><input readOnly value={shareURL} className="flex-1 text-xs border border-gray-200 rounded-lg px-3 py-2 bg-gray-50 text-gray-500 truncate" /><button onClick={copyLink} className={`flex items-center gap-1 px-3 py-2 rounded-lg text-xs font-medium ${copied ? "bg-emerald-500 text-white" : "bg-gray-800 text-white"}`}>{copied ? <><Check className="w-3.5 h-3.5" />Copied</> : <><Copy className="w-3.5 h-3.5" />Copy</>}</button></div> },
        { icon: <Mail className="w-4 h-4 text-purple-500" />, title: "Send via Gmail", desc: "AI-drafts a status email.", action: <div className="flex gap-2"><input value={emailTo} onChange={e => setEmailTo(e.target.value)} placeholder="client@email.com" className="flex-1 text-xs border border-gray-200 rounded-lg px-3 py-2 outline-none" /><button onClick={sendEmail} disabled={sending || !emailTo.trim()} className={`flex items-center gap-1 px-3 py-2 rounded-lg text-xs font-medium ${emailSent ? "bg-emerald-500 text-white" : sending ? "bg-gray-200 text-gray-400" : "bg-purple-600 text-white"} disabled:opacity-50`}>{emailSent ? "Opened" : sending ? "Drafting..." : "Gmail"}</button></div> },
        { icon: <FileDown className="w-4 h-4 text-emerald-500" />, title: "HTML File", desc: "Standalone file, opens in any browser.", action: <button onClick={downloadHTML} className="flex items-center gap-2 w-full justify-center px-4 py-2 bg-emerald-600 text-white text-xs font-medium rounded-lg"><Download className="w-3.5 h-3.5" />Download HTML</button> },
      ].map((s, i) => <div key={i} className="border border-gray-200 rounded-xl p-4 mb-3 last:mb-0">
        <div className="flex items-center gap-2 mb-1">{s.icon}<span className="text-sm font-medium text-gray-700">{s.title}</span></div>
        <p className="text-xs text-gray-400 mb-3">{s.desc}</p>
        {s.action}
      </div>)}
    </div>
  </div>;
}

// ── PANEL SETTINGS ─────────────────────────────────────────────────────────────
function PanelSettings({ panels, onChange }) {
  const [open, setOpen] = useState(false);
  return <div className="relative">
    <button onClick={() => setOpen(o => !o)} className="flex items-center gap-1.5 px-3 py-2 bg-white border border-gray-200 text-gray-600 text-sm rounded-lg hover:border-gray-400 shadow-sm">
      <Settings className="w-4 h-4" /> Panels
    </button>
    {open && <div className="absolute right-0 top-10 bg-white border border-gray-200 rounded-xl shadow-lg z-50 p-4 w-72">
      <p className="text-xs font-semibold text-gray-500 mb-3 uppercase tracking-wide">Toggle Panels</p>
      <div className="space-y-2">
        {Object.entries(PANEL_LABELS).map(([key, label]) => <label key={key} className="flex items-center gap-2 cursor-pointer">
          <input type="checkbox" checked={panels[key]} onChange={e => onChange(key, e.target.checked)} className="rounded" />
          <span className="text-sm text-gray-700">{label}</span>
          {panels[key] ? <Eye className="w-3.5 h-3.5 text-gray-300 ml-auto" /> : <EyeOff className="w-3.5 h-3.5 text-gray-300 ml-auto" />}
        </label>)}
      </div>
      <button onClick={() => setOpen(false)} className="mt-3 w-full text-xs text-gray-400 text-center">Done</button>
    </div>}
  </div>;
}

// ── DRAG TABLE ─────────────────────────────────────────────────────────────────
function DragTable({ tasks, onUpdate, onDelete, onAdd, onReorder }) {
  const dragIdx = useRef(null); const [dragOver, setDragOver] = useState(null);
  const start = (e, i) => { dragIdx.current = i; };
  const over = (e, i) => { e.preventDefault(); setDragOver(i); };
  const drop = (e, i) => { e.preventDefault(); if (dragIdx.current !== null && dragIdx.current !== i) { const r = [...tasks]; const [m] = r.splice(dragIdx.current, 1); r.splice(i, 0, m); onReorder(r); } dragIdx.current = null; setDragOver(null); };
  return <Card>
    <SH title={<>Tasks <span className="text-xs text-gray-400 font-normal ml-1">drag to reorder</span></>} onAdd={onAdd} addLabel="Add task" />
    <div className="overflow-x-auto"><table className="w-full text-sm">
      <thead><tr className="text-left text-xs text-gray-400 border-b border-gray-100"><th className="pb-2 w-5" /><th className="pb-2 font-medium">Task</th><th className="pb-2 font-medium">Owner</th><th className="pb-2 font-medium">Due</th><th className="pb-2 font-medium">Status</th><th className="pb-2 w-5" /></tr></thead>
      <tbody>{tasks.map((t, i) => <tr key={t.id} draggable onDragStart={e => start(e, i)} onDragOver={e => over(e, i)} onDrop={e => drop(e, i)} onDragEnd={() => { dragIdx.current = null; setDragOver(null); }} className={`border-b border-gray-50 last:border-0 group transition-colors ${dragOver === i ? "bg-blue-50" : ""}`}>
        <td className="py-2"><GripVertical className="w-3.5 h-3.5 text-gray-300 cursor-grab group-hover:text-gray-400" /></td>
        <td className="py-2"><IT value={t.name} onSave={v => onUpdate(t.id, "name", v)} wide /></td>
        <td className="py-2 text-gray-500"><IT value={t.owner} onSave={v => onUpdate(t.id, "owner", v)} /></td>
        <td className="py-2 text-gray-500"><IT value={t.due} onSave={v => onUpdate(t.id, "due", v)} /></td>
        <td className="py-2"><IS value={t.status} options={STATUS_OPTIONS} onSave={v => onUpdate(t.id, "status", v)} /></td>
        <td className="py-2 text-right"><button onClick={() => onDelete(t.id)} className="opacity-0 group-hover:opacity-100"><Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button></td>
      </tr>)}</tbody>
    </table></div>
  </Card>;
}

// ── MAIN ───────────────────────────────────────────────────────────────────────
const INIT_STATE = { dashTitle: "Project Dashboard", projects: [blankProject(1)], updatedAt: now() };

export default function App() {
  const [state, setState] = useState(() => {
    const saved = loadState();
    // migrate old projects missing new fields
    if (saved) {
      saved.projects = saved.projects.map(p => ({
        meetingDate: "", revision: "", confidential: false, logoDataUrl: "", talkingPoints: "",
        ...p
      }));
    }
    return saved || INIT_STATE;
  });
  const [activeId, setActiveId] = useState(state.projects[0]?.id || 1);
  const [panels, setPanels] = useState(DEFAULT_PANELS);
  const [showShare, setShowShare] = useState(false);
  const [saved, setSaved] = useState(false);
  const [showExport, setShowExport] = useState(false);
  const [importErr, setImportErr] = useState("");

  const { dashTitle, projects, updatedAt } = state;
  const proj = projects.find(p => p.id === activeId) || projects[0];

  const touch = (newState) => {
    const updated = { ...newState, updatedAt: now() };
    setState(updated); saveState(updated);
    setSaved(true); setTimeout(() => setSaved(false), 1500);
  };
  const setProjects = ps => touch({ ...state, projects: ps });
  const up = (field, value) => setProjects(projects.map(p => p.id === activeId ? { ...p, [field]: value } : p));
  const addProject = () => { const id = Date.now(); touch({ ...state, projects: [...projects, blankProject(id)] }); setActiveId(id); };
  const removeProject = id => { if (projects.length === 1) return; const ps = projects.filter(p => p.id !== id); touch({ ...state, projects: ps }); setActiveId(ps[0].id); };

  const updTask = (tid, f, v) => up("tasks", proj.tasks.map(t => t.id === tid ? { ...t, [f]: v } : t));
  const updMile = (i, f, v) => up("milestones", proj.milestones.map((m, idx) => idx === i ? { ...m, [f]: v } : m));
  const updDeliv = (tid, f, v) => up("deliverables", proj.deliverables.map(d => d.id === tid ? { ...d, [f]: v } : d));
  const updRisk = (tid, f, v) => up("risks", proj.risks.map(r => r.id === tid ? { ...r, [f]: v } : r));
  const updDec = (tid, f, v) => up("decisions", proj.decisions.map(d => d.id === tid ? { ...d, [f]: v } : d));
  const updAsk = (tid, f, v) => up("openAsks", proj.openAsks.map(a => a.id === tid ? { ...a, [f]: v } : a));
  const updMeet = (tid, f, v) => up("meetings", proj.meetings.map(m => m.id === tid ? { ...m, [f]: v } : m));

  const exportJSON = () => { const a = Object.assign(document.createElement("a"), { href: URL.createObjectURL(new Blob([JSON.stringify(state, null, 2)], { type: "application/json" })), download: "dashboard_backup.json" }); a.click(); };
  const importJSON = e => {
    const file = e.target.files?.[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = ev => { try { const p = JSON.parse(ev.target.result); if (!p.projects) throw new Error(); touch(p); setActiveId(p.projects[0]?.id); setShowExport(false); setImportErr(""); } catch { setImportErr("Invalid file."); } };
    reader.readAsText(file);
  };

  const milDone = proj.milestones.filter(m => m.done).length;
  const milPct = pct(milDone, proj.milestones.length);
  const budPct = pct(proj.spent, proj.budget);

  return (
    <div className="min-h-screen bg-gray-50 font-sans">
      {proj.confidential && <ConfidentialBanner />}
      {showShare && <ShareModal proj={proj} updatedAt={updatedAt} onClose={() => setShowShare(false)} />}

      <div className="p-6">
        {/* Header */}
        <div className="flex items-start justify-between flex-wrap gap-3 mb-2">
          <div>
            <IT value={dashTitle} onSave={v => touch({ ...state, dashTitle: v })} className="text-2xl font-bold text-gray-800" wide placeholder="Dashboard Title" />
            <div className="flex items-center gap-3 mt-1">
              <span className="text-xs text-gray-400">Click any value to edit</span>
              {saved && <span className="text-xs text-emerald-500 flex items-center gap-1"><Check className="w-3 h-3" />Saved</span>}
              <span className="text-xs text-gray-300">Updated: {updatedAt}</span>
            </div>
          </div>
          <div className="flex gap-2 flex-wrap">
            <PanelSettings panels={panels} onChange={(k, v) => setPanels(p => ({ ...p, [k]: v }))} />
            <div className="relative">
              <button onClick={() => setShowExport(o => !o)} className="flex items-center gap-1.5 px-3 py-2 bg-white border border-gray-200 text-gray-600 text-sm rounded-lg hover:border-gray-400 shadow-sm">
                <Download className="w-4 h-4" /> Export
              </button>
              {showExport && <div className="absolute right-0 top-10 bg-white border border-gray-200 rounded-xl shadow-lg z-50 p-4 w-52">
                <p className="text-xs font-semibold text-gray-500 mb-3 uppercase tracking-wide">Export</p>
                <div className="space-y-1">
                  <button onClick={() => { exportCSV(proj); setShowExport(false); }} className="flex items-center gap-2 w-full text-sm text-gray-700 hover:text-gray-900 py-1.5"><FileText className="w-3.5 h-3.5 text-gray-400" />CSV</button>
                  <button onClick={() => { exportExcel(proj); setShowExport(false); }} className="flex items-center gap-2 w-full text-sm text-gray-700 hover:text-gray-900 py-1.5"><FileText className="w-3.5 h-3.5 text-emerald-500" />Excel (.xlsx)</button>
                  <button onClick={() => { exportPPT(proj, updatedAt); setShowExport(false); }} className="flex items-center gap-2 w-full text-sm text-gray-700 hover:text-gray-900 py-1.5"><FileText className="w-3.5 h-3.5 text-orange-500" />PowerPoint (.pptx)</button>
                  <button onClick={() => { window.print(); setShowExport(false); }} className="flex items-center gap-2 w-full text-sm text-gray-700 hover:text-gray-900 py-1.5"><FileText className="w-3.5 h-3.5 text-red-400" />PDF (print)</button>
                  <hr className="my-2 border-gray-100" />
                  <button onClick={() => { exportJSON(); setShowExport(false); }} className="flex items-center gap-2 w-full text-sm text-gray-700 hover:text-gray-900 py-1.5"><Save className="w-3.5 h-3.5" />Backup (JSON)</button>
                  <label className="flex items-center gap-2 w-full text-sm text-gray-700 hover:text-gray-900 py-1.5 cursor-pointer"><Upload className="w-3.5 h-3.5" />Import backup<input type="file" accept=".json" className="hidden" onChange={importJSON} /></label>
                  <button onClick={() => { if (window.confirm("Reset everything?")) { touch(INIT_STATE); setActiveId(INIT_STATE.projects[0].id); setShowExport(false); } }} className="flex items-center gap-2 w-full text-sm text-red-400 hover:text-red-600 py-1.5"><RefreshCw className="w-3.5 h-3.5" />Reset all</button>
                </div>
                {importErr && <p className="text-xs text-red-500 mt-2">{importErr}</p>}
              </div>}
            </div>
            <button onClick={() => setShowShare(true)} className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm rounded-lg shadow-sm">
              <Share2 className="w-4 h-4" /> Share
            </button>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex gap-2 mb-5 flex-wrap items-center">
          {projects.map(p => (
            <div key={p.id} className={`flex items-center gap-1 rounded-lg border transition-all ${activeId === p.id ? "bg-gray-800 border-gray-800" : "bg-white border-gray-200 hover:border-gray-400"}`}>
              <button onClick={() => setActiveId(p.id)} className="flex items-center gap-2 px-3 py-2 text-sm font-medium">
                <span className={`w-2.5 h-2.5 rounded-full shrink-0 ${RAG_DOT[p.rag] || "bg-gray-300"}`} />
