              <thead><tr className="text-xs text-gray-400 border-b border-gray-100 text-left"><th className="pb-2 w-24">Date</th><th className="pb-2 w-40">Attendees</th><th className="pb-2">Summary</th><th className="pb-2 w-5" /></tr></thead>
              <tbody>{proj.meetings.map(m => <tr key={m.id} className="border-b border-gray-50 last:border-0 group">
                <td className="py-2 text-gray-500 align-top"><IT value={m.date} onSave={v => updMeet(m.id, "date", v)} /></td>
                <td className="py-2 text-gray-500 align-top"><IT value={m.attendees} onSave={v => updMeet(m.id, "attendees", v)} wide /></td>
                <td className="py-2 text-gray-700 align-top"><IT value={m.summary} onSave={v => updMeet(m.id, "summary", v)} wide /></td>
                <td className="py-2 align-top text-right"><button onClick={() => up("meetings", proj.meetings.filter(x => x.id !== m.id))} className="opacity-0 group-hover:opacity-100"><Trash2 className="w-3.5 h-3.5 text-gray-300 hover:text-red-400" /></button></td>
              </tr>)}</tbody>
