-- Dashboard state: one row per user session (keyed by a user_id stored in localStorage)
create table if not exists dashboard_state (
  id uuid primary key default gen_random_uuid(),
  user_id text not null unique,
  state jsonb not null,
  updated_at timestamptz default now()
);

-- Consultant settings: one row per user
create table if not exists consultant_settings (
  id uuid primary key default gen_random_uuid(),
  user_id text not null unique,
  settings jsonb not null,
  updated_at timestamptz default now()
);

-- Auto-update updated_at on save
create or replace function update_updated_at()
returns trigger as $$
begin
  new.updated_at = now();
  return new;
end;
$$ language plpgsql;

create trigger dashboard_state_updated_at
  before update on dashboard_state
  for each row execute function update_updated_at();

create trigger consultant_settings_updated_at
  before update on consultant_settings
  for each row execute function update_updated_at();

-- Enable Row Level Security (open read/write by anon key — single user app)
alter table dashboard_state enable row level security;
alter table consultant_settings enable row level security;

create policy "allow all on dashboard_state" on dashboard_state for all using (true) with check (true);
create policy "allow all on consultant_settings" on consultant_settings for all using (true) with check (true);

