// ── AI EXEC SUMMARY ────────────────────────────────────────────────────────────
function ExecSummaryPanel({ proj, execSummary, onSave }) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const generate = async () => {
    setLoading(true); setError("");
    try {
      const apiKey = import.meta.env.VITE_ANTHROPIC_API_KEY;
      if (!apiKey) throw new Error("no key");
      const milDone = proj.milestones.filter(m => m.done).length;
      const budPct = pct(proj.spent, proj.budget);
      const openTasks = proj.tasks.filter(t => t.status !== "Done" && t.status !== "Complete").length;
      const openRisks = proj.risks.filter(r => r.flag === "Red").length;
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json", "x-api-key": apiKey, "anthropic-version": "2023-06-01", "anthropic-dangerous-direct-browser-access": "true" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514", max_tokens: 300,
          system: "You are a consulting engagement manager. Write a concise 2–3 sentence executive summary of a project's current status for a client-facing dashboard. Be direct, factual, and professional. No bullet points, no headers — plain prose only.",
          messages: [{ role: "user", content: `Write an executive summary for this project:\n\nProject: ${proj.name}\nClient: ${proj.client}\nRAG Status: ${proj.rag}\nBudget used: $${proj.spent.toLocaleString()} of $${proj.budget.toLocaleString()} (${budPct}%)\nMilestones complete: ${milDone} of ${proj.milestones.length}\nOpen tasks: ${openTasks} of ${proj.tasks.length}\nRed risks: ${openRisks}\nOpen asks from client: ${proj.openAsks.filter(a=>!a.done).length}\nNext milestone: ${proj.milestones.find(m=>!m.done)?.name || "None"} on ${proj.milestones.find(m=>!m.done)?.date || "TBD"}\n\nKeep it to 2–3 sentences. State where the project stands, what's on track or at risk, and what's coming next.` }]
        })
      });
      const data = await res.json();
      const text = data.content?.find(b => b.type === "text")?.text || "";
      onSave(text.trim());
    } catch {
      setError("Set VITE_ANTHROPIC_API_KEY in Netlify environment variables to enable AI generation.");
    }
    setLoading(false);
  };

  return <Card className="mb-6">
    <div className="flex items-center justify-between mb-3">
      <h2 className="text-sm font-semibold text-gray-700">Executive Summary</h2>
      <button onClick={generate} disabled={loading}
        className={`print:hidden flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg transition-colors ${loading ? "bg-gray-100 text-gray-400" : "bg-blue-600 text-white hover:bg-blue-700"}`}>
        {loading ? "Generating…" : "✦ Generate with AI"}
      </button>
    </div>
    {error && <p className="text-xs text-amber-600 bg-amber-50 rounded-lg p-2 mb-3">{error}</p>}
    <TA value={execSummary} onSave={onSave} rows={3} placeholder="Click 'Generate with AI' or write a 2–3 sentence status summary for the client…" />
  </Card>;
}

