import React, { useState } from 'react';
import { LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { Upload, FileText, Loader2, BarChart2, TrendingUp, Table, Hash } from 'lucide-react';

const VIZ_TYPES = [
  { id: 'bar_chart',  label: 'Bar Chart',   Icon: BarChart2,  desc: 'Compare categories' },
  { id: 'line_chart', label: 'Line Chart',  Icon: TrendingUp, desc: 'Show trends over time' },
  { id: 'table',      label: 'Table',       Icon: Table,      desc: 'Detailed row data' },
  { id: 'count',      label: 'Single Value',Icon: Hash,       desc: 'Sum, avg, or count' },
];

const CSVDataVisualizer = () => {
  const [csvData, setCsvData] = useState(null);
  const [headers, setHeaders] = useState([]);
  const [displayData, setDisplayData] = useState([]);
  const [analysisQuery, setAnalysisQuery] = useState('');
  const [selectedViz, setSelectedViz] = useState(null);
  const [analysisResult, setAnalysisResult] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState('');
  const [error, setError] = useState('');

  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    try {
      const text = await new Promise((res, rej) => {
        const r = new FileReader();
        r.onload = ev => res(ev.target.result);
        r.onerror = rej;
        r.readAsText(file);
      });
      const lines = text.trim().split('\n');
      const parsedHeaders = lines[0].split(',').map(h => h.trim());
      setHeaders(parsedHeaders);
      const rows = [];
      for (let i = 1; i < Math.min(6, lines.length); i++) {
        const vals = lines[i].split(',').map(v => v.trim());
        const row = {};
        parsedHeaders.forEach((h, idx) => { row[h] = vals[idx] || ''; });
        rows.push(row);
      }
      setDisplayData(rows);
      setCsvData(text);
      setAnalysisResult(null);
      setError('');
    } catch (err) {
      setError('Error reading CSV file: ' + err.message);
    }
  };

  const runAnalysis = async () => {
    if (!csvData || !analysisQuery.trim()) {
      setError('Please upload a CSV file and enter an analysis query.');
      return;
    }
    if (!selectedViz) {
      setError('Please select a visualization type before running analysis.');
      return;
    }
    setIsLoading(true);
    setLoadingStatus('Planning analysis...');
    setError('');

    try {
      const sampleData = csvData.trim().split('\n').slice(0, 6).join('\n');

      const vizInstructions = {
        bar_chart:  'Output type MUST be "bar_chart". data = { labels: string[], values: number[], title?: string }',
        line_chart: 'Output type MUST be "line_chart". data = { labels: string[], values: number[], title?: string }',
        table:      'Output type MUST be "table". data = { headers: string[], rows: any[][] }',
        count:      'Output type MUST be "count". data = { value: number, label?: string }',
      };

      const prompt = `Given this CSV data (first 5 rows shown):
${sampleData}

User's analysis request: "${analysisQuery}"

The user has chosen the visualization type: ${selectedViz}.
${vizInstructions[selectedViz]}

Write JavaScript code that:
1. Parses the full CSV (available in variable 'csvData')
2. Performs the requested analysis
3. Assigns: analysisResult = { type: '${selectedViz}', data: <structure above>, config: {} }

IMPORTANT: Return ONLY raw JavaScript code. No markdown, no backticks, no explanation.`;

      const response = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514",
          max_tokens: 1000,
          messages: [{ role: "user", content: prompt }]
        })
      });

      if (!response.ok) throw new Error(`API request failed: ${response.status}`);
      const data = await response.json();
      const code = data.content[0].text;

      setLoadingStatus('Calculating results...');
      const execute = new Function('csvData', code + '\nreturn analysisResult;');
      setAnalysisResult(execute(csvData));
    } catch (err) {
      setError('Error during analysis: ' + err.message);
    } finally {
      setIsLoading(false);
      setLoadingStatus('');
    }
  };

  const renderVisualization = () => {
    if (!analysisResult) return null;
    const { type, data } = analysisResult;

    if (type === 'bar_chart') {
      const chartData = data.labels.map((l, i) => ({ name: l, value: data.values[i] }));
      return (
        <div className="mt-6">
          <h3 className="text-xl font-semibold mb-4">{data.title || 'Bar Chart'}</h3>
          <ResponsiveContainer width="100%" height={400}>
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip />
              <Legend />
              <Bar dataKey="value" fill="#3B82F6" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      );
    }

    if (type === 'line_chart') {
      const chartData = data.labels.map((l, i) => ({ name: l, value: data.values[i] }));
      return (
        <div className="mt-6">
