                  {data.headers.map((h, i) => (
                    <th key={i} className="border border-gray-300 px-4 py-2 text-left font-semibold">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {data.rows.map((row, ri) => (
                  <tr key={ri} className="hover:bg-gray-50">
                    {row.map((cell, ci) => (
                      <td key={ci} className="border border-gray-300 px-4 py-2">{cell}</td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      );
    }

    if (type === 'count') {
      return (
        <div className="mt-6 text-center py-8">
          <p className="text-gray-500 text-lg mb-2">{data.label || 'Result'}</p>
          <div className="text-6xl font-bold text-blue-600">{data.value}</div>
