    return <div className="mt-6 text-red-600">Unknown visualization type: {type}</div>;
  };

  return (
    <div className="min-h-screen bg-white p-8">
      <div className="max-w-5xl mx-auto">
        <h1 className="text-3xl font-bold text-gray-900 mb-2">CSV Data Visualizer</h1>
        <p className="text-gray-500 mb-8">Upload a CSV, pick a chart type, then describe what you want to see.</p>

        {/* Upload */}
        <label className="flex items-center justify-center w-full h-28 px-4 mb-8 bg-white border-2 border-gray-300 border-dashed rounded-lg cursor-pointer hover:border-blue-400 transition">
          <div className="flex flex-col items-center gap-1">
            <Upload className="w-7 h-7 text-gray-400" />
