import { Upload, FileText, Loader2, Download, Plus, X, AlignLeft, BarChart2, TrendingUp, Table, Hash, Clipboard, ChevronDown, ChevronUp } from "lucide-react";

const PRESETS = [
  "Show revenue trend over time",
  "Top 10 by value",
  "Month-over-month change",
  "Distribution by category",
  "Average by group",
  "Count of records by type",
];

const VIZ_TYPES = [
  { id: "bar_chart", label: "Bar", Icon: BarChart2 },
  { id: "line_chart", label: "Line", Icon: TrendingUp },
  { id: "table", label: "Table", Icon: Table },
  { id: "count", label: "Value", Icon: Hash },
];

function detectType(samples) {
  const nonEmpty = samples.filter(Boolean);
  if (!nonEmpty.length) return "empty";
  const dateRe = /^\d{1,4}[-\/]\d{1,2}[-\/]\d{1,4}$/;
  if (nonEmpty.every(v => !isNaN(Number(v)))) return "numeric";
  if (nonEmpty.every(v => dateRe.test(v.trim()))) return "date";
  return "categorical";
}

function parseCSV(text) {
  const lines = text.trim().split("\n");
  const headers = lines[0].split(",").map(h => h.trim().replace(/^"|"$/g, ""));
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const vals = lines[i].split(",").map(v => v.trim().replace(/^"|"$/g, ""));
    if (vals.length === headers.length) {
      const row = {};
      headers.forEach((h, idx) => { row[h] = vals[idx]; });
      rows.push(row);
    }
  }
  return { headers, rows };
}

function buildQuality(headers, rows) {
  return headers.map(h => {
    const vals = rows.map(r => r[h]);
    const nulls = vals.filter(v => v === "" || v == null).length;
    const samples = vals.filter(Boolean).slice(0, 20);
    return { header: h, nulls, pctNull: ((nulls / rows.length) * 100).toFixed(0), type: detectType(samples) };
  });
}

const TYPE_COLOR = { numeric: "#378ADD", date: "#1D9E75", categorical: "#7F77DD", empty: "#888780" };
const TYPE_BG = { numeric: "#E6F1FB", date: "#E1F5EE", categorical: "#EEEDFE", empty: "#F1EFE8" };

async function callClaude(prompt, systemPrompt = "") {
  const messages = [{ role: "user", content: prompt }];
  const body = { model: "claude-sonnet-4-20250514", max_tokens: 1000, messages };
  if (systemPrompt) body.system = systemPrompt;
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body)
  });
  if (!res.ok) throw new Error(`API error ${res.status}`);
  const data = await res.json();
  return data.content[0].text;
}

function ChartBlock({ result, idx, onRemove }) {
  const [annotation, setAnnotation] = useState("");
  const [showAnnotInput, setShowAnnotInput] = useState(false);
  const [savedAnnot, setSavedAnnot] = useState("");
  const chartRef = useRef(null);

  const exportPNG = () => {
    const svg = chartRef.current?.querySelector("svg");
    if (!svg) return;
    const svgData = new XMLSerializer().serializeToString(svg);
    const canvas = document.createElement("canvas");
    canvas.width = svg.clientWidth || 600; canvas.height = svg.clientHeight || 400;
    const ctx = canvas.getContext("2d");
    const img = new Image();
    img.onload = () => { ctx.fillStyle = "#fff"; ctx.fillRect(0,0,canvas.width,canvas.height); ctx.drawImage(img,0,0); const a = document.createElement("a"); a.download = `chart-${idx+1}.png`; a.href = canvas.toDataURL(); a.click(); };
    img.src = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(svgData)));
  };

  const exportCSV = () => {
    const { type, data } = result;
    let csv = "";
    if (type === "table") {
      csv = data.headers.join(",") + "\n" + data.rows.map(r => r.join(",")).join("\n");
    } else if (type === "bar_chart" || type === "line_chart") {
      csv = "label,value\n" + data.labels.map((l,i) => `${l},${data.values[i]}`).join("\n");
    } else {
      csv = `label,value\n${data.label || "result"},${data.value}`;
    }
    const a = document.createElement("a"); a.download = `chart-${idx+1}.csv`; a.href = "data:text/csv;charset=utf-8," + encodeURIComponent(csv); a.click();
  };

  const { type, data, query } = result;

  return (
    <div style={{ background: "var(--color-background-primary)", border: "0.5px solid var(--color-border-tertiary)", borderRadius: "var(--border-radius-lg)", padding: "16px 18px", marginBottom: 14 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
        <span style={{ fontSize: 13, fontWeight: 500, color: "var(--color-text-secondary)" }}>{query}</span>
        <div style={{ display: "flex", gap: 6 }}>
          <button onClick={() => setShowAnnotInput(v => !v)} title="Annotate" style={{ background: "none", border: "0.5px solid var(--color-border-tertiary)", borderRadius: 6, padding: "4px 8px", cursor: "pointer", fontSize: 12, color: "var(--color-text-secondary)" }}>
            <AlignLeft size={13} style={{ verticalAlign: "middle" }} /> note
          </button>
          <button onClick={exportPNG} title="Export PNG" style={{ background: "none", border: "0.5px solid var(--color-border-tertiary)", borderRadius: 6, padding: "4px 8px", cursor: "pointer", fontSize: 12, color: "var(--color-text-secondary)" }}>
            <Download size={13} style={{ verticalAlign: "middle" }} /> PNG
          </button>
          <button onClick={exportCSV} title="Export CSV" style={{ background: "none", border: "0.5px solid var(--color-border-tertiary)", borderRadius: 6, padding: "4px 8px", cursor: "pointer", fontSize: 12, color: "var(--color-text-secondary)" }}>
            <Download size={13} style={{ verticalAlign: "middle" }} /> CSV
          </button>
          <button onClick={() => onRemove(idx)} style={{ background: "none", border: "none", cursor: "pointer", color: "var(--color-text-tertiary)", padding: "4px" }}><X size={14} /></button>
        </div>
      </div>

      {savedAnnot && <div style={{ background: "#FAEEDA", borderLeft: "3px solid #BA7517", borderRadius: 4, padding: "6px 10px", fontSize: 12, color: "#633806", marginBottom: 10 }}>{savedAnnot}</div>}

      {showAnnotInput && (
        <div style={{ display: "flex", gap: 6, marginBottom: 10 }}>
          <input value={annotation} onChange={e => setAnnotation(e.target.value)} placeholder="Add a note for this chart..." style={{ flex: 1, fontSize: 12, padding: "6px 10px", borderRadius: 6, border: "0.5px solid var(--color-border-secondary)" }} />
          <button onClick={() => { setSavedAnnot(annotation); setShowAnnotInput(false); }} style={{ background: "#378ADD", color: "#fff", border: "none", borderRadius: 6, padding: "6px 12px", cursor: "pointer", fontSize: 12 }}>Save</button>
        </div>
      )}

      <div ref={chartRef}>
        {(type === "bar_chart") && (() => {
          const d = data.labels.map((l,i) => ({ name: l, value: data.values[i] }));
          return (
            <div>
              <div style={{ fontSize: 14, fontWeight: 500, marginBottom: 8 }}>{data.title || "Bar Chart"}</div>
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={d}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="name" tick={{ fontSize: 11 }} /><YAxis tick={{ fontSize: 11 }} /><Tooltip /><Bar dataKey="value" fill="#378ADD" /></BarChart>
              </ResponsiveContainer>
            </div>
          );
        })()}
        {(type === "line_chart") && (() => {
          const d = data.labels.map((l,i) => ({ name: l, value: data.values[i] }));
          return (
            <div>
              <div style={{ fontSize: 14, fontWeight: 500, marginBottom: 8 }}>{data.title || "Line Chart"}</div>
              <ResponsiveContainer width="100%" height={300}>
                <LineChart data={d}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="name" tick={{ fontSize: 11 }} /><YAxis tick={{ fontSize: 11 }} /><Tooltip /><Line type="monotone" dataKey="value" stroke="#378ADD" strokeWidth={2} dot={false} /></LineChart>
              </ResponsiveContainer>
            </div>
          );
        })()}
        {type === "table" && (
          <div style={{ overflowX: "auto" }}>
            <div style={{ fontSize: 14, fontWeight: 500, marginBottom: 8 }}>{data.title || "Table"}</div>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
              <thead><tr>{data.headers.map((h,i) => <th key={i} style={{ borderBottom: "1px solid var(--color-border-tertiary)", padding: "6px 10px", textAlign: "left", fontWeight: 500, color: "var(--color-text-secondary)" }}>{h}</th>)}</tr></thead>
              <tbody>{data.rows.map((row,ri) => <tr key={ri}>{row.map((c,ci) => <td key={ci} style={{ borderBottom: "0.5px solid var(--color-border-tertiary)", padding: "5px 10px", color: "var(--color-text-primary)" }}>{c}</td>)}</tr>)}</tbody>
            </table>
          </div>
        )}
        {type === "count" && (
          <div style={{ textAlign: "center", padding: "24px 0" }}>
            <div style={{ fontSize: 12, color: "var(--color-text-secondary)", marginBottom: 4 }}>{data.label || "Result"}</div>
            <div style={{ fontSize: 52, fontWeight: 500, color: "#378ADD" }}>{typeof data.value === "number" ? data.value.toLocaleString() : data.value}</div>
          </div>
        )}
      </div>
    </div>
  );
}

export default function App() {
  const [csvData, setCsvData] = useState(null);
  const [parsed, setParsed] = useState(null);
  const [quality, setQuality] = useState(null);
  const [summary, setSummary] = useState(null);
  const [summaryLoading, setSummaryLoading] = useState(false);
  const [clientCtx, setClientCtx] = useState({ name: "", goal: "", notes: "" });
  const [showCtx, setShowCtx] = useState(true);
  const [query, setQuery] = useState("");
  const [vizType, setVizType] = useState("bar_chart");
  const [charts, setCharts] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [talkingPts, setTalkingPts] = useState("");
  const [tpLoading, setTpLoading] = useState(false);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState("");
  const [showQuality, setShowQuality] = useState(false);

  const handleUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const text = await file.text();
    const p = parseCSV(text);
    const q = buildQuality(p.headers, p.rows);
    setCsvData(text);
    setParsed(p);
    setQuality(q);
    setCharts([]);
    setTalkingPts("");
    setSummary(null);
    setError("");
    generateSummary(text, p, q);
  };

  const generateSummary = async (text, p, q) => {
    setSummaryLoading(true);
    try {
      const sampleLines = text.trim().split("\n").slice(0, 8).join("\n");
      const prompt = `Given this CSV data sample:\n${sampleLines}\n\nHeaders: ${p.headers.join(", ")}\nRow count: ${p.rows.length}\n\nGenerate a JSON summary with these exact keys: { "rowCount": number, "colCount": number, "stats": [{ "label": string, "value": string }] } where stats contains 4 key metrics (totals, averages, date range, etc.) that are most useful for a quick business overview. Respond with ONLY valid JSON, no backticks.`;
      const raw = await callClaude(prompt);
      const clean = raw.replace(/```json|```/g, "").trim();
      setSummary(JSON.parse(clean));
    } catch { setSummary({ rowCount: p.rows.length, colCount: p.headers.length, stats: [] }); }
    setSummaryLoading(false);
  };

  const runAnalysis = async () => {
    if (!csvData || !query.trim()) { setError("Enter a query first."); return; }
    setIsLoading(true); setError("");
    try {
      const sampleLines = csvData.trim().split("\n").slice(0, 6).join("\n");
      const ctxStr = clientCtx.name ? `\nClient context — Name: ${clientCtx.name}, Goal: ${clientCtx.goal}, Notes: ${clientCtx.notes}` : "";
      const vizMap = {
        bar_chart: 'type MUST be "bar_chart", data = { labels: string[], values: number[], title?: string }',
        line_chart: 'type MUST be "line_chart", data = { labels: string[], values: number[], title?: string }',
        table: 'type MUST be "table", data = { headers: string[], rows: any[][], title?: string }',
        count: 'type MUST be "count", data = { value: number, label?: string }',
      };
      const prompt = `CSV sample:\n${sampleLines}\n${ctxStr}\n\nUser request: "${query}"\n\nWrite JavaScript that:\n1. Parses full CSV in variable 'csvData'\n2. Sets: analysisResult = { type, data, query: "${query}" }\n${vizMap[vizType]}\n\nReturn ONLY raw JavaScript. No markdown.`;
      const code = await callClaude(prompt);
      const fn = new Function("csvData", code + "\nreturn analysisResult;");
      const result = fn(csvData);
      result.query = query;
      setCharts(prev => [...prev, result]);
      setQuery("");
    } catch (err) { setError("Analysis error: " + err.message); }
    setIsLoading(false);
  };

  const generateTalkingPoints = async () => {
    if (!csvData) return;
    setTpLoading(true); setTalkingPts("");
    try {
      const sampleLines = csvData.trim().split("\n").slice(0, 10).join("\n");
      const ctxStr = clientCtx.name ? `Client: ${clientCtx.name}. Goal: ${clientCtx.goal}. Notes: ${clientCtx.notes}.` : "";
      const chartSummaries = charts.map((c,i) => `Chart ${i+1} (${c.query}): ${JSON.stringify(c.data).slice(0,200)}`).join("\n");
      const prompt = `${ctxStr}\nCSV data sample:\n${sampleLines}\n\nCharts generated:\n${chartSummaries || "None yet"}\n\nGenerate 5 concise executive talking points for a client call. Each point should be one sentence, data-driven, and directly actionable. Format as a numbered list 1-5. No preamble.`;
      const pts = await callClaude(prompt);
      setTalkingPts(pts);
    } catch (err) { setError("Talking points error: " + err.message); }
    setTpLoading(false);
  };

  const copyTalkingPts = () => { navigator.clipboard.writeText(talkingPts); setCopied(true); setTimeout(() => setCopied(false), 1800); };

  return (
    <div style={{ maxWidth: 820, margin: "0 auto", padding: "24px 16px", fontFamily: "var(--font-sans)" }}>
      <div style={{ marginBottom: 20 }}>
        <h1 style={{ fontSize: 22, fontWeight: 500, color: "var(--color-text-primary)", margin: 0 }}>CSV Visualizer</h1>
        <p style={{ fontSize: 13, color: "var(--color-text-secondary)", marginTop: 4 }}>Client call prep — upload data, build charts, generate talking points</p>
      </div>

      {/* Client context */}
      <div style={{ background: "var(--color-background-primary)", border: "0.5px solid var(--color-border-tertiary)", borderRadius: "var(--border-radius-lg)", marginBottom: 16, overflow: "hidden" }}>
        <div onClick={() => setShowCtx(v => !v)} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "12px 16px", cursor: "pointer" }}>
          <span style={{ fontSize: 13, fontWeight: 500, color: "var(--color-text-primary)" }}>Client context</span>
          {showCtx ? <ChevronUp size={15} color="var(--color-text-secondary)" /> : <ChevronDown size={15} color="var(--color-text-secondary)" />}
        </div>
        {showCtx && (
          <div style={{ padding: "0 16px 14px", display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
            <input placeholder="Client name" value={clientCtx.name} onChange={e => setClientCtx(p => ({...p, name: e.target.value}))} style={{ fontSize: 13, padding: "7px 10px", borderRadius: 6, border: "0.5px solid var(--color-border-secondary)", gridColumn: "1" }} />
            <input placeholder="Meeting goal" value={clientCtx.goal} onChange={e => setClientCtx(p => ({...p, goal: e.target.value}))} style={{ fontSize: 13, padding: "7px 10px", borderRadius: 6, border: "0.5px solid var(--color-border-secondary)" }} />
            <input placeholder="Notes (context, concerns, focus areas...)" value={clientCtx.notes} onChange={e => setClientCtx(p => ({...p, notes: e.target.value}))} style={{ fontSize: 13, padding: "7px 10px", borderRadius: 6, border: "0.5px solid var(--color-border-secondary)", gridColumn: "1 / -1" }} />
          </div>
        )}
      </div>

      {/* Upload */}
      <label style={{ display: "flex", alignItems: "center", justifyContent: "center", width: "100%", height: 72, border: "1.5px dashed var(--color-border-secondary)", borderRadius: "var(--border-radius-lg)", cursor: "pointer", marginBottom: 16, background: "var(--color-background-secondary)" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <Upload size={16} color="var(--color-text-secondary)" />
          <span style={{ fontSize: 13, color: "var(--color-text-secondary)" }}>{csvData ? `✓ File loaded — drop a new file to replace` : "Drop CSV here or click to upload"}</span>
        </div>
        <input type="file" accept=".csv" onChange={handleUpload} style={{ display: "none" }} />
      </label>

      {/* Summary card */}
      {summaryLoading && <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "10px 0", color: "var(--color-text-secondary)", fontSize: 13 }}><Loader2 size={14} className="animate-spin" style={{ animation: "spin 1s linear infinite" }} /> Generating summary...</div>}
      {summary && (
        <div style={{ marginBottom: 16 }}>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(130px, 1fr))", gap: 10, marginBottom: 10 }}>
            <div style={{ background: "var(--color-background-secondary)", borderRadius: "var(--border-radius-md)", padding: "12px 14px" }}>
              <div style={{ fontSize: 11, color: "var(--color-text-secondary)", marginBottom: 4 }}>Rows</div>
              <div style={{ fontSize: 22, fontWeight: 500 }}>{summary.rowCount?.toLocaleString()}</div>
            </div>
            <div style={{ background: "var(--color-background-secondary)", borderRadius: "var(--border-radius-md)", padding: "12px 14px" }}>
              <div style={{ fontSize: 11, color: "var(--color-text-secondary)", marginBottom: 4 }}>Columns</div>
              <div style={{ fontSize: 22, fontWeight: 500 }}>{summary.colCount}</div>
            </div>
            {summary.stats?.map((s,i) => (
              <div key={i} style={{ background: "var(--color-background-secondary)", borderRadius: "var(--border-radius-md)", padding: "12px 14px" }}>
                <div style={{ fontSize: 11, color: "var(--color-text-secondary)", marginBottom: 4 }}>{s.label}</div>
                <div style={{ fontSize: 18, fontWeight: 500, wordBreak: "break-word" }}>{s.value}</div>
              </div>
            ))}
          </div>

          {/* Data quality toggle */}
          {quality && (
            <div style={{ background: "var(--color-background-primary)", border: "0.5px solid var(--color-border-tertiary)", borderRadius: "var(--border-radius-md)", overflow: "hidden" }}>
              <div onClick={() => setShowQuality(v => !v)} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "9px 14px", cursor: "pointer" }}>
                <span style={{ fontSize: 12, fontWeight: 500, color: "var(--color-text-secondary)" }}>Column quality &amp; types</span>
                {showQuality ? <ChevronUp size={13} color="var(--color-text-secondary)" /> : <ChevronDown size={13} color="var(--color-text-secondary)" />}
              </div>
              {showQuality && (
                <div style={{ padding: "0 14px 12px", display: "flex", flexWrap: "wrap", gap: 6 }}>
                  {quality.map((col, i) => (
                    <div key={i} style={{ fontSize: 11, padding: "4px 8px", borderRadius: 20, background: TYPE_BG[col.type], color: TYPE_COLOR[col.type], display: "flex", alignItems: "center", gap: 5 }}>
                      <span style={{ fontWeight: 500 }}>{col.header}</span>
                      <span style={{ opacity: 0.7 }}>{col.type}</span>
                      {col.nulls > 0 && <span style={{ background: "#F7C1C1", color: "#A32D2D", borderRadius: 10, padding: "1px 5px" }}>{col.pctNull}% null</span>}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {/* Analysis panel */}
      {csvData && (
        <div style={{ background: "var(--color-background-primary)", border: "0.5px solid var(--color-border-tertiary)", borderRadius: "var(--border-radius-lg)", padding: "16px", marginBottom: 16 }}>
          {/* Preset buttons */}
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 12 }}>
            {PRESETS.map((p,i) => (
              <button key={i} onClick={() => setQuery(p)} style={{ fontSize: 11, padding: "4px 10px", borderRadius: 20, border: "0.5px solid var(--color-border-secondary)", background: "var(--color-background-secondary)", cursor: "pointer", color: "var(--color-text-secondary)" }}>{p}</button>
            ))}
          </div>

          {/* Viz type */}
          <div style={{ display: "flex", gap: 6, marginBottom: 10 }}>
            {VIZ_TYPES.map(({ id, label, Icon }) => (
              <button key={id} onClick={() => setVizType(id)} style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 12, padding: "5px 12px", borderRadius: 6, border: vizType === id ? "1.5px solid #378ADD" : "0.5px solid var(--color-border-secondary)", background: vizType === id ? "#E6F1FB" : "var(--color-background-secondary)", color: vizType === id ? "#0C447C" : "var(--color-text-secondary)", cursor: "pointer", fontWeight: vizType === id ? 500 : 400 }}>
                <Icon size={13} />{label}
              </button>
            ))}
          </div>

          {/* Query input */}
          <div style={{ display: "flex", gap: 8 }}>
            <input value={query} onChange={e => setQuery(e.target.value)} onKeyDown={e => e.key === "Enter" && runAnalysis()} placeholder='Describe what you want to see, or pick a preset above...' style={{ flex: 1, fontSize: 13, padding: "8px 12px", borderRadius: 6, border: "0.5px solid var(--color-border-secondary)" }} disabled={isLoading} />
            <button onClick={runAnalysis} disabled={isLoading || !query.trim()} style={{ display: "flex", alignItems: "center", gap: 6, padding: "8px 16px", background: "#378ADD", color: "#fff", border: "none", borderRadius: 6, fontSize: 13, fontWeight: 500, cursor: "pointer", whiteSpace: "nowrap", opacity: isLoading || !query.trim() ? 0.5 : 1 }}>
              {isLoading ? <Loader2 size={14} style={{ animation: "spin 1s linear infinite" }} /> : <Plus size={14} />}
              {isLoading ? "Running..." : "Add chart"}
            </button>
          </div>
        </div>
      )}

      {error && <div style={{ background: "#FCEBEB", border: "0.5px solid #F09595", borderRadius: 6, padding: "8px 12px", fontSize: 12, color: "#A32D2D", marginBottom: 12 }}>{error}</div>}

      {/* Charts */}
      {charts.length > 0 && (
        <div style={{ marginBottom: 16 }}>
          {charts.map((c,i) => <ChartBlock key={i} result={c} idx={i} onRemove={idx => setCharts(prev => prev.filter((_,j) => j !== idx))} />)}
        </div>
      )}

      {/* Talking points */}
      {csvData && (
        <div style={{ background: "var(--color-background-primary)", border: "0.5px solid var(--color-border-tertiary)", borderRadius: "var(--border-radius-lg)", padding: "16px" }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: talkingPts ? 12 : 0 }}>
            <span style={{ fontSize: 13, fontWeight: 500 }}>Talking points</span>
            <div style={{ display: "flex", gap: 6 }}>
              {talkingPts && <button onClick={copyTalkingPts} style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 12, padding: "5px 10px", borderRadius: 6, border: "0.5px solid var(--color-border-secondary)", background: "var(--color-background-secondary)", cursor: "pointer", color: "var(--color-text-secondary)" }}><Clipboard size={12} />{copied ? "Copied!" : "Copy"}</button>}
              <button onClick={generateTalkingPoints} disabled={tpLoading} style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 12, padding: "5px 12px", borderRadius: 6, border: "none", background: "#378ADD", color: "#fff", cursor: "pointer", opacity: tpLoading ? 0.6 : 1 }}>
                {tpLoading ? <Loader2 size={12} style={{ animation: "spin 1s linear infinite" }} /> : null}
                {tpLoading ? "Generating..." : talkingPts ? "Regenerate" : "Generate for this call"}
              </button>
            </div>
          </div>
          {talkingPts && (
            <div style={{ fontSize: 13, color: "var(--color-text-primary)", lineHeight: 1.8, whiteSpace: "pre-line", paddingTop: 8, borderTop: "0.5px solid var(--color-border-tertiary)" }}>{talkingPts}</div>
          )}
        </div>
      )}

      <style>{`@keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }`}</style>
    </div>
  );
}

