import { useState, useRef, useCallback } from "react";
import { BarChart, Bar, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from "recharts";
import { Upload, Loader2, Download, Plus, X, AlignLeft, BarChart2, TrendingUp, Table, Hash, Clipboard, ChevronDown, ChevronUp, Share2, Printer, FileCode } from "lucide-react";

const PRESETS = [
  "Show revenue trend over time","Top 10 by value","Month-over-month change",
  "Distribution by category","Average by group","Count of records by type",
];
const VIZ_TYPES = [
  { id:"bar_chart", label:"Bar", Icon:BarChart2 },
  { id:"line_chart", label:"Line", Icon:TrendingUp },
  { id:"table", label:"Table", Icon:Table },
  { id:"count", label:"Value", Icon:Hash },
];
const TYPE_COLOR = { numeric:"#378ADD", date:"#1D9E75", categorical:"#7F77DD", empty:"#888780" };
const TYPE_BG    = { numeric:"#E6F1FB", date:"#E1F5EE", categorical:"#EEEDFE", empty:"#F1EFE8" };

function detectType(samples) {
  const n = samples.filter(Boolean);
  if (!n.length) return "empty";
  if (n.every(v => !isNaN(Number(v)))) return "numeric";
  if (n.every(v => /^\d{1,4}[-\/]\d{1,2}[-\/]\d{1,4}$/.test(v.trim()))) return "date";
  return "categorical";
}
function parseCSV(text) {
  const lines = text.trim().split("\n");
  const headers = lines[0].split(",").map(h => h.trim().replace(/^"|"$/g,""));
  const rows = [];
  for (let i=1;i<lines.length;i++) {
    const vals = lines[i].split(",").map(v=>v.trim().replace(/^"|"$/g,""));
    if (vals.length===headers.length) { const r={}; headers.forEach((h,j)=>{r[h]=vals[j];}); rows.push(r); }
  }
  return { headers, rows };
}
function buildQuality(headers, rows) {
  return headers.map(h => {
    const vals = rows.map(r=>r[h]);
    const nulls = vals.filter(v=>v===""||v==null).length;
    return { header:h, nulls, pctNull:((nulls/rows.length)*100).toFixed(0), type:detectType(vals.filter(Boolean).slice(0,20)) };
  });
}
async function callClaude(prompt, sys="") {
  const body = { model:"claude-sonnet-4-20250514", max_tokens:1000, messages:[{role:"user",content:prompt}] };
  if (sys) body.system = sys;
  const r = await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});
  if (!r.ok) throw new Error(`API ${r.status}`);
  return (await r.json()).content[0].text;
}

function renderChartSVGString(type, data) {
  if (type==="count") return `<div style="text-align:center;padding:24px 0"><div style="font-size:13px;color:#666;margin-bottom:4px">${data.label||"Result"}</div><div style="font-size:48px;font-weight:500;color:#378ADD">${typeof data.value==="number"?data.value.toLocaleString():data.value}</div></div>`;
  if (type==="table") return `<table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr>${data.headers.map(h=>`<th style="border-bottom:1px solid #ddd;padding:6px 10px;text-align:left;font-weight:500;color:#666">${h}</th>`).join("")}</tr></thead><tbody>${data.rows.map(row=>`<tr>${row.map(c=>`<td style="border-bottom:0.5px solid #eee;padding:5px 10px">${c}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
  return `<div style="color:#999;font-size:12px;padding:8px">Chart preview not available in static export — see data below.</div>`;
}

function ChartBlock({ result, idx, onRemove, chartRef: extRef }) {
  const [annotation, setAnnotation] = useState("");
  const [showAnnot, setShowAnnot] = useState(false);
  const [savedAnnot, setSavedAnnot] = useState("");
  const localRef = useRef(null);
  const ref = extRef || localRef;
  const { type, data, query } = result;

  const exportPNG = () => {
    const svg = ref.current?.querySelector("svg");
    if (!svg) return;
    const s = new XMLSerializer().serializeToString(svg);
    const c = document.createElement("canvas"); c.width=svg.clientWidth||600; c.height=svg.clientHeight||350;
    const ctx=c.getContext("2d"); const img=new Image();
    img.onload=()=>{ ctx.fillStyle="#fff"; ctx.fillRect(0,0,c.width,c.height); ctx.drawImage(img,0,0); const a=document.createElement("a"); a.download=`chart-${idx+1}.png`; a.href=c.toDataURL(); a.click(); };
    img.src="data:image/svg+xml;base64,"+btoa(unescape(encodeURIComponent(s)));
  };
  const exportCSV = () => {
    let csv="";
    if (type==="table") csv=data.headers.join(",")+"\n"+data.rows.map(r=>r.join(",")).join("\n");
    else if (type==="bar_chart"||type==="line_chart") csv="label,value\n"+data.labels.map((l,i)=>`${l},${data.values[i]}`).join("\n");
    else csv=`label,value\n${data.label||"result"},${data.value}`;
    const a=document.createElement("a"); a.download=`chart-${idx+1}.csv`; a.href="data:text/csv;charset=utf-8,"+encodeURIComponent(csv); a.click();
  };

  return (
    <div ref={ref} data-chart-idx={idx} style={{background:"var(--color-background-primary)",border:"0.5px solid var(--color-border-tertiary)",borderRadius:"var(--border-radius-lg)",padding:"16px 18px",marginBottom:14}}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:10}}>
        <span style={{fontSize:13,fontWeight:500,color:"var(--color-text-secondary)"}}>{query}</span>
        <div style={{display:"flex",gap:6}}>
          {[["note",()=>setShowAnnot(v=>!v),<AlignLeft size={13}/>],["PNG",exportPNG,<Download size={13}/>],["CSV",exportCSV,<Download size={13}/>]].map(([lbl,fn,ic])=>(
            <button key={lbl} onClick={fn} style={{background:"none",border:"0.5px solid var(--color-border-tertiary)",borderRadius:6,padding:"4px 8px",cursor:"pointer",fontSize:12,color:"var(--color-text-secondary)",display:"flex",alignItems:"center",gap:4}}>{ic}{lbl}</button>
          ))}
          <button onClick={()=>onRemove(idx)} style={{background:"none",border:"none",cursor:"pointer",color:"var(--color-text-tertiary)",padding:"4px"}}><X size={14}/></button>
        </div>
      </div>
      {savedAnnot && <div style={{background:"#FAEEDA",borderLeft:"3px solid #BA7517",borderRadius:4,padding:"6px 10px",fontSize:12,color:"#633806",marginBottom:10}}>{savedAnnot}</div>}
      {showAnnot && (
        <div style={{display:"flex",gap:6,marginBottom:10}}>
          <input value={annotation} onChange={e=>setAnnotation(e.target.value)} placeholder="Add a note..." style={{flex:1,fontSize:12,padding:"6px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)"}}/>
          <button onClick={()=>{setSavedAnnot(annotation);setShowAnnot(false);}} style={{background:"#378ADD",color:"#fff",border:"none",borderRadius:6,padding:"6px 12px",cursor:"pointer",fontSize:12}}>Save</button>
        </div>
      )}
      {(type==="bar_chart") && (() => {
        const d=data.labels.map((l,i)=>({name:l,value:data.values[i]}));
        return <div><div style={{fontSize:13,fontWeight:500,marginBottom:6}}>{data.title||"Bar Chart"}</div><ResponsiveContainer width="100%" height={260}><BarChart data={d}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name" tick={{fontSize:10}}/><YAxis tick={{fontSize:10}}/><Tooltip/><Bar dataKey="value" fill="#378ADD"/></BarChart></ResponsiveContainer></div>;
      })()}
      {(type==="line_chart") && (() => {
        const d=data.labels.map((l,i)=>({name:l,value:data.values[i]}));
        return <div><div style={{fontSize:13,fontWeight:500,marginBottom:6}}>{data.title||"Line Chart"}</div><ResponsiveContainer width="100%" height={260}><LineChart data={d}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name" tick={{fontSize:10}}/><YAxis tick={{fontSize:10}}/><Tooltip/><Line type="monotone" dataKey="value" stroke="#378ADD" strokeWidth={2} dot={false}/></LineChart></ResponsiveContainer></div>;
      })()}
      {type==="table" && (
        <div style={{overflowX:"auto"}}><div style={{fontSize:13,fontWeight:500,marginBottom:6}}>{data.title||"Table"}</div>
        <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
          <thead><tr>{data.headers.map((h,i)=><th key={i} style={{borderBottom:"1px solid var(--color-border-tertiary)",padding:"6px 10px",textAlign:"left",fontWeight:500,color:"var(--color-text-secondary)"}}>{h}</th>)}</tr></thead>
          <tbody>{data.rows.map((row,ri)=><tr key={ri}>{row.map((c,ci)=><td key={ci} style={{borderBottom:"0.5px solid var(--color-border-tertiary)",padding:"5px 10px"}}>{c}</td>)}</tr>)}</tbody>
        </table></div>
      )}
      {type==="count" && (
        <div style={{textAlign:"center",padding:"20px 0"}}>
          <div style={{fontSize:12,color:"var(--color-text-secondary)",marginBottom:4}}>{data.label||"Result"}</div>
          <div style={{fontSize:48,fontWeight:500,color:"#378ADD"}}>{typeof data.value==="number"?data.value.toLocaleString():data.value}</div>
        </div>
      )}
    </div>
  );
}

// ── Share modal ──────────────────────────────────────────────────────────────
function ShareModal({ onClose, charts, talkingPts, summary, clientCtx, csvData }) {
  const [copied, setCopied] = useState(false);

  const clientName = clientCtx.name || "Client";

  const buildTextSummary = () => {
    const lines = [];
    if (clientCtx.name) lines.push(`CLIENT: ${clientCtx.name}${clientCtx.goal?" — "+clientCtx.goal:""}`);
    lines.push("=".repeat(48));
    if (summary) {
      lines.push(`DATA OVERVIEW`);
      lines.push(`Rows: ${summary.rowCount?.toLocaleString()}  |  Columns: ${summary.colCount}`);
      summary.stats?.forEach(s=>lines.push(`${s.label}: ${s.value}`));
      lines.push("");
    }
    if (talkingPts) { lines.push("TALKING POINTS"); lines.push(talkingPts); lines.push(""); }
    if (charts.length) {
      lines.push("CHARTS");
      charts.forEach((c,i)=>{
        lines.push(`\n${i+1}. ${c.query}`);
        if (c.type==="count") lines.push(`   ${c.data.label||"Result"}: ${c.data.value}`);
        else if (c.type==="bar_chart"||c.type==="line_chart") {
          c.data.labels?.slice(0,8).forEach((l,j)=>lines.push(`   ${l}: ${c.data.values[j]}`));
          if (c.data.labels?.length>8) lines.push(`   ... and ${c.data.labels.length-8} more`);
        } else if (c.type==="table") {
          lines.push("   "+c.data.headers.join(" | "));
          c.data.rows?.slice(0,5).forEach(r=>lines.push("   "+r.join(" | ")));
          if (c.data.rows?.length>5) lines.push(`   ... and ${c.data.rows.length-5} more rows`);
        }
      });
    }
    return lines.join("\n");
  };

  const copyText = () => { navigator.clipboard.writeText(buildTextSummary()); setCopied(true); setTimeout(()=>setCopied(false),2000); };

  const exportHTML = () => {
    const chartsHTML = charts.map((c,i)=>{
      let viz="";
      if (c.type==="count") viz=`<div style="text-align:center;padding:20px 0"><div style="font-size:13px;color:#666">${c.data.label||"Result"}</div><div style="font-size:48px;font-weight:500;color:#378ADD">${typeof c.data.value==="number"?c.data.value.toLocaleString():c.data.value}</div></div>`;
      else if (c.type==="table") viz=`<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr>${c.data.headers.map(h=>`<th style="border-bottom:1px solid #eee;padding:7px 10px;text-align:left;color:#555">${h}</th>`).join("")}</tr></thead><tbody>${c.data.rows.map(r=>`<tr>${r.map(cell=>`<td style="border-bottom:0.5px solid #f0f0f0;padding:6px 10px">${cell}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`;
      else viz=`<p style="color:#999;font-size:12px">Chart data — ${c.data.labels?.slice(0,5).map((l,j)=>`${l}: ${c.data.values[j]}`).join(", ")}${c.data.labels?.length>5?" ...":""}</p>`;
      return `<div style="background:#fff;border:1px solid #e8e8e8;border-radius:12px;padding:18px;margin-bottom:14px"><div style="font-size:13px;font-weight:500;color:#555;margin-bottom:10px">${c.query}</div>${viz}</div>`;
    }).join("");

    const statsHTML = summary?.stats?.map(s=>`<div style="background:#f6f7f8;border-radius:8px;padding:12px 14px"><div style="font-size:11px;color:#888;margin-bottom:3px">${s.label}</div><div style="font-size:20px;font-weight:500">${s.value}</div></div>`).join("")||"";

    const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${clientName} — Data Brief</title><style>body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;max-width:860px;margin:0 auto;padding:40px 24px;color:#1a1a1a;background:#f9f9f8}h1{font-size:22px;font-weight:500;margin:0 0 4px}p.sub{font-size:13px;color:#888;margin:0 0 28px}.section{margin-bottom:32px}.section-label{font-size:11px;font-weight:500;text-transform:uppercase;letter-spacing:.06em;color:#999;margin-bottom:10px}.stats-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin-bottom:16px}.tp{background:#fff;border:1px solid #e8e8e8;border-radius:12px;padding:18px;font-size:14px;line-height:1.8;white-space:pre-line}.footer{margin-top:40px;font-size:11px;color:#bbb;border-top:1px solid #eee;padding-top:16px}</style></head><body><h1>${clientName}${clientCtx.goal?" — "+clientCtx.goal:""}</h1><p class="sub">Generated ${new Date().toLocaleDateString("en-US",{month:"long",day:"numeric",year:"numeric"})}</p>${summary?`<div class="section"><div class="section-label">Data overview</div><div class="stats-grid"><div style="background:#f6f7f8;border-radius:8px;padding:12px 14px"><div style="font-size:11px;color:#888;margin-bottom:3px">Rows</div><div style="font-size:20px;font-weight:500">${summary.rowCount?.toLocaleString()}</div></div><div style="background:#f6f7f8;border-radius:8px;padding:12px 14px"><div style="font-size:11px;color:#888;margin-bottom:3px">Columns</div><div style="font-size:20px;font-weight:500">${summary.colCount}</div></div>${statsHTML}</div></div>`:""}${talkingPts?`<div class="section"><div class="section-label">Talking points</div><div class="tp">${talkingPts}</div></div>`:""}${chartsHTML?`<div class="section"><div class="section-label">Charts &amp; analysis</div>${chartsHTML}</div>`:""}${clientCtx.notes?`<div class="section"><div class="section-label">Notes</div><div class="tp">${clientCtx.notes}</div></div>`:""}<div class="footer">CSV Data Visualizer — exported ${new Date().toISOString()}</div></body></html>`;

    const a=document.createElement("a"); a.download=`${clientName.replace(/\s+/g,"-").toLowerCase()}-brief.html`; a.href="data:text/html;charset=utf-8,"+encodeURIComponent(html); a.click();
  };

  const printView = () => {
    const w = window.open("","_blank","width=900,height=700");
    exportHTML(); // also trigger download
    w.document.write(`<script>window.onload=()=>{window.print();window.close();}<\/script><style>body{font-family:system-ui,sans-serif;max-width:800px;margin:0 auto;padding:32px;color:#111}h1{font-size:20px;font-weight:500}pre{white-space:pre-wrap;font-family:inherit;font-size:13px;line-height:1.7}hr{border:none;border-top:1px solid #ddd;margin:20px 0}</style>`);
    w.document.write(`<h1>${clientName}${clientCtx.goal?" — "+clientCtx.goal:""}</h1><p style="color:#888;font-size:13px">${new Date().toLocaleDateString("en-US",{month:"long",day:"numeric",year:"numeric"})}</p><hr>`);
    if (summary) w.document.write(`<p><strong>Rows:</strong> ${summary.rowCount?.toLocaleString()} &nbsp; <strong>Columns:</strong> ${summary.colCount}</p>`);
    if (talkingPts) w.document.write(`<h2 style="font-size:15px;font-weight:500">Talking points</h2><pre>${talkingPts}</pre><hr>`);
    charts.forEach((c,i)=>{
      w.document.write(`<h2 style="font-size:14px;font-weight:500">${i+1}. ${c.query}</h2>`);
      if (c.type==="count") w.document.write(`<p style="font-size:36px;font-weight:500;color:#378ADD">${c.data.value}</p>`);
      else if (c.type==="table") w.document.write(`<table style="width:100%;border-collapse:collapse;font-size:12px">${c.data.headers.map(h=>`<th style="border-bottom:1px solid #eee;padding:5px 8px;text-align:left">${h}</th>`).join("")}${c.data.rows.map(r=>`<tr>${r.map(cell=>`<td style="border-bottom:0.5px solid #f0f0f0;padding:4px 8px">${cell}</td>`).join("")}</tr>`).join("")}</table>`);
      else w.document.write(`<p style="font-size:12px;color:#999">${c.data.labels?.slice(0,10).map((l,j)=>`${l}: ${c.data.values[j]}`).join(" · ")}</p>`);
      w.document.write("<hr>");
    });
    w.document.close();
  };

  return (
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.4)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:1000}} onClick={e=>{if(e.target===e.currentTarget)onClose();}}>
      <div style={{background:"var(--color-background-primary)",borderRadius:"var(--border-radius-lg)",padding:"24px",width:"100%",maxWidth:420,boxSizing:"border-box"}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:20}}>
          <div>
            <div style={{fontSize:16,fontWeight:500}}>Share with client</div>
            <div style={{fontSize:12,color:"var(--color-text-secondary)",marginTop:2}}>Choose how to deliver this brief</div>
          </div>
          <button onClick={onClose} style={{background:"none",border:"none",cursor:"pointer",color:"var(--color-text-tertiary)"}}><X size={16}/></button>
        </div>

        {[
          { Icon:FileCode, label:"Export HTML file", sub:"Self-contained file they open in any browser", action:exportHTML, btnLabel:"Download .html" },
          { Icon:Printer,  label:"Print / Save PDF",  sub:"Opens print dialog — save as PDF or print",  action:printView,  btnLabel:"Open print view" },
          { Icon:Clipboard,label:"Copy text summary",  sub:"Paste into email, Slack, or a doc",          action:copyText,   btnLabel: copied?"Copied!":"Copy to clipboard" },
        ].map(({Icon,label,sub,action,btnLabel})=>(
          <div key={label} style={{display:"flex",alignItems:"center",gap:14,padding:"14px 0",borderBottom:"0.5px solid var(--color-border-tertiary)"}}>
            <div style={{width:36,height:36,borderRadius:8,background:"var(--color-background-secondary)",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
              <Icon size={16} color="var(--color-text-secondary)"/>
            </div>
            <div style={{flex:1,minWidth:0}}>
              <div style={{fontSize:13,fontWeight:500}}>{label}</div>
              <div style={{fontSize:11,color:"var(--color-text-secondary)",marginTop:1}}>{sub}</div>
            </div>
            <button onClick={action} style={{flexShrink:0,fontSize:12,padding:"6px 12px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)",background:"var(--color-background-secondary)",cursor:"pointer",color:"var(--color-text-primary)",whiteSpace:"nowrap"}}>{btnLabel}</button>
          </div>
        ))}

        <div style={{marginTop:16,fontSize:11,color:"var(--color-text-tertiary)"}}>
          Includes: data overview, talking points, and all {charts.length} chart{charts.length!==1?"s":""}{clientCtx.notes?" + notes":""}.
        </div>
      </div>
    </div>
  );
}

// ── Main app ─────────────────────────────────────────────────────────────────
export default function App() {
  const [csvData, setCsvData] = useState(null);
  const [parsed, setParsed] = useState(null);
  const [quality, setQuality] = useState(null);
  const [summary, setSummary] = useState(null);
  const [summaryLoading, setSummaryLoading] = useState(false);
  const [clientCtx, setClientCtx] = useState({ name:"", goal:"", notes:"" });
  const [showCtx, setShowCtx] = useState(true);
  const [query, setQuery] = useState("");
  const [vizType, setVizType] = useState("bar_chart");
  const [charts, setCharts] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [talkingPts, setTalkingPts] = useState("");
  const [tpLoading, setTpLoading] = useState(false);
  const [tpCopied, setTpCopied] = useState(false);
  const [error, setError] = useState("");
  const [showQuality, setShowQuality] = useState(false);
  const [showShare, setShowShare] = useState(false);

  const handleUpload = async (e) => {
    const file = e.target.files[0]; if (!file) return;
    const text = await file.text();
    const p = parseCSV(text); const q = buildQuality(p.headers, p.rows);
    setCsvData(text); setParsed(p); setQuality(q); setCharts([]); setTalkingPts(""); setSummary(null); setError("");
    genSummary(text, p, q);
  };

  const genSummary = async (text, p) => {
    setSummaryLoading(true);
    try {
      const sample = text.trim().split("\n").slice(0,8).join("\n");
      const raw = await callClaude(`CSV sample:\n${sample}\n\nHeaders: ${p.headers.join(", ")}\nRows: ${p.rows.length}\n\nReturn ONLY valid JSON (no backticks): { "rowCount": number, "colCount": number, "stats": [{"label":string,"value":string}] } with 4 key business metrics.`);
      setSummary(JSON.parse(raw.replace(/```json|```/g,"").trim()));
    } catch { setSummary({ rowCount:p.rows.length, colCount:p.headers.length, stats:[] }); }
    setSummaryLoading(false);
  };

  const runAnalysis = async () => {
    if (!csvData||!query.trim()) { setError("Enter a query first."); return; }
    setIsLoading(true); setError("");
    try {
      const sample = csvData.trim().split("\n").slice(0,6).join("\n");
      const ctx = clientCtx.name ? `\nClient: ${clientCtx.name}. Goal: ${clientCtx.goal}. Notes: ${clientCtx.notes}.` : "";
      const vizMap = {
        bar_chart:'type MUST be "bar_chart", data={labels:string[],values:number[],title?:string}',
        line_chart:'type MUST be "line_chart", data={labels:string[],values:number[],title?:string}',
        table:'type MUST be "table", data={headers:string[],rows:any[][],title?:string}',
        count:'type MUST be "count", data={value:number,label?:string}',
      };
      const code = await callClaude(`CSV sample:\n${sample}${ctx}\n\nRequest: "${query}"\n\nWrite JS that parses 'csvData' and sets: analysisResult = { type, data, query:"${query}" }\n${vizMap[vizType]}\n\nReturn ONLY raw JS.`);
      const fn = new Function("csvData", code+"\nreturn analysisResult;");
      const result = fn(csvData); result.query = query;
      setCharts(prev=>[...prev, result]); setQuery("");
    } catch(err) { setError("Analysis error: "+err.message); }
    setIsLoading(false);
  };

  const genTalkingPts = async () => {
    if (!csvData) return; setTpLoading(true); setTalkingPts("");
    try {
      const sample = csvData.trim().split("\n").slice(0,10).join("\n");
      const ctx = clientCtx.name ? `Client: ${clientCtx.name}. Goal: ${clientCtx.goal}. Notes: ${clientCtx.notes}.` : "";
      const chartSum = charts.map((c,i)=>`Chart ${i+1} (${c.query}): ${JSON.stringify(c.data).slice(0,200)}`).join("\n")||"None yet";
      const pts = await callClaude(`${ctx}\nCSV sample:\n${sample}\n\nCharts:\n${chartSum}\n\nGenerate 5 concise exec talking points for a client call. Numbered list 1-5. Data-driven. No preamble.`);
      setTalkingPts(pts);
    } catch(err) { setError("Talking points error: "+err.message); }
    setTpLoading(false);
  };

  const copyTp = () => { navigator.clipboard.writeText(talkingPts); setTpCopied(true); setTimeout(()=>setTpCopied(false),1800); };

  return (
    <div style={{maxWidth:820,margin:"0 auto",padding:"24px 16px",fontFamily:"var(--font-sans)"}}>
      {showShare && <ShareModal onClose={()=>setShowShare(false)} charts={charts} talkingPts={talkingPts} summary={summary} clientCtx={clientCtx} csvData={csvData}/>}

      <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",marginBottom:20}}>
        <div>
          <h1 style={{fontSize:22,fontWeight:500,margin:0}}>CSV Visualizer</h1>
          <p style={{fontSize:13,color:"var(--color-text-secondary)",marginTop:4}}>Client call prep — upload data, build charts, generate talking points</p>
        </div>
        {csvData && (
          <button onClick={()=>setShowShare(true)} style={{display:"flex",alignItems:"center",gap:6,padding:"8px 16px",background:"#378ADD",color:"#fff",border:"none",borderRadius:8,fontSize:13,fontWeight:500,cursor:"pointer"}}>
            <Share2 size={14}/> Share
          </button>
        )}
      </div>

      {/* Client context */}
      <div style={{background:"var(--color-background-primary)",border:"0.5px solid var(--color-border-tertiary)",borderRadius:"var(--border-radius-lg)",marginBottom:16,overflow:"hidden"}}>
        <div onClick={()=>setShowCtx(v=>!v)} style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"12px 16px",cursor:"pointer"}}>
          <span style={{fontSize:13,fontWeight:500}}>Client context</span>
          {showCtx ? <ChevronUp size={15} color="var(--color-text-secondary)"/> : <ChevronDown size={15} color="var(--color-text-secondary)"/>}
        </div>
        {showCtx && (
          <div style={{padding:"0 16px 14px",display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
            <input placeholder="Client name" value={clientCtx.name} onChange={e=>setClientCtx(p=>({...p,name:e.target.value}))} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)"}}/>
            <input placeholder="Meeting goal" value={clientCtx.goal} onChange={e=>setClientCtx(p=>({...p,goal:e.target.value}))} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)"}}/>
            <input placeholder="Notes — context, concerns, focus areas..." value={clientCtx.notes} onChange={e=>setClientCtx(p=>({...p,notes:e.target.value}))} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)",gridColumn:"1 / -1"}}/>
          </div>
        )}
      </div>

      {/* Upload */}
      <label style={{display:"flex",alignItems:"center",justifyContent:"center",width:"100%",height:68,border:"1.5px dashed var(--color-border-secondary)",borderRadius:"var(--border-radius-lg)",cursor:"pointer",marginBottom:16,background:"var(--color-background-secondary)",boxSizing:"border-box"}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          <Upload size={15} color="var(--color-text-secondary)"/>
          <span style={{fontSize:13,color:"var(--color-text-secondary)"}}>{csvData ? "✓ File loaded — drop a new file to replace" : "Drop CSV here or click to upload"}</span>
        </div>
        <input type="file" accept=".csv" onChange={handleUpload} style={{display:"none"}}/>
      </label>

      {/* Summary */}
      {summaryLoading && <div style={{display:"flex",alignItems:"center",gap:8,padding:"8px 0",color:"var(--color-text-secondary)",fontSize:13}}><Loader2 size={14} style={{animation:"spin 1s linear infinite"}}/> Generating summary...</div>}
      {summary && (
        <div style={{marginBottom:16}}>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(120px,1fr))",gap:10,marginBottom:10}}>
            {[{label:"Rows",value:summary.rowCount?.toLocaleString()},{label:"Columns",value:summary.colCount},...(summary.stats||[])].map((s,i)=>(
              <div key={i} style={{background:"var(--color-background-secondary)",borderRadius:"var(--border-radius-md)",padding:"12px 14px"}}>
                <div style={{fontSize:11,color:"var(--color-text-secondary)",marginBottom:3}}>{s.label}</div>
                <div style={{fontSize:20,fontWeight:500,wordBreak:"break-word"}}>{s.value}</div>
              </div>
            ))}
          </div>
          {quality && (
            <div style={{background:"var(--color-background-primary)",border:"0.5px solid var(--color-border-tertiary)",borderRadius:"var(--border-radius-md)",overflow:"hidden"}}>
