import { useState, useRef, useCallback, useEffect } from "react";
import { BarChart, Bar, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from "recharts";
import { Upload, Loader2, Download, Plus, X, AlignLeft, BarChart2, TrendingUp, Table, Hash, Clipboard, ChevronDown, ChevronUp, Share2, Printer, FileCode, FileText } from "lucide-react";

const PRESETS = [
  "Show revenue trend over time","Top 10 by value","Month-over-month change",
  "Distribution by category","Average by group","Count of records by type",
];
const VIZ_TYPES = [
  { id:"bar_chart", label:"Bar", Icon:BarChart2 },
  { id:"line_chart", label:"Line", Icon:TrendingUp },
  { id:"table", label:"Table", Icon:Table },
  { id:"count", label:"Value", Icon:Hash },
];
const TYPE_COLOR = { numeric:"#378ADD", date:"#1D9E75", categorical:"#7F77DD", empty:"#888780" };
const TYPE_BG    = { numeric:"#E6F1FB", date:"#E1F5EE", categorical:"#EEEDFE", empty:"#F1EFE8" };

function detectType(samples) {
  const n = samples.filter(Boolean);
  if (!n.length) return "empty";
  if (n.every(v => !isNaN(Number(v)))) return "numeric";
  if (n.every(v => /^\d{1,4}[-\/]\d{1,2}[-\/]\d{1,4}$/.test(v.trim()))) return "date";
  return "categorical";
}
function parseCSV(text) {
  const lines = text.trim().split("\n");
  const headers = lines[0].split(",").map(h => h.trim().replace(/^"|"$/g,""));
  const rows = [];
  for (let i=1;i<lines.length;i++) {
    const vals = lines[i].split(",").map(v=>v.trim().replace(/^"|"$/g,""));
    if (vals.length===headers.length) { const r={}; headers.forEach((h,j)=>{r[h]=vals[j];}); rows.push(r); }
  }
  return { headers, rows };
}
function buildQuality(headers, rows) {
  return headers.map(h => {
    const vals = rows.map(r=>r[h]);
    const nulls = vals.filter(v=>v===""||v==null).length;
    return { header:h, nulls, pctNull:((nulls/rows.length)*100).toFixed(0), type:detectType(vals.filter(Boolean).slice(0,20)) };
  });
}
async function callClaude(prompt, sys="") {
  const body = { model:"claude-sonnet-4-20250514", max_tokens:1000, messages:[{role:"user",content:prompt}] };
  if (sys) body.system = sys;
  const r = await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});
  if (!r.ok) throw new Error(`API ${r.status}`);
  return (await r.json()).content[0].text;
}

// capture recharts SVG as base64 PNG
async function svgToPngDataUrl(svgEl) {
  return new Promise((resolve) => {
    try {
      const s = new XMLSerializer().serializeToString(svgEl);
      const w = svgEl.clientWidth||600, h = svgEl.clientHeight||280;
      const c = document.createElement("canvas"); c.width=w*2; c.height=h*2;
      const ctx = c.getContext("2d"); ctx.scale(2,2);
      const img = new Image();
      img.onload = () => { ctx.fillStyle="#fff"; ctx.fillRect(0,0,w,h); ctx.drawImage(img,0,0); resolve(c.toDataURL("image/png")); };
      img.onerror = () => resolve(null);
      img.src = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(s)));
    } catch { resolve(null); }
  });
}

function ChartBlock({ result, idx, onRemove, onCaptureRef }) {
  const [annotation, setAnnotation] = useState("");
  const [showAnnot, setShowAnnot] = useState(false);
  const [savedAnnot, setSavedAnnot] = useState("");
  const wrapRef = useRef(null);

  useEffect(() => { if (onCaptureRef) onCaptureRef(idx, wrapRef); }, [idx]);

  const { type, data, query } = result;

  const exportPNG = () => {
    const svg = wrapRef.current?.querySelector("svg");
    if (!svg) return;
    svgToPngDataUrl(svg).then(url => { if (!url) return; const a=document.createElement("a"); a.download=`chart-${idx+1}.png`; a.href=url; a.click(); });
  };
  const exportCSV = () => {
    let csv="";
    if (type==="table") csv=data.headers.join(",")+"\n"+data.rows.map(r=>r.join(",")).join("\n");
    else if (type==="bar_chart"||type==="line_chart") csv="label,value\n"+data.labels.map((l,i)=>`${l},${data.values[i]}`).join("\n");
    else csv=`label,value\n${data.label||"result"},${data.value}`;
    const a=document.createElement("a"); a.download=`chart-${idx+1}.csv`; a.href="data:text/csv;charset=utf-8,"+encodeURIComponent(csv); a.click();
  };

  return (
    <div ref={wrapRef} style={{background:"var(--color-background-primary)",border:"0.5px solid var(--color-border-tertiary)",borderRadius:"var(--border-radius-lg)",padding:"16px 18px",marginBottom:14}}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:10}}>
        <span style={{fontSize:13,fontWeight:500,color:"var(--color-text-secondary)"}}>{query}</span>
        <div style={{display:"flex",gap:6}}>
          {[["note",()=>setShowAnnot(v=>!v),<AlignLeft size={13}/>],["PNG",exportPNG,<Download size={13}/>],["CSV",exportCSV,<Download size={13}/>]].map(([lbl,fn,ic])=>(
            <button key={lbl} onClick={fn} style={{background:"none",border:"0.5px solid var(--color-border-tertiary)",borderRadius:6,padding:"4px 8px",cursor:"pointer",fontSize:12,color:"var(--color-text-secondary)",display:"flex",alignItems:"center",gap:4}}>{ic}{lbl}</button>
          ))}
          <button onClick={()=>onRemove(idx)} style={{background:"none",border:"none",cursor:"pointer",color:"var(--color-text-tertiary)",padding:"4px"}}><X size={14}/></button>
        </div>
      </div>
      {savedAnnot && <div style={{background:"#FAEEDA",borderLeft:"3px solid #BA7517",borderRadius:4,padding:"6px 10px",fontSize:12,color:"#633806",marginBottom:10}}>{savedAnnot}</div>}
      {showAnnot && (
        <div style={{display:"flex",gap:6,marginBottom:10}}>
          <input value={annotation} onChange={e=>setAnnotation(e.target.value)} placeholder="Add a note..." style={{flex:1,fontSize:12,padding:"6px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)"}}/>
          <button onClick={()=>{setSavedAnnot(annotation);setShowAnnot(false);}} style={{background:"#378ADD",color:"#fff",border:"none",borderRadius:6,padding:"6px 12px",cursor:"pointer",fontSize:12}}>Save</button>
        </div>
      )}
      {type==="bar_chart" && (() => {
        const d=data.labels.map((l,i)=>({name:l,value:data.values[i]}));
        return <div><div style={{fontSize:13,fontWeight:500,marginBottom:6}}>{data.title||"Bar Chart"}</div><ResponsiveContainer width="100%" height={260}><BarChart data={d}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name" tick={{fontSize:10}}/><YAxis tick={{fontSize:10}}/><Tooltip/><Bar dataKey="value" fill="#378ADD"/></BarChart></ResponsiveContainer></div>;
      })()}
      {type==="line_chart" && (() => {
        const d=data.labels.map((l,i)=>({name:l,value:data.values[i]}));
        return <div><div style={{fontSize:13,fontWeight:500,marginBottom:6}}>{data.title||"Line Chart"}</div><ResponsiveContainer width="100%" height={260}><LineChart data={d}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name" tick={{fontSize:10}}/><YAxis tick={{fontSize:10}}/><Tooltip/><Line type="monotone" dataKey="value" stroke="#378ADD" strokeWidth={2} dot={false}/></LineChart></ResponsiveContainer></div>;
      })()}
      {type==="table" && (
        <div style={{overflowX:"auto"}}><div style={{fontSize:13,fontWeight:500,marginBottom:6}}>{data.title||"Table"}</div>
        <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
          <thead><tr>{data.headers.map((h,i)=><th key={i} style={{borderBottom:"1px solid var(--color-border-tertiary)",padding:"6px 10px",textAlign:"left",fontWeight:500,color:"var(--color-text-secondary)"}}>{h}</th>)}</tr></thead>
          <tbody>{data.rows.map((row,ri)=><tr key={ri}>{row.map((c,ci)=><td key={ci} style={{borderBottom:"0.5px solid var(--color-border-tertiary)",padding:"5px 10px"}}>{c}</td>)}</tr>)}</tbody>
        </table></div>
      )}
      {type==="count" && (
        <div style={{textAlign:"center",padding:"20px 0"}}>
          <div style={{fontSize:12,color:"var(--color-text-secondary)",marginBottom:4}}>{data.label||"Result"}</div>
          <div style={{fontSize:48,fontWeight:500,color:"#378ADD"}}>{typeof data.value==="number"?data.value.toLocaleString():data.value}</div>
        </div>
      )}
    </div>
  );
}

