      const img=chartImgs[i];
      if (img) w.document.write(`<img src="${img}" style="width:100%;margin:8px 0"/>`);
      else if (c.type==="count") w.document.write(`<p style="font-size:36px;font-weight:500;color:${accentColor}">${c.data.value}</p>`);
      else if (c.type==="table") w.document.write(`<table><thead><tr>${c.data.headers.map(h=>`<th>${h}</th>`).join("")}</tr></thead><tbody>${c.data.rows.map(r=>`<tr>${r.map(cell=>`<td>${cell}</td>`).join("")}</tr>`).join("")}</tbody></table>`);
      w.document.write("<hr>");
    });
    if (brand.firmName) w.document.write(`<p style="font-size:10px;color:#bbb">${brand.firmName} — ${new Date().toISOString().split("T")[0]}</p>`);
    w.document.write(`<script>window.onload=()=>{setTimeout(()=>{window.print();},400);}<\/script></body></html>`);
    w.document.close();
    setExporting(false);
  };

  const copyText = () => { navigator.clipboard.writeText(buildTextSummary()); setCopied(true); setTimeout(()=>setCopied(false),2000); };

  return (
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.4)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:1000,padding:16}} onClick={e=>{if(e.target===e.currentTarget)onClose();}}>
      <div style={{background:"var(--color-background-primary)",borderRadius:"var(--border-radius-lg)",padding:"24px",width:"100%",maxWidth:440,boxSizing:"border-box",maxHeight:"90vh",overflowY:"auto"}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:20}}>
          <div>
            <div style={{fontSize:16,fontWeight:500}}>Share with client</div>
            <div style={{fontSize:12,color:"var(--color-text-secondary)",marginTop:2}}>Choose how to deliver this brief</div>
          </div>
          <button onClick={onClose} style={{background:"none",border:"none",cursor:"pointer",color:"var(--color-text-tertiary)"}}><X size={16}/></button>
        </div>

        {[
          { Icon:FileCode, label:"Export HTML file", sub:"Self-contained file, opens in any browser — charts included as images", action:exportHTML, btnLabel: exporting?"Exporting...":"Download .html" },
          { Icon:Printer,  label:"Print / Save PDF",  sub:"Opens print dialog — save as PDF or send to printer",  action:printView,  btnLabel: exporting?"Preparing...":"Open print view" },
          { Icon:Clipboard,label:"Copy text summary",  sub:"Paste into email, Slack, or a doc",                   action:copyText,   btnLabel: copied?"Copied!":"Copy to clipboard" },
        ].map(({Icon,label,sub,action,btnLabel})=>(
          <div key={label} style={{display:"flex",alignItems:"center",gap:14,padding:"14px 0",borderBottom:"0.5px solid var(--color-border-tertiary)"}}>
            <div style={{width:36,height:36,borderRadius:8,background:"var(--color-background-secondary)",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
              <Icon size={16} color="var(--color-text-secondary)"/>
            </div>
            <div style={{flex:1,minWidth:0}}>
              <div style={{fontSize:13,fontWeight:500}}>{label}</div>
              <div style={{fontSize:11,color:"var(--color-text-secondary)",marginTop:1}}>{sub}</div>
            </div>
            <button onClick={action} disabled={exporting} style={{flexShrink:0,fontSize:12,padding:"6px 12px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)",background:"var(--color-background-secondary)",cursor:"pointer",color:"var(--color-text-primary)",whiteSpace:"nowrap",opacity:exporting?0.6:1}}>{btnLabel}</button>
          </div>
        ))}

        <div style={{marginTop:14,fontSize:11,color:"var(--color-text-tertiary)"}}>
          Includes: data overview · {charts.length} chart{charts.length!==1?"s":""} · talking points{clientCtx.notes?" · notes":""}.
        </div>
      </div>
    </div>
  );
}

