import { useState, useRef, useCallback, useEffect } from "react";
import { BarChart, Bar, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from "recharts";
import { Upload, Loader2, Download, Plus, X, AlignLeft, BarChart2, TrendingUp, Table, Hash, Clipboard, ChevronDown, ChevronUp, Share2, Printer, FileCode, FileText, Save, RotateCcw, GripVertical, Check, Edit2 } from "lucide-react";

const PRESETS = [
  "Show revenue trend over time","Top 10 by value","Month-over-month change",
  "Distribution by category","Average by group","Count of records by type",
];
const VIZ_TYPES = [
  { id:"bar_chart", label:"Bar", Icon:BarChart2 },
  { id:"line_chart", label:"Line", Icon:TrendingUp },
  { id:"table", label:"Table", Icon:Table },
  { id:"count", label:"Value", Icon:Hash },
];
const TYPE_COLOR = { numeric:"#378ADD", date:"#1D9E75", categorical:"#7F77DD", empty:"#888780" };
const TYPE_BG    = { numeric:"#E6F1FB", date:"#E1F5EE", categorical:"#EEEDFE", empty:"#F1EFE8" };

function detectType(s) {
  const n=s.filter(Boolean); if(!n.length) return "empty";
  if(n.every(v=>!isNaN(Number(v)))) return "numeric";
  if(n.every(v=>/^\d{1,4}[-\/]\d{1,2}[-\/]\d{1,4}$/.test(v.trim()))) return "date";
  return "categorical";
}
function parseCSV(text) {
  const lines=text.trim().split("\n");
  const headers=lines[0].split(",").map(h=>h.trim().replace(/^"|"$/g,""));
  const rows=[];
  for(let i=1;i<lines.length;i++){
    const vals=lines[i].split(",").map(v=>v.trim().replace(/^"|"$/g,""));
    if(vals.length===headers.length){const r={};headers.forEach((h,j)=>{r[h]=vals[j];});rows.push(r);}
  }
  return {headers,rows};
}
function buildQuality(headers,rows){
  return headers.map(h=>{
    const vals=rows.map(r=>r[h]);
    const nulls=vals.filter(v=>v===""||v==null).length;
    return{header:h,nulls,pctNull:((nulls/rows.length)*100).toFixed(0),type:detectType(vals.filter(Boolean).slice(0,20))};
  });
}
async function callClaude(prompt){
  const r=await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:"claude-sonnet-4-20250514",max_tokens:1000,messages:[{role:"user",content:prompt}]})});
  if(!r.ok) throw new Error(`API ${r.status}`);
  return (await r.json()).content[0].text;
}
async function svgToPng(svgEl){
  return new Promise(res=>{
    try{
      const s=new XMLSerializer().serializeToString(svgEl);
      const w=svgEl.clientWidth||600,h=svgEl.clientHeight||280;
      const c=document.createElement("canvas");c.width=w*2;c.height=h*2;
      const ctx=c.getContext("2d");ctx.scale(2,2);
      const img=new Image();
      img.onload=()=>{ctx.fillStyle="#fff";ctx.fillRect(0,0,w,h);ctx.drawImage(img,0,0);res(c.toDataURL("image/png"));};
      img.onerror=()=>res(null);
      img.src="data:image/svg+xml;base64,"+btoa(unescape(encodeURIComponent(s)));
    }catch{res(null);}
  });
}

// ── Toast ─────────────────────────────────────────────────────────────────────
function Toast({message,onDone}){
  useEffect(()=>{const t=setTimeout(onDone,2200);return()=>clearTimeout(t);},[]);
  return(
    <div style={{position:"fixed",bottom:24,left:"50%",transform:"translateX(-50%)",background:"#1a1a1a",color:"#fff",borderRadius:8,padding:"9px 18px",fontSize:13,display:"flex",alignItems:"center",gap:8,zIndex:2000,whiteSpace:"nowrap",boxShadow:"0 2px 12px rgba(0,0,0,.18)"}}>
      <Check size={14}/>{message}
    </div>
  );
}

// ── Chart block ───────────────────────────────────────────────────────────────
function ChartBlock({result,idx,onRemove,onCaptureRef,onRename,accentColor,dragHandleProps}){
  const [annotation,setAnnotation]=useState("");
  const [showAnnot,setShowAnnot]=useState(false);
  const [savedAnnot,setSavedAnnot]=useState("");
  const [editingTitle,setEditingTitle]=useState(false);
  const [titleDraft,setTitleDraft]=useState(result.query);
  const wrapRef=useRef(null);
  useEffect(()=>{if(onCaptureRef)onCaptureRef(idx,wrapRef);},[idx]);

  const exportPNG=()=>{
    const svg=wrapRef.current?.querySelector("svg");if(!svg)return;
    svgToPng(svg).then(url=>{if(!url)return;const a=document.createElement("a");a.download=`chart-${idx+1}.png`;a.href=url;a.click();});
  };
  const exportCSV=()=>{
    const{type,data}=result;let csv="";
    if(type==="table")csv=data.headers.join(",")+"\n"+data.rows.map(r=>r.join(",")).join("\n");
    else if(type==="bar_chart"||type==="line_chart")csv="label,value\n"+data.labels.map((l,i)=>`${l},${data.values[i]}`).join("\n");
    else csv=`label,value\n${data.label||"result"},${data.value}`;
    const a=document.createElement("a");a.download=`chart-${idx+1}.csv`;a.href="data:text/csv;charset=utf-8,"+encodeURIComponent(csv);a.click();
  };

  const{type,data}=result;
  const displayTitle=result.customTitle||result.query;

  return(
    <div ref={wrapRef} style={{background:"var(--color-background-primary)",border:"0.5px solid var(--color-border-tertiary)",borderRadius:"var(--border-radius-lg)",padding:"14px 16px",marginBottom:12}}>
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:10}}>
        <div {...dragHandleProps} style={{cursor:"grab",color:"var(--color-text-tertiary)",flexShrink:0,paddingTop:1}}><GripVertical size={14}/></div>
        {editingTitle?(
          <input autoFocus value={titleDraft} onChange={e=>setTitleDraft(e.target.value)}
            onBlur={()=>{onRename(idx,titleDraft);setEditingTitle(false);}}
            onKeyDown={e=>{if(e.key==="Enter"){onRename(idx,titleDraft);setEditingTitle(false);}}}
            style={{flex:1,fontSize:13,fontWeight:500,padding:"2px 6px",borderRadius:4,border:"1px solid var(--color-border-secondary)",color:"var(--color-text-primary)"}}/>
        ):(
          <span style={{flex:1,fontSize:13,fontWeight:500,color:"var(--color-text-secondary)",cursor:"pointer"}} onClick={()=>setEditingTitle(true)}>{displayTitle}</span>
        )}
        <div style={{display:"flex",gap:5,flexShrink:0}}>
          <button onClick={()=>setEditingTitle(v=>!v)} title="Rename" style={{background:"none",border:"0.5px solid var(--color-border-tertiary)",borderRadius:6,padding:"3px 7px",cursor:"pointer",color:"var(--color-text-secondary)",display:"flex",alignItems:"center"}}><Edit2 size={12}/></button>
          {[["note",()=>setShowAnnot(v=>!v),<AlignLeft size={12}/>],["PNG",exportPNG,<Download size={12}/>],["CSV",exportCSV,<Download size={12}/>]].map(([lbl,fn,ic])=>(
            <button key={lbl} onClick={fn} style={{background:"none",border:"0.5px solid var(--color-border-tertiary)",borderRadius:6,padding:"3px 7px",cursor:"pointer",fontSize:11,color:"var(--color-text-secondary)",display:"flex",alignItems:"center",gap:3}}>{ic}{lbl}</button>
          ))}
          <button onClick={()=>onRemove(idx)} style={{background:"none",border:"none",cursor:"pointer",color:"var(--color-text-tertiary)",padding:"3px"}}><X size={13}/></button>
        </div>
      </div>
      {savedAnnot&&<div style={{background:"#FAEEDA",borderLeft:"3px solid #BA7517",borderRadius:4,padding:"6px 10px",fontSize:12,color:"#633806",marginBottom:10}}>{savedAnnot}</div>}
      {showAnnot&&(
        <div style={{display:"flex",gap:6,marginBottom:10}}>
          <input value={annotation} onChange={e=>setAnnotation(e.target.value)} placeholder="Add a note..." style={{flex:1,fontSize:12,padding:"6px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)"}}/>
          <button onClick={()=>{setSavedAnnot(annotation);setShowAnnot(false);}} style={{background:accentColor,color:"#fff",border:"none",borderRadius:6,padding:"6px 12px",cursor:"pointer",fontSize:12}}>Save</button>
        </div>
      )}
      {type==="bar_chart"&&(()=>{
        const d=data.labels.map((l,i)=>({name:l,value:data.values[i]}));
        return<div><div style={{fontSize:12,fontWeight:500,marginBottom:4,color:"var(--color-text-secondary)"}}>{data.title||""}</div><ResponsiveContainer width="100%" height={240}><BarChart data={d}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name" tick={{fontSize:10}}/><YAxis tick={{fontSize:10}}/><Tooltip/><Bar dataKey="value" fill={accentColor}/></BarChart></ResponsiveContainer></div>;
      })()}
      {type==="line_chart"&&(()=>{
        const d=data.labels.map((l,i)=>({name:l,value:data.values[i]}));
        return<div><div style={{fontSize:12,fontWeight:500,marginBottom:4,color:"var(--color-text-secondary)"}}>{data.title||""}</div><ResponsiveContainer width="100%" height={240}><LineChart data={d}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name" tick={{fontSize:10}}/><YAxis tick={{fontSize:10}}/><Tooltip/><Line type="monotone" dataKey="value" stroke={accentColor} strokeWidth={2} dot={false}/></LineChart></ResponsiveContainer></div>;
      })()}
      {type==="table"&&(
        <div style={{overflowX:"auto"}}><div style={{fontSize:12,fontWeight:500,marginBottom:4,color:"var(--color-text-secondary)"}}>{data.title||""}</div>
        <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
          <thead><tr>{data.headers.map((h,i)=><th key={i} style={{borderBottom:"1px solid var(--color-border-tertiary)",padding:"6px 10px",textAlign:"left",fontWeight:500,color:"var(--color-text-secondary)"}}>{h}</th>)}</tr></thead>
          <tbody>{data.rows.map((row,ri)=><tr key={ri}>{row.map((c,ci)=><td key={ci} style={{borderBottom:"0.5px solid var(--color-border-tertiary)",padding:"5px 10px"}}>{c}</td>)}</tr>)}</tbody>
        </table></div>
      )}
      {type==="count"&&(
        <div style={{textAlign:"center",padding:"16px 0"}}>
          <div style={{fontSize:12,color:"var(--color-text-secondary)",marginBottom:4}}>{data.label||"Result"}</div>
          <div style={{fontSize:46,fontWeight:500,color:accentColor}}>{typeof data.value==="number"?data.value.toLocaleString():data.value}</div>
        </div>
      )}
    </div>
  );
}

// ── Share modal ───────────────────────────────────────────────────────────────
function ShareModal({onClose,charts,chartRefs,talkingPts,summary,clientCtx,fileName,brand,confidential,revision}){
  const [copied,setCopied]=useState(false);
  const [exporting,setExporting]=useState(false);
  const clientName=clientCtx.name||"Client";
  const meetingDate=clientCtx.meetingDate?new Date(clientCtx.meetingDate).toLocaleDateString("en-US",{month:"long",day:"numeric",year:"numeric"}):new Date().toLocaleDateString("en-US",{month:"long",day:"numeric",year:"numeric"});
  const accent=brand.accentColor||"#378ADD";

  const buildText=()=>{
    const l=[];
    if(brand.firmName)l.push(brand.firmName.toUpperCase());
    l.push(`CLIENT: ${clientName}${clientCtx.goal?" — "+clientCtx.goal:""}`);
    if(brand.preparedBy)l.push(`Prepared by: ${brand.preparedBy}`);
    l.push(`Date: ${meetingDate}`);
    if(revision)l.push(`Version: Rev ${revision}`);
    if(fileName)l.push(`Source: ${fileName}`);
    if(confidential)l.push("⚠ CONFIDENTIAL — Do not distribute");
    l.push("=".repeat(48));
    if(summary){l.push("\nDATA OVERVIEW");l.push(`Rows: ${summary.rowCount?.toLocaleString()}  |  Columns: ${summary.colCount}`);summary.stats?.forEach(s=>l.push(`${s.label}: ${s.value}`));}
    if(talkingPts){l.push("\nTALKING POINTS");l.push(talkingPts);}
    if(charts.length){
      l.push("\nCHARTS");
      charts.forEach((c,i)=>{
        l.push(`\n${i+1}. ${c.customTitle||c.query}`);
        if(c.type==="count")l.push(`   ${c.data.label||"Result"}: ${c.data.value}`);
        else if(c.type==="bar_chart"||c.type==="line_chart"){c.data.labels?.slice(0,8).forEach((lb,j)=>l.push(`   ${lb}: ${c.data.values[j]}`));if(c.data.labels?.length>8)l.push(`   ...+${c.data.labels.length-8} more`);}
        else if(c.type==="table"){l.push("   "+c.data.headers.join(" | "));c.data.rows?.slice(0,5).forEach(r=>l.push("   "+r.join(" | ")));if(c.data.rows?.length>5)l.push(`   ...+${c.data.rows.length-5} more rows`);}
      });
    }
    return l.join("\n");
  };

  const exportHTML=async()=>{
    setExporting(true);
    const imgs={};
    for(let i=0;i<charts.length;i++){const ref=chartRefs.current[i];const svg=ref?.current?.querySelector("svg");if(svg)imgs[i]=await svgToPng(svg);}
    const statsHTML=[{label:"Rows",value:summary?.rowCount?.toLocaleString()},{label:"Columns",value:summary?.colCount},...(summary?.stats||[])].filter(s=>s.value).map(s=>`<div style="background:#f6f7f8;border-radius:8px;padding:10px 13px"><div style="font-size:10px;color:#999;margin-bottom:2px;text-transform:uppercase;letter-spacing:.05em">${s.label}</div><div style="font-size:18px;font-weight:500;color:#111">${s.value}</div></div>`).join("");
    const chartsHTML=charts.map((c,i)=>{
      let viz="";const img=imgs[i];
      if((c.type==="bar_chart"||c.type==="line_chart")&&img)viz=`<img src="${img}" style="width:100%;border-radius:6px;display:block" alt="${c.customTitle||c.query}"/>`;
      else if(c.type==="table")viz=`<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr>${c.data.headers.map(h=>`<th style="border-bottom:1px solid #eee;padding:7px 10px;text-align:left;color:#666;font-weight:500">${h}</th>`).join("")}</tr></thead><tbody>${c.data.rows.map(r=>`<tr>${r.map(cell=>`<td style="border-bottom:0.5px solid #f0f0f0;padding:6px 10px">${cell}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`;
      else if(c.type==="count")viz=`<div style="text-align:center;padding:16px 0"><div style="font-size:12px;color:#888;margin-bottom:4px">${c.data.label||"Result"}</div><div style="font-size:44px;font-weight:500;color:${accent}">${typeof c.data.value==="number"?c.data.value.toLocaleString():c.data.value}</div></div>`;
      return`<div style="background:#fff;border:1px solid #e8e8e8;border-radius:10px;padding:16px;margin-bottom:12px"><div style="font-size:12px;font-weight:500;color:#666;margin-bottom:10px">${c.customTitle||c.query}</div>${viz}</div>`;
    }).join("");
    const logoHTML=brand.logoDataUrl?`<img src="${brand.logoDataUrl}" style="height:30px;object-fit:contain;margin-bottom:8px;display:block" alt="logo"/>`:"";
    const confBanner=confidential?`<div style="background:#fff3cd;border:1px solid #ffc107;border-radius:6px;padding:7px 14px;font-size:11px;color:#856404;margin-bottom:20px;display:flex;align-items:center;gap:6px">⚠ CONFIDENTIAL — For intended recipient only. Do not distribute.</div>`:"";
    const html=`<!DOCTYPE html><html><head><meta charset="utf-8"><title>${clientName} — Data Brief${revision?" Rev "+revision:""}</title><style>*{box-sizing:border-box}body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;max-width:820px;margin:0 auto;padding:40px 28px;color:#1a1a1a;background:#f9f9f8;font-size:14px}header{border-bottom:2px solid ${accent};padding-bottom:16px;margin-bottom:24px}.meta{font-size:11px;color:#888;margin-top:6px;line-height:1.8}.section{margin-bottom:28px}.label{font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.07em;color:#999;margin-bottom:10px}.stats-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;margin-bottom:12px}.tp{background:#fff;border:1px solid #e8e8e8;border-radius:10px;padding:16px;font-size:13px;line-height:1.9;white-space:pre-line}.footer{margin-top:36px;font-size:10px;color:#ccc;border-top:1px solid #eee;padding-top:14px;display:flex;justify-content:space-between}</style></head><body>${confBanner}<header>${logoHTML}<h1 style="font-size:20px;font-weight:500;margin:0 0 4px">${clientName}${clientCtx.goal?" — "+clientCtx.goal:""}</h1><div class="meta">${brand.preparedBy?"Prepared by "+brand.preparedBy+" &nbsp;·&nbsp; ":""}${meetingDate}${revision?" &nbsp;·&nbsp; Rev "+revision:""}${fileName?" &nbsp;·&nbsp; "+fileName:""}</div></header>${summary?`<div class="section"><div class="label">Data overview</div><div class="stats-grid">${statsHTML}</div></div>`:""}${talkingPts?`<div class="section"><div class="label">Talking points</div><div class="tp">${talkingPts}</div></div>`:""}${chartsHTML?`<div class="section"><div class="label">Analysis</div>${chartsHTML}</div>`:""}${clientCtx.notes?`<div class="section"><div class="label">Notes</div><div class="tp">${clientCtx.notes}</div></div>`:""}<div class="footer"><span>${brand.firmName||"CSV Data Visualizer"}</span><span>Exported ${new Date().toISOString().split("T")[0]}</span></div></body></html>`;
    const a=document.createElement("a");a.download=`${clientName.replace(/\s+/g,"-").toLowerCase()}-brief${revision?"-rev"+revision:""}.html`;a.href="data:text/html;charset=utf-8,"+encodeURIComponent(html);a.click();
    setExporting(false);
  };

  const printView=async()=>{
    setExporting(true);
    const imgs={};
    for(let i=0;i<charts.length;i++){const ref=chartRefs.current[i];const svg=ref?.current?.querySelector("svg");if(svg)imgs[i]=await svgToPng(svg);}
    const w=window.open("","_blank","width=900,height=700");
    w.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><style>*{box-sizing:border-box}body{font-family:system-ui,sans-serif;max-width:780px;margin:0 auto;padding:32px;color:#111;font-size:13px}h1{font-size:18px;font-weight:500;margin:0 0 4px}hr{border:none;border-top:1px solid #ddd;margin:18px 0}.meta{font-size:11px;color:#888;line-height:1.8;margin-bottom:16px}pre{white-space:pre-wrap;font-family:inherit;font-size:13px;line-height:1.7}table{width:100%;border-collapse:collapse;font-size:12px}th{border-bottom:1px solid #eee;padding:5px 8px;text-align:left;color:#666}td{border-bottom:0.5px solid #f0f0f0;padding:4px 8px}img{max-width:100%;border-radius:6px}.conf{background:#fff3cd;border:1px solid #ffc107;border-radius:6px;padding:7px 14px;font-size:11px;color:#856404;margin-bottom:20px}@media print{body{padding:16px}}</style></head><body>`);
    if(confidential)w.document.write(`<div class="conf">⚠ CONFIDENTIAL — For intended recipient only. Do not distribute.</div>`);
    if(brand.logoDataUrl)w.document.write(`<img src="${brand.logoDataUrl}" style="height:26px;display:block;margin-bottom:8px"/>`);
    w.document.write(`<h1>${clientName}${clientCtx.goal?" — "+clientCtx.goal:""}</h1><div class="meta">${brand.preparedBy?"Prepared by "+brand.preparedBy+" · ":""}${meetingDate}${revision?" · Rev "+revision:""}${fileName?" · "+fileName:""}</div><hr>`);
    if(summary)w.document.write(`<p style="font-size:12px"><strong>Rows:</strong> ${summary.rowCount?.toLocaleString()} &nbsp;<strong>Columns:</strong> ${summary.colCount}${summary.stats?.map(s=>" &nbsp;<strong>"+s.label+":</strong> "+s.value).join("")||""}</p><hr>`);
    if(talkingPts)w.document.write(`<h2 style="font-size:14px;font-weight:500">Talking points</h2><pre>${talkingPts}</pre><hr>`);
    charts.forEach((c,i)=>{
      w.document.write(`<h2 style="font-size:13px;font-weight:500">${i+1}. ${c.customTitle||c.query}</h2>`);
      const img=imgs[i];
      if(img)w.document.write(`<img src="${img}" style="width:100%;margin:8px 0"/>`);
      else if(c.type==="count")w.document.write(`<p style="font-size:36px;font-weight:500;color:${accent}">${c.data.value}</p>`);
      else if(c.type==="table")w.document.write(`<table><thead><tr>${c.data.headers.map(h=>`<th>${h}</th>`).join("")}</tr></thead><tbody>${c.data.rows.map(r=>`<tr>${r.map(cell=>`<td>${cell}</td>`).join("")}</tr>`).join("")}</tbody></table>`);
      w.document.write("<hr>");
    });
    if(brand.firmName)w.document.write(`<p style="font-size:10px;color:#bbb">${brand.firmName} — ${new Date().toISOString().split("T")[0]}</p>`);
    w.document.write(`<script>window.onload=()=>{setTimeout(()=>{window.print();},400);}<\/script></body></html>`);
    w.document.close();
    setExporting(false);
  };

  return(
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.4)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:1000,padding:16}} onClick={e=>{if(e.target===e.currentTarget)onClose();}}>
      <div style={{background:"var(--color-background-primary)",borderRadius:"var(--border-radius-lg)",padding:"24px",width:"100%",maxWidth:440,boxSizing:"border-box",maxHeight:"90vh",overflowY:"auto"}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:20}}>
          <div><div style={{fontSize:16,fontWeight:500}}>Share with client</div><div style={{fontSize:12,color:"var(--color-text-secondary)",marginTop:2}}>Choose how to deliver this brief</div></div>
          <button onClick={onClose} style={{background:"none",border:"none",cursor:"pointer",color:"var(--color-text-tertiary)"}}><X size={16}/></button>
        </div>
        {[
          {Icon:FileCode,label:"Export HTML file",sub:"Self-contained file — charts embedded as images",action:exportHTML,btnLabel:exporting?"Exporting...":"Download .html"},
          {Icon:Printer,label:"Print / Save PDF",sub:"Opens print dialog — save as PDF or send to printer",action:printView,btnLabel:exporting?"Preparing...":"Open print view"},
          {Icon:Clipboard,label:"Copy text summary",sub:"Paste into email, Slack, or a doc",action:()=>{navigator.clipboard.writeText(buildText());setCopied(true);setTimeout(()=>setCopied(false),2000);},btnLabel:copied?"Copied!":"Copy to clipboard"},
        ].map(({Icon,label,sub,action,btnLabel})=>(
          <div key={label} style={{display:"flex",alignItems:"center",gap:14,padding:"14px 0",borderBottom:"0.5px solid var(--color-border-tertiary)"}}>
            <div style={{width:36,height:36,borderRadius:8,background:"var(--color-background-secondary)",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}><Icon size={16} color="var(--color-text-secondary)"/></div>
            <div style={{flex:1,minWidth:0}}><div style={{fontSize:13,fontWeight:500}}>{label}</div><div style={{fontSize:11,color:"var(--color-text-secondary)",marginTop:1}}>{sub}</div></div>
            <button onClick={action} disabled={exporting} style={{flexShrink:0,fontSize:12,padding:"6px 12px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)",background:"var(--color-background-secondary)",cursor:"pointer",color:"var(--color-text-primary)",whiteSpace:"nowrap",opacity:exporting?0.6:1}}>{btnLabel}</button>
          </div>
        ))}
        <div style={{marginTop:14,fontSize:11,color:"var(--color-text-tertiary)"}}>
          Includes: data overview · {charts.length} chart{charts.length!==1?"s":""} · talking points{clientCtx.notes?" · notes":""}{confidential?" · confidential watermark":""}{revision?" · Rev "+revision:""}.
        </div>
      </div>
    </div>
  );
}

