// ── Main app ──────────────────────────────────────────────────────────────────
export default function App(){
  const [csvData,setCsvData]=useState(null);
  const [fileName,setFileName]=useState("");
  const [parsed,setParsed]=useState(null);
  const [quality,setQuality]=useState(null);
  const [summary,setSummary]=useState(null);
  const [summaryLoading,setSummaryLoading]=useState(false);
  const [clientCtx,setClientCtx]=useState({name:"",goal:"",notes:"",meetingDate:""});
  const [brand,setBrand]=useState({firmName:"",preparedBy:"",accentColor:"#378ADD",logoDataUrl:""});
  const [confidential,setConfidential]=useState(false);
  const [revision,setRevision]=useState("");
  const [showCtx,setShowCtx]=useState(true);
  const [showBrand,setShowBrand]=useState(false);
  const [query,setQuery]=useState("");
  const [vizType,setVizType]=useState("bar_chart");
  const [charts,setCharts]=useState([]);
  const [dragIdx,setDragIdx]=useState(null);
  const [dragOverIdx,setDragOverIdx]=useState(null);
  const chartRefs=useRef({});
  const [isLoading,setIsLoading]=useState(false);
  const [talkingPts,setTalkingPts]=useState("");
  const [tpLoading,setTpLoading]=useState(false);
  const [tpCopied,setTpCopied]=useState(false);
  const [error,setError]=useState("");
  const [showQuality,setShowQuality]=useState(false);
  const [showShare,setShowShare]=useState(false);
  const [toast,setToast]=useState(null);

  const accent=brand.accentColor||"#378ADD";

  const showToast=msg=>{setToast(msg);};

  const handleCaptureRef=useCallback((idx,ref)=>{chartRefs.current[idx]=ref;},[]);

  const handleLogoUpload=e=>{
    const file=e.target.files[0];if(!file)return;
    const reader=new FileReader();reader.onload=ev=>setBrand(b=>({...b,logoDataUrl:ev.target.result}));reader.readAsDataURL(file);
  };

  const handleUpload=async e=>{
    const file=e.target.files[0];if(!file)return;
    const text=await file.text();
    const p=parseCSV(text);const q=buildQuality(p.headers,p.rows);
    setCsvData(text);setFileName(file.name);setParsed(p);setQuality(q);
    setCharts([]);setTalkingPts("");setSummary(null);setError("");chartRefs.current={};
    genSummary(text,p);
  };

  const genSummary=async(text,p)=>{
    setSummaryLoading(true);
    try{
      const sample=text.trim().split("\n").slice(0,8).join("\n");
      const raw=await callClaude(`CSV sample:\n${sample}\n\nHeaders: ${p.headers.join(", ")}\nRows: ${p.rows.length}\n\nReturn ONLY valid JSON (no backticks): { "rowCount": number, "colCount": number, "stats": [{"label":string,"value":string}] } with 4 key business metrics.`);
      setSummary(JSON.parse(raw.replace(/```json|```/g,"").trim()));
    }catch{setSummary({rowCount:p.rows.length,colCount:p.headers.length,stats:[]});}
    setSummaryLoading(false);
  };

  const saveSession=()=>{
    const session={csvData,fileName,parsed,quality,summary,clientCtx,brand,confidential,revision,charts,talkingPts};
    const a=document.createElement("a");a.download=`${(clientCtx.name||"session").replace(/\s+/g,"-").toLowerCase()}-session.json`;
    a.href="data:application/json;charset=utf-8,"+encodeURIComponent(JSON.stringify(session));a.click();
    showToast("Session saved");
  };

  const loadSession=e=>{
    const file=e.target.files[0];if(!file)return;
    const reader=new FileReader();
    reader.onload=ev=>{
      try{
        const s=JSON.parse(ev.target.result);
        setCsvData(s.csvData||null);setFileName(s.fileName||"");setParsed(s.parsed||null);
        setQuality(s.quality||null);setSummary(s.summary||null);setClientCtx(s.clientCtx||{name:"",goal:"",notes:"",meetingDate:""});
        setBrand(s.brand||{firmName:"",preparedBy:"",accentColor:"#378ADD",logoDataUrl:""});
        setConfidential(s.confidential||false);setRevision(s.revision||"");
        setCharts(s.charts||[]);setTalkingPts(s.talkingPts||"");chartRefs.current={};
        showToast("Session restored");
      }catch{setError("Could not load session file.");}
    };
    reader.readAsText(file);
  };

  const runAnalysis=async()=>{
    if(!csvData||!query.trim()){setError("Enter a query first.");return;}
    setIsLoading(true);setError("");
    try{
      const sample=csvData.trim().split("\n").slice(0,6).join("\n");
      const ctx=clientCtx.name?`\nClient: ${clientCtx.name}. Goal: ${clientCtx.goal}. Notes: ${clientCtx.notes}.`:"";
      const vizMap={
        bar_chart:'type MUST be "bar_chart", data={labels:string[],values:number[],title?:string}',
        line_chart:'type MUST be "line_chart", data={labels:string[],values:number[],title?:string}',
        table:'type MUST be "table", data={headers:string[],rows:any[][],title?:string}',
        count:'type MUST be "count", data={value:number,label?:string}',
      };
      const code=await callClaude(`CSV sample:\n${sample}${ctx}\n\nRequest: "${query}"\n\nWrite JS that parses 'csvData' and sets: analysisResult = { type, data, query:"${query}" }\n${vizMap[vizType]}\n\nReturn ONLY raw JS.`);
      const fn=new Function("csvData",code+"\nreturn analysisResult;");
      const result=fn(csvData);result.query=query;
      setCharts(prev=>[...prev,result]);setQuery("");
      showToast("Chart added");
    }catch(err){setError("Analysis error: "+err.message);}
    setIsLoading(false);
  };

  const renameChart=(idx,title)=>{
    setCharts(prev=>prev.map((c,i)=>i===idx?{...c,customTitle:title}:c));
  };

  // drag-to-reorder
  const onDragStart=(i)=>setDragIdx(i);
  const onDragOver=(e,i)=>{e.preventDefault();setDragOverIdx(i);};
  const onDrop=(i)=>{
    if(dragIdx===null||dragIdx===i)return;
    const next=[...charts];const[moved]=next.splice(dragIdx,1);next.splice(i,0,moved);
    setCharts(next);setDragIdx(null);setDragOverIdx(null);
  };

  const genTalkingPts=async()=>{
    if(!csvData)return;setTpLoading(true);setTalkingPts("");
    try{
      const sample=csvData.trim().split("\n").slice(0,10).join("\n");
      const ctx=clientCtx.name?`Client: ${clientCtx.name}. Goal: ${clientCtx.goal}. Notes: ${clientCtx.notes}.`:"";
      const chartSum=charts.map((c,i)=>`Chart ${i+1} (${c.customTitle||c.query}): ${JSON.stringify(c.data).slice(0,200)}`).join("\n")||"None yet";
      const pts=await callClaude(`${ctx}\nCSV sample:\n${sample}\n\nCharts:\n${chartSum}\n\nGenerate 5 concise exec talking points for a client call. Numbered 1-5. Data-driven. No preamble.`);
      setTalkingPts(pts);
    }catch(err){setError("Talking points error: "+err.message);}
    setTpLoading(false);
  };

  return(
    <div style={{maxWidth:820,margin:"0 auto",padding:"24px 16px",fontFamily:"var(--font-sans)"}}>
      {toast&&<Toast message={toast} onDone={()=>setToast(null)}/>}
      {showShare&&<ShareModal onClose={()=>setShowShare(false)} charts={charts} chartRefs={chartRefs} talkingPts={talkingPts} summary={summary} clientCtx={clientCtx} fileName={fileName} brand={brand} confidential={confidential} revision={revision}/>}

      {/* Header */}
      <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",marginBottom:20}}>
        <div style={{display:"flex",alignItems:"center",gap:12}}>
          {brand.logoDataUrl&&<img src={brand.logoDataUrl} style={{height:28,objectFit:"contain"}} alt="logo"/>}
          <div>
            <h1 style={{fontSize:22,fontWeight:500,margin:0,color:accent}}>CSV Visualizer</h1>
            <p style={{fontSize:13,color:"var(--color-text-secondary)",marginTop:3,margin:0}}>
              {fileName?<span style={{display:"inline-flex",alignItems:"center",gap:5}}><FileText size={12}/>{fileName}</span>:"Client call prep tool"}
            </p>
          </div>
        </div>
        <div style={{display:"flex",gap:8,alignItems:"center"}}>
          <button onClick={saveSession} title="Save session" style={{display:"flex",alignItems:"center",gap:5,padding:"7px 12px",background:"none",border:"0.5px solid var(--color-border-secondary)",borderRadius:7,fontSize:12,cursor:"pointer",color:"var(--color-text-secondary)"}}><Save size={13}/>Save</button>
          <label title="Restore session" style={{display:"flex",alignItems:"center",gap:5,padding:"7px 12px",background:"none",border:"0.5px solid var(--color-border-secondary)",borderRadius:7,fontSize:12,cursor:"pointer",color:"var(--color-text-secondary)"}}>
            <RotateCcw size={13}/>Restore<input type="file" accept=".json" onChange={loadSession} style={{display:"none"}}/>
          </label>
          {csvData&&<button onClick={()=>setShowShare(true)} style={{display:"flex",alignItems:"center",gap:6,padding:"8px 16px",background:accent,color:"#fff",border:"none",borderRadius:8,fontSize:13,fontWeight:500,cursor:"pointer"}}><Share2 size={14}/>Share</button>}
        </div>
      </div>

      {/* Branding */}
      <div style={{background:"var(--color-background-primary)",border:"0.5px solid var(--color-border-tertiary)",borderRadius:"var(--border-radius-lg)",marginBottom:10,overflow:"hidden"}}>
        <div onClick={()=>setShowBrand(v=>!v)} style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"11px 16px",cursor:"pointer"}}>
          <span style={{fontSize:13,fontWeight:500}}>Branding</span>
          {showBrand?<ChevronUp size={15} color="var(--color-text-secondary)"/>:<ChevronDown size={15} color="var(--color-text-secondary)"/>}
        </div>
        {showBrand&&(
          <div style={{padding:"0 16px 14px",display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
            <input placeholder="Firm / company name" value={brand.firmName} onChange={e=>setBrand(b=>({...b,firmName:e.target.value}))} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)"}}/>
            <input placeholder="Prepared by (your name)" value={brand.preparedBy} onChange={e=>setBrand(b=>({...b,preparedBy:e.target.value}))} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)"}}/>
            <div style={{display:"flex",alignItems:"center",gap:8}}>
              <label style={{fontSize:12,color:"var(--color-text-secondary)",whiteSpace:"nowrap"}}>Accent</label>
              <input type="color" value={brand.accentColor} onChange={e=>setBrand(b=>({...b,accentColor:e.target.value}))} style={{width:36,height:32,borderRadius:6,border:"0.5px solid var(--color-border-secondary)",padding:2,cursor:"pointer"}}/>
            </div>
            <label style={{display:"flex",alignItems:"center",gap:8,cursor:"pointer",fontSize:13,color:"var(--color-text-secondary)",border:"0.5px solid var(--color-border-secondary)",borderRadius:6,padding:"7px 10px"}}>
              <Upload size={13}/>{brand.logoDataUrl?"Logo uploaded ✓":"Upload logo"}
              <input type="file" accept="image/*" onChange={handleLogoUpload} style={{display:"none"}}/>
            </label>
          </div>
        )}
      </div>

      {/* Client context */}
      <div style={{background:"var(--color-background-primary)",border:"0.5px solid var(--color-border-tertiary)",borderRadius:"var(--border-radius-lg)",marginBottom:16,overflow:"hidden"}}>
        <div onClick={()=>setShowCtx(v=>!v)} style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"11px 16px",cursor:"pointer"}}>
          <span style={{fontSize:13,fontWeight:500}}>Client context</span>
          {showCtx?<ChevronUp size={15} color="var(--color-text-secondary)"/>:<ChevronDown size={15} color="var(--color-text-secondary)"/>}
        </div>
        {showCtx&&(
          <div style={{padding:"0 16px 14px",display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
            <input placeholder="Client name" value={clientCtx.name} onChange={e=>setClientCtx(p=>({...p,name:e.target.value}))} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)"}}/>
            <input placeholder="Meeting goal" value={clientCtx.goal} onChange={e=>setClientCtx(p=>({...p,goal:e.target.value}))} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)"}}/>
            <div style={{display:"flex",alignItems:"center",gap:8}}>
              <label style={{fontSize:12,color:"var(--color-text-secondary)",whiteSpace:"nowrap"}}>Meeting date</label>
              <input type="date" value={clientCtx.meetingDate} onChange={e=>setClientCtx(p=>({...p,meetingDate:e.target.value}))} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)",flex:1}}/>
            </div>
            <div style={{display:"flex",alignItems:"center",gap:8}}>
              <label style={{fontSize:12,color:"var(--color-text-secondary)",whiteSpace:"nowrap"}}>Revision</label>
              <input placeholder="e.g. 1, 2, A" value={revision} onChange={e=>setRevision(e.target.value)} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)",flex:1}}/>
            </div>
            <input placeholder="Notes — context, concerns, focus areas..." value={clientCtx.notes} onChange={e=>setClientCtx(p=>({...p,notes:e.target.value}))} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)",gridColumn:"1 / -1"}}/>
            <label style={{display:"flex",alignItems:"center",gap:8,fontSize:13,cursor:"pointer",color:"var(--color-text-secondary)",gridColumn:"1 / -1"}}>
              <input type="checkbox" checked={confidential} onChange={e=>setConfidential(e.target.checked)} style={{accentColor:accent}}/>
              Mark as confidential — adds watermark banner to all exports
            </label>
          </div>
        )}
      </div>

      {/* Upload */}
      <label style={{display:"flex",alignItems:"center",justifyContent:"center",width:"100%",height:68,border:"1.5px dashed var(--color-border-secondary)",borderRadius:"var(--border-radius-lg)",cursor:"pointer",marginBottom:16,background:"var(--color-background-secondary)",boxSizing:"border-box"}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          <Upload size={15} color="var(--color-text-secondary)"/>
          <span style={{fontSize:13,color:"var(--color-text-secondary)"}}>{fileName?`✓ ${fileName} loaded — drop a new file to replace`:"Drop CSV here or click to upload"}</span>
        </div>
        <input type="file" accept=".csv" onChange={handleUpload} style={{display:"none"}}/>
      </label>

      {/* Empty state */}
      {!csvData&&!summaryLoading&&<EmptyState accent={accent}/>}

      {/* Summary */}
      {summaryLoading&&<div style={{display:"flex",alignItems:"center",gap:8,padding:"8px 0",color:"var(--color-text-secondary)",fontSize:13}}><Loader2 size={14} style={{animation:"spin 1s linear infinite"}}/> Generating summary...</div>}
      {summary&&(
        <div style={{marginBottom:16}}>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(120px,1fr))",gap:10,marginBottom:10}}>
            {[{label:"Rows",value:summary.rowCount?.toLocaleString()},{label:"Columns",value:summary.colCount},...(summary.stats||[])].map((s,i)=>(
              <div key={i} style={{background:"var(--color-background-secondary)",borderRadius:"var(--border-radius-md)",padding:"12px 14px"}}>
                <div style={{fontSize:11,color:"var(--color-text-secondary)",marginBottom:3}}>{s.label}</div>
                <div style={{fontSize:20,fontWeight:500,wordBreak:"break-word"}}>{s.value}</div>
              </div>
            ))}
          </div>
          {quality&&(
            <div style={{background:"var(--color-background-primary)",border:"0.5px solid var(--color-border-tertiary)",borderRadius:"var(--border-radius-md)",overflow:"hidden"}}>
              <div onClick={()=>setShowQuality(v=>!v)} style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"9px 14px",cursor:"pointer"}}>
                <span style={{fontSize:12,fontWeight:500,color:"var(--color-text-secondary)"}}>Column quality &amp; types</span>
                {showQuality?<ChevronUp size={13} color="var(--color-text-secondary)"/>:<ChevronDown size={13} color="var(--color-text-secondary)"/>}
              </div>
              {showQuality&&(
                <div style={{padding:"0 14px 12px",display:"flex",flexWrap:"wrap",gap:6}}>
                  {quality.map((col,i)=>(
                    <div key={i} style={{fontSize:11,padding:"4px 8px",borderRadius:20,background:TYPE_BG[col.type],color:TYPE_COLOR[col.type],display:"flex",alignItems:"center",gap:5}}>
                      <span style={{fontWeight:500}}>{col.header}</span>
                      <span style={{opacity:.7}}>{col.type}</span>
                      {col.nulls>0&&<span style={{background:"#F7C1C1",color:"#A32D2D",borderRadius:10,padding:"1px 5px"}}>{col.pctNull}% null</span>}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {/* Analysis panel */}
      {csvData&&(
        <div style={{background:"var(--color-background-primary)",border:"0.5px solid var(--color-border-tertiary)",borderRadius:"var(--border-radius-lg)",padding:16,marginBottom:16}}>
          <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:12}}>
            {PRESETS.map((p,i)=><button key={i} onClick={()=>setQuery(p)} style={{fontSize:11,padding:"4px 10px",borderRadius:20,border:"0.5px solid var(--color-border-secondary)",background:"var(--color-background-secondary)",cursor:"pointer",color:"var(--color-text-secondary)"}}>{p}</button>)}
          </div>
          <div style={{display:"flex",gap:6,marginBottom:10}}>
            {VIZ_TYPES.map(({id,label,Icon})=>(
              <button key={id} onClick={()=>setVizType(id)} style={{display:"flex",alignItems:"center",gap:5,fontSize:12,padding:"5px 12px",borderRadius:6,border:vizType===id?`1.5px solid ${accent}`:"0.5px solid var(--color-border-secondary)",background:vizType===id?"#E6F1FB":"var(--color-background-secondary)",color:vizType===id?"#0C447C":"var(--color-text-secondary)",cursor:"pointer",fontWeight:vizType===id?500:400}}>
                <Icon size={13}/>{label}
              </button>
            ))}
          </div>
          <div style={{display:"flex",gap:8}}>
            <input value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>e.key==="Enter"&&runAnalysis()} placeholder="Describe what you want to see, or pick a preset above..." style={{flex:1,fontSize:13,padding:"8px 12px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)"}} disabled={isLoading}/>
            <button onClick={runAnalysis} disabled={isLoading||!query.trim()} style={{display:"flex",alignItems:"center",gap:6,padding:"8px 16px",background:accent,color:"#fff",border:"none",borderRadius:6,fontSize:13,fontWeight:500,cursor:"pointer",whiteSpace:"nowrap",opacity:isLoading||!query.trim()?0.5:1}}>
              {isLoading?<Loader2 size={14} style={{animation:"spin 1s linear infinite"}}/>:<Plus size={14}/>}
              {isLoading?"Running...":"Add chart"}
            </button>
          </div>
        </div>
      )}

      {error&&<div style={{background:"#FCEBEB",border:"0.5px solid #F09595",borderRadius:6,padding:"8px 12px",fontSize:12,color:"#A32D2D",marginBottom:12}}>{error}</div>}

      {/* Charts — drag to reorder */}
      {charts.length>0&&(
        <div style={{marginBottom:16}}>
          {charts.map((c,i)=>(
            <div key={i} draggable onDragStart={()=>onDragStart(i)} onDragOver={e=>onDragOver(e,i)} onDrop={()=>onDrop(i)} onDragEnd={()=>{setDragIdx(null);setDragOverIdx(null);}}
              style={{opacity:dragIdx===i?0.4:1,outline:dragOverIdx===i&&dragIdx!==i?`2px solid ${accent}`:"none",borderRadius:12,transition:"opacity .15s"}}>
              <ChartBlock result={c} idx={i} onRemove={idx=>setCharts(prev=>prev.filter((_,j)=>j!==idx))} onCaptureRef={handleCaptureRef} onRename={renameChart} accentColor={accent} dragHandleProps={{}}/>
            </div>
          ))}
        </div>
      )}

      {/* Talking points */}
      {csvData&&(
        <div style={{background:"var(--color-background-primary)",border:"0.5px solid var(--color-border-tertiary)",borderRadius:"var(--border-radius-lg)",padding:16}}>
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:talkingPts?12:0}}>
            <span style={{fontSize:13,fontWeight:500}}>Talking points</span>
            <div style={{display:"flex",gap:6}}>
              {talkingPts&&<button onClick={()=>{navigator.clipboard.writeText(talkingPts);setTpCopied(true);setTimeout(()=>setTpCopied(false),1800);}} style={{display:"flex",alignItems:"center",gap:5,fontSize:12,padding:"5px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)",background:"var(--color-background-secondary)",cursor:"pointer"}}><Clipboard size={12}/>{tpCopied?"Copied!":"Copy"}</button>}
              <button onClick={genTalkingPts} disabled={tpLoading} style={{display:"flex",alignItems:"center",gap:5,fontSize:12,padding:"5px 12px",borderRadius:6,border:"none",background:accent,color:"#fff",cursor:"pointer",opacity:tpLoading?0.6:1}}>
                {tpLoading&&<Loader2 size={12} style={{animation:"spin 1s linear infinite"}}/>}
                {tpLoading?"Generating...":talkingPts?"Regenerate":"Generate for this call"}
              </button>
            </div>
          </div>
          {talkingPts&&<div style={{fontSize:13,lineHeight:1.8,whiteSpace:"pre-line",paddingTop:8,borderTop:"0.5px solid var(--color-border-tertiary)"}}>{talkingPts}</div>}
        </div>
      )}
      <style>{`@keyframes spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}`}</style>
    </div>
  );
}

