        {activeBrandFields.firmName&&<input placeholder="Firm / company name" value={brand.firmName} onChange={e=>setBrand(b=>({...b,firmName:e.target.value}))} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)"}}/>}
        {activeBrandFields.preparedBy&&<input placeholder="Prepared by (your name)" value={brand.preparedBy} onChange={e=>setBrand(b=>({...b,preparedBy:e.target.value}))} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)"}}/>}
