  { id:"summary",    label:"Summary", Icon:List       },
];
const TYPE_COLOR = { numeric:"#378ADD", date:"#1D9E75", categorical:"#7F77DD", empty:"#888780" };
const TYPE_BG    = { numeric:"#E6F1FB", date:"#E1F5EE", categorical:"#EEEDFE", empty:"#F1EFE8" };

// ── Helpers ───────────────────────────────────────────────────────────────────
function detectType(samples) {
  const n = samples.filter(Boolean);
  if (!n.length) return "empty";
  if (n.every(v => !isNaN(Number(v)))) return "numeric";
  if (n.every(v => /^\d{1,4}[-/]\d{1,2}[-/]\d{1,4}$/.test(v.trim()))) return "date";
  return "categorical";
}

function parseCSV(text) {
  const lines = text.trim().split("\n");
  const headers = lines[0].split(",").map(h => h.trim().replace(/^"|"$/g, ""));
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const vals = lines[i].split(",").map(v => v.trim().replace(/^"|"$/g, ""));
    if (vals.length === headers.length) {
      const r = {};
      headers.forEach((h, j) => { r[h] = vals[j]; });
      rows.push(r);
    }
  }
  return { headers, rows };
}

function buildQuality(headers, rows) {
  return headers.map(h => {
    const vals = rows.map(r => r[h]);
    const nulls = vals.filter(v => v === "" || v == null).length;
    return { header: h, nulls, pctNull: ((nulls / rows.length) * 100).toFixed(0), type: detectType(vals.filter(Boolean).slice(0, 20)) };
  });
}

async function callClaude(prompt, maxTokens) {
  const mt = maxTokens || 1000;
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model: "claude-sonnet-4-20250514", max_tokens: mt, messages: [{ role: "user", content: prompt }] })
  });
  if (!res.ok) throw new Error("API " + res.status);
  return (await res.json()).content[0].text;
}

function cleanAndExec(raw, csvData) {
  let code = raw
    .replace(/^```[a-z]*\n?/im, "").replace(/```\s*$/m, "").trim()
    .replace(/^\s*return\s+analysisResult\s*;?\s*$/m, "");
  // unwrap if model wrapped in a function
  const fnMatch = code.match(/^(?:function\s*\w*\s*\([^)]*\)\s*\{)([\s\S]*)\}\s*$/s);
  if (fnMatch) code = fnMatch[1].trim();
  const fn = new Function("csvData", code + "\nreturn typeof analysisResult !== 'undefined' ? analysisResult : null;");
  return fn(csvData);
}

async function svgToPng(svgEl) {
  return new Promise(function(resolve) {
    try {
      var s = new XMLSerializer().serializeToString(svgEl);
      var w = svgEl.clientWidth || 600;
      var h = svgEl.clientHeight || 280;
      var c = document.createElement("canvas");
      c.width = w * 2; c.height = h * 2;
      var ctx = c.getContext("2d");
      ctx.scale(2, 2);
      var img = new Image();
      img.onload = function() { ctx.fillStyle = "#fff"; ctx.fillRect(0,0,w,h); ctx.drawImage(img,0,0); resolve(c.toDataURL("image/png")); };
      img.onerror = function() { resolve(null); };
      img.src = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(s)));
    } catch(e) { resolve(null); }
  });
}

