    w.document.close();
    setExporting(false);
  }

  return (
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.4)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:1000,padding:16}} onClick={function(e){if(e.target===e.currentTarget)onClose();}}>
      <div style={{background:"var(--color-background-primary)",borderRadius:"var(--border-radius-lg)",padding:"24px",width:"100%",maxWidth:440,boxSizing:"border-box"}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:20}}>
          <div>
            <div style={{fontSize:16,fontWeight:500}}>Share with client</div>
            <div style={{fontSize:12,color:"var(--color-text-secondary)",marginTop:2}}>Choose how to deliver this brief</div>
          </div>
          <button onClick={onClose} style={{background:"none",border:"none",cursor:"pointer",color:"var(--color-text-tertiary)"}}><X size={16}/></button>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:10,margin:"4px 0 8px"}}>
          {[
            {Icon:FileCode, label:"HTML file",   sub:"Opens in any browser",       action:exportHTML, btnLabel:exporting?"Exporting...":"Download"},
            {Icon:Printer,  label:"Print / PDF", sub:"Save as PDF or print",       action:printView,  btnLabel:exporting?"Preparing...":"Open"},
            {Icon:Clipboard,label:"Copy text",   sub:"Paste into email or Slack",  action:function(){navigator.clipboard.writeText(buildText());setCopied(true);setTimeout(function(){setCopied(false);},2000);}, btnLabel:copied?"Copied!":"Copy"},
          ].map(function(item) {
            return (
              <div key={item.label} onClick={!exporting?item.action:undefined}
                style={{background:"var(--color-background-secondary)",border:"0.5px solid var(--color-border-tertiary)",borderRadius:"var(--border-radius-lg)",padding:"16px 12px",cursor:exporting?"default":"pointer",textAlign:"center",opacity:exporting?0.6:1}}
                onMouseEnter={function(e){if(!exporting)e.currentTarget.style.borderColor=accent;}}
                onMouseLeave={function(e){e.currentTarget.style.borderColor="var(--color-border-tertiary)";}}>
                <div style={{width:36,height:36,borderRadius:10,background:"var(--color-background-primary)",border:"0.5px solid var(--color-border-tertiary)",display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 10px"}}><item.Icon size={18} color={accent}/></div>
                <div style={{fontSize:13,fontWeight:500,marginBottom:3}}>{item.label}</div>
                <div style={{fontSize:11,color:"var(--color-text-secondary)",lineHeight:1.4,marginBottom:10}}>{item.sub}</div>
                <div style={{fontSize:12,fontWeight:500,color:accent}}>{item.btnLabel}</div>
              </div>
            );
          })}
        </div>
        <div style={{marginTop:14,fontSize:11,color:"var(--color-text-tertiary)"}}>
          Includes: data overview · {charts.length} chart{charts.length!==1?"s":""} · talking points{clientCtx.notes?" · notes":""}{confidential?" · confidential":""}{revision?" · Rev "+revision:""}.
        </div>
      </div>
    </div>
  );
}

// ── Empty State ───────────────────────────────────────────────────────────────
function EmptyState(props) {
  return (
    <div style={{textAlign:"center",padding:"48px 24px"}}>
      <div style={{width:56,height:56,borderRadius:16,background:"var(--color-background-secondary)",display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 16px"}}><BarChart2 size={24} color={props.accent}/></div>
      <div style={{fontSize:16,fontWeight:500,marginBottom:6}}>Upload a CSV to get started</div>
      <div style={{fontSize:13,color:"var(--color-text-secondary)",maxWidth:340,margin:"0 auto",lineHeight:1.6}}>Add your client's data above, fill in the context fields, then build charts and talking points for your call — all exportable as a branded brief.</div>
      <div style={{display:"flex",justifyContent:"center",gap:24,marginTop:24,flexWrap:"wrap"}}>
        {["Auto summary on upload","AI-powered charts","Branded export","Talking points"].map(function(f){
          return <div key={f} style={{display:"flex",alignItems:"center",gap:6,fontSize:12,color:"var(--color-text-secondary)"}}><Check size={12} color={props.accent}/>{f}</div>;
        })}
      </div>
    </div>
  );
}

// ── Main App ──────────────────────────────────────────────────────────────────
export default function App() {
  var [csvData,setCsvData]         = useState(null);
  var [fileName,setFileName]       = useState("");
  var [parsed,setParsed]           = useState(null);
  var [quality,setQuality]         = useState(null);
  var [summary,setSummary]         = useState(null);
  var [summaryLoading,setSummaryLoading] = useState(false);
  var [clientCtx,setClientCtx]     = useState({name:"",goal:"",notes:"",meetingDate:""});
  var [brand,setBrand]             = useState({firmName:"",preparedBy:"",accentColor:"#378ADD",logoDataUrl:""});
  var [confidential,setConfidential] = useState(false);
  var [revision,setRevision]       = useState("");
  var [showCtx,setShowCtx]         = useState(true);
  var [showBrand,setShowBrand]     = useState(false);
  var [activeCtxFields,setActiveCtxFields]   = useState({name:true,goal:true,meetingDate:false,revision:false,notes:false,confidential:false});
  var [activeBrandFields,setActiveBrandFields] = useState({firmName:false,preparedBy:false,accentColor:false,logo:false});
  var [query,setQuery]             = useState("");
  var [vizType,setVizType]         = useState("bar_chart");
  var [charts,setCharts]           = useState([]);
  var [dragIdx,setDragIdx]         = useState(null);
  var [dragOverIdx,setDragOverIdx] = useState(null);
  var chartRefs                    = useRef({});
  var [isLoading,setIsLoading]     = useState(false);
  var [talkingPts,setTalkingPts]   = useState("");
  var [tpLoading,setTpLoading]     = useState(false);
  var [tpCopied,setTpCopied]       = useState(false);
  var [error,setError]             = useState("");
  var [showQuality,setShowQuality] = useState(false);
  var [showShare,setShowShare]     = useState(false);
  var [toast,setToast]             = useState(null);

  var accent = brand.accentColor || "#378ADD";

  function showToastMsg(msg) { setToast(msg); }

  var handleCaptureRef = useCallback(function(idx, ref) { chartRefs.current[idx] = ref; }, []);

  function handleLogoUpload(e) {
    var file = e.target.files[0]; if (!file) return;
    var reader = new FileReader();
    reader.onload = function(ev) { setBrand(function(b){return Object.assign({},b,{logoDataUrl:ev.target.result});}); };
    reader.readAsDataURL(file);
  }

  async function handleUpload(e) {
    var file = e.target.files[0]; if (!file) return;
    var text = await file.text();
    var p = parseCSV(text); var q = buildQuality(p.headers, p.rows);
    setCsvData(text); setFileName(file.name); setParsed(p); setQuality(q);
    setCharts([]); setTalkingPts(""); setSummary(null); setError(""); chartRefs.current = {};
    genSummary(text, p);
  }

  async function genSummary(text, p) {
    setSummaryLoading(true);
    try {
      var sample = text.trim().split("\n").slice(0,8).join("\n");
      var raw = await callClaude("CSV sample:\n"+sample+"\n\nHeaders: "+p.headers.join(", ")+"\nRows: "+p.rows.length+"\n\nReturn ONLY valid JSON (no backticks): { \"rowCount\": number, \"colCount\": number, \"stats\": [{\"label\":string,\"value\":string}] } with 4 key business metrics.", 800);
      setSummary(JSON.parse(raw.replace(/```json|```/g,"").trim()));
    } catch(e) { setSummary({rowCount:p.rows.length,colCount:p.headers.length,stats:[]}); }
    setSummaryLoading(false);
  }

  function saveSession() {
    var session = {csvData,fileName,parsed,quality,summary,clientCtx,brand,confidential,revision,charts,talkingPts};
    var a = document.createElement("a");
    a.download = ((clientCtx.name||"session").replace(/\s+/g,"-").toLowerCase())+"-session.json";
    a.href = "data:application/json;charset=utf-8,"+encodeURIComponent(JSON.stringify(session)); a.click();
    showToastMsg("Session saved");
  }

  function loadSession(e) {
    var file = e.target.files[0]; if (!file) return;
    var reader = new FileReader();
    reader.onload = function(ev) {
      try {
        var s = JSON.parse(ev.target.result);
        setCsvData(s.csvData||null); setFileName(s.fileName||""); setParsed(s.parsed||null);
        setQuality(s.quality||null); setSummary(s.summary||null);
        setClientCtx(s.clientCtx||{name:"",goal:"",notes:"",meetingDate:""});
        setBrand(s.brand||{firmName:"",preparedBy:"",accentColor:"#378ADD",logoDataUrl:""});
        setConfidential(s.confidential||false); setRevision(s.revision||"");
        setCharts(s.charts||[]); setTalkingPts(s.talkingPts||""); chartRefs.current={};
        showToastMsg("Session restored");
      } catch(err) { setError("Could not load session file."); }
    };
    reader.readAsText(file);
  }

  async function runAnalysis() {
    if (!csvData || !query.trim()) { setError("Enter a query first."); return; }
    setIsLoading(true); setError("");
    try {
      var lines = csvData.trim().split("\n");
      var sample = [lines[0]].concat(lines.slice(1,6)).join("\n");
      var safeQuery = query.replace(/`/g,"'").replace(/\\/g,"");
      var ctx = clientCtx.name ? "\nClient: "+clientCtx.name+". Goal: "+clientCtx.goal+"." : "";
      var vizInstructions = {
        bar_chart:"type=\"bar_chart\", data={labels:string[], values:number[], title:string}",
        line_chart:"type=\"line_chart\", data={labels:string[], values:number[], title:string}",
        table:"type=\"table\", data={headers:string[], rows:string[][], title:string}",
        count:"type=\"count\", data={value:number, label:string}",
        summary:"type=\"summary\", data={bullets:string[], title:string} where bullets has 3-6 insight strings",
      };

      function makePrompt(retry) {
        return "Write browser JavaScript to analyze CSV data.\n\nCSV headers and sample rows:\n"+sample+ctx+"\n\nTask: "+safeQuery+"\nOutput format: "+vizInstructions[vizType]+"\n\n"+(retry?"PREVIOUS ATTEMPT FAILED. Use only basic var declarations, for loops, and simple string operations.\n":"")+"\nSTRICT RULES:\n- Use only: var, for, if/else, basic string/array/object operations\n- NO const, NO let, NO arrow functions, NO template literals, NO destructuring\n- csvData is already a string variable — do NOT redefine it\n- Parse csvData: split by newline, first line is headers\n- Final line must be: var analysisResult = { type: \"...\", data: {...}, query: \""+safeQuery+"\" }\n- Output raw JavaScript only. No markdown. No comments.";
      }

      var result = null; var lastErr = null;
      for (var attempt=0; attempt<3; attempt++) {
        try {
          var raw = await callClaude(makePrompt(attempt>0), 1000);
          result = cleanAndExec(raw, csvData);
          if (result) break;
          lastErr = new Error("No result returned");
        } catch(e) { lastErr = e; }
      }
      if (!result) throw lastErr || new Error("Analysis failed — try rephrasing.");
      result.query = query;
      setCharts(function(prev){return prev.concat([result]);});
      setQuery("");
      showToastMsg("Chart added");
    } catch(err) { setError("Analysis error: "+err.message); }
    setIsLoading(false);
  }

  function renameChart(idx, title) {
    setCharts(function(prev){return prev.map(function(c,i){return i===idx?Object.assign({},c,{customTitle:title}):c;});});
  }

  function onDragStart(i) { setDragIdx(i); }
  function onDragOver(e,i) { e.preventDefault(); setDragOverIdx(i); }
  function onDrop(i) {
    if (dragIdx===null||dragIdx===i) return;
    var next = charts.slice(); var moved = next.splice(dragIdx,1)[0]; next.splice(i,0,moved);
    setCharts(next); setDragIdx(null); setDragOverIdx(null);
  }

  async function genTalkingPts() {
    if (!csvData) return; setTpLoading(true); setTalkingPts("");
    try {
      var sample = csvData.trim().split("\n").slice(0,10).join("\n");
      var ctx = clientCtx.name ? "Client: "+clientCtx.name+". Goal: "+clientCtx.goal+". Notes: "+clientCtx.notes+"." : "";
      var chartSum = charts.length ? charts.map(function(c,i){return"Chart "+(i+1)+" ("+((c.customTitle||c.query))+"): "+JSON.stringify(c.data).slice(0,200);}).join("\n") : "None yet";
      var pts = await callClaude(ctx+"\nCSV sample:\n"+sample+"\n\nCharts:\n"+chartSum+"\n\nGenerate 5 concise exec talking points for a client call. Numbered 1-5. Data-driven. No preamble.", 800);
      setTalkingPts(pts);
    } catch(err) { setError("Talking points error: "+err.message); }
    setTpLoading(false);
  }

  return (
    <div style={{maxWidth:820,margin:"0 auto",padding:"24px 16px",fontFamily:"var(--font-sans)"}}>
      {toast && <Toast message={toast} onDone={function(){setToast(null);}}/>}
      {showShare && <ShareModal onClose={function(){setShowShare(false);}} charts={charts} chartRefs={chartRefs} talkingPts={talkingPts} summary={summary} clientCtx={clientCtx} fileName={fileName} brand={brand} confidential={confidential} revision={revision}/>}

      {/* Header */}
      <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",marginBottom:20}}>
        <div style={{display:"flex",alignItems:"center",gap:12}}>
          {brand.logoDataUrl && <img src={brand.logoDataUrl} style={{height:28,objectFit:"contain"}} alt="logo"/>}
          <div>
            <h1 style={{fontSize:22,fontWeight:500,margin:0,color:accent}}>CSV Visualizer</h1>
            <p style={{fontSize:13,color:"var(--color-text-secondary)",marginTop:3,marginBottom:0}}>
              {fileName ? <span style={{display:"inline-flex",alignItems:"center",gap:5}}><FileText size={12}/>{fileName}</span> : "Client call prep tool"}
            </p>
          </div>
        </div>
        <div style={{display:"flex",gap:8,alignItems:"center"}}>
          <button onClick={saveSession} style={{display:"flex",alignItems:"center",gap:5,padding:"7px 12px",background:"none",border:"0.5px solid var(--color-border-secondary)",borderRadius:7,fontSize:12,cursor:"pointer",color:"var(--color-text-secondary)"}}><Save size={13}/>Save</button>
          <label style={{display:"flex",alignItems:"center",gap:5,padding:"7px 12px",background:"none",border:"0.5px solid var(--color-border-secondary)",borderRadius:7,fontSize:12,cursor:"pointer",color:"var(--color-text-secondary)"}}>
            <RotateCcw size={13}/>Restore<input type="file" accept=".json" onChange={loadSession} style={{display:"none"}}/>
          </label>
          {csvData && <button onClick={function(){setShowShare(true);}} style={{display:"flex",alignItems:"center",gap:6,padding:"8px 16px",background:accent,color:"#fff",border:"none",borderRadius:8,fontSize:13,fontWeight:500,cursor:"pointer"}}><Share2 size={14}/>Share</button>}
        </div>
      </div>

      {/* Branding */}
      <div style={{background:"var(--color-background-primary)",border:"0.5px solid var(--color-border-tertiary)",borderRadius:"var(--border-radius-lg)",marginBottom:10,overflow:"hidden"}}>
        <div onClick={function(){setShowBrand(function(v){return !v;});}} style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"11px 16px",cursor:"pointer"}}>
          <span style={{fontSize:13,fontWeight:500}}>Branding</span>
          <div style={{display:"flex",alignItems:"center",gap:8}}>
            <span style={{fontSize:11,color:"var(--color-text-tertiary)"}}>{Object.values(activeBrandFields).filter(Boolean).length} of {Object.keys(activeBrandFields).length} fields active</span>
            {showBrand?<ChevronUp size={15} color="var(--color-text-secondary)"/>:<ChevronDown size={15} color="var(--color-text-secondary)"/>}
          </div>
        </div>
        {showBrand && (
          <div style={{padding:"0 16px 14px"}}>
            <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:12}}>
              {[["firmName","Firm name"],["preparedBy","Prepared by"],["accentColor","Accent color"],["logo","Logo"]].map(function(item){
                return <button key={item[0]} onClick={function(){setActiveBrandFields(function(f){var n=Object.assign({},f);n[item[0]]=!f[item[0]];return n;});}}
                  style={{fontSize:11,padding:"4px 10px",borderRadius:20,border:"1px solid "+(activeBrandFields[item[0]]?accent:"var(--color-border-secondary)"),background:activeBrandFields[item[0]]?"#E6F1FB":"var(--color-background-secondary)",color:activeBrandFields[item[0]]?"#0C447C":"var(--color-text-secondary)",cursor:"pointer",fontWeight:activeBrandFields[item[0]]?500:400}}>
                  {activeBrandFields[item[0]]?"✓ ":""}{item[1]}
                </button>;
              })}
            </div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
              {activeBrandFields.firmName && <input placeholder="Firm / company name" value={brand.firmName} onChange={function(e){setBrand(function(b){return Object.assign({},b,{firmName:e.target.value});});}} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)"}}/>}
              {activeBrandFields.preparedBy && <input placeholder="Prepared by" value={brand.preparedBy} onChange={function(e){setBrand(function(b){return Object.assign({},b,{preparedBy:e.target.value});});}} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)"}}/>}
              {activeBrandFields.accentColor && <div style={{display:"flex",alignItems:"center",gap:8}}>
                <label style={{fontSize:12,color:"var(--color-text-secondary)",whiteSpace:"nowrap"}}>Accent</label>
                <input type="color" value={brand.accentColor} onChange={function(e){setBrand(function(b){return Object.assign({},b,{accentColor:e.target.value});});}} style={{width:36,height:32,borderRadius:6,border:"0.5px solid var(--color-border-secondary)",padding:2,cursor:"pointer"}}/>
              </div>}
              {activeBrandFields.logo && <label style={{display:"flex",alignItems:"center",gap:8,cursor:"pointer",fontSize:13,color:"var(--color-text-secondary)",border:"0.5px solid var(--color-border-secondary)",borderRadius:6,padding:"7px 10px"}}>
                <Upload size={13}/>{brand.logoDataUrl?"Logo uploaded ✓":"Upload logo"}
                <input type="file" accept="image/*" onChange={handleLogoUpload} style={{display:"none"}}/>
              </label>}
            </div>
          </div>
        )}
      </div>

      {/* Client context */}
      <div style={{background:"var(--color-background-primary)",border:"0.5px solid var(--color-border-tertiary)",borderRadius:"var(--border-radius-lg)",marginBottom:16,overflow:"hidden"}}>
        <div onClick={function(){setShowCtx(function(v){return !v;});}} style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"11px 16px",cursor:"pointer"}}>
          <span style={{fontSize:13,fontWeight:500}}>Client context</span>
          <div style={{display:"flex",alignItems:"center",gap:8}}>
            <span style={{fontSize:11,color:"var(--color-text-tertiary)"}}>{Object.values(activeCtxFields).filter(Boolean).length} of {Object.keys(activeCtxFields).length} fields active</span>
            {showCtx?<ChevronUp size={15} color="var(--color-text-secondary)"/>:<ChevronDown size={15} color="var(--color-text-secondary)"/>}
          </div>
        </div>
        {showCtx && (
          <div style={{padding:"0 16px 14px"}}>
            <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:12}}>
              {[["name","Client name"],["goal","Meeting goal"],["meetingDate","Meeting date"],["revision","Revision"],["notes","Notes"],["confidential","Confidential"]].map(function(item){
                return <button key={item[0]} onClick={function(){setActiveCtxFields(function(f){var n=Object.assign({},f);n[item[0]]=!f[item[0]];return n;});}}
                  style={{fontSize:11,padding:"4px 10px",borderRadius:20,border:"1px solid "+(activeCtxFields[item[0]]?accent:"var(--color-border-secondary)"),background:activeCtxFields[item[0]]?"#E6F1FB":"var(--color-background-secondary)",color:activeCtxFields[item[0]]?"#0C447C":"var(--color-text-secondary)",cursor:"pointer",fontWeight:activeCtxFields[item[0]]?500:400}}>
                  {activeCtxFields[item[0]]?"✓ ":""}{item[1]}
                </button>;
              })}
            </div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
              {activeCtxFields.name && <input placeholder="Client name" value={clientCtx.name} onChange={function(e){setClientCtx(function(p){return Object.assign({},p,{name:e.target.value});});}} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)"}}/>}
              {activeCtxFields.goal && <input placeholder="Meeting goal" value={clientCtx.goal} onChange={function(e){setClientCtx(function(p){return Object.assign({},p,{goal:e.target.value});});}} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)"}}/>}
              {activeCtxFields.meetingDate && <div style={{display:"flex",alignItems:"center",gap:8}}>
                <label style={{fontSize:12,color:"var(--color-text-secondary)",whiteSpace:"nowrap"}}>Date</label>
                <input type="date" value={clientCtx.meetingDate} onChange={function(e){setClientCtx(function(p){return Object.assign({},p,{meetingDate:e.target.value});});}} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)",flex:1}}/>
              </div>}
              {activeCtxFields.revision && <div style={{display:"flex",alignItems:"center",gap:8}}>
                <label style={{fontSize:12,color:"var(--color-text-secondary)",whiteSpace:"nowrap"}}>Revision</label>
                <input placeholder="e.g. 1, 2, A" value={revision} onChange={function(e){setRevision(e.target.value);}} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)",flex:1}}/>
              </div>}
              {activeCtxFields.notes && <input placeholder="Notes — context, concerns, focus areas..." value={clientCtx.notes} onChange={function(e){setClientCtx(function(p){return Object.assign({},p,{notes:e.target.value});});}} style={{fontSize:13,padding:"7px 10px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)",gridColumn:"1 / -1"}}/>}
              {activeCtxFields.confidential && <label style={{display:"flex",alignItems:"center",gap:8,fontSize:13,cursor:"pointer",color:"var(--color-text-secondary)",gridColumn:"1 / -1"}}>
                <input type="checkbox" checked={confidential} onChange={function(e){setConfidential(e.target.checked);}} style={{accentColor:accent}}/>
                Mark as confidential — adds watermark banner to all exports
              </label>}
            </div>
          </div>
        )}
      </div>

      {/* Upload */}
      <label style={{display:"flex",alignItems:"center",justifyContent:"center",width:"100%",height:68,border:"1.5px dashed var(--color-border-secondary)",borderRadius:"var(--border-radius-lg)",cursor:"pointer",marginBottom:16,background:"var(--color-background-secondary)",boxSizing:"border-box"}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          <Upload size={15} color="var(--color-text-secondary)"/>
          <span style={{fontSize:13,color:"var(--color-text-secondary)"}}>{fileName ? "✓ "+fileName+" loaded — drop a new file to replace" : "Drop CSV here or click to upload"}</span>
        </div>
        <input type="file" accept=".csv" onChange={handleUpload} style={{display:"none"}}/>
      </label>

      {!csvData && !summaryLoading && <EmptyState accent={accent}/>}

      {summaryLoading && <div style={{display:"flex",alignItems:"center",gap:8,padding:"8px 0",color:"var(--color-text-secondary)",fontSize:13}}><Loader2 size={14} style={{animation:"spin 1s linear infinite"}}/> Generating summary...</div>}

      {summary && (
        <div style={{marginBottom:16}}>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(120px,1fr))",gap:10,marginBottom:10}}>
            {[{label:"Rows",value:summary.rowCount&&summary.rowCount.toLocaleString()},{label:"Columns",value:summary.colCount}].concat(summary.stats||[]).map(function(s,i){
              return <div key={i} style={{background:"var(--color-background-secondary)",borderRadius:"var(--border-radius-md)",padding:"12px 14px"}}>
                <div style={{fontSize:11,color:"var(--color-text-secondary)",marginBottom:3}}>{s.label}</div>
                <div style={{fontSize:20,fontWeight:500,wordBreak:"break-word"}}>{s.value}</div>
              </div>;
            })}
          </div>
          {quality && (
