  var code = raw
    .replace(/^```[a-z]*\n?/im, "").replace(/```\s*$/m, "").trim();

  // unwrap function wrapper if present
  var fnMatch = code.match(/^(?:function\s*\w*\s*\([^)]*\)\s*\{)([\s\S]*)\}\s*$/);
  if (fnMatch) code = fnMatch[1].trim();

  // remove ALL return statements (any form)
  code = code.replace(/\breturn\s+[^;]+;?/g, "");

  // strip const/let -> var so new Function doesn't choke on block-scoped edge cases
  code = code.replace(/\bconst\b/g, "var").replace(/\blet\b/g, "var");

  var fn = new Function("csvData", code + "\nreturn typeof analysisResult !== 'undefined' ? analysisResult : null;");
  return fn(csvData);
}

