async function runAnalysis() {
  if (!csvData || !query.trim()) { setError("Enter a query first."); return; }
  setIsLoading(true); setError("");
  try {
    var lines = csvData.trim().split("\n");
    var headerLine = lines[0];
    var headers = headerLine.split(",").map(function(h){ return h.trim().replace(/^"|"$/g,""); });
    var sample = [headerLine].concat(lines.slice(1,8)).join("\n");
    var safeQuery = query.replace(/`/g,"'").replace(/\\/g,"").replace(/"/g,"'");
    var ctx = clientCtx.name ? "\nClient: "+clientCtx.name+". Goal: "+clientCtx.goal+"." : "";

    var vizInstructions = {
      bar_chart: "type=\"bar_chart\", data={labels:string[], values:number[], title:string}",
      line_chart: "type=\"line_chart\", data={labels:string[], values:number[], title:string}",
      table: "type=\"table\", data={headers:string[], rows:string[][], title:string}",
      count: "type=\"count\", data={value:number, label:string}",
    };

    function makePrompt(attempt) {
      var extra = attempt > 0
        ? "IMPORTANT: Previous attempt failed. Keep the code extremely simple. Use only basic for loops and var declarations. Do not use map/filter/reduce.\n\n"
        : "";
      return "Analyze this CSV data and produce a chart.\n\n" +
        "CSV headers: " + headers.join(", ") + "\n" +
        "Sample rows:\n" + sample + "\n" +
        "Total rows in full dataset: " + (lines.length - 1) + "\n" +
        ctx + "\n\n" +
        "Task: " + safeQuery + "\n" +
        "Output format: " + vizInstructions[vizType] + "\n\n" +
        extra +
        "Write JavaScript that:\n" +
        "1. Parses the string variable csvData (split by newline, first line = headers, split each row by comma)\n" +
        "2. Computes the result for the task\n" +
        "3. Sets: var analysisResult = { type: '...', data: {...}, query: '" + safeQuery + "' }\n\n" +
        "RULES:\n" +
        "- Use var only (no const, no let)\n" +
        "- No arrow functions\n" +
        "- No template literals\n" +
        "- No return statements\n" +
        "- No markdown or code fences\n" +
        "- The variable analysisResult MUST be assigned before the code ends\n" +
        "- If data is missing or ambiguous, produce a best-effort result rather than nothing";
    }

    var result = null;
    var lastErr = null;
    for (var attempt = 0; attempt < 3; attempt++) {
      try {
        var raw = await callClaude(makePrompt(attempt), 1200);
        result = cleanAndExec(raw, csvData);
        if (result && result.type && result.data) break;
        result = null;
        lastErr = new Error("No result returned — try rephrasing your query");
      } catch(e) {
        lastErr = e;
        result = null;
      }
    }

    if (!result) throw lastErr || new Error("Analysis failed after 3 attempts — try rephrasing.");
    result.query = query;
    setCharts(function(prev){ return prev.concat([result]); });
    setQuery("");
    showToastMsg("Chart added");
  } catch(err) { setError("Analysis error: " + err.message); }
  setIsLoading(false);
}

