const TYPE_COLOR = { numeric:"#378ADD", date:"#1D9E75", categorical:"#7F77DD", empty:"#888780" };
const TYPE_BG    = { numeric:"#E6F1FB", date:"#E1F5EE", categorical:"#EEEDFE", empty:"#F1EFE8" };

function detectType(samples) {
  var n = samples.filter(Boolean);
  if (!n.length) return "empty";
  if (n.every(function(v){return !isNaN(Number(v));})) return "numeric";
  if (n.every(function(v){return /^\d{1,4}[-/]\d{1,2}[-/]\d{1,4}$/.test(v.trim());})) return "date";
  return "categorical";
}
function parseCSV(text) {
  var lines = text.trim().split("\n");
  var headers = lines[0].split(",").map(function(h){return h.trim().replace(/^"|"$/g,"");});
  var rows = [];
  for (var i=1;i<lines.length;i++) {
    var vals = lines[i].split(",").map(function(v){return v.trim().replace(/^"|"$/g,"");});
    if (vals.length===headers.length) { var r={}; headers.forEach(function(h,j){r[h]=vals[j];}); rows.push(r); }
  }
  return {headers,rows};
}
function buildQuality(headers, rows) {
  return headers.map(function(h) {
    var vals = rows.map(function(r){return r[h];});
    var nulls = vals.filter(function(v){return v===""||v==null;}).length;
    return {header:h, nulls, pctNull:((nulls/rows.length)*100).toFixed(0), type:detectType(vals.filter(Boolean).slice(0,20))};
  });
}
async function callClaude(prompt, maxTokens) {
  var mt = maxTokens||1000;
  var res = await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({model:"claude-sonnet-4-20250514",max_tokens:mt,messages:[{role:"user",content:prompt}]})});
  if(!res.ok) throw new Error("API "+res.status);
  return (await res.json()).content[0].text;
}
function cleanAndExec(raw, csvData) {
  var code = raw.replace(/^```[a-z]*\n?/im,"").replace(/```\s*$/m,"").trim();
  code = code.replace(/\bconst\b/g,"var").replace(/\blet\b/g,"var");
  var wrapped = "var analysisResult;\n(function(){\n"+code+"\n})();\nreturn typeof analysisResult!=='undefined'?analysisResult:null;";
  var fn = new Function("csvData", wrapped);
  return fn(csvData);
}
async function svgToPng(svgEl) {
  return new Promise(function(resolve){
    try {
      var s=new XMLSerializer().serializeToString(svgEl);
      var w=svgEl.clientWidth||600,h=svgEl.clientHeight||280;
      var c=document.createElement("canvas");c.width=w*2;c.height=h*2;
      var ctx=c.getContext("2d");ctx.scale(2,2);
      var img=new Image();
      img.onload=function(){ctx.fillStyle="#fff";ctx.fillRect(0,0,w,h);ctx.drawImage(img,0,0);resolve(c.toDataURL("image/png"));};
      img.onerror=function(){resolve(null);};
      img.src="data:image/svg+xml;base64,"+btoa(unescape(encodeURIComponent(s)));
    }catch(e){resolve(null);}
  });
}

// ── Toast ─────────────────────────────────────────────────────────────────────
function Toast(props) {
  useEffect(function(){var t=setTimeout(props.onDone,2200);return function(){clearTimeout(t);};}, []);
  return (
    <div style={{position:"fixed",bottom:24,left:"50%",transform:"translateX(-50%)",background:"#1a1a1a",color:"#fff",borderRadius:8,padding:"9px 18px",fontSize:13,display:"flex",alignItems:"center",gap:8,zIndex:2000,whiteSpace:"nowrap"}}>
      <Check size={14}/>{props.message}
    </div>
  );
}

