          ? <input autoFocus value={titleDraft} onChange={function(e){setTitleDraft(e.target.value);}} onBlur={function(){onRename(idx,titleDraft);setEditingTitle(false);}} onKeyDown={function(e){if(e.key==="Enter"){onRename(idx,titleDraft);setEditingTitle(false);}}} style={{flex:1,fontSize:13,fontWeight:500,padding:"2px 6px",borderRadius:4,border:"1px solid var(--color-border-secondary)"}}/>
