      {/* Upload */}
      <label style={{display:"flex",alignItems:"center",justifyContent:"center",width:"100%",height:62,border:"1.5px dashed var(--color-border-secondary)",borderRadius:"var(--border-radius-lg)",cursor:"pointer",marginBottom:16,background:"var(--color-background-secondary)",boxSizing:"border-box"}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
