        <div style={{background:"var(--color-background-secondary)",border:"1.5px solid var(--color-border-secondary)",borderRadius:"var(--border-radius-lg)",padding:"18px",marginBottom:12}}>
          <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:14}}>
            <Loader2 size={14} color={accent} style={{animation:"spin 1s linear infinite"}}/>
            <span style={{fontSize:13,fontWeight:500,color:accent}}>Generating dataset overview...</span>
          </div>
