          </div>
          <div style={{display:"flex",gap:6,marginBottom:10}}>
            {VIZ_TYPES.map(function(vt){var Icon=vt.Icon;return <button key={vt.id} onClick={function(){setVizType(vt.id);}} style={{display:"flex",alignItems:"center",gap:5,fontSize:12,padding:"5px 12px",borderRadius:6,border:vizType===vt.id?"1.5px solid "+accent:"0.5px solid var(--color-border-secondary)",background:vizType===vt.id?"#E6F1FB":"var(--color-background-secondary)",color:vizType===vt.id?"#0C447C":"var(--color-text-secondary)",cursor:"pointer",fontWeight:vizType===vt.id?500:400}}><Icon size={13}/>{vt.label}</button>;})}
          </div>
          <div style={{display:"flex",gap:8}}>
            <input value={query} onChange={function(e){setQuery(e.target.value);}} onKeyDown={function(e){if(e.key==="Enter")runAnalysis();}} placeholder="Describe what you want to see, or pick a preset above..." style={{flex:1,fontSize:13,padding:"8px 12px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)"}} disabled={isLoading}/>
            <button onClick={runAnalysis} disabled={isLoading||!query.trim()} style={{display:"flex",alignItems:"center",gap:6,padding:"8px 16px",background:accent,color:"#fff",border:"none",borderRadius:6,fontSize:13,fontWeight:500,cursor:"pointer",whiteSpace:"nowrap",opacity:isLoading||!query.trim()?0.5:1}}>
              {isLoading?<Loader2 size={14} style={{animation:"spin 1s linear infinite"}}/>:<Plus size={14}/>}
