          <div style={{background:"var(--color-background-primary)",border:"0.5px solid var(--color-border-tertiary)",borderRadius:"var(--border-radius-lg)",padding:14}}>
            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:talkingPts?10:0}}>
              <span style={{fontSize:12,fontWeight:500}}>Talking points</span>
              <div style={{display:"flex",gap:5}}>
                {talkingPts&&<button onClick={function(){navigator.clipboard.writeText(talkingPts);setTpCopied(true);setTimeout(function(){setTpCopied(false);},1800);}} style={{display:"flex",alignItems:"center",gap:4,fontSize:11,padding:"4px 8px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)",background:"var(--color-background-secondary)",cursor:"pointer"}}><Clipboard size={11}/>{tpCopied?"Copied!":"Copy"}</button>}
                <button onClick={genTalkingPts} disabled={tpLoading} style={{display:"flex",alignItems:"center",gap:4,fontSize:11,padding:"4px 8px",borderRadius:6,border:"none",background:accent,color:"#fff",cursor:"pointer",opacity:tpLoading?0.6:1}}>
                  {tpLoading&&<Loader2 size={11} style={{animation:"spin 1s linear infinite"}}/>}
                  {tpLoading?"...":talkingPts?"Regen":"Generate"}
                </button>
              </div>
            </div>
            {talkingPts&&<div style={{fontSize:12,lineHeight:1.8,whiteSpace:"pre-line",paddingTop:8,borderTop:"0.5px solid var(--color-border-tertiary)",color:"var(--color-text-secondary)"}}>{talkingPts}</div>}
            {!talkingPts&&<div style={{fontSize:11,color:"var(--color-text-tertiary)",marginTop:6}}>5 exec bullet points for the call</div>}
          </div>

          {/* Actionables */}
          <div style={{background:"var(--color-background-primary)",border:"0.5px solid var(--color-border-tertiary)",borderRadius:"var(--border-radius-lg)",padding:14}}>
            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:actionables?10:0}}>
              <span style={{fontSize:12,fontWeight:500}}>Actionables</span>
              <div style={{display:"flex",gap:5}}>
                {actionables&&<button onClick={function(){navigator.clipboard.writeText(actionables);setActCopied(true);setTimeout(function(){setActCopied(false);},1800);}} style={{display:"flex",alignItems:"center",gap:4,fontSize:11,padding:"4px 8px",borderRadius:6,border:"0.5px solid var(--color-border-secondary)",background:"var(--color-background-secondary)",cursor:"pointer"}}><Clipboard size={11}/>{actCopied?"Copied!":"Copy"}</button>}
                <button onClick={genActionables} disabled={actLoading} style={{display:"flex",alignItems:"center",gap:4,fontSize:11,padding:"4px 8px",borderRadius:6,border:"none",background:accent,color:"#fff",cursor:"pointer",opacity:actLoading?0.6:1}}>
                  {actLoading&&<Loader2 size={11} style={{animation:"spin 1s linear infinite"}}/>}
                  {actLoading?"...":actionables?"Regen":"Generate"}
                </button>
              </div>
            </div>
            {actionables&&<div style={{fontSize:12,lineHeight:1.8,whiteSpace:"pre-line",paddingTop:8,borderTop:"0.5px solid var(--color-border-tertiary)",color:"var(--color-text-secondary)"}}>{actionables}</div>}
            {!actionables&&<div style={{fontSize:11,color:"var(--color-text-tertiary)",marginTop:6}}>5 prioritized next steps from the data</div>}
          </div>
        </div>
      )}
      <style>{`@keyframes spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}`}</style>
    </div>
  );
}

