const appLocale = '{{APP_LOCALE}}';
const browserLocale = navigator.languages?.[0] || navigator.language || 'en-US';
const findMatchingLocale = (locale) => {
  if (TRANSLATIONS[locale]) return locale;
  const lang = locale.split('-')[0];
  const match = Object.keys(TRANSLATIONS).find(key => key.startsWith(lang + '-'));
  return match || 'en-US';
};
const locale = (appLocale !== '{{APP_LOCALE}}') ? findMatchingLocale(appLocale) : findMatchingLocale(browserLocale);
const t = (key) => TRANSLATIONS[locale]?.[key] || TRANSLATIONS['en-US'][key] || key;

const ColorContrastChecker = () => {
  useEffect(() => {
    const link = document.createElement('link');
    link.href = 'https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700&display=swap';
    link.rel = 'stylesheet';
    document.head.appendChild(link);

    // Add responsive styles
    const style = document.createElement('style');
    style.textContent = `
      .responsive-container {
        display: flex;
        flex-direction: row;
        width: 100%;
        max-width: 1024px;
        margin: 0 auto;
      }

      .left-section {
        width: 50%;
        padding: 24px;
        background-color: white;
        border-top-left-radius: 16px;
        border-bottom-left-radius: 16px;
        border: 1px solid #d1d5db;
        border-right: none;
      }

      .separator {
        width: 1px;
        background-color: #d1d5db;
      }

      .right-section {
        width: 50%;
        padding: 24px;
        background-color: white;
        border-top-right-radius: 16px;
        border-bottom-right-radius: 16px;
        border: 1px solid #d1d5db;
        border-left: none;
      }

      @media (max-width: 768px) {
        .responsive-container {
          flex-direction: column;
        }

        .left-section {
          width: 100%;
          border-radius: 16px 16px 0 0;
          border-right: 1px solid #d1d5db;
          border-bottom: none;
        }

        .separator {
          width: 100%;
          height: 1px;
        }

        .right-section {
          width: 100%;
          border-radius: 0 0 16px 16px;
          border-left: 1px solid #d1d5db;
          border-top: none;
        }
      }
    `;
    document.head.appendChild(style);

    return () => {
      document.head.removeChild(link);
      document.head.removeChild(style);
    };
  }, []);

  const [textColor, setTextColor] = useState('#5cffb3');
  const [backgroundColor, setBackgroundColor] = useState('#10421e');
  const [contrastRatio, setContrastRatio] = useState(21);

  const hexToRgb = (hex) => {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    return result ? {
      r: parseInt(result[1], 16),
      g: parseInt(result[2], 16),
      b: parseInt(result[3], 16)
    } : null;
  };

  const getLuminance = (rgb) => {
    const { r, g, b } = rgb;
    const [rs, gs, bs] = [r, g, b].map(c => {
      c = c / 255;
      return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
    });
    return 0.2126 * rs + 0.7152 * gs + 0.0722 * bs;
  };

  const calculateContrast = (color1, color2) => {
    const rgb1 = hexToRgb(color1);
    const rgb2 = hexToRgb(color2);

    if (!rgb1 || !rgb2) return 1;

    const lum1 = getLuminance(rgb1);
    const lum2 = getLuminance(rgb2);

    const brightest = Math.max(lum1, lum2);
    const darkest = Math.min(lum1, lum2);

    return (brightest + 0.05) / (darkest + 0.05);
  };

  useEffect(() => {
    const ratio = calculateContrast(textColor, backgroundColor);
    setContrastRatio(ratio);
  }, [textColor, backgroundColor]);

  const getCompliance = (ratio) => {
    return {
      normalAA: ratio >= 4.5,
      normalAAA: ratio >= 7,
      largeAA: ratio >= 3,
      largeAAA: ratio >= 4.5
    };
  };

  const getResultColor = (ratio) => {
    if (ratio >= 7) return '#059669';
    if (ratio >= 4.5) return '#d97706';
    if (ratio >= 3) return '#ea580c';
    return '#dc2626';
  };

  const compliance = getCompliance(contrastRatio);
  const resultColor = getResultColor(contrastRatio);

  const ComplianceIcon = ({ passed }) => {
    return (
      <span style={{
        padding: '4px 8px',
        backgroundColor: passed ? '#dcfce7' : '#fecaca',
        color: passed ? '#166534' : '#991b1b',
        fontSize: '12px',
        fontWeight: '500',
        borderRadius: '9999px'
      }}>
        {passed ? t('pass') : t('fail')}
      </span>
    );
  };

  return (
    <div style={{ 
      fontFamily: 'Outfit, sans-serif', 
      padding: '64px 24px 40px 24px', 
      backgroundColor: 'white',
      width: '100%'
    }}>
      {/* Header */}
      <div style={{ textAlign: 'center', marginBottom: '48px' }}>
        <h1 style={{ 
          fontSize: '48px', 
          fontWeight: '900', 
          color: '#111827', 
          marginBottom: '8px' 
        }}>
          {t('title')}
        </h1>
        <p style={{ color: '#6b7280', fontSize: '16px' }}>
          {t('subtitle')}
        </p>
      </div>

      {/* Main Content */}
      <div className="responsive-container">
        {/* Left Section */}
        <div className="left-section">
          {/* Color Inputs */}
          <div style={{ 
            display: 'grid', 
            gridTemplateColumns: '1fr 1fr', 
            gap: '16px',
            marginBottom: '24px'
          }}>
            <div>
              <label style={{ 
                display: 'block', 
                fontSize: '14px', 
                fontWeight: '500', 
                color: '#374151',
                marginBottom: '12px'
              }}>
                {t('textColorLabel')}
              </label>
              <div style={{ position: 'relative' }}>
                <input
                  type="text"
                  value={textColor}
                  onChange={(e) => setTextColor(e.target.value)}
                  style={{
                    width: '100%',
                    padding: '8px 48px 8px 12px',
                    border: '1px solid #d1d5db',
                    borderRadius: '12px',
                    fontSize: '14px'
                  }}
                  placeholder={t('textColorPlaceholder')}
                />
                <div style={{ 
                  position: 'absolute', 
                  right: '8px', 
                  top: '50%', 
                  transform: 'translateY(-50%)'
                }}>
                  <input
                    type="color"
                    value={textColor}
                    onChange={(e) => setTextColor(e.target.value)}
                    style={{
                      width: '32px',
                      height: '32px',
                      borderRadius: '8px',
                      cursor: 'pointer',
                      border: '1px solid #d1d5db',
                      opacity: 0,
                      position: 'absolute'
                    }}
                  />
                  <div style={{
                    width: '24px',
                    height: '24px',
                    borderRadius: '6px',
                    backgroundColor: textColor,
                    cursor: 'pointer',
                    pointerEvents: 'none'
                  }} />
                </div>
              </div>
            </div>

            <div>
              <label style={{ 
                display: 'block', 
                fontSize: '14px', 
                fontWeight: '500', 
                color: '#374151',
                marginBottom: '12px'
              }}>
                {t('backgroundColorLabel')}
              </label>
              <div style={{ position: 'relative' }}>
                <input
                  type="text"
                  value={backgroundColor}
                  onChange={(e) => setBackgroundColor(e.target.value)}
                  style={{
                    width: '100%',
                    padding: '8px 48px 8px 12px',
                    border: '1px solid #d1d5db',
                    borderRadius: '12px',
                    fontSize: '14px'
                  }}
                  placeholder={t('backgroundColorPlaceholder')}
                />
                <div style={{ 
                  position: 'absolute', 
                  right: '8px', 
                  top: '50%', 
                  transform: 'translateY(-50%)'
                }}>
                  <input
                    type="color"
                    value={backgroundColor}
                    onChange={(e) => setBackgroundColor(e.target.value)}
                    style={{
                      width: '32px',
                      height: '32px',
                      borderRadius: '8px',
                      cursor: 'pointer',
                      border: '1px solid #d1d5db',
                      opacity: 0,
                      position: 'absolute'
                    }}
                  />
                  <div style={{
