export default ColorContrastChecker;

import { useState, useRef, useCallback } from "react";
import { ExternalLink, Upload, Link, X, RefreshCw } from "lucide-react";

const ANTHROPIC_MODEL = "claude-sonnet-4-20250514";

// ── helpers ──────────────────────────────────────────────────────────────────
const hexToRgb = (hex) => {
  const r = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return r ? { r: parseInt(r[1],16), g: parseInt(r[2],16), b: parseInt(r[3],16) } : null;
};
const getLuminance = ({r,g,b}) => {
  const c = [r,g,b].map(v => { v/=255; return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4); });
  return .2126*c[0]+.7152*c[1]+.0722*c[2];
};
const contrast = (a,b) => {
  const rgb1=hexToRgb(a), rgb2=hexToRgb(b);
  if(!rgb1||!rgb2) return 1;
  const l1=getLuminance(rgb1), l2=getLuminance(rgb2);
  return (Math.max(l1,l2)+.05)/(Math.min(l1,l2)+.05);
};
const ratioColor = r => r>=7?"#059669":r>=4.5?"#d97706":r>=3?"#ea580c":"#dc2626";
const ratioLabel = r => r>=7?"AAA":r>=4.5?"AA":r>=3?"AA Large Only":"Fail";

const Badge = ({pass}) => (
  <span style={{padding:"3px 8px",borderRadius:9999,fontSize:11,fontWeight:600,
    background:pass?"#dcfce7":"#fecaca",color:pass?"#166534":"#991b1b"}}>
    {pass?"Pass":"Fail"}
  </span>
);

const PairCard = ({pair, idx}) => {
  const ratio = contrast(pair.textColor, pair.bgColor);
  const rc = ratioColor(ratio);
  return (
    <div style={{border:"1px solid #e5e7eb",borderRadius:12,overflow:"hidden",marginBottom:12}}>
      <div style={{padding:"14px 16px",background:pair.bgColor,color:pair.textColor,minHeight:72,display:"flex",flexDirection:"column",justifyContent:"center"}}>
        <div style={{fontWeight:700,fontSize:16}}>{pair.label||`Pair ${idx+1}`}</div>
        <div style={{fontSize:13,marginTop:2}}>{pair.sampleText||"Sample body text"}</div>
      </div>
      <div style={{padding:"10px 16px",background:"#f9fafb",display:"flex",flexWrap:"wrap",gap:12,alignItems:"center",justifyContent:"space-between"}}>
        <div style={{display:"flex",gap:8,alignItems:"center"}}>
          <ColorDot color={pair.textColor} label="Text" />
          <ColorDot color={pair.bgColor} label="BG" />
        </div>
        <div style={{display:"flex",gap:8,alignItems:"center"}}>
          <span style={{fontWeight:700,fontSize:18,color:rc}}>{ratio.toFixed(2)}:1</span>
          <span style={{fontSize:12,fontWeight:600,color:rc}}>{ratioLabel(ratio)}</span>
        </div>
      </div>
    </div>
  );
};

const ColorDot = ({color,label}) => (
  <div style={{display:"flex",alignItems:"center",gap:5}}>
    <div style={{width:18,height:18,borderRadius:4,background:color,border:"1px solid #d1d5db"}}/>
    <span style={{fontSize:11,color:"#6b7280"}}>{label}: {color}</span>
  </div>
);

const SwatchRow = ({colors,label}) => (
  <div style={{marginBottom:12}}>
    <div style={{fontSize:12,fontWeight:600,color:"#6b7280",marginBottom:6}}>{label}</div>
    <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
      {colors.map((c,i)=>(
        <div key={i} style={{display:"flex",flexDirection:"column",alignItems:"center",gap:3}}>
          <div style={{width:36,height:36,borderRadius:8,background:c,border:"1px solid #d1d5db"}}/>
          <span style={{fontSize:10,color:"#6b7280"}}>{c}</span>
        </div>
      ))}
    </div>
  </div>
);

// ── main component ────────────────────────────────────────────────────────────
export default function App() {
  const [tab, setTab] = useState("upload"); // "upload" | "url"
  const [urlInput, setUrlInput] = useState("");
  const [imgData, setImgData] = useState(null);      // base64 for uploaded image
  const [imgPreview, setImgPreview] = useState(null); // blob URL for preview
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const fileRef = useRef();

  const reset = () => { setResult(null); setError(null); setImgData(null); setImgPreview(null); setUrlInput(""); };

  const handleFile = useCallback((file) => {
    if (!file || !file.type.startsWith("image/")) { setError("Please upload an image file."); return; }
    const reader = new FileReader();
    reader.onload = (e) => {
      setImgPreview(e.target.result);
      setImgData(e.target.result.split(",")[1]);
      setResult(null); setError(null);
    };
    reader.readAsDataURL(file);
  }, []);

  const onDrop = useCallback((e) => {
    e.preventDefault();
    handleFile(e.dataTransfer.files[0]);
  }, [handleFile]);

  const analyze = async () => {
    if (tab==="upload" && !imgData) { setError("Please upload an image first."); return; }
    if (tab==="url" && !urlInput.trim()) { setError("Please enter a URL."); return; }
    setLoading(true); setError(null); setResult(null);

    const systemPrompt = `You are a professional UI/UX accessibility auditor and color theory expert. 
Analyze the provided design (screenshot or described via URL) and return ONLY a valid JSON object with this exact shape:

{
  "dominantPalette": ["#hex1","#hex2","#hex3","#hex4","#hex5"],
  "accentColors": ["#hex1","#hex2"],
  "backgroundColors": ["#hex1","#hex2"],
  "textColors": ["#hex1","#hex2"],
  "colorPairs": [
    {
      "label": "Heading on Hero",
      "textColor": "#hex",
      "bgColor": "#hex",
      "sampleText": "Example heading text"
    }
  ],
  "fonts": {
    "detected": ["Font Name 1","Font Name 2"],
    "categories": ["serif","sans-serif","monospace"],
    "notes": "Brief observation about typography choices"
  },
  "issues": [
    {
      "severity": "critical|warning|info",
      "description": "Specific issue found"
    }
  ],
  "suggestions": [
    {
      "title": "Short suggestion title",
      "description": "Actionable improvement",
      "originalColor": "#hex or null",
      "suggestedColor": "#hex or null",
      "suggestedFont": "Font name or null",
      "reason": "Why this improves accessibility or aesthetics"
    }
  ],
  "overallScore": 0-100,
  "overallSummary": "2-3 sentence summary of the design's accessibility and aesthetic quality"
}

Identify at least 3-5 color pairs from the design. Be specific about hex codes (estimate if needed). Return ONLY the JSON, no markdown, no backticks.`;

    let messages;
    if (tab==="upload" && imgData) {
      messages = [{
        role:"user",
        content:[
          {type:"image",source:{type:"base64",media_type:"image/png",data:imgData}},
          {type:"text",text:"Analyze this UI screenshot for color contrast, palette, typography, and accessibility improvements."}
        ]
      }];
    } else {
      messages = [{
        role:"user",
        content:`Analyze the website at this URL for color contrast, palette, typography, and accessibility improvements: ${urlInput}\n\nImagine you are looking at the page and describe what you'd typically expect from this site's design based on the URL, or analyze based on any knowledge you have of it.`
      }];
    }

    try {
      const res = await fetch("https://api.anthropic.com/v1/messages",{
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({model:ANTHROPIC_MODEL,max_tokens:1800,system:systemPrompt,messages})
      });
      const data = await res.json();
      const raw = data.content?.find(b=>b.type==="text")?.text||"";
      const clean = raw.replace(/```json|```/g,"").trim();
      const parsed = JSON.parse(clean);
      setResult(parsed);
    } catch(e) {
      setError("Analysis failed. Try a different image or URL.");
      console.error(e);
    } finally { setLoading(false); }
  };

  const severityColor = s => s==="critical"?"#dc2626":s==="warning"?"#d97706":"#2563eb";
  const severityBg   = s => s==="critical"?"#fef2f2":s==="warning"?"#fffbeb":"#eff6ff";

  return (
    <div style={{fontFamily:"system-ui,sans-serif",maxWidth:860,margin:"0 auto",padding:"40px 20px",background:"white",minHeight:"100vh"}}>
      <div style={{textAlign:"center",marginBottom:36}}>
        <h1 style={{fontSize:32,fontWeight:800,color:"#111827",margin:0}}>Color Contrast Analyzer</h1>
        <p style={{color:"#6b7280",marginTop:8,fontSize:15}}>Upload a screenshot or paste a URL — get a full accessibility + palette audit</p>
      </div>

      {!result && (
        <div style={{border:"1px solid #e5e7eb",borderRadius:16,padding:28,marginBottom:24}}>
          {/* tabs */}
          <div style={{display:"flex",gap:8,marginBottom:20}}>
            {["upload","url"].map(t=>(
              <button key={t} onClick={()=>{setTab(t);setError(null);}}
                style={{padding:"8px 20px",borderRadius:8,border:"none",cursor:"pointer",fontWeight:600,fontSize:14,
                  background:tab===t?"#111827":"#f3f4f6",color:tab===t?"white":"#374151"}}>
                {t==="upload"?"📁 Upload Image":"🔗 Paste URL"}
              </button>
            ))}
          </div>

          {tab==="upload" && (
            <div
              onDrop={onDrop} onDragOver={e=>e.preventDefault()}
              onClick={()=>!imgPreview&&fileRef.current.click()}
              style={{border:"2px dashed #d1d5db",borderRadius:12,padding:32,textAlign:"center",
                cursor:imgPreview?"default":"pointer",background:"#fafafa",position:"relative"}}>
              <input ref={fileRef} type="file" accept="image/*" style={{display:"none"}}
                onChange={e=>handleFile(e.target.files[0])} />
              {imgPreview ? (
                <div>
                  <img src={imgPreview} alt="preview" style={{maxHeight:220,maxWidth:"100%",borderRadius:8,objectFit:"contain"}}/>
                  <button onClick={(e)=>{e.stopPropagation();reset();}}
                    style={{position:"absolute",top:10,right:10,background:"#374151",color:"white",border:"none",
                      borderRadius:"50%",width:28,height:28,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>
                    <X size={14}/>
                  </button>
                </div>
              ) : (
                <>
                  <Upload size={32} style={{color:"#9ca3af",margin:"0 auto 12px"}}/>
                  <p style={{color:"#374151",fontWeight:600,margin:0}}>Drop a screenshot here or click to browse</p>
                  <p style={{color:"#9ca3af",fontSize:13,marginTop:4}}>PNG, JPG, WEBP supported</p>
                </>
              )}
            </div>
          )}

          {tab==="url" && (
            <div style={{display:"flex",gap:10}}>
              <div style={{flex:1,position:"relative"}}>
                <Link size={16} style={{position:"absolute",left:12,top:"50%",transform:"translateY(-50%)",color:"#9ca3af"}}/>
                <input value={urlInput} onChange={e=>setUrlInput(e.target.value)}
                  placeholder="https://example.com"
                  style={{width:"100%",padding:"10px 12px 10px 36px",border:"1px solid #d1d5db",borderRadius:10,fontSize:14,boxSizing:"border-box"}}/>
              </div>
            </div>
          )}

          {error && <p style={{color:"#dc2626",fontSize:13,marginTop:12,marginBottom:0}}>{error}</p>}

          <button onClick={analyze} disabled={loading}
            style={{marginTop:20,width:"100%",padding:"12px",borderRadius:10,border:"none",
              background:loading?"#9ca3af":"#111827",color:"white",fontWeight:700,fontSize:15,cursor:loading?"not-allowed":"pointer",
              display:"flex",alignItems:"center",justifyContent:"center",gap:8}}>
            {loading ? <><RefreshCw size={16} style={{animation:"spin 1s linear infinite"}}/> Analyzing…</> : "🔍 Analyze Design"}
          </button>
        </div>
      )}

      {/* ── RESULTS ─────────────────────────────────────────────────── */}
      {result && (
        <div>
          {/* header bar */}
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:24}}>
            <div>
              <div style={{fontSize:13,color:"#6b7280",fontWeight:500}}>Overall Score</div>
              <div style={{fontSize:40,fontWeight:800,color:result.overallScore>=70?"#059669":result.overallScore>=50?"#d97706":"#dc2626",lineHeight:1}}>
                {result.overallScore}<span style={{fontSize:20,color:"#9ca3af"}}>/100</span>
              </div>
            </div>
            <button onClick={reset}
              style={{padding:"8px 18px",borderRadius:10,border:"1px solid #e5e7eb",background:"white",
                fontWeight:600,fontSize:13,cursor:"pointer",display:"flex",alignItems:"center",gap:6}}>
              <RefreshCw size={14}/> New Analysis
            </button>
          </div>

          <p style={{color:"#374151",fontSize:14,lineHeight:1.7,marginBottom:24,padding:"14px 16px",
            background:"#f9fafb",borderRadius:10,border:"1px solid #e5e7eb"}}>
            {result.overallSummary}
          </p>

          {/* palettes */}
          <div style={{border:"1px solid #e5e7eb",borderRadius:14,padding:20,marginBottom:20}}>
            <h3 style={{margin:"0 0 16px",fontSize:16,fontWeight:700}}>🎨 Color Palette</h3>
            <SwatchRow colors={result.dominantPalette||[]} label="Dominant Colors" />
            {result.accentColors?.length>0 && <SwatchRow colors={result.accentColors} label="Accent Colors" />}
            {result.backgroundColors?.length>0 && <SwatchRow colors={result.backgroundColors} label="Backgrounds" />}
            {result.textColors?.length>0 && <SwatchRow colors={result.textColors} label="Text Colors" />}
          </div>

          {/* contrast pairs */}
          <div style={{border:"1px solid #e5e7eb",borderRadius:14,padding:20,marginBottom:20}}>
            <h3 style={{margin:"0 0 16px",fontSize:16,fontWeight:700}}>⚖️ Contrast Pairs</h3>
            {(result.colorPairs||[]).map((p,i)=><PairCard key={i} pair={p} idx={i}/>)}
          </div>

          {/* fonts */}
          {result.fonts && (
            <div style={{border:"1px solid #e5e7eb",borderRadius:14,padding:20,marginBottom:20}}>
              <h3 style={{margin:"0 0 12px",fontSize:16,fontWeight:700}}>🔤 Typography</h3>
              {result.fonts.detected?.length>0 && (
                <div style={{display:"flex",flexWrap:"wrap",gap:8,marginBottom:10}}>
                  {result.fonts.detected.map((f,i)=>(
                    <span key={i} style={{padding:"4px 12px",background:"#f3f4f6",borderRadius:20,fontSize:13,fontWeight:500}}>{f}</span>
                  ))}
                </div>
              )}
