                  <p style={{fontSize:13,color:"#374151",margin:"0 0 8px"}}>{s.description}</p>
                  {(s.originalColor||s.suggestedColor) && (
                    <div style={{display:"flex",gap:12,alignItems:"center",marginBottom:8}}>
                      {s.originalColor && (
                        <div style={{display:"flex",alignItems:"center",gap:6}}>
                          <div style={{width:24,height:24,borderRadius:6,background:s.originalColor,border:"1px solid #d1d5db"}}/>
