                        </div>
                      )}
                      {s.originalColor && s.suggestedColor && <span style={{color:"#9ca3af"}}>→</span>}
                      {s.suggestedColor && (
                        <div style={{display:"flex",alignItems:"center",gap:6}}>
                          <div style={{width:24,height:24,borderRadius:6,background:s.suggestedColor,border:"1px solid #d1d5db"}}/>
                          <span style={{fontSize:12,color:"#6b7280"}}>After: {s.suggestedColor}</span>
                        </div>
                      )}
                      {s.suggestedColor && (
                        <Badge pass={contrast(s.suggestedColor, result.backgroundColors?.[0]||"#ffffff")>=4.5}/>
                      )}
                    </div>
                  )}
                  {s.suggestedFont && (
                    <div style={{fontSize:12,color:"#2563eb",fontWeight:500}}>Suggested font: {s.suggestedFont}</div>
                  )}
                  <p style={{fontSize:12,color:"#9ca3af",margin:"6px 0 0",fontStyle:"italic"}}>{s.reason}</p>
                </div>
              ))}
            </div>
          )}

