              target="_blank" rel="noopener noreferrer"
              style={{fontSize:13,color:"#3b82f6",display:"inline-flex",alignItems:"center",gap:4,textDecoration:"none"}}>
              WCAG 2.2 Contrast Guidelines <ExternalLink size={12}/>
            </a>
          </div>
        </div>
      )}

      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
    </div>
  );
}

