// ── color math ────────────────────────────────────────────────────────────────
const hexToRgb = h => { const r=/^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(h); return r?{r:parseInt(r[1],16),g:parseInt(r[2],16),b:parseInt(r[3],16)}:null; };
const lum = ({r,g,b}) => { const c=[r,g,b].map(v=>{v/=255;return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4);}); return .2126*c[0]+.7152*c[1]+.0722*c[2]; };
const contrast = (a,b) => { const r1=hexToRgb(a),r2=hexToRgb(b); if(!r1||!r2)return 1; const l1=lum(r1),l2=lum(r2); return (Math.max(l1,l2)+.05)/(Math.min(l1,l2)+.05); };
const ratioColor = r => r>=7?"#059669":r>=4.5?"#d97706":r>=3?"#ea580c":"#dc2626";
const ratioLabel = r => r>=7?"AAA":r>=4.5?"AA":r>=3?"AA Large Only":"Fail";

// ── small UI pieces ───────────────────────────────────────────────────────────
const Badge = ({pass}) => <span style={{padding:"3px 8px",borderRadius:9999,fontSize:11,fontWeight:600,background:pass?"#dcfce7":"#fecaca",color:pass?"#166534":"#991b1b"}}>{pass?"Pass":"Fail"}</span>;

const ColorDot = ({color,label}) => (
  <div style={{display:"flex",alignItems:"center",gap:5}}>
    <div style={{width:18,height:18,borderRadius:4,background:color,border:"1px solid #d1d5db"}}/>
    <span style={{fontSize:11,color:"#6b7280"}}>{label}: {color}</span>
  </div>
);

const SwatchRow = ({colors,label}) => colors?.length ? (
  <div style={{marginBottom:12}}>
    <div style={{fontSize:12,fontWeight:600,color:"#6b7280",marginBottom:6}}>{label}</div>
    <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
      {colors.map((c,i)=>(
        <div key={i} style={{display:"flex",flexDirection:"column",alignItems:"center",gap:3}}>
          <div style={{width:36,height:36,borderRadius:8,background:c,border:"1px solid #d1d5db"}}/>
          <span style={{fontSize:10,color:"#6b7280"}}>{c}</span>
        </div>
      ))}
    </div>
  </div>
) : null;

const PairCard = ({pair,idx}) => {
  const r = contrast(pair.textColor,pair.bgColor);
  const rc = ratioColor(r);
  return (
    <div style={{border:"1px solid #e5e7eb",borderRadius:12,overflow:"hidden",marginBottom:10}}>
      <div style={{padding:"14px 16px",background:pair.bgColor,color:pair.textColor,minHeight:64,display:"flex",flexDirection:"column",justifyContent:"center"}}>
        <div style={{fontWeight:700,fontSize:16}}>{pair.label||`Pair ${idx+1}`}</div>
        <div style={{fontSize:13,marginTop:2}}>{pair.sampleText||"Sample body text"}</div>
      </div>
      <div style={{padding:"10px 16px",background:"#f9fafb",display:"flex",flexWrap:"wrap",gap:10,alignItems:"center",justifyContent:"space-between"}}>
        <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}>
          <ColorDot color={pair.textColor} label="Text"/><ColorDot color={pair.bgColor} label="BG"/>
        </div>
        <div style={{display:"flex",gap:8,alignItems:"center"}}>
          <span style={{fontWeight:700,fontSize:18,color:rc}}>{r.toFixed(2)}:1</span>
          <span style={{fontSize:12,fontWeight:600,color:rc}}>{ratioLabel(r)}</span>
        </div>
      </div>
    </div>
  );
};

const severityColor = s => s==="critical"?"#dc2626":s==="warning"?"#d97706":"#2563eb";
const severityBg   = s => s==="critical"?"#fef2f2":s==="warning"?"#fffbeb":"#eff6ff";

// ── main ──────────────────────────────────────────────────────────────────────
export default function App() {
