  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [statusMsg, setStatusMsg] = useState("");
  const fileRef = useRef();

  const reset = () => { setResult(null);setError(null);setImgData(null);setImgPreview(null);setUrlInput("");setStatusMsg(""); };

  const handleFile = useCallback((file) => {
    if(!file||!file.type.startsWith("image/")){setError("Please upload an image file.");return;}
    const reader=new FileReader();
    reader.onload=e=>{setImgPreview(e.target.result);setImgData(e.target.result.split(",")[1]);setResult(null);setError(null);};
    reader.readAsDataURL(file);
  },[]);

  const onDrop = useCallback((e)=>{e.preventDefault();handleFile(e.dataTransfer.files[0]);},[handleFile]);

  // ── screenshot via ScreenshotOne ──────────────────────────────────────────
  const captureScreenshot = async () => {
    if(!apiKey.trim()){setError("Enter your ScreenshotOne API key first.");return;}
    let url = urlInput.trim();
    if(!url){setError("Enter a URL to capture.");return;}
    if(!/^https?:\/\//i.test(url)) url = "https://"+url;

    setScreenshotting(true);setError(null);setStatusMsg("📸 Capturing screenshot…");
    try {
      const params = new URLSearchParams({
        access_key: apiKey,
        url,
        format: "jpg",
        viewport_width: 1280,
        viewport_height: 900,
        device_scale_factor: 1,
        full_page: false,
        block_ads: true,
        block_cookie_banners: true,
        delay: 2,
      });
      const res = await fetch(`${SCREENSHOT_API}?${params}`);
      if(!res.ok){
        const txt = await res.text();
        throw new Error(txt||`Screenshot API error ${res.status}`);
      }
      const blob = await res.blob();
      const b64 = await new Promise((resolve,reject)=>{
        const r=new FileReader();
        r.onload=()=>resolve(r.result.split(",")[1]);
        r.onerror=reject;
        r.readAsDataURL(blob);
      });
      const preview = URL.createObjectURL(blob);
      setImgData(b64);setImgPreview(preview);setStatusMsg("✅ Screenshot captured — ready to analyze.");
    } catch(e){
      setError("Screenshot failed: "+e.message);setStatusMsg("");
    } finally { setScreenshotting(false); }
