  // ── AI analysis ───────────────────────────────────────────────────────────
  const analyze = async () => {
    if(!imgData){setError("Capture a screenshot or upload an image first.");return;}
    setAnalyzing(true);setError(null);setStatusMsg("🔍 Analyzing colors, contrast & typography…");

    const system = `You are a professional UI/UX accessibility auditor and color theory expert.
Analyze the provided screenshot and return ONLY a valid JSON object with this exact shape — no markdown, no backticks:

{
  "dominantPalette": ["#hex1","#hex2","#hex3","#hex4","#hex5"],
  "accentColors": ["#hex1","#hex2"],
  "backgroundColors": ["#hex1","#hex2"],
  "textColors": ["#hex1","#hex2"],
  "colorPairs": [
    { "label": "Hero heading", "textColor": "#hex", "bgColor": "#hex", "sampleText": "Example text" }
  ],
  "fonts": {
    "detected": ["Font Name"],
    "categories": ["sans-serif"],
    "notes": "Short typography observation"
  },
  "issues": [
    { "severity": "critical|warning|info", "description": "Specific issue" }
  ],
  "suggestions": [
    {
      "title": "Short title",
      "description": "Actionable fix",
      "originalColor": "#hex or null",
      "suggestedColor": "#hex or null",
      "suggestedFont": "Font name or null",
