    }
  ],
  "overallScore": 0-100,
  "overallSummary": "2-3 sentence accessibility + aesthetic summary"
}

Identify at least 4-6 real color pairs from the design. Estimate hex values precisely from what you see.`;

    try {
      const res = await fetch("https://api.anthropic.com/v1/messages",{
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({
          model:ANTHROPIC_MODEL,max_tokens:2000,system,
          messages:[{role:"user",content:[
            {type:"image",source:{type:"base64",media_type:"image/jpeg",data:imgData}},
            {type:"text",text:"Analyze this website screenshot for color contrast, accessible palette usage, typography, and specific improvement suggestions."}
          ]}]
        })
      });
      const data = await res.json();
      const raw = data.content?.find(b=>b.type==="text")?.text||"";
      const parsed = JSON.parse(raw.replace(/```json|```/g,"").trim());
      setResult(parsed);setStatusMsg("");
