        <h1 style={{fontSize:30,fontWeight:800,color:"#111827",margin:0}}>Color Contrast Analyzer</h1>
        <p style={{color:"#6b7280",marginTop:6,fontSize:14}}>Paste any URL → auto-screenshot → full accessibility + palette audit</p>
      </div>

      {!result && (
        <>
          {/* API key input */}
          <div style={{border:"1px solid #e5e7eb",borderRadius:14,padding:20,marginBottom:16,background:"#fafafa"}}>
            <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:10}}>
              <Key size={15} style={{color:"#6b7280"}}/>
              <span style={{fontWeight:600,fontSize:14,color:"#374151"}}>ScreenshotOne API Key</span>
              <a href="https://screenshotone.com" target="_blank" rel="noopener noreferrer"
                style={{fontSize:12,color:"#3b82f6",display:"flex",alignItems:"center",gap:3,textDecoration:"none",marginLeft:"auto"}}>
                Get free key <ExternalLink size={11}/>
              </a>
            </div>
            <div style={{position:"relative"}}>
              <input
                type={showKey?"text":"password"}
                value={apiKey}
                onChange={e=>setApiKey(e.target.value)}
                placeholder="Paste your ScreenshotOne access key…"
                style={{width:"100%",padding:"9px 40px 9px 12px",border:"1px solid #d1d5db",borderRadius:8,fontSize:13,boxSizing:"border-box"}}
              />
              <button onClick={()=>setShowKey(v=>!v)}
                style={{position:"absolute",right:10,top:"50%",transform:"translateY(-50%)",background:"none",border:"none",cursor:"pointer",color:"#9ca3af",padding:0}}>
                {showKey?<EyeOff size={15}/>:<Eye size={15}/>}
              </button>
            </div>
            <p style={{fontSize:11,color:"#9ca3af",margin:"6px 0 0"}}>Free tier: 100 screenshots/month. Key is used only in your browser and never stored.</p>
