          {/* URL input + capture */}
          <div style={{border:"1px solid #e5e7eb",borderRadius:14,padding:20,marginBottom:16}}>
            <label style={{fontSize:14,fontWeight:600,color:"#374151",display:"block",marginBottom:10}}>
              <Link size={14} style={{verticalAlign:"middle",marginRight:6}}/>Website URL
            </label>
            <div style={{display:"flex",gap:8}}>
              <input
                value={urlInput}
                onChange={e=>setUrlInput(e.target.value)}
                onKeyDown={e=>e.key==="Enter"&&captureScreenshot()}
                placeholder="https://example.com"
                style={{flex:1,padding:"9px 12px",border:"1px solid #d1d5db",borderRadius:8,fontSize:13}}
              />
              <button onClick={captureScreenshot} disabled={loading}
                style={{padding:"9px 18px",borderRadius:8,border:"none",background:loading?"#9ca3af":"#374151",
                  color:"white",fontWeight:600,fontSize:13,cursor:loading?"not-allowed":"pointer",whiteSpace:"nowrap"}}>
                {screenshotting?"Capturing…":"📸 Capture"}
              </button>
            </div>

            {/* or upload fallback */}
            <div style={{display:"flex",alignItems:"center",gap:10,margin:"14px 0 10px"}}>
              <div style={{flex:1,height:1,background:"#e5e7eb"}}/>
              <span style={{fontSize:12,color:"#9ca3af"}}>or upload a screenshot manually</span>
              <div style={{flex:1,height:1,background:"#e5e7eb"}}/>
            </div>

            <div
              onDrop={onDrop} onDragOver={e=>e.preventDefault()}
              onClick={()=>!imgPreview&&fileRef.current.click()}
              style={{border:"2px dashed #d1d5db",borderRadius:10,padding:imgPreview?12:24,
                textAlign:"center",cursor:imgPreview?"default":"pointer",background:"#f9fafb",position:"relative"}}>
              <input ref={fileRef} type="file" accept="image/*" style={{display:"none"}} onChange={e=>handleFile(e.target.files[0])}/>
              {imgPreview ? (
                <div style={{position:"relative",display:"inline-block"}}>
                  <img src={imgPreview} alt="preview" style={{maxHeight:200,maxWidth:"100%",borderRadius:8,objectFit:"contain",display:"block"}}/>
                  <button onClick={e=>{e.stopPropagation();reset();}}
                    style={{position:"absolute",top:-8,right:-8,background:"#374151",color:"white",border:"none",
                      borderRadius:"50%",width:22,height:22,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>
                    <X size={12}/>
                  </button>
                </div>
              ) : (
                <>
                  <Upload size={24} style={{color:"#9ca3af",margin:"0 auto 8px"}}/>
                  <p style={{color:"#6b7280",fontWeight:500,margin:0,fontSize:13}}>Drop screenshot or click to browse</p>
