          {statusMsg && <p style={{fontSize:13,color:"#2563eb",margin:"0 0 12px",textAlign:"center"}}>{statusMsg}</p>}
          {error && <p style={{fontSize:13,color:"#dc2626",margin:"0 0 12px",textAlign:"center"}}>{error}</p>}

          <button onClick={analyze} disabled={loading||!imgData}
            style={{width:"100%",padding:"13px",borderRadius:10,border:"none",
              background:loading||!imgData?"#9ca3af":"#111827",color:"white",fontWeight:700,
