            {analyzing?<><RefreshCw size={16} style={{animation:"spin 1s linear infinite"}}/>Analyzing…</>:"🔍 Analyze Design"}
          </button>
        </>
      )}

      {/* ── RESULTS ──────────────────────────────────────────────────────── */}
      {result && (
        <div>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20}}>
            <div>
              <div style={{fontSize:12,color:"#6b7280",fontWeight:500}}>Overall Score</div>
              <div style={{fontSize:42,fontWeight:800,lineHeight:1,
                color:result.overallScore>=70?"#059669":result.overallScore>=50?"#d97706":"#dc2626"}}>
                {result.overallScore}<span style={{fontSize:18,color:"#9ca3af"}}>/100</span>
              </div>
            </div>
            {imgPreview && <img src={imgPreview} alt="analyzed" style={{height:70,borderRadius:8,border:"1px solid #e5e7eb",objectFit:"cover"}}/>}
            <button onClick={reset}
              style={{padding:"8px 16px",borderRadius:10,border:"1px solid #e5e7eb",background:"white",
                fontWeight:600,fontSize:13,cursor:"pointer",display:"flex",alignItems:"center",gap:6}}>
              <RefreshCw size={13}/> New
            </button>
          </div>

          <p style={{color:"#374151",fontSize:14,lineHeight:1.7,marginBottom:20,padding:"12px 16px",
