          {result.fonts && (
            <Section title="🔤 Typography">
              <div style={{display:"flex",flexWrap:"wrap",gap:8,marginBottom:8}}>
                {result.fonts.detected?.map((f,i)=>(
                  <span key={i} style={{padding:"4px 12px",background:"#f3f4f6",borderRadius:20,fontSize:13,fontWeight:500}}>{f}</span>
                ))}
              </div>
              <p style={{fontSize:13,color:"#6b7280",margin:0}}>{result.fonts.notes}</p>
            </Section>
          )}

          {result.issues?.length>0 && (
            <Section title="⚠️ Issues Found">
              {result.issues.map((issue,i)=>(
                <div key={i} style={{padding:"10px 14px",borderRadius:10,marginBottom:8,
                  background:severityBg(issue.severity),borderLeft:`3px solid ${severityColor(issue.severity)}`}}>
                  <span style={{fontSize:11,fontWeight:700,color:severityColor(issue.severity),textTransform:"uppercase"}}>{issue.severity}</span>
                  <p style={{margin:"4px 0 0",fontSize:13,color:"#374151"}}>{issue.description}</p>
                </div>
              ))}
            </Section>
          )}

          {result.suggestions?.length>0 && (
            <Section title="✅ Suggested Improvements">
              {result.suggestions.map((s,i)=>(
                <div key={i} style={{padding:"14px 16px",borderRadius:12,border:"1px solid #e5e7eb",marginBottom:10,background:"#fafafa"}}>
                  <div style={{fontWeight:700,fontSize:14,marginBottom:4}}>{s.title}</div>
                  <p style={{fontSize:13,color:"#374151",margin:"0 0 8px"}}>{s.description}</p>
                  {(s.originalColor||s.suggestedColor) && (
                    <div style={{display:"flex",gap:12,alignItems:"center",marginBottom:6,flexWrap:"wrap"}}>
                      {s.originalColor && <ColorDot color={s.originalColor} label="Before"/>}
                      {s.originalColor&&s.suggestedColor&&<span style={{color:"#9ca3af"}}>→</span>}
                      {s.suggestedColor && <ColorDot color={s.suggestedColor} label="After"/>}
                      {s.suggestedColor && <Badge pass={contrast(s.suggestedColor,result.backgroundColors?.[0]||"#ffffff")>=4.5}/>}
                    </div>
                  )}
                  {s.suggestedFont && <div style={{fontSize:12,color:"#2563eb",fontWeight:500}}>Font: {s.suggestedFont}</div>}
                  <p style={{fontSize:12,color:"#9ca3af",margin:"6px 0 0",fontStyle:"italic"}}>{s.reason}</p>
                </div>
              ))}
            </Section>
          )}

          <div style={{textAlign:"center",paddingTop:12}}>
            <a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html"
              target="_blank" rel="noopener noreferrer"
              style={{fontSize:12,color:"#3b82f6",display:"inline-flex",alignItems:"center",gap:4,textDecoration:"none"}}>
              WCAG 2.2 Contrast Guidelines <ExternalLink size={11}/>
            </a>
          </div>
        </div>
      )}
      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
    </div>
  );
}

const Section = ({title,children}) => (
  <div style={{border:"1px solid #e5e7eb",borderRadius:14,padding:18,marginBottom:16}}>
    <h3 style={{margin:"0 0 14px",fontSize:15,fontWeight:700}}>{title}</h3>
    {children}
  </div>
);

import { useState, useRef, useCallback } from "react";

const ANTHROPIC_MODEL = "claude-sonnet-4-20250514";
const SCREENSHOT_API = "https://api.screenshotone.com/take";

const hexToRgb = h => { const r=/^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(h); return r?{r:parseInt(r[1],16),g:parseInt(r[2],16),b:parseInt(r[3],16)}:null; };
const lum = ({r,g,b}) => { const c=[r,g,b].map(v=>{v/=255;return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4);}); return .2126*c[0]+.7152*c[1]+.0722*c[2]; };
const contrastRatio = (a,b) => { const r1=hexToRgb(a),r2=hexToRgb(b); if(!r1||!r2)return 1; const l1=lum(r1),l2=lum(r2); return (Math.max(l1,l2)+.05)/(Math.min(l1,l2)+.05); };
const rColor = r => r>=7?"#059669":r>=4.5?"#d97706":r>=3?"#ea580c":"#dc2626";
const rLabel = r => r>=7?"AAA ✓":r>=4.5?"AA ✓":r>=3?"Large AA only":"Fail ✗";

export default function App() {
  const [apiKey, setApiKey]     = useState("");
  const [showKey, setShowKey]   = useState(false);
  const [url, setUrl]           = useState("");
  const [preview, setPreview]   = useState(null);
  const [imgB64, setImgB64]     = useState(null);
  const [status, setStatus]     = useState("");
  const [error, setError]       = useState("");
  const [loading, setLoading]   = useState(false);
  const [step, setStep]         = useState("idle"); // idle | captured | done
  const [result, setResult]     = useState(null);
  const fileRef = useRef();

  const reset = () => { setApiKey(""); setUrl(""); setPreview(null); setImgB64(null); setStatus(""); setError(""); setLoading(false); setStep("idle"); setResult(null); };

  // file upload
  const loadFile = f => {
    if (!f || !f.type.startsWith("image/")) { setError("Image files only (PNG, JPG, WEBP)."); return; }
    const rd = new FileReader();
    rd.onload = e => { setPreview(e.target.result); setImgB64(e.target.result.split(",")[1]); setStep("captured"); setError(""); setStatus("Image loaded — click Analyze."); };
    rd.readAsDataURL(f);
  };
  const onDrop = useCallback(e => { e.preventDefault(); loadFile(e.dataTransfer.files[0]); }, []);

  // screenshot
  const capture = async () => {
    if (!apiKey.trim()) { setError("Enter your ScreenshotOne API key."); return; }
    let u = url.trim();
    if (!u) { setError("Enter a URL."); return; }
    if (!/^https?:\/\//i.test(u)) u = "https://" + u;
    setLoading(true); setError(""); setStatus("📸 Capturing screenshot…");
    try {
      const p = new URLSearchParams({ access_key: apiKey, url: u, format: "jpg", viewport_width: 1280, viewport_height: 900, full_page: false, block_ads: true, block_cookie_banners: true, delay: 2 });
      const res = await fetch(`${SCREENSHOT_API}?${p}`);
      if (!res.ok) throw new Error(`API error ${res.status}: ${await res.text()}`);
      const blob = await res.blob();
      const b64 = await new Promise((res,rej) => { const r=new FileReader(); r.onload=()=>res(r.result.split(",")[1]); r.onerror=rej; r.readAsDataURL(blob); });
      setPreview(URL.createObjectURL(blob)); setImgB64(b64); setStep("captured"); setStatus("✅ Screenshot captured — click Analyze.");
    } catch(e) { setError("Screenshot failed: " + e.message); }
    finally { setLoading(false); }
  };

  // analyze
  const analyze = async () => {
    if (!imgB64) { setError("Capture a screenshot or upload an image first."); return; }
    setLoading(true); setError(""); setStatus("🔍 Analyzing…");
    const sys = `You are a UI accessibility auditor. Analyze the screenshot and return ONLY valid JSON (no markdown, no backticks):
{
  "overallScore": 0-100,
  "overallSummary": "2-3 sentences",
  "dominantPalette": ["#hex","#hex","#hex","#hex","#hex"],
  "accentColors": ["#hex"],
  "backgroundColors": ["#hex"],
  "textColors": ["#hex"],
  "colorPairs": [{"label":"string","textColor":"#hex","bgColor":"#hex","sampleText":"string"}],
  "fonts": {"detected":["string"],"notes":"string"},
  "issues": [{"severity":"critical|warning|info","description":"string"}],
  "suggestions": [{"title":"string","description":"string","originalColor":"#hex or null","suggestedColor":"#hex or null","suggestedFont":"string or null","reason":"string"}]
}`;
    try {
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ model: ANTHROPIC_MODEL, max_tokens: 2000, system: sys, messages: [{ role: "user", content: [{ type: "image", source: { type: "base64", media_type: "image/jpeg", data: imgB64 } }, { type: "text", text: "Analyze this screenshot for color contrast, palette, typography, and accessibility." }] }] })
      });
      const data = await res.json();
      const raw = data.content?.find(b => b.type === "text")?.text || "";
      const parsed = JSON.parse(raw.replace(/```json|```/g,"").trim());
      setResult(parsed); setStep("done"); setStatus("");
    } catch(e) { setError("Analysis failed — " + e.message); }
    finally { setLoading(false); }
  };

  // ── styles ────────────────────────────────────────────────────────────────
  const card  = { border:"1px solid #e5e7eb", borderRadius:12, padding:20, marginBottom:16, background:"#fff" };
  const label = { display:"block", fontSize:13, fontWeight:600, color:"#374151", marginBottom:6 };
  const input = { width:"100%", padding:"10px 12px", border:"1px solid #d1d5db", borderRadius:8, fontSize:14, boxSizing:"border-box", background:"#fff", color:"#111827" };
  const btn   = (bg="#111827",disabled=false) => ({ padding:"10px 20px", borderRadius:8, border:"none", background:disabled?"#9ca3af":bg, color:"#fff", fontWeight:700, fontSize:14, cursor:disabled?"not-allowed":"pointer" });
  const swatch = c => ({ width:32, height:32, borderRadius:6, background:c, border:"1px solid #d1d5db", display:"inline-block", verticalAlign:"middle" });

  return (
    <div style={{ fontFamily:"system-ui,-apple-system,sans-serif", maxWidth:820, margin:"0 auto", padding:24, background:"#f9fafb", minHeight:"100vh" }}>

      {/* HEADER */}
      <div style={{ textAlign:"center", marginBottom:28 }}>
        <h1 style={{ fontSize:26, fontWeight:800, color:"#111827", margin:0 }}>Color Contrast Analyzer</h1>
        <p style={{ color:"#6b7280", fontSize:14, marginTop:6 }}>Enter a URL to auto-screenshot, or upload a screenshot manually</p>
      </div>

      {step !== "done" && (
        <>
          {/* API KEY */}
          <div style={card}>
            <label style={label}>🔑 ScreenshotOne API Key <a href="https://screenshotone.com" target="_blank" rel="noreferrer" style={{ fontSize:12, color:"#3b82f6", fontWeight:400, marginLeft:8 }}>Get free key →</a></label>
            <div style={{ display:"flex", gap:8 }}>
              <input style={{ ...input, flex:1 }} type={showKey?"text":"password"} value={apiKey} onChange={e=>setApiKey(e.target.value)} placeholder="Paste your access key here…" />
              <button style={{ ...btn("#6b7280"), padding:"10px 14px", flexShrink:0 }} onClick={()=>setShowKey(v=>!v)}>{showKey?"Hide":"Show"}</button>
            </div>
            <p style={{ fontSize:11, color:"#9ca3af", margin:"6px 0 0" }}>Free tier: 100 screenshots/month. Key stays in your browser only.</p>
          </div>

          {/* URL */}
          <div style={card}>
            <label style={label}>🌐 Website URL</label>
            <div style={{ display:"flex", gap:8 }}>
              <input style={{ ...input, flex:1 }} type="text" value={url} onChange={e=>setUrl(e.target.value)} onKeyDown={e=>e.key==="Enter"&&capture()} placeholder="https://example.com" />
              <button style={{ ...btn("#1d4ed8", loading), flexShrink:0 }} onClick={capture} disabled={loading}>{loading && step==="idle" ? "Capturing…" : "📸 Capture"}</button>
            </div>
          </div>

          {/* DIVIDER */}
          <div style={{ display:"flex", alignItems:"center", gap:12, margin:"4px 0 16px" }}>
            <div style={{ flex:1, height:1, background:"#e5e7eb" }}/>
            <span style={{ fontSize:12, color:"#9ca3af" }}>or upload manually</span>
            <div style={{ flex:1, height:1, background:"#e5e7eb" }}/>
          </div>

          {/* UPLOAD */}
          <div style={card}>
            <div onDrop={onDrop} onDragOver={e=>e.preventDefault()} onClick={()=>!preview&&fileRef.current.click()}
              style={{ border:"2px dashed #d1d5db", borderRadius:10, padding:preview?12:32, textAlign:"center", cursor:preview?"default":"pointer", background:"#fafafa", position:"relative" }}>
              <input ref={fileRef} type="file" accept="image/*" style={{ display:"none" }} onChange={e=>loadFile(e.target.files[0])} />
              {preview ? (
                <div style={{ position:"relative", display:"inline-block" }}>
                  <img src={preview} alt="preview" style={{ maxHeight:200, maxWidth:"100%", borderRadius:8, objectFit:"contain", display:"block" }} />
                  <button onClick={e=>{e.stopPropagation();reset();}} style={{ position:"absolute", top:-8, right:-8, width:22, height:22, borderRadius:"50%", background:"#374151", color:"#fff", border:"none", cursor:"pointer", fontSize:14, lineHeight:1, display:"flex", alignItems:"center", justifyContent:"center" }}>×</button>
                </div>
              ) : (
                <>
                  <div style={{ fontSize:32, marginBottom:8 }}>📁</div>
                  <p style={{ color:"#6b7280", fontWeight:500, margin:0, fontSize:14 }}>Drop a screenshot here or click to browse</p>
                  <p style={{ color:"#9ca3af", fontSize:12, marginTop:4 }}>PNG, JPG, WEBP</p>
                </>
              )}
            </div>
          </div>

          {/* STATUS / ERROR */}
          {status && <p style={{ textAlign:"center", color:"#2563eb", fontSize:13, margin:"0 0 12px" }}>{status}</p>}
          {error  && <p style={{ textAlign:"center", color:"#dc2626", fontSize:13, margin:"0 0 12px" }}>{error}</p>}

          {/* ANALYZE BUTTON */}
          <button style={{ ...btn("#111827", loading||!imgB64), width:"100%", padding:14, fontSize:15, borderRadius:10 }} onClick={analyze} disabled={loading||!imgB64}>
            {loading && step==="captured" ? "⏳ Analyzing…" : "🔍 Analyze Design"}
          </button>
        </>
      )}

      {/* ── RESULTS ──────────────────────────────────────────────────────── */}
      {step==="done" && result && (
        <div>
          {/* score row */}
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:20 }}>
            <div>
              <div style={{ fontSize:12, color:"#6b7280", fontWeight:500 }}>Overall Score</div>
              <div style={{ fontSize:44, fontWeight:800, lineHeight:1, color:result.overallScore>=70?"#059669":result.overallScore>=50?"#d97706":"#dc2626" }}>
                {result.overallScore}<span style={{ fontSize:18, color:"#9ca3af" }}>/100</span>
              </div>
            </div>
            {preview && <img src={preview} alt="analyzed" style={{ height:64, borderRadius:8, border:"1px solid #e5e7eb" }} />}
            <button style={{ ...btn("#374151"), fontSize:13 }} onClick={reset}>↩ New Analysis</button>
          </div>

          <div style={{ ...card, background:"#f0fdf4", borderColor:"#bbf7d0" }}>
            <p style={{ margin:0, fontSize:14, color:"#166534", lineHeight:1.7 }}>{result.overallSummary}</p>
          </div>

          {/* palette */}
          <div style={card}>
            <h3 style={{ margin:"0 0 14px", fontSize:15, fontWeight:700 }}>🎨 Color Palette</h3>
            {[["Dominant", result.dominantPalette],["Accents", result.accentColors],["Backgrounds", result.backgroundColors],["Text", result.textColors]].map(([lbl,cols])=>
              cols?.length ? (
                <div key={lbl} style={{ marginBottom:12 }}>
                  <div style={{ fontSize:12, fontWeight:600, color:"#6b7280", marginBottom:6 }}>{lbl}</div>
                  <div style={{ display:"flex", flexWrap:"wrap", gap:8 }}>
                    {cols.map((c,i)=>(
                      <div key={i} style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:3 }}>
                        <div style={swatch(c)} />
                        <span style={{ fontSize:10, color:"#6b7280" }}>{c}</span>
                      </div>
                    ))}
                  </div>
                </div>
              ) : null
            )}
          </div>

          {/* contrast pairs */}
          <div style={card}>
            <h3 style={{ margin:"0 0 14px", fontSize:15, fontWeight:700 }}>⚖️ Contrast Pairs</h3>
            {result.colorPairs?.map((p,i)=>{
              const r = contrastRatio(p.textColor,p.bgColor);
              return (
                <div key={i} style={{ border:"1px solid #e5e7eb", borderRadius:10, overflow:"hidden", marginBottom:10 }}>
                  <div style={{ padding:"12px 16px", background:p.bgColor, color:p.textColor }}>
                    <div style={{ fontWeight:700, fontSize:15 }}>{p.label}</div>
                    <div style={{ fontSize:13, marginTop:2 }}>{p.sampleText}</div>
                  </div>
                  <div style={{ padding:"8px 14px", background:"#f9fafb", display:"flex", flexWrap:"wrap", gap:10, alignItems:"center", justifyContent:"space-between" }}>
                    <div style={{ display:"flex", gap:10, flexWrap:"wrap" }}>
                      <span style={{ fontSize:11, color:"#6b7280" }}><span style={{ ...swatch(p.textColor), width:14, height:14, borderRadius:3 }} /> Text: {p.textColor}</span>
                      <span style={{ fontSize:11, color:"#6b7280" }}><span style={{ ...swatch(p.bgColor), width:14, height:14, borderRadius:3 }} /> BG: {p.bgColor}</span>
                    </div>
                    <span style={{ fontWeight:700, fontSize:16, color:rColor(r) }}>{r.toFixed(2)}:1 — {rLabel(r)}</span>
                  </div>
                </div>
              );
            })}
          </div>

          {/* typography */}
          {result.fonts && (
            <div style={card}>
              <h3 style={{ margin:"0 0 12px", fontSize:15, fontWeight:700 }}>🔤 Typography</h3>
              <div style={{ display:"flex", flexWrap:"wrap", gap:8, marginBottom:8 }}>
                {result.fonts.detected?.map((f,i)=><span key={i} style={{ padding:"4px 12px", background:"#f3f4f6", borderRadius:20, fontSize:13, fontWeight:500 }}>{f}</span>)}
              </div>
              <p style={{ fontSize:13, color:"#6b7280", margin:0 }}>{result.fonts.notes}</p>
            </div>
          )}

          {/* issues */}
          {result.issues?.length>0 && (
            <div style={card}>
              <h3 style={{ margin:"0 0 12px", fontSize:15, fontWeight:700 }}>⚠️ Issues</h3>
              {result.issues.map((iss,i)=>(
                <div key={i} style={{ padding:"10px 14px", borderRadius:8, marginBottom:8, background:iss.severity==="critical"?"#fef2f2":iss.severity==="warning"?"#fffbeb":"#eff6ff", borderLeft:`3px solid ${iss.severity==="critical"?"#dc2626":iss.severity==="warning"?"#d97706":"#2563eb"}` }}>
                  <span style={{ fontSize:10, fontWeight:700, textTransform:"uppercase", color:iss.severity==="critical"?"#dc2626":iss.severity==="warning"?"#d97706":"#2563eb" }}>{iss.severity}</span>
                  <p style={{ margin:"4px 0 0", fontSize:13, color:"#374151" }}>{iss.description}</p>
                </div>
              ))}
            </div>
          )}

          {/* suggestions */}
          {result.suggestions?.length>0 && (
            <div style={card}>
              <h3 style={{ margin:"0 0 12px", fontSize:15, fontWeight:700 }}>✅ Suggestions</h3>
              {result.suggestions.map((s,i)=>(
                <div key={i} style={{ padding:"14px", borderRadius:10, border:"1px solid #e5e7eb", marginBottom:10, background:"#fafafa" }}>
                  <div style={{ fontWeight:700, fontSize:14, marginBottom:4 }}>{s.title}</div>
                  <p style={{ fontSize:13, color:"#374151", margin:"0 0 8px" }}>{s.description}</p>
                  {(s.originalColor||s.suggestedColor) && (
                    <div style={{ display:"flex", gap:10, alignItems:"center", flexWrap:"wrap", marginBottom:6 }}>
                      {s.originalColor && <><div style={swatch(s.originalColor)}/><span style={{ fontSize:12, color:"#6b7280" }}>{s.originalColor}</span></>}
                      {s.originalColor&&s.suggestedColor&&<span style={{ color:"#9ca3af", fontSize:18 }}>→</span>}
                      {s.suggestedColor && <><div style={swatch(s.suggestedColor)}/><span style={{ fontSize:12, color:"#6b7280" }}>{s.suggestedColor}</span></>}
                    </div>
                  )}
                  {s.suggestedFont && <div style={{ fontSize:12, color:"#2563eb", fontWeight:500, marginBottom:4 }}>Font suggestion: {s.suggestedFont}</div>}
                  <p style={{ fontSize:12, color:"#9ca3af", margin:0, fontStyle:"italic" }}>{s.reason}</p>
                </div>
              ))}
            </div>
          )}

          <p style={{ textAlign:"center", fontSize:12, color:"#9ca3af", marginTop:8 }}>
            Contrast ratios calculated per <a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html" target="_blank" rel="noreferrer" style={{ color:"#3b82f6" }}>WCAG 2.2</a>
          </p>
        </div>
      )}
    </div>
  );
}

