// screenshot via image URL (avoids CORS)
const capture = async () => {
  if (!apiKey.trim()) { setError("Enter your ScreenshotOne API key."); return; }
  let u = url.trim();
  if (!u) { setError("Enter a URL."); return; }
  if (!/^https?:\/\//i.test(u)) u = "https://" + u;
  setLoading(true); setError(""); setStatus("📸 Capturing screenshot…");
  try {
    const p = new URLSearchParams({
      access_key: apiKey, url: u, format: "jpg",
      viewport_width: 1280, viewport_height: 900,
      full_page: false, block_ads: true,
      block_cookie_banners: true, delay: 2,
      response_type: "json"
    });
    const screenshotUrl = `${SCREENSHOT_API}?${p}`;

    // load via image element to bypass CORS, then draw to canvas → base64
    await new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => {
        const canvas = document.createElement("canvas");
        canvas.width = img.naturalWidth || 1280;
        canvas.height = img.naturalHeight || 900;
        canvas.getContext("2d").drawImage(img, 0, 0);
        try {
          const dataUrl = canvas.toDataURL("image/jpeg", 0.92);
          setPreview(dataUrl);
          setImgB64(dataUrl.split(",")[1]);
          setStep("captured");
          setStatus("✅ Screenshot captured — click Analyze.");
          resolve();
        } catch {
          // canvas tainted — fall back to direct URL display only
          setPreview(screenshotUrl);
          setImgB64(null);
          setStatus("⚠️ Screenshot loaded but canvas blocked — use manual upload for analysis.");
          resolve();
        }
      };
      img.onerror = () => reject(new Error("Could not load screenshot. Check your API key and URL."));
      img.src = screenshotUrl;
    });
  } catch(e) { setError("Screenshot failed: " + e.message); }
  finally { setLoading(false); }
};

