import { useState, useRef, useCallback } from "react";

const ANTHROPIC_MODEL = "claude-sonnet-4-20250514";

const hexToRgb = h => { const r=/^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(h); return r?{r:parseInt(r[1],16),g:parseInt(r[2],16),b:parseInt(r[3],16)}:null; };
const lum = ({r,g,b}) => { const c=[r,g,b].map(v=>{v/=255;return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4);}); return .2126*c[0]+.7152*c[1]+.0722*c[2]; };
const contrastRatio = (a,b) => { const r1=hexToRgb(a),r2=hexToRgb(b); if(!r1||!r2)return 1; const l1=lum(r1),l2=lum(r2); return (Math.max(l1,l2)+.05)/(Math.min(l1,l2)+.05); };
const rColor = r => r>=7?"#059669":r>=4.5?"#d97706":r>=3?"#ea580c":"#dc2626";
const rLabel = r => r>=7?"AAA ✓":r>=4.5?"AA ✓":r>=3?"Large AA only":"Fail ✗";

export default function App() {
  const [url, setUrl]           = useState("");
  const [thumbUrl, setThumbUrl] = useState("");
  const [imgB64, setImgB64]     = useState(null);
  const [imgLoaded, setImgLoaded] = useState(false);
  const [status, setStatus]     = useState("");
  const [error, setError]       = useState("");
  const [loading, setLoading]   = useState(false);
  const [step, setStep]         = useState("idle"); // idle | previewing | done
  const [result, setResult]     = useState(null);
  const canvasRef = useRef();
  const imgRef    = useRef();
  const fileRef   = useRef();

  const reset = () => { setUrl(""); setThumbUrl(""); setImgB64(null); setImgLoaded(false); setStatus(""); setError(""); setLoading(false); setStep("idle"); setResult(null); };

  // ── load screenshot via thum.io ───────────────────────────────────────────
  const capture = () => {
    let u = url.trim();
    if (!u) { setError("Enter a URL first."); return; }
    if (!/^https?:\/\//i.test(u)) u = "https://" + u;
    setError(""); setImgLoaded(false); setImgB64(null);
    // thum.io: free, no key, returns image directly
    const thumb = `https://image.thum.io/get/width/1280/crop/900/noanimate/${u}`;
    setThumbUrl(thumb);
    setStep("previewing");
    setStatus("Loading screenshot…");
  };

  // once the <img> loads, draw to canvas → base64
  const onImgLoad = () => {
    setImgLoaded(true);
    setStatus("✅ Screenshot ready — click Analyze.");
    try {
      const canvas = canvasRef.current;
      const img    = imgRef.current;
      canvas.width  = img.naturalWidth  || 1280;
      canvas.height = img.naturalHeight || 900;
      canvas.getContext("2d").drawImage(img, 0, 0);
      const dataUrl = canvas.toDataURL("image/jpeg", 0.92);
      setImgB64(dataUrl.split(",")[1]);
    } catch {
      // canvas tainted by cross-origin — still allow manual upload path
      setImgB64(null);
      setStatus("Screenshot displayed but could not be read for analysis — upload the image manually below.");
    }
  };

  // ── manual file upload ────────────────────────────────────────────────────
  const loadFile = f => {
    if (!f || !f.type.startsWith("image/")) { setError("Image files only (PNG, JPG, WEBP)."); return; }
    const rd = new FileReader();
    rd.onload = e => {
      setImgB64(e.target.result.split(",")[1]);
      setThumbUrl(e.target.result);
      setImgLoaded(true);
      setStep("previewing");
      setError("");
      setStatus("Image loaded — click Analyze.");
    };
    rd.readAsDataURL(f);
  };
  const onDrop = useCallback(e => { e.preventDefault(); loadFile(e.dataTransfer.files[0]); }, []);

  // ── AI analysis ───────────────────────────────────────────────────────────
  const analyze = async () => {
    if (!imgB64) { setError("No image data available — please upload the screenshot manually."); return; }
    setLoading(true); setError(""); setStatus("🔍 Analyzing…");
    const sys = `You are a UI accessibility auditor. Analyze the screenshot and return ONLY valid JSON (no markdown, no backticks):
{
  "overallScore": 0-100,
  "overallSummary": "2-3 sentences",
  "dominantPalette": ["#hex","#hex","#hex","#hex","#hex"],
  "accentColors": ["#hex"],
  "backgroundColors": ["#hex"],
  "textColors": ["#hex"],
  "colorPairs": [{"label":"string","textColor":"#hex","bgColor":"#hex","sampleText":"string"}],
  "fonts": {"detected":["string"],"notes":"string"},
  "issues": [{"severity":"critical|warning|info","description":"string"}],
  "suggestions": [{"title":"string","description":"string","originalColor":"#hex or null","suggestedColor":"#hex or null","suggestedFont":"string or null","reason":"string"}]
}`;
    try {
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: ANTHROPIC_MODEL, max_tokens: 2000, system: sys,
          messages: [{ role: "user", content: [
            { type: "image", source: { type: "base64", media_type: "image/jpeg", data: imgB64 } },
            { type: "text", text: "Analyze this screenshot for color contrast, palette, typography, and accessibility." }
          ]}]
        })
      });
      const data = await res.json();
      const raw  = data.content?.find(b => b.type === "text")?.text || "";
      const parsed = JSON.parse(raw.replace(/```json|```/g,"").trim());
      setResult(parsed); setStep("done"); setStatus("");
    } catch(e) { setError("Analysis failed — " + e.message); }
    finally { setLoading(false); }
  };

  // ── shared styles ─────────────────────────────────────────────────────────
  const card  = { border:"1px solid #e5e7eb", borderRadius:12, padding:20, marginBottom:16, background:"#fff" };
  const lbl   = { display:"block", fontSize:13, fontWeight:600, color:"#374151", marginBottom:6 };
  const inp   = { width:"100%", padding:"10px 12px", border:"1px solid #d1d5db", borderRadius:8, fontSize:14, boxSizing:"border-box", background:"#fff", color:"#111827" };
  const btn   = (bg,dis) => ({ padding:"10px 20px", borderRadius:8, border:"none", background:dis?"#9ca3af":bg, color:"#fff", fontWeight:700, fontSize:14, cursor:dis?"not-allowed":"pointer", flexShrink:0 });
  const sw    = c => ({ width:32, height:32, borderRadius:6, background:c, border:"1px solid #d1d5db", display:"inline-block" });

  return (
    <div style={{ fontFamily:"system-ui,-apple-system,sans-serif", maxWidth:820, margin:"0 auto", padding:24, background:"#f9fafb", minHeight:"100vh" }}>
      <canvas ref={canvasRef} style={{ display:"none" }} />

      {/* HEADER */}
      <div style={{ textAlign:"center", marginBottom:24 }}>
        <h1 style={{ fontSize:26, fontWeight:800, color:"#111827", margin:0 }}>Color Contrast Analyzer</h1>
        <p style={{ color:"#6b7280", fontSize:14, marginTop:6 }}>Paste a URL to auto-screenshot, or upload a screenshot directly</p>
      </div>

      {step !== "done" && (<>

        {/* URL INPUT */}
        <div style={card}>
          <label style={lbl}>🌐 Website URL <span style={{ fontSize:12, color:"#9ca3af", fontWeight:400 }}>— powered by thum.io (no API key needed)</span></label>
          <div style={{ display:"flex", gap:8 }}>
            <input style={{ ...inp, flex:1 }} type="text" value={url} onChange={e=>setUrl(e.target.value)}
              onKeyDown={e=>e.key==="Enter"&&capture()} placeholder="https://example.com" />
            <button style={btn("#1d4ed8", loading)} onClick={capture} disabled={loading}>
              📸 Capture
            </button>
          </div>
        </div>

        {/* SCREENSHOT PREVIEW */}
        {thumbUrl && (
          <div style={card}>
            <label style={lbl}>Preview</label>
            <img ref={imgRef} src={thumbUrl} alt="screenshot preview"
              onLoad={onImgLoad}
              onError={()=>{ setError("Could not load screenshot — the site may block thumbnailing. Try uploading manually."); setStatus(""); }}
              style={{ width:"100%", borderRadius:8, border:"1px solid #e5e7eb", display:"block" }} />
          </div>
        )}

        {/* DIVIDER */}
        <div style={{ display:"flex", alignItems:"center", gap:12, margin:"4px 0 16px" }}>
          <div style={{ flex:1, height:1, background:"#e5e7eb" }}/>
          <span style={{ fontSize:12, color:"#9ca3af" }}>or upload a screenshot manually</span>
          <div style={{ flex:1, height:1, background:"#e5e7eb" }}/>
        </div>

        {/* UPLOAD */}
        <div style={card}>
          <div onDrop={onDrop} onDragOver={e=>e.preventDefault()}
            onClick={()=>fileRef.current.click()}
            style={{ border:"2px dashed #d1d5db", borderRadius:10, padding:28, textAlign:"center", cursor:"pointer", background:"#fafafa" }}>
            <input ref={fileRef} type="file" accept="image/*" style={{ display:"none" }} onChange={e=>loadFile(e.target.files[0])} />
            <div style={{ fontSize:28, marginBottom:6 }}>📁</div>
            <p style={{ color:"#6b7280", fontWeight:500, margin:0, fontSize:14 }}>Drop a screenshot here or click to browse</p>
            <p style={{ color:"#9ca3af", fontSize:12, marginTop:4 }}>PNG, JPG, WEBP — use this if URL capture fails</p>
          </div>
        </div>

        {status && <p style={{ textAlign:"center", color:"#2563eb", fontSize:13, margin:"0 0 12px" }}>{status}</p>}
        {error  && <p style={{ textAlign:"center", color:"#dc2626", fontSize:13, margin:"0 0 12px" }}>{error}</p>}

        <button style={{ ...btn("#111827", loading||!imgB64), width:"100%", padding:14, fontSize:15, borderRadius:10 }}
          onClick={analyze} disabled={loading||!imgB64}>
          {loading ? "⏳ Analyzing…" : "🔍 Analyze Design"}
        </button>

      </>)}

      {/* RESULTS */}
      {step==="done" && result && (<>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:20 }}>
          <div>
            <div style={{ fontSize:12, color:"#6b7280", fontWeight:500 }}>Overall Score</div>
            <div style={{ fontSize:44, fontWeight:800, lineHeight:1, color:result.overallScore>=70?"#059669":result.overallScore>=50?"#d97706":"#dc2626" }}>
              {result.overallScore}<span style={{ fontSize:18, color:"#9ca3af" }}>/100</span>
            </div>
          </div>
          {thumbUrl && <img src={thumbUrl} alt="analyzed" style={{ height:60, borderRadius:8, border:"1px solid #e5e7eb" }} />}
          <button style={btn("#374151",false)} onClick={reset}>↩ New Analysis</button>
        </div>

        <div style={{ ...card, background:"#f0fdf4", borderColor:"#bbf7d0" }}>
          <p style={{ margin:0, fontSize:14, color:"#166534", lineHeight:1.7 }}>{result.overallSummary}</p>
        </div>

        {/* palette */}
        <div style={card}>
          <h3 style={{ margin:"0 0 14px", fontSize:15, fontWeight:700 }}>🎨 Color Palette</h3>
          {[["Dominant",result.dominantPalette],["Accents",result.accentColors],["Backgrounds",result.backgroundColors],["Text",result.textColors]].map(([l,cols])=>
            cols?.length ? (
              <div key={l} style={{ marginBottom:12 }}>
                <div style={{ fontSize:12, fontWeight:600, color:"#6b7280", marginBottom:6 }}>{l}</div>
                <div style={{ display:"flex", flexWrap:"wrap", gap:8 }}>
                  {cols.map((c,i)=>(
                    <div key={i} style={{ display:"flex",flexDirection:"column",alignItems:"center",gap:3 }}>
                      <div style={sw(c)}/>
                      <span style={{ fontSize:10,color:"#6b7280" }}>{c}</span>
                    </div>
                  ))}
                </div>
              </div>
            ):null
          )}
        </div>

        {/* contrast pairs */}
        <div style={card}>
          <h3 style={{ margin:"0 0 14px", fontSize:15, fontWeight:700 }}>⚖️ Contrast Pairs</h3>
          {result.colorPairs?.map((p,i)=>{
            const r=contrastRatio(p.textColor,p.bgColor);
            return (
              <div key={i} style={{ border:"1px solid #e5e7eb",borderRadius:10,overflow:"hidden",marginBottom:10 }}>
                <div style={{ padding:"12px 16px",background:p.bgColor,color:p.textColor }}>
                  <div style={{ fontWeight:700,fontSize:15 }}>{p.label}</div>
                  <div style={{ fontSize:13,marginTop:2 }}>{p.sampleText}</div>
                </div>
                <div style={{ padding:"8px 14px",background:"#f9fafb",display:"flex",flexWrap:"wrap",gap:10,alignItems:"center",justifyContent:"space-between" }}>
                  <div style={{ display:"flex",gap:10,flexWrap:"wrap",alignItems:"center" }}>
                    <div style={sw(p.textColor)}/><span style={{ fontSize:11,color:"#6b7280" }}>Text: {p.textColor}</span>
                    <div style={sw(p.bgColor)}/><span style={{ fontSize:11,color:"#6b7280" }}>BG: {p.bgColor}</span>
                  </div>
                  <span style={{ fontWeight:700,fontSize:15,color:rColor(r) }}>{r.toFixed(2)}:1 — {rLabel(r)}</span>
                </div>
              </div>
            );
          })}
        </div>

        {/* fonts */}
        {result.fonts && (
          <div style={card}>
            <h3 style={{ margin:"0 0 12px",fontSize:15,fontWeight:700 }}>🔤 Typography</h3>
            <div style={{ display:"flex",flexWrap:"wrap",gap:8,marginBottom:8 }}>
              {result.fonts.detected?.map((f,i)=><span key={i} style={{ padding:"4px 12px",background:"#f3f4f6",borderRadius:20,fontSize:13,fontWeight:500 }}>{f}</span>)}
            </div>
            <p style={{ fontSize:13,color:"#6b7280",margin:0 }}>{result.fonts.notes}</p>
          </div>
        )}

        {/* issues */}
        {result.issues?.length>0 && (
          <div style={card}>
            <h3 style={{ margin:"0 0 12px",fontSize:15,fontWeight:700 }}>⚠️ Issues</h3>
            {result.issues.map((iss,i)=>(
              <div key={i} style={{ padding:"10px 14px",borderRadius:8,marginBottom:8,
                background:iss.severity==="critical"?"#fef2f2":iss.severity==="warning"?"#fffbeb":"#eff6ff",
                borderLeft:`3px solid ${iss.severity==="critical"?"#dc2626":iss.severity==="warning"?"#d97706":"#2563eb"}` }}>
                <span style={{ fontSize:10,fontWeight:700,textTransform:"uppercase",
                  color:iss.severity==="critical"?"#dc2626":iss.severity==="warning"?"#d97706":"#2563eb" }}>{iss.severity}</span>
                <p style={{ margin:"4px 0 0",fontSize:13,color:"#374151" }}>{iss.description}</p>
              </div>
            ))}
          </div>
        )}

        {/* suggestions */}
        {result.suggestions?.length>0 && (
          <div style={card}>
            <h3 style={{ margin:"0 0 12px",fontSize:15,fontWeight:700 }}>✅ Suggestions</h3>
            {result.suggestions.map((s,i)=>(
              <div key={i} style={{ padding:"14px",borderRadius:10,border:"1px solid #e5e7eb",marginBottom:10,background:"#fafafa" }}>
                <div style={{ fontWeight:700,fontSize:14,marginBottom:4 }}>{s.title}</div>
                <p style={{ fontSize:13,color:"#374151",margin:"0 0 8px" }}>{s.description}</p>
                {(s.originalColor||s.suggestedColor) && (
                  <div style={{ display:"flex",gap:10,alignItems:"center",flexWrap:"wrap",marginBottom:6 }}>
                    {s.originalColor&&<><div style={sw(s.originalColor)}/><span style={{ fontSize:12,color:"#6b7280" }}>{s.originalColor}</span></>}
                    {s.originalColor&&s.suggestedColor&&<span style={{ color:"#9ca3af",fontSize:18 }}>→</span>}
                    {s.suggestedColor&&<><div style={sw(s.suggestedColor)}/><span style={{ fontSize:12,color:"#6b7280" }}>{s.suggestedColor}</span></>}
                  </div>
                )}
                {s.suggestedFont&&<div style={{ fontSize:12,color:"#2563eb",fontWeight:500,marginBottom:4 }}>Font suggestion: {s.suggestedFont}</div>}
                <p style={{ fontSize:12,color:"#9ca3af",margin:0,fontStyle:"italic" }}>{s.reason}</p>
              </div>
            ))}
          </div>
        )}

        <p style={{ textAlign:"center",fontSize:12,color:"#9ca3af",marginTop:8 }}>
          Contrast ratios per <a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html" target="_blank" rel="noreferrer" style={{ color:"#3b82f6" }}>WCAG 2.2</a>
        </p>
      </>)}
    </div>
  );
}

import { useState, useRef, useCallback } from "react";

const MODEL = "claude-sonnet-4-20250514";

const hexToRgb = h => { const r=/^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(h); return r?{r:parseInt(r[1],16),g:parseInt(r[2],16),b:parseInt(r[3],16)}:null; };
const lum = ({r,g,b}) => [r,g,b].map(v=>{v/=255;return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4);}).reduce((s,v,i)=>s+[.2126,.7152,.0722][i]*v,0);
const cr  = (a,b) => { const ra=hexToRgb(a),rb=hexToRgb(b); if(!ra||!rb)return 1; const la=lum(ra),lb=lum(rb); return (Math.max(la,lb)+.05)/(Math.min(la,lb)+.05); };
const rc  = r => r>=7?"#059669":r>=4.5?"#d97706":r>=3?"#ea580c":"#dc2626";
const rl  = r => r>=7?"AAA ✓":r>=4.5?"AA ✓":r>=3?"Large AA":"Fail ✗";

export default function App() {
  const [preview, setPreview] = useState(null);
  const [b64, setB64]         = useState(null);
  const [status, setStatus]   = useState("");
  const [error, setError]     = useState("");
  const [busy, setBusy]       = useState(false);
  const [result, setResult]   = useState(null);
  const fileRef = useRef();

  const reset = () => { setPreview(null); setB64(null); setStatus(""); setError(""); setBusy(false); setResult(null); };

  const loadFile = f => {
    if (!f) return;
    if (!f.type.startsWith("image/")) { setError("Please upload a PNG, JPG, or WEBP image."); return; }
    setError(""); setResult(null);
    const rd = new FileReader();
    rd.onload = e => {
      setPreview(e.target.result);
      setB64(e.target.result.split(",")[1]);
      setStatus("Image loaded — click Analyze.");
    };
    rd.readAsDataURL(f);
  };

  const onDrop = useCallback(e => { e.preventDefault(); e.stopPropagation(); loadFile(e.dataTransfer.files[0]); }, []);
  const onDragOver = e => { e.preventDefault(); e.stopPropagation(); };

  const analyze = async () => {
    if (!b64) { setError("Upload a screenshot first."); return; }
    setBusy(true); setError(""); setStatus("Analyzing…");
    const sys = `You are a UI accessibility auditor. Analyze the screenshot carefully and return ONLY a raw JSON object. No markdown fences, no backticks, no extra text — just the JSON object starting with { and ending with }.

{
  "overallScore": <integer 0-100>,
  "overallSummary": "<2-3 sentence summary>",
  "dominantPalette": ["#rrggbb","#rrggbb","#rrggbb","#rrggbb","#rrggbb"],
  "accentColors": ["#rrggbb"],
  "backgroundColors": ["#rrggbb"],
  "textColors": ["#rrggbb"],
  "colorPairs": [
    {"label":"<where this pair appears>","textColor":"#rrggbb","bgColor":"#rrggbb","sampleText":"<example text from the design>"}
  ],
  "fonts": {"detected":["<font name>"],"notes":"<typography observation>"},
  "issues": [{"severity":"critical","description":"<issue>"}],
  "suggestions": [
    {"title":"<short title>","description":"<fix>","originalColor":"#rrggbb or null","suggestedColor":"#rrggbb or null","suggestedFont":"<name> or null","reason":"<why>"}
  ]
}`;

    try {
      const res  = await fetch("https://api.anthropic.com/v1/messages", {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({ model:MODEL, max_tokens:2000, system:sys,
          messages:[{ role:"user", content:[
            { type:"image", source:{ type:"base64", media_type:"image/jpeg", data:b64 }},
            { type:"text",  text:"Analyze this UI screenshot for color palette, contrast ratios, typography, accessibility issues, and improvement suggestions." }
          ]}]
        })
      });
      const data = await res.json();
      if (data.error) throw new Error(data.error.message);
      const raw  = data.content?.find(b=>b.type==="text")?.text || "";
      // extract first {...} block robustly
      const match = raw.match(/\{[\s\S]*\}/);
      if (!match) throw new Error("No JSON found in response.");
      const parsed = JSON.parse(match[0]);
      setResult(parsed); setStatus("");
    } catch(e) {
      setError("Analysis failed: " + e.message);
    } finally { setBusy(false); }
  };

  // ── styles ────────────────────────────────────────────────────────────────
  const card = { border:"1px solid #e5e7eb", borderRadius:12, padding:20, marginBottom:16, background:"#fff" };
  const sw   = c => ({ width:32, height:32, borderRadius:6, background:c, border:"1px solid #d1d5db", display:"inline-block", flexShrink:0 });

  if (result) return (
    <div style={{fontFamily:"system-ui,sans-serif",maxWidth:800,margin:"0 auto",padding:24,background:"#f9fafb",minHeight:"100vh"}}>
      {/* score */}
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20}}>
        <div>
          <div style={{fontSize:12,color:"#6b7280",fontWeight:500}}>Overall Score</div>
          <div style={{fontSize:44,fontWeight:800,lineHeight:1,color:result.overallScore>=70?"#059669":result.overallScore>=50?"#d97706":"#dc2626"}}>
            {result.overallScore}<span style={{fontSize:18,color:"#9ca3af"}}>/100</span>
          </div>
        </div>
        <img src={preview} alt="analyzed" style={{height:60,borderRadius:8,border:"1px solid #e5e7eb",objectFit:"cover"}}/>
        <button onClick={reset} style={{padding:"10px 18px",borderRadius:8,border:"none",background:"#374151",color:"#fff",fontWeight:700,cursor:"pointer"}}>↩ New</button>
      </div>

      <div style={{...card,background:"#f0fdf4",borderColor:"#bbf7d0"}}>
        <p style={{margin:0,fontSize:14,color:"#166534",lineHeight:1.7}}>{result.overallSummary}</p>
      </div>

      {/* palette */}
      <div style={card}>
        <h3 style={{margin:"0 0 14px",fontSize:15,fontWeight:700}}>🎨 Color Palette</h3>
        {[["Dominant",result.dominantPalette],["Accents",result.accentColors],["Backgrounds",result.backgroundColors],["Text",result.textColors]].map(([l,cols])=>
          cols?.length ? (
            <div key={l} style={{marginBottom:12}}>
              <div style={{fontSize:12,fontWeight:600,color:"#6b7280",marginBottom:6}}>{l}</div>
              <div style={{display:"flex",flexWrap:"wrap",gap:8}}>
                {cols.map((c,i)=>(
                  <div key={i} style={{display:"flex",flexDirection:"column",alignItems:"center",gap:3}}>
                    <div style={sw(c)}/><span style={{fontSize:10,color:"#6b7280"}}>{c}</span>
                  </div>
                ))}
              </div>
            </div>
          ):null
        )}
      </div>

      {/* contrast pairs */}
      <div style={card}>
        <h3 style={{margin:"0 0 14px",fontSize:15,fontWeight:700}}>⚖️ Contrast Pairs</h3>
        {result.colorPairs?.map((p,i)=>{
          const r=cr(p.textColor,p.bgColor);
          return (
            <div key={i} style={{border:"1px solid #e5e7eb",borderRadius:10,overflow:"hidden",marginBottom:10}}>
              <div style={{padding:"12px 16px",background:p.bgColor,color:p.textColor}}>
                <div style={{fontWeight:700,fontSize:15}}>{p.label}</div>
                <div style={{fontSize:13,marginTop:2}}>{p.sampleText}</div>
              </div>
              <div style={{padding:"8px 14px",background:"#f9fafb",display:"flex",flexWrap:"wrap",gap:10,alignItems:"center",justifyContent:"space-between"}}>
                <div style={{display:"flex",gap:10,flexWrap:"wrap",alignItems:"center"}}>
                  <div style={sw(p.textColor)}/><span style={{fontSize:11,color:"#6b7280"}}>Text: {p.textColor}</span>
                  <div style={sw(p.bgColor)}/><span style={{fontSize:11,color:"#6b7280"}}>BG: {p.bgColor}</span>
                </div>
                <span style={{fontWeight:700,fontSize:15,color:rc(r)}}>{r.toFixed(2)}:1 — {rl(r)}</span>
              </div>
            </div>
          );
        })}
      </div>

      {/* fonts */}
      {result.fonts && (
        <div style={card}>
          <h3 style={{margin:"0 0 12px",fontSize:15,fontWeight:700}}>🔤 Typography</h3>
          <div style={{display:"flex",flexWrap:"wrap",gap:8,marginBottom:8}}>
            {result.fonts.detected?.map((f,i)=><span key={i} style={{padding:"4px 12px",background:"#f3f4f6",borderRadius:20,fontSize:13,fontWeight:500}}>{f}</span>)}
          </div>
          <p style={{fontSize:13,color:"#6b7280",margin:0}}>{result.fonts.notes}</p>
        </div>
      )}

      {/* issues */}
      {result.issues?.length>0 && (
        <div style={card}>
          <h3 style={{margin:"0 0 12px",fontSize:15,fontWeight:700}}>⚠️ Issues</h3>
          {result.issues.map((iss,i)=>(
            <div key={i} style={{padding:"10px 14px",borderRadius:8,marginBottom:8,
              background:iss.severity==="critical"?"#fef2f2":iss.severity==="warning"?"#fffbeb":"#eff6ff",
              borderLeft:`3px solid ${iss.severity==="critical"?"#dc2626":iss.severity==="warning"?"#d97706":"#2563eb"}`}}>
              <span style={{fontSize:10,fontWeight:700,textTransform:"uppercase",
                color:iss.severity==="critical"?"#dc2626":iss.severity==="warning"?"#d97706":"#2563eb"}}>{iss.severity}</span>
              <p style={{margin:"4px 0 0",fontSize:13,color:"#374151"}}>{iss.description}</p>
            </div>
          ))}
        </div>
      )}

      {/* suggestions */}
      {result.suggestions?.length>0 && (
        <div style={card}>
          <h3 style={{margin:"0 0 12px",fontSize:15,fontWeight:700}}>✅ Suggestions</h3>
          {result.suggestions.map((s,i)=>(
            <div key={i} style={{padding:"14px",borderRadius:10,border:"1px solid #e5e7eb",marginBottom:10,background:"#fafafa"}}>
              <div style={{fontWeight:700,fontSize:14,marginBottom:4}}>{s.title}</div>
              <p style={{fontSize:13,color:"#374151",margin:"0 0 8px"}}>{s.description}</p>
              {(s.originalColor||s.suggestedColor)&&(
                <div style={{display:"flex",gap:10,alignItems:"center",flexWrap:"wrap",marginBottom:6}}>
                  {s.originalColor&&<><div style={sw(s.originalColor)}/><span style={{fontSize:12,color:"#6b7280"}}>{s.originalColor}</span></>}
                  {s.originalColor&&s.suggestedColor&&<span style={{color:"#9ca3af",fontSize:18}}>→</span>}
                  {s.suggestedColor&&<><div style={sw(s.suggestedColor)}/><span style={{fontSize:12,color:"#6b7280"}}>{s.suggestedColor}</span></>}
                </div>
              )}
              {s.suggestedFont&&<div style={{fontSize:12,color:"#2563eb",fontWeight:500,marginBottom:4}}>Font: {s.suggestedFont}</div>}
              <p style={{fontSize:12,color:"#9ca3af",margin:0,fontStyle:"italic"}}>{s.reason}</p>
            </div>
          ))}
        </div>
      )}
      <p style={{textAlign:"center",fontSize:12,color:"#9ca3af",marginTop:8}}>
        Ratios per <a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html" target="_blank" rel="noreferrer" style={{color:"#3b82f6"}}>WCAG 2.2</a>
      </p>
    </div>
  );

  // ── INPUT SCREEN ──────────────────────────────────────────────────────────
  return (
    <div style={{fontFamily:"system-ui,sans-serif",maxWidth:800,margin:"0 auto",padding:24,background:"#f9fafb",minHeight:"100vh"}}>
      <div style={{textAlign:"center",marginBottom:24}}>
        <h1 style={{fontSize:26,fontWeight:800,color:"#111827",margin:0}}>Color Contrast Analyzer</h1>
        <p style={{color:"#6b7280",fontSize:14,marginTop:6}}>Upload a screenshot to get a full accessibility and palette audit</p>
      </div>

      {/* how to screenshot */}
      <div style={{...card,background:"#eff6ff",borderColor:"#bfdbfe"}}>
        <div style={{fontWeight:700,fontSize:14,color:"#1e40af",marginBottom:10}}>📸 How to capture any website</div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
          {[
            ["Mac","Cmd + Shift + 4","Drag to select, saves to Desktop"],
            ["Windows","Win + Shift + S","Select area, save from clipboard"],
            ["Chrome / Edge","F12 → Ctrl+Shift+P → screenshot","Full page or viewport via DevTools"],
            ["Firefox","Right-click → Take Screenshot","Built-in full page or visible area"],
          ].map(([title,keys,note])=>(
            <div key={title} style={{background:"white",borderRadius:8,padding:12,border:"1px solid #bfdbfe"}}>
              <div style={{fontWeight:600,fontSize:13,marginBottom:4}}>{title}</div>
              <code style={{fontSize:11,color:"#374151",display:"block",marginBottom:4}}>{keys}</code>
              <p style={{fontSize:11,color:"#6b7280",margin:0}}>{note}</p>
            </div>
          ))}
        </div>
        <p style={{fontSize:12,color:"#3b82f6",margin:"10px 0 0"}}>Then drop the file into the upload box below ↓</p>
      </div>

      {/* upload zone */}
      <div style={card}>
        <input ref={fileRef} type="file" accept="image/png,image/jpeg,image/webp" style={{display:"none"}}
          onChange={e=>{ if(e.target.files[0]) loadFile(e.target.files[0]); }} />

        {preview ? (
          <div style={{position:"relative"}}>
            <img src={preview} alt="preview" style={{width:"100%",borderRadius:8,border:"1px solid #e5e7eb",display:"block",objectFit:"contain",maxHeight:320}}/>
            <button onClick={()=>{setPreview(null);setB64(null);setStatus("");setError("");}}
              style={{position:"absolute",top:8,right:8,width:28,height:28,borderRadius:"50%",background:"#374151",color:"#fff",border:"none",cursor:"pointer",fontSize:16,display:"flex",alignItems:"center",justifyContent:"center"}}>×</button>
          </div>
        ) : (
          <div
            onDrop={onDrop}
            onDragOver={onDragOver}
            onClick={()=>fileRef.current.click()}
            style={{border:"2px dashed #93c5fd",borderRadius:10,padding:48,textAlign:"center",cursor:"pointer",background:"#f0f9ff",transition:"background .15s"}}
            onMouseEnter={e=>e.currentTarget.style.background="#dbeafe"}
            onMouseLeave={e=>e.currentTarget.style.background="#f0f9ff"}
          >
            <div style={{fontSize:40,marginBottom:10}}>📁</div>
            <p style={{color:"#1d4ed8",fontWeight:600,margin:0,fontSize:15}}>Click to browse or drag & drop</p>
            <p style={{color:"#6b7280",fontSize:13,marginTop:6}}>PNG · JPG · WEBP</p>
          </div>
        )}
      </div>

      {status && <p style={{textAlign:"center",color:"#2563eb",fontSize:13,margin:"0 0 12px"}}>{status}</p>}
      {error  && <p style={{textAlign:"center",color:"#dc2626",fontSize:13,margin:"0 0 12px"}}>{error}</p>}

      <button
        onClick={analyze}
        disabled={busy || !b64}
        style={{width:"100%",padding:14,borderRadius:10,border:"none",
          background:busy||!b64?"#9ca3af":"#111827",
          color:"#fff",fontWeight:700,fontSize:15,cursor:busy||!b64?"not-allowed":"pointer"}}>
        {busy ? "⏳ Analyzing…" : "🔍 Analyze Design"}
      </button>
    </div>
  );
}

