import { useState, useRef, useCallback, useEffect } from "react";

const MODEL = "claude-sonnet-4-20250514";
const hexToRgb = h => { const r=/^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(h); return r?{r:parseInt(r[1],16),g:parseInt(r[2],16),b:parseInt(r[3],16)}:null; };
const lum = ({r,g,b}) => [r,g,b].map(v=>{v/=255;return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4);}).reduce((s,v,i)=>s+[.2126,.7152,.0722][i]*v,0);
const cr = (a,b) => { const ra=hexToRgb(a),rb=hexToRgb(b); if(!ra||!rb)return 1; const la=lum(ra),lb=lum(rb); return (Math.max(la,lb)+.05)/(Math.min(la,lb)+.05); };
const rcol = r => r>=7?"#059669":r>=4.5?"#d97706":r>=3?"#ea580c":"#dc2626";
const rl = (r,lvl) => lvl==="AAA"?(r>=7?"AAA ✓":r>=4.5?"AA ✓":"Fail ✗"):(r>=4.5?"AA ✓":r>=3?"Large AA":"Fail ✗");
const sevcol = s => s==="critical"?"#dc2626":s==="warning"?"#d97706":"#2563eb";
const sevbg  = s => s==="critical"?"#fef2f2":s==="warning"?"#fffbeb":"#eff6ff";

// ── Clipboard copy ────────────────────────────────────────────────────────────
const useCopy = () => {
  const [copied, setCopied] = useState("");
  const copy = (text, key) => { navigator.clipboard.writeText(text).then(()=>{ setCopied(key); setTimeout(()=>setCopied(""),1500); }); };
  return [copied, copy];
};

// ── Swatch with click-to-copy ─────────────────────────────────────────────────
const Swatch = ({ color, size=32 }) => {
  const [copied, copy] = useCopy();
  return (
    <div onClick={()=>copy(color,color)} title={`Copy ${color}`}
      style={{display:"flex",flexDirection:"column",alignItems:"center",gap:3,cursor:"pointer"}}>
      <div style={{width:size,height:size,borderRadius:6,background:color,border:"1px solid #d1d5db",position:"relative"}}>
        {copied===color && <div style={{position:"absolute",inset:0,background:"rgba(0,0,0,.6)",borderRadius:6,display:"flex",alignItems:"center",justifyContent:"center",fontSize:10,color:"#fff"}}>✓</div>}
      </div>
      <span style={{fontSize:10,color:"#6b7280"}}>{color}</span>
    </div>
  );
};

// ── Score ring ────────────────────────────────────────────────────────────────
const ScoreRing = ({ score }) => {
  const c = score>=70?"#059669":score>=50?"#d97706":"#dc2626";
  const r = 28, circ = 2*Math.PI*r, dash = (score/100)*circ;
  return (
    <svg width={72} height={72} style={{transform:"rotate(-90deg)"}}>
      <circle cx={36} cy={36} r={r} fill="none" stroke="#e5e7eb" strokeWidth={6}/>
      <circle cx={36} cy={36} r={r} fill="none" stroke={c} strokeWidth={6} strokeDasharray={`${dash} ${circ}`} strokeLinecap="round" style={{transition:"stroke-dasharray .6s ease"}}/>
      <text x={36} y={36} textAnchor="middle" dominantBaseline="central" fill={c} fontSize={14} fontWeight={800} style={{transform:"rotate(90deg)",transformOrigin:"36px 36px"}}>{score}</text>
    </svg>
  );
};

// ── Skeleton loader ───────────────────────────────────────────────────────────
const Skeleton = () => (
  <div style={{padding:24}}>
    <style>{`@keyframes shimmer{0%{background-position:-400px 0}100%{background-position:400px 0}}.sk{background:linear-gradient(90deg,#f0f0f0 25%,#e0e0e0 50%,#f0f0f0 75%);background-size:400px 100%;animation:shimmer 1.4s infinite;border-radius:6px}`}</style>
    {[80,200,120,160,100].map((w,i)=>(
      <div key={i} className="sk" style={{height:i===1?120:16,width:`${w}%`.replace("%%","%"),maxWidth:"100%",marginBottom:14}}/>
    ))}
    <div style={{display:"flex",gap:10,marginTop:20}}>
      {[1,2,3,4,5].map(i=><div key={i} className="sk" style={{width:48,height:48,borderRadius:8}}/>)}
    </div>
    <div style={{marginTop:20,color:"#6b7280",fontSize:13,textAlign:"center"}}>Analyzing colors, contrast & typography…</div>
  </div>
);

// ── Main ──────────────────────────────────────────────────────────────────────
export default function App() {
  const [files, setFiles]         = useState([]); // [{name,preview,b64,mime,result}]
  const [activeIdx, setActiveIdx] = useState(0);
  const [compareMode, setCompare] = useState(false);
  const [wcagLevel, setWcag]      = useState("AA");
  const [busy, setBusy]           = useState(false);
  const [busyIdx, setBusyIdx]     = useState(null);
  const [error, setError]         = useState("");
  const [history, setHistory]     = useState([]); // last 5 completed audits
  const [zoom, setZoom]           = useState(false);
  const [copied, copy]            = useCopy();
  const fileRef  = useRef();
  const file2Ref = useRef();

  const active  = files[activeIdx];
  const compare = files[1];

  const card = { border:"1px solid #e5e7eb", borderRadius:12, padding:20, marginBottom:16, background:"#fff" };

  const loadFile = (f, slot=0) => {
    if (!f||!f.type.startsWith("image/")) { setError("Image files only (PNG, JPG, WEBP)."); return; }
    setError("");
    const mime = f.type==="image/jpg"?"image/jpeg":f.type;
    const rd = new FileReader();
    rd.onload = e => {
      const entry = { name:f.name, preview:e.target.result, b64:e.target.result.split(",")[1], mime, result:null };
      setFiles(prev => { const n=[...prev]; n[slot]=entry; return n; });
      setActiveIdx(slot);
    };
    rd.readAsDataURL(f);
  };

  const onDrop = useCallback((e,slot=0)=>{ e.preventDefault(); loadFile(e.dataTransfer.files[0],slot); },[]);

  const analyze = async (slot=0) => {
    const f = files[slot];
    if (!f?.b64) { setError("Upload an image first."); return; }
    setBusy(true); setBusyIdx(slot); setError("");
    const sys = `UI accessibility auditor. Return ONLY raw JSON, no markdown, no backticks. Be concise (max 15 words per string). Limit: dominantPalette≤5, colorPairs≤5, issues≤5, suggestions≤5.
{"overallScore":0-100,"overallSummary":"string","dominantPalette":["#hex"],"accentColors":["#hex"],"backgroundColors":["#hex"],"textColors":["#hex"],"alternativePalette":[{"hex":"#hex","role":"string","reason":"string"}],"colorPairs":[{"label":"string","textColor":"#hex","bgColor":"#hex","sampleText":"string"}],"fonts":{"detected":["string"],"googleFontsLinks":["https://fonts.google.com/specimen/Name"],"notes":"string"},"issues":[{"severity":"critical|warning|info","description":"string","screenshotRegion":"top|middle|bottom|left|right or null"}],"suggestions":[{"title":"string","description":"string","originalColor":"#hex or null","suggestedColor":"#hex or null","suggestedFont":"string or null","googleFontLink":"url or null","reason":"string"}],"subScores":{"contrast":0-100,"typography":0-100,"paletteHarmony":0-100}}`;
    try {
      const res = await fetch("https://api.anthropic.com/v1/messages",{
        method:"POST", headers:{"Content-Type":"application/json"},
        body:JSON.stringify({ model:MODEL, max_tokens:4000, system:sys,
          messages:[{role:"user",content:[
            {type:"image",source:{type:"base64",media_type:f.mime,data:f.b64}},
            {type:"text",text:"Analyze this UI screenshot for color contrast, palette, typography, and accessibility. Include an alternativePalette with 4-5 accessible replacement colors."}
          ]}]
        })
      });
      const data = await res.json();
      if (data.error) throw new Error(data.error.message);
      const raw = data.content?.find(b=>b.type==="text")?.text||"";
      const match = raw.match(/\{[\s\S]*\}/);
      if (!match) throw new Error("No JSON in response.");
      const parsed = JSON.parse(match[0]);
      setFiles(prev=>{ const n=[...prev]; n[slot]={...n[slot],result:parsed}; return n; });
      setHistory(prev=>[{name:f.name,preview:f.preview,result:parsed,ts:Date.now()},...prev].slice(0,5));
    } catch(e) { setError("Analysis failed: "+e.message); }
    finally { setBusy(false); setBusyIdx(null); }
  };

  const exportMarkdown = (result, name) => {
    const lines = [
      `# Color Contrast Audit — ${name}`,``,
      `**Overall Score:** ${result.overallScore}/100`,``,
      `## Summary`,result.overallSummary,``,
      `## Sub-scores`,
      `- Contrast: ${result.subScores?.contrast??"-"}/100`,
      `- Typography: ${result.subScores?.typography??"-"}/100`,
      `- Palette Harmony: ${result.subScores?.paletteHarmony??"-"}/100`,``,
      `## Color Palette`,
      `**Dominant:** ${result.dominantPalette?.join(", ")}`,
      `**Accents:** ${result.accentColors?.join(", ")}`,
      `**Backgrounds:** ${result.backgroundColors?.join(", ")}`,
      `**Text:** ${result.textColors?.join(", ")}`,``,
      `## Contrast Pairs`,
      ...(result.colorPairs||[]).map(p=>`- **${p.label}**: ${p.textColor} on ${p.bgColor} → ${cr(p.textColor,p.bgColor).toFixed(2)}:1`),``,
      `## Typography`,
      `Fonts: ${result.fonts?.detected?.join(", ")}`,
      result.fonts?.notes,``,
      `## Issues`,
      ...(result.issues||[]).map(i=>`- [${i.severity.toUpperCase()}] ${i.description}`),``,
      `## Suggestions`,
      ...(result.suggestions||[]).map(s=>`- **${s.title}**: ${s.description}${s.originalColor?` (${s.originalColor} → ${s.suggestedColor})`:""}`)
    ];
    const blob = new Blob([lines.join("\n")],{type:"text/markdown"});
    const a = document.createElement("a"); a.href=URL.createObjectURL(blob); a.download=`audit-${name.replace(/\s/g,"-")}.md`; a.click();
  };

  const reset = () => { setFiles([]); setActiveIdx(0); setCompare(false); setError(""); };

  const hasResult = active?.result;

  // ── UPLOAD SCREEN ─────────────────────────────────────────────────────────
  if (!files.length || (!hasResult && !busy)) return (
    <div style={{fontFamily:"system-ui,sans-serif",maxWidth:820,margin:"0 auto",padding:24,background:"#f9fafb",minHeight:"100vh"}}>
      <div style={{textAlign:"center",marginBottom:24}}>
        <h1 style={{fontSize:26,fontWeight:800,color:"#111827",margin:0}}>Color Contrast Analyzer</h1>
        <p style={{color:"#6b7280",fontSize:14,marginTop:6}}>Upload screenshots for a full accessibility, palette & typography audit</p>
      </div>

      {/* history */}
      {history.length>0 && (
        <div style={card}>
          <div style={{fontWeight:700,fontSize:14,marginBottom:10}}>🕐 Recent Audits</div>
          <div style={{display:"flex",gap:10,flexWrap:"wrap"}}>
            {history.map((h,i)=>(
              <div key={i} onClick={()=>{ setFiles([{name:h.name,preview:h.preview,b64:null,mime:null,result:h.result}]); setActiveIdx(0); }}
                style={{cursor:"pointer",borderRadius:8,overflow:"hidden",border:"1px solid #e5e7eb",width:100}}>
                <img src={h.preview} alt={h.name} style={{width:"100%",height:60,objectFit:"cover"}}/>
                <div style={{padding:"4px 6px",fontSize:10,color:"#6b7280",whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{h.name}</div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* screenshot guide */}
      <div style={{...card,background:"#eff6ff",borderColor:"#bfdbfe"}}>
        <div style={{fontWeight:700,fontSize:14,color:"#1e40af",marginBottom:10}}>📸 How to capture any website</div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(170px,1fr))",gap:10}}>
          {[["Mac","Cmd+Shift+4","Drag to select, saves to Desktop"],["Windows","Win+Shift+S","Select area, save from clipboard"],["Chrome/Edge","F12 → Ctrl+Shift+P → screenshot","Full page via DevTools"],["Firefox","Right-click → Take Screenshot","Built-in full page capture"]].map(([t,k,n])=>(
            <div key={t} style={{background:"white",borderRadius:8,padding:10,border:"1px solid #bfdbfe"}}>
              <div style={{fontWeight:600,fontSize:12,marginBottom:3}}>{t}</div>
              <code style={{fontSize:11,color:"#374151",display:"block",marginBottom:3}}>{k}</code>
              <p style={{fontSize:11,color:"#6b7280",margin:0}}>{n}</p>
            </div>
          ))}
        </div>
      </div>

      {/* upload zone */}
      <div style={card}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
          <span style={{fontWeight:600,fontSize:14}}>Upload Screenshot{compareMode?" 1":""}</span>
          <label style={{display:"flex",alignItems:"center",gap:6,fontSize:13,color:"#374151",cursor:"pointer"}}>
            <input type="checkbox" checked={compareMode} onChange={e=>setCompare(e.target.checked)} style={{accentColor:"#1d4ed8"}}/>
            Compare two designs
          </label>
        </div>
        <input ref={fileRef} type="file" accept="image/*" style={{display:"none"}} onChange={e=>loadFile(e.target.files[0],0)}/>
        <DropZone preview={files[0]?.preview} onDrop={e=>onDrop(e,0)} onClick={()=>fileRef.current.click()} onClear={()=>setFiles(prev=>{const n=[...prev];n[0]=undefined;return n.filter(Boolean);})}/>
        {compareMode && (<>
          <div style={{fontWeight:600,fontSize:14,margin:"14px 0 8px"}}>Screenshot 2</div>
          <input ref={file2Ref} type="file" accept="image/*" style={{display:"none"}} onChange={e=>loadFile(e.target.files[0],1)}/>
          <DropZone preview={files[1]?.preview} onDrop={e=>onDrop(e,1)} onClick={()=>file2Ref.current.click()} onClear={()=>setFiles(prev=>{const n=[...prev];n[1]=undefined;return n.filter(Boolean);})}/>
        </>)}
      </div>

      {/* WCAG toggle */}
      <div style={{...card,display:"flex",alignItems:"center",gap:14}}>
        <span style={{fontWeight:600,fontSize:14}}>WCAG Target Level</span>
        {["AA","AAA"].map(l=>(
          <button key={l} onClick={()=>setWcag(l)}
            style={{padding:"6px 18px",borderRadius:20,border:"none",cursor:"pointer",fontWeight:700,fontSize:13,
              background:wcagLevel===l?"#1d4ed8":"#f3f4f6",color:wcagLevel===l?"#fff":"#374151"}}>
            {l}
          </button>
        ))}
        <span style={{fontSize:12,color:"#9ca3af"}}>{wcagLevel==="AA"?"Min 4.5:1 normal text":"Min 7:1 normal text"}</span>
      </div>

      {error && <p style={{color:"#dc2626",fontSize:13,textAlign:"center",margin:"0 0 12px"}}>{error}</p>}

      <button onClick={()=>analyze(0)} disabled={busy||!files[0]?.b64}
        style={{width:"100%",padding:14,borderRadius:10,border:"none",background:busy||!files[0]?.b64?"#9ca3af":"#111827",color:"#fff",fontWeight:700,fontSize:15,cursor:busy||!files[0]?.b64?"not-allowed":"pointer"}}>
        {busy?"⏳ Analyzing…":"🔍 Analyze Design"}
      </button>
    </div>
  );

  // ── LOADING ───────────────────────────────────────────────────────────────
  if (busy) return (
    <div style={{fontFamily:"system-ui,sans-serif",maxWidth:820,margin:"0 auto",padding:24,background:"#f9fafb",minHeight:"100vh"}}>
      <div style={{textAlign:"center",marginBottom:16}}>
        <h1 style={{fontSize:22,fontWeight:800,color:"#111827",margin:0}}>Analyzing…</h1>
      </div>
      {active?.preview && <img src={active.preview} alt="preview" style={{width:"100%",borderRadius:10,border:"1px solid #e5e7eb",marginBottom:16,maxHeight:260,objectFit:"cover"}}/>}
      <div style={{...card}}><Skeleton/></div>
    </div>
  );

  // ── RESULTS ───────────────────────────────────────────────────────────────
  const res  = active?.result;
  const res2 = compare?.result;

  const renderResult = (r, f, idx) => {
    if (!r) return (
      <div style={{flex:1,minWidth:0}}>
        <div style={{...card,textAlign:"center"}}>
          <p style={{color:"#6b7280",fontSize:14}}>No result yet</p>
          <button onClick={()=>analyze(idx)} disabled={busy||!f?.b64}
            style={{padding:"8px 20px",borderRadius:8,border:"none",background:"#1d4ed8",color:"#fff",fontWeight:700,cursor:"pointer"}}>
            Analyze
          </button>
        </div>
      </div>
    );
    return (
      <div style={{flex:1,minWidth:0}}>
        {/* score bar */}
        <div style={{...card,display:"flex",flexWrap:"wrap",gap:16,alignItems:"center",justifyContent:"space-between"}}>
          <div style={{display:"flex",gap:16,alignItems:"center"}}>
            <ScoreRing score={r.overallScore}/>
            <div>
              <div style={{fontSize:12,color:"#6b7280",fontWeight:500}}>Overall Score</div>
              <div style={{display:"flex",gap:10,marginTop:6}}>
                {[["Contrast",r.subScores?.contrast],["Typography",r.subScores?.typography],["Palette",r.subScores?.paletteHarmony]].map(([l,v])=>(
                  <div key={l} style={{textAlign:"center"}}>
                    <div style={{fontSize:16,fontWeight:800,color:v>=70?"#059669":v>=50?"#d97706":"#dc2626"}}>{v??"-"}</div>
                    <div style={{fontSize:10,color:"#9ca3af"}}>{l}</div>
                  </div>
                ))}
              </div>
            </div>
          </div>
          {f?.preview && (
            <img src={f.preview} alt="analyzed" onClick={()=>setZoom(true)} style={{height:56,borderRadius:8,border:"1px solid #e5e7eb",cursor:"zoom-in",objectFit:"cover"}}/>
          )}
        </div>

        <div style={{...card,background:"#f0fdf4",borderColor:"#bbf7d0"}}>
          <p style={{margin:0,fontSize:13,color:"#166534",lineHeight:1.7}}>{r.overallSummary}</p>
        </div>

        {/* palette */}
        <div style={card}>
          <h3 style={{margin:"0 0 12px",fontSize:15,fontWeight:700}}>🎨 Color Palette <span style={{fontSize:11,color:"#9ca3af",fontWeight:400}}>click any swatch to copy hex</span></h3>
          {[["Dominant",r.dominantPalette],["Accents",r.accentColors],["Backgrounds",r.backgroundColors],["Text",r.textColors]].map(([l,cols])=>
            cols?.length?(
              <div key={l} style={{marginBottom:12}}>
                <div style={{fontSize:12,fontWeight:600,color:"#6b7280",marginBottom:6}}>{l}</div>
                <div style={{display:"flex",flexWrap:"wrap",gap:8}}>{cols.map((c,i)=><Swatch key={i} color={c}/>)}</div>
              </div>
            ):null
          )}
          {r.alternativePalette?.length>0 && (
            <div style={{marginTop:12,paddingTop:12,borderTop:"1px solid #f3f4f6"}}>
              <div style={{fontSize:12,fontWeight:700,color:"#6b7280",marginBottom:8}}>✨ Suggested Accessible Alternative Palette</div>
              <div style={{display:"flex",flexWrap:"wrap",gap:10}}>
                {r.alternativePalette.map((p,i)=>(
                  <div key={i} style={{display:"flex",flexDirection:"column",alignItems:"center",gap:3}}>
                    <Swatch color={p.hex}/>
                    <span style={{fontSize:10,color:"#374151",fontWeight:500}}>{p.role}</span>
                    <span style={{fontSize:9,color:"#9ca3af",textAlign:"center",maxWidth:60}}>{p.reason}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* contrast pairs */}
        <div style={card}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}>
            <h3 style={{margin:0,fontSize:15,fontWeight:700}}>⚖️ Contrast Pairs</h3>
            <span style={{fontSize:12,padding:"3px 10px",borderRadius:20,background:"#eff6ff",color:"#1d4ed8",fontWeight:600}}>WCAG {wcagLevel}</span>
          </div>
          {r.colorPairs?.map((p,i)=>{
            const ratio=cr(p.textColor,p.bgColor);
            const pass=wcagLevel==="AAA"?ratio>=7:ratio>=4.5;
            return (
              <div key={i} style={{border:"1px solid #e5e7eb",borderRadius:10,overflow:"hidden",marginBottom:10}}>
                <div style={{padding:"12px 16px",background:p.bgColor,color:p.textColor}}>
                  <div style={{fontWeight:700,fontSize:15}}>{p.label}</div>
                  <div style={{fontSize:13,marginTop:2}}>{p.sampleText}</div>
                </div>
                <div style={{padding:"8px 14px",background:"#f9fafb",display:"flex",flexWrap:"wrap",gap:8,alignItems:"center",justifyContent:"space-between"}}>
                  <div style={{display:"flex",gap:8,flexWrap:"wrap",alignItems:"center"}}>
                    <Swatch color={p.textColor} size={20}/><span style={{fontSize:11,color:"#6b7280"}}>{p.textColor}</span>
                    <Swatch color={p.bgColor} size={20}/><span style={{fontSize:11,color:"#6b7280"}}>{p.bgColor}</span>
                  </div>
                  <div style={{display:"flex",gap:8,alignItems:"center"}}>
                    <span style={{fontWeight:700,fontSize:15,color:rcol(ratio)}}>{ratio.toFixed(2)}:1</span>
                    <span style={{padding:"2px 8px",borderRadius:20,fontSize:11,fontWeight:700,background:pass?"#dcfce7":"#fecaca",color:pass?"#166534":"#991b1b"}}>{rl(ratio,wcagLevel)}</span>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* fonts */}
        {r.fonts && (
          <div style={card}>
            <h3 style={{margin:"0 0 12px",fontSize:15,fontWeight:700}}>🔤 Typography</h3>
            <div style={{display:"flex",flexWrap:"wrap",gap:8,marginBottom:8}}>
              {r.fonts.detected?.map((f,i)=>{
                const link=r.fonts.googleFontsLinks?.[i];
                return link
                  ? <a key={i} href={link} target="_blank" rel="noreferrer" style={{padding:"4px 12px",background:"#eff6ff",borderRadius:20,fontSize:13,fontWeight:500,color:"#1d4ed8",textDecoration:"none"}}>{f} ↗</a>
                  : <span key={i} style={{padding:"4px 12px",background:"#f3f4f6",borderRadius:20,fontSize:13,fontWeight:500}}>{f}</span>;
              })}
            </div>
            <p style={{fontSize:13,color:"#6b7280",margin:0}}>{r.fonts.notes}</p>
          </div>
        )}

        {/* issues */}
        {r.issues?.length>0 && (
          <div style={card}>
            <h3 style={{margin:"0 0 12px",fontSize:15,fontWeight:700}}>⚠️ Issues</h3>
            {r.issues.map((iss,i)=>(
              <div key={i} style={{padding:"10px 14px",borderRadius:8,marginBottom:8,background:sevbg(iss.severity),borderLeft:`3px solid ${sevcol(iss.severity)}`}}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                  <span style={{fontSize:10,fontWeight:700,textTransform:"uppercase",color:sevcol(iss.severity)}}>{iss.severity}</span>
                  {iss.screenshotRegion && <span style={{fontSize:10,color:"#9ca3af",background:"#f3f4f6",padding:"2px 6px",borderRadius:4}}>📍 {iss.screenshotRegion}</span>}
                </div>
                <p style={{margin:"4px 0 0",fontSize:13,color:"#374151"}}>{iss.description}</p>
              </div>
            ))}
          </div>
        )}

        {/* suggestions */}
        {r.suggestions?.length>0 && (
          <div style={card}>
            <h3 style={{margin:"0 0 12px",fontSize:15,fontWeight:700}}>✅ Suggestions</h3>
            {r.suggestions.map((s,i)=>(
              <div key={i} style={{padding:"14px",borderRadius:10,border:"1px solid #e5e7eb",marginBottom:10,background:"#fafafa"}}>
                <div style={{fontWeight:700,fontSize:14,marginBottom:4}}>{s.title}</div>
                <p style={{fontSize:13,color:"#374151",margin:"0 0 8px"}}>{s.description}</p>
                {(s.originalColor||s.suggestedColor) && (
                  <div style={{display:"flex",gap:10,alignItems:"center",flexWrap:"wrap",marginBottom:6}}>
                    {s.originalColor && <><Swatch color={s.originalColor} size={28}/><span style={{fontSize:12,color:"#6b7280"}}>{s.originalColor}</span></>}
                    {s.originalColor&&s.suggestedColor && <span style={{fontSize:18,color:"#9ca3af"}}>→</span>}
                    {s.suggestedColor && <><Swatch color={s.suggestedColor} size={28}/><span style={{fontSize:12,color:"#6b7280"}}>{s.suggestedColor}</span></>}
                    {s.originalColor&&s.suggestedColor && (
                      <span style={{padding:"3px 8px",borderRadius:20,fontSize:11,fontWeight:700,
                        background:cr(s.suggestedColor,r.backgroundColors?.[0]||"#ffffff")>=(wcagLevel==="AAA"?7:4.5)?"#dcfce7":"#fef9c3",
                        color:cr(s.suggestedColor,r.backgroundColors?.[0]||"#ffffff")>=(wcagLevel==="AAA"?7:4.5)?"#166534":"#92400e"}}>
                        {cr(s.suggestedColor,r.backgroundColors?.[0]||"#ffffff").toFixed(2)}:1
                      </span>
                    )}
                  </div>
                )}
                {s.suggestedFont && (
                  s.googleFontLink
                    ? <a href={s.googleFontLink} target="_blank" rel="noreferrer" style={{fontSize:12,color:"#2563eb",fontWeight:500,display:"block",marginBottom:4}}>Font: {s.suggestedFont} ↗ Google Fonts</a>
                    : <div style={{fontSize:12,color:"#2563eb",fontWeight:500,marginBottom:4}}>Font: {s.suggestedFont}</div>
                )}
                <p style={{fontSize:12,color:"#9ca3af",margin:0,fontStyle:"italic"}}>{s.reason}</p>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

  return (
    <div style={{fontFamily:"system-ui,sans-serif",maxWidth:compareMode&&res2?1100:820,margin:"0 auto",padding:24,background:"#f9fafb",minHeight:"100vh"}}>
      {/* topbar */}
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20,flexWrap:"wrap",gap:10}}>
        <h1 style={{fontSize:20,fontWeight:800,color:"#111827",margin:0}}>Color Contrast Analyzer</h1>
        <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
          <select value={wcagLevel} onChange={e=>setWcag(e.target.value)}
            style={{padding:"6px 12px",borderRadius:8,border:"1px solid #d1d5db",fontSize:13,fontWeight:600,cursor:"pointer"}}>
            <option value="AA">WCAG AA</option>
            <option value="AAA">WCAG AAA</option>
          </select>
          {res && <button onClick={()=>exportMarkdown(res,active.name)}
            style={{padding:"6px 14px",borderRadius:8,border:"1px solid #d1d5db",background:"#fff",fontWeight:600,fontSize:13,cursor:"pointer"}}>
            ⬇ Export MD
          </button>}
          <button onClick={reset}
            style={{padding:"6px 14px",borderRadius:8,border:"none",background:"#374151",color:"#fff",fontWeight:600,fontSize:13,cursor:"pointer"}}>
            ↩ New
          </button>
        </div>
      </div>

      {error && <p style={{color:"#dc2626",fontSize:13,textAlign:"center",margin:"0 0 12px"}}>{error}</p>}

      {/* compare layout */}
      <div style={{display:"flex",gap:20,alignItems:"flex-start",flexWrap:compareMode&&res2?"nowrap":"wrap"}}>
        {renderResult(res, active, 0)}
        {compareMode && renderResult(res2, compare, 1)}
      </div>

      <p style={{textAlign:"center",fontSize:11,color:"#9ca3af",marginTop:8}}>
        Ratios per <a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html" target="_blank" rel="noreferrer" style={{color:"#3b82f6"}}>WCAG 2.2</a>
      </p>

      {/* zoom modal */}
      {zoom && active?.preview && (
        <div onClick={()=>setZoom(false)} style={{position:"fixed",inset:0,background:"rgba(0,0,0,.85)",zIndex:1000,display:"flex",alignItems:"center",justifyContent:"center",cursor:"zoom-out",padding:24}}>
          <img src={active.preview} alt="zoom" style={{maxWidth:"100%",maxHeight:"100%",borderRadius:8,objectFit:"contain"}}/>
        </div>
      )}
    </div>
  );
}

// ── DropZone component ────────────────────────────────────────────────────────
const DropZone = ({ preview, onDrop, onClick, onClear }) => (
  preview ? (
    <div style={{position:"relative"}}>
      <img src={preview} alt="preview" style={{width:"100%",borderRadius:8,border:"1px solid #e5e7eb",display:"block",maxHeight:280,objectFit:"cover"}}/>
      <button onClick={onClear} style={{position:"absolute",top:8,right:8,width:26,height:26,borderRadius:"50%",background:"#374151",color:"#fff",border:"none",cursor:"pointer",fontSize:15,display:"flex",alignItems:"center",justifyContent:"center"}}>×</button>
    </div>
  ) : (
    <div onDrop={onDrop} onDragOver={e=>e.preventDefault()} onClick={onClick}
      style={{border:"2px dashed #93c5fd",borderRadius:10,padding:40,textAlign:"center",cursor:"pointer",background:"#f0f9ff"}}
      onMouseEnter={e=>e.currentTarget.style.background="#dbeafe"}
      onMouseLeave={e=>e.currentTarget.style.background="#f0f9ff"}>
      <div style={{fontSize:36,marginBottom:8}}>📁</div>
      <p style={{color:"#1d4ed8",fontWeight:600,margin:0,fontSize:14}}>Click to browse or drag & drop</p>
      <p style={{color:"#6b7280",fontSize:12,marginTop:4}}>PNG · JPG · WEBP</p>
    </div>
  )
);

