{"language": "html", "code": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Addie — Buying Strategy & Operations</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,600;1,300;1,400&family=Syne:wght@400;500;600;700&display=swap" rel="stylesheet">

<style>
  :root {
    --bg:           #0e0d0b;
    --surface:      #161410;
    --surface-2:    #1e1c18;
    --border:       rgba(255,245,220,0.07);
    --border-warm:  rgba(255,245,220,0.13);
    --text-primary: #f5f0e8;
    --text-muted:   #9e9688;
    --text-dim:     #5a5549;
    --accent:       #c8a96e;
    --accent-dim:   rgba(200,169,110,0.12);
    --accent-line:  rgba(200,169,110,0.35);
    --font-display: 'Cormorant Garamond', Georgia, serif;
    --font-sans:    'Syne', system-ui, sans-serif;
    --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  }

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  html { scroll-behavior: smooth; }

  body {
    background: var(--bg);
    color: var(--text-primary);
    font-family: var(--font-sans);
    font-size: 15px;
    line-height: 1.65;
    -webkit-font-smoothing: antialiased;
    overflow-x: hidden;
  }

  /* ─── NOISE TEXTURE OVERLAY ─── */
  body::before {
    content: '';
    position: fixed;
    inset: 0;
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.03'/%3E%3C/svg%3E");
    pointer-events: none;
    z-index: 9999;
    opacity: 0.4;
  }

  /* ─── NAVIGATION ─── */
  nav {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    z-index: 100;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 24px 48px;
    background: linear-gradient(to bottom, var(--bg) 0%, transparent 100%);
  }

  .nav-mark {
    font-family: var(--font-display);
    font-size: 1.1rem;
    font-weight: 300;
    letter-spacing: 0.04em;
    color: var(--text-primary);
    text-decoration: none;
  }

  .nav-links {
    display: flex;
    gap: 36px;
    list-style: none;
  }

  .nav-links a {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--text-muted);
    text-decoration: none;
    transition: color 200ms ease;
  }

  .nav-links a:hover { color: var(--text-primary); }

  /* ─── HERO ─── */
  .hero {
    min-height: 100vh;
    display: grid;
    grid-template-columns: 1fr 1fr;
    position: relative;
    overflow: hidden;
  }

  .hero-left {
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    padding: 120px 48px 80px;
    position: relative;
    z-index: 2;
  }

  .hero-eyebrow {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 32px;
    opacity: 0;
    animation: fadeUp 0.9s var(--ease-out) 0.2s both;
  }

  .hero-eyebrow-line {
    width: 32px;
    height: 1px;
    background: var(--accent);
  }

  .hero-eyebrow span {
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--accent);
  }

  .hero-name {
    font-family: var(--font-display);
    font-size: clamp(3.5rem, 7vw, 6rem);
    font-weight: 300;
    line-height: 0.95;
    letter-spacing: -0.01em;
    margin-bottom: 40px;
    opacity: 0;
    animation: fadeUp 1s var(--ease-out) 0.35s both;
  }

  .hero-name em {
    font-style: italic;
    color: var(--accent);
  }

  .hero-desc {
    max-width: 380px;
    font-size: 14px;
    line-height: 1.75;
    color: var(--text-muted);
    margin-bottom: 48px;
    opacity: 0;
    animation: fadeUp 1s var(--ease-out) 0.5s both;
  }

  .hero-cta {
    display: flex;
    gap: 20px;
    align-items: center;
    opacity: 0;
    animation: fadeUp 1s var(--ease-out) 0.65s both;
  }

  .btn-primary {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 14px 28px;
    background: var(--accent);
    color: var(--bg);
    font-family: var(--font-sans);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    text-decoration: none;
    transition: all 200ms ease;
  }

  .btn-primary:hover {
    background: var(--text-primary);
    transform: translateY(-1px);
  }

  .btn-ghost {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--text-muted);
    text-decoration: none;
    transition: color 200ms ease;
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .btn-ghost::after {
    content: '→';
    transition: transform 200ms ease;
  }

  .btn-ghost:hover { color: var(--text-primary); }
  .btn-ghost:hover::after { transform: translateX(4px); }

  .hero-right {
    position: relative;
    display: flex;
    align-items: flex-end;
    justify-content: flex-end;
    padding: 0;
    overflow: hidden;
  }

  .hero-stat-block {
    position: absolute;
    bottom: 80px;
    right: 48px;
    display: flex;
    flex-direction: column;
    gap: 24px;
    text-align: right;
    z-index: 2;
    opacity: 0;
    animation: fadeUp 1s var(--ease-out) 0.8s both;
  }

  .hero-stat {
    border-right: 1px solid var(--accent-line);
    padding-right: 20px;
  }

  .hero-stat-number {
    font-family: var(--font-display);
    font-size: 2.6rem;
    font-weight: 300;
    line-height: 1;
    color: var(--text-primary);
  }

  .hero-stat-label {
    font-size: 10px;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--text-dim);
    margin-top: 4px;
  }

  /* Large decorative letter */
  .hero-bg-letter {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-family: var(--font-display);
    font-size: 40vw;
    font-weight: 300;
    color: rgba(255,245,220,0.015);
    pointer-events: none;
    user-select: none;
    line-height: 1;
    white-space: nowrap;
    z-index: 1;
  }

  /* Vertical line accent */
  .hero::after {
    content: '';
    position: absolute;
    top: 15%;
    bottom: 15%;
    left: 50%;
    width: 1px;
    background: linear-gradient(to bottom, transparent, var(--border-warm), transparent);
    z-index: 1;
  }

  /* ─── SECTION STRUCTURE ─── */
  section { padding: 120px 48px; }

  .section-header {
    display: flex;
    align-items: center;
    gap: 24px;
    margin-bottom: 72px;
  }

  .section-num {
    font-family: var(--font-display);
    font-size: 0.8rem;
    font-style: italic;
    color: var(--accent);
    min-width: 28px;
  }

  .section-title {
    font-family: var(--font-display);
    font-size: clamp(2.2rem, 4vw, 3.2rem);
    font-weight: 300;
    letter-spacing: -0.01em;
    line-height: 1.1;
  }

  .section-title em { font-style: italic; color: var(--accent); }

  .section-line {
    flex: 1;
    height: 1px;
    background: var(--border);
    max-width: 200px;
  }

  /* ─── ABOUT ─── */
  #about {
    max-width: 1200px;
    margin: 0 auto;
  }

  .about-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 80px;
    align-items: start;
  }

  .about-body {
    font-family: var(--font-display);
    font-size: 1.25rem;
    font-weight: 300;
    line-height: 1.75;
    color: var(--text-primary);
  }

  .about-body p + p { margin-top: 1.4em; }

  .about-body strong {
    font-weight: 400;
    color: var(--accent);
  }

  .about-sidebar {
    display: flex;
    flex-direction: column;
    gap: 32px;
    padding-top: 8px;
  }

  .skill-tag-group {
    border-top: 1px solid var(--border);
    padding-top: 24px;
  }

  .skill-tag-group-label {
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: var(--text-dim);
    margin-bottom: 12px;
  }

  .skill-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }

  .skill-tag {
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 0.06em;
    color: var(--text-muted);
    border: 1px solid var(--border-warm);
    padding: 5px 12px;
    transition: all 200ms ease;
  }

  .skill-tag:hover {
    border-color: var(--accent-line);
    color: var(--accent);
  }

  /* ─── WORK EXPERIENCE ─── */
  #work {
    background: var(--surface);
    border-top: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
  }

  .work-inner {
    max-width: 1200px;
    margin: 0 auto;
  }

  .work-entries {
    display: flex;
    flex-direction: column;
    gap: 0;
  }

  .work-entry {
    display: grid;
    grid-template-columns: 200px 1fr;
    gap: 48px;
    padding: 48px 0;
    border-bottom: 1px solid var(--border);
    transition: background 300ms ease;
    position: relative;
  }

  .work-entry:last-child { border-bottom: none; }

  .work-entry::before {
    content: '';
    position: absolute;
    left: -48px;
    right: -48px;
    top: 0;
    bottom: 0;
    background: transparent;
    transition: background 300ms ease;
    z-index: 0;
  }

  .work-entry:hover::before {
    background: rgba(200,169,110,0.03);
  }

  .work-entry > * { position: relative; z-index: 1; }

  .work-meta { padding-top: 4px; }

  .work-dates {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--accent);
    margin-bottom: 8px;
  }

  .work-company {
    font-family: var(--font-display);
    font-size: 1rem;
    font-weight: 300;
    color: var(--text-muted);
    line-height: 1.3;
  }

  .work-main {}

  .work-title {
    font-family: var(--font-display);
    font-size: 1.8rem;
    font-weight: 300;
    line-height: 1.15;
    margin-bottom: 16px;
    letter-spacing: -0.01em;
  }

  .work-title em { font-style: italic; color: var(--accent); }

  .work-desc {
    font-size: 13.5px;
    line-height: 1.75;
    color: var(--text-muted);
    max-width: 640px;
    margin-bottom: 20px;
  }

  .work-achievements {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }

  .achievement-chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 11px;
    font-weight: 500;
    color: var(--text-muted);
    background: var(--accent-dim);
    border: 1px solid var(--accent-line);
    padding: 4px 10px;
  }

  .achievement-chip::before {
    content: '';
    width: 4px;
    height: 4px;
    background: var(--accent);
    border-radius: 50%;
    flex-shrink: 0;
  }

  /* ─── PROJECTS ─── */
  #projects {
    max-width: 1200px;
    margin: 0 auto;
    padding-left: 48px;
    padding-right: 48px;
  }

  .projects-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1px;
    background: var(--border);
    border: 1px solid var(--border);
  }

  .project-card {
    background: var(--bg);
    padding: 40px 36px;
    display: flex;
    flex-direction: column;
    min-height: 300px;
    transition: background 250ms ease;
    text-decoration: none;
    color: inherit;
    cursor: default;
    position: relative;
    overflow: hidden;
  }

  .project-card::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 2px;
    background: var(--accent);
    transform: scaleX(0);
    transform-origin: left;
    transition: transform 400ms var(--ease-out);
  }

  .project-card:hover { background: var(--surface-2); }
  .project-card:hover::after { transform: scaleX(1); }

  .project-index {
    font-family: var(--font-display);
    font-size: 0.75rem;
    font-style: italic;
    color: var(--text-dim);
    margin-bottom: 24px;
  }

  .project-name {
    font-family: var(--font-display);
    font-size: 1.55rem;
    font-weight: 300;
    line-height: 1.2;
    margin-bottom: 16px;
    letter-spacing: -0.01em;
    flex: 1;
  }

  .project-name em { font-style: italic; color: var(--accent); }

  .project-desc {
    font-size: 12.5px;
    line-height: 1.7;
    color: var(--text-muted);
    margin-bottom: 24px;
  }

  .project-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
  }

  .project-tag {
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--text-dim);
    border-bottom: 1px solid var(--border-warm);
    padding-bottom: 1px;
  }

  /* ─── SIDE PROJECTS / BEYOND WORK ─── */
  #beyond {
    background: var(--surface);
    border-top: 1px solid var(--border);
  }

  .beyond-inner {
    max-width: 1200px;
    margin: 0 auto;
  }

  .beyond-grid {
    display: grid;
    grid-template-columns: 1fr 1.4fr;
    gap: 80px;
    align-items: start;
  }

  .beyond-intro {
    font-family: var(--font-display);
    font-size: 1.15rem;
    font-weight: 300;
    line-height: 1.75;
    color: var(--text-muted);
  }

  .beyond-intro strong {
    font-weight: 400;
    color: var(--text-primary);
    font-style: italic;
  }

  .beyond-items {
    display: flex;
    flex-direction: column;
    gap: 0;
  }

  .beyond-item {
    display: grid;
    grid-template-columns: 48px 1fr;
    gap: 20px;
    padding: 28px 0;
    border-bottom: 1px solid var(--border);
    align-items: start;
  }

  .beyond-item:first-child { border-top: 1px solid var(--border); }

  .beyond-icon {
    width: 40px;
    height: 40px;
    background: var(--accent-dim);
    border: 1px solid var(--accent-line);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    margin-top: 2px;
  }

  .beyond-icon svg {
    width: 18px;
    height: 18px;
    stroke: var(--accent);
    fill: none;
    stroke-width: 1.5;
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  .beyond-item-title {
    font-family: var(--font-display);
    font-size: 1.1rem;
    font-weight: 300;
    letter-spacing: -0.01em;
    margin-bottom: 4px;
  }

  .beyond-item-desc {
    font-size: 12.5px;
    color: var(--text-muted);
    line-height: 1.65;
  }

  /* ─── CONTACT ─── */
  #contact {
    max-width: 1200px;
    margin: 0 auto;
    padding-left: 48px;
    padding-right: 48px;
  }

  .contact-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 80px;
    align-items: center;
  }

  .contact-headline {
    font-family: var(--font-display);
    font-size: clamp(2.5rem, 5vw, 4rem);
    font-weight: 300;
    line-height: 1.1;
    letter-spacing: -0.02em;
  }

  .contact-headline em {
    font-style: italic;
    color: var(--accent);
  }

  .contact-sub {
    margin-top: 20px;
    font-size: 14px;
    color: var(--text-muted);
    line-height: 1.7;
    max-width: 380px;
  }

  .contact-links {
    display: flex;
    flex-direction: column;
    gap: 16px;
  }

  .contact-link {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 20px 24px;
    border: 1px solid var(--border);
    text-decoration: none;
    color: var(--text-primary);
    transition: all 250ms ease;
    position: relative;
    overflow: hidden;
  }

  .contact-link::before {
    content: '';
    position: absolute;
    inset: 0;
    background: var(--accent-dim);
    transform: scaleX(0);
    transform-origin: left;
    transition: transform 350ms var(--ease-out);
  }

  .contact-link:hover { border-color: var(--accent-line); }
  .contact-link:hover::before { transform: scaleX(1); }

  .contact-link-inner {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
  }

  .contact-link-label {
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--text-dim);
    display: block;
