{"language": "javascript", "code": "const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageNumber, TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

// ─── Color palette ───────────────────────────────────────────────────────────
const C = {
  black:      "1A1A1A",
  slate:      "2C3E50",
  accent:     "1D4E89",   // deep navy
  accentMid:  "2E75B6",   // mid blue
  accentLight:"D6E4F0",   // pale blue fill
  red:        "C0392B",
  redLight:   "FDECEA",
  amber:      "D35400",
  amberLight: "FEF3E2",
  green:      "1E6B3C",
  greenLight: "E8F5EE",
  grey:       "6C757D",
  greyLight:  "F5F5F5",
  white:      "FFFFFF",
  divider:    "D0D7DE",
};

// ─── Helpers ──────────────────────────────────────────────────────────────────
const border = (color = C.divider) => ({
  top:    { style: BorderStyle.SINGLE, size: 1, color },
  bottom: { style: BorderStyle.SINGLE, size: 1, color },
  left:   { style: BorderStyle.SINGLE, size: 1, color },
  right:  { style: BorderStyle.SINGLE, size: 1, color },
});
const noBorder = () => ({
  top:    { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  left:   { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  right:  { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
});

const cell = (children, opts = {}) => new TableCell({
  children: Array.isArray(children) ? children : [children],
  borders: opts.borders || border(),
  width: opts.width ? { size: opts.width, type: WidthType.DXA } : undefined,
  shading: opts.fill ? { fill: opts.fill, type: ShadingType.CLEAR } : undefined,
  margins: { top: 80, bottom: 80, left: 140, right: 140 },
  verticalAlign: opts.valign || undefined,
  columnSpan: opts.span || undefined,
});

const p = (text, opts = {}) => new Paragraph({
  children: [new TextRun({
    text,
    bold: opts.bold || false,
    color: opts.color || C.black,
    size: opts.size || 20,
    font: "Calibri",
    italics: opts.italic || false,
  })],
  alignment: opts.align || AlignmentType.LEFT,
  spacing: { before: opts.spaceBefore || 0, after: opts.spaceAfter || 60 },
  numbering: opts.numbering || undefined,
});

const h1 = (text) => new Paragraph({
  children: [new TextRun({ text, bold: true, color: C.white, size: 28, font: "Calibri" })],
  shading: { fill: C.accent, type: ShadingType.CLEAR },
  spacing: { before: 280, after: 140 },
  indent: { left: 160, right: 160 },
});

const h2 = (text, color = C.slate) => new Paragraph({
  children: [
    new TextRun({ text, bold: true, color, size: 24, font: "Calibri" }),
  ],
  spacing: { before: 240, after: 80 },
